export default {"1":{"html":"<p>تصور کریں کہ آپ ایک نانبائی ہیں، اور آپ جانتے ہیں کہ دو ماہ میں آپ کو بڑی مقدار میں گندم کی ضرورت ہوگی۔ آج قیمت مناسب لگ رہی ہے، لیکن آپ کو خدشہ ہے کہ آپ کے خریدنے سے پہلے اس میں اضافہ ہو سکتا ہے۔ لہذا آپ کو ایک کسان ملے اور آپ دونوں تحریری طور پر، آج سے دو ماہ بعد ڈیلیوری کے لیے ابھی قیمت پر متفق ہیں۔ آپ نے ابھی تک ادائیگی نہیں کی۔ گندم منتقل نہیں ہوئی۔ لیکن قیمت مقفل ہے۔ آپ نے ابھی مستقبل کے معاہدے کے بہت قریب کچھ مارا ہے، اور لوگ صدیوں سے بالکل ایسا ہی کر رہے ہیں۔ اسٹاک مارکیٹ کا جدید ورژن زیادہ چمکدار ہے اور اسکرین پر تجارت کی جاتی ہے، پھر بھی یہ خیال بالکل نہیں بدلا ہے۔</p>\n<p>اے <strong>مستقبل کا معاہدہ</strong> کسی چیز کی ایک مقررہ مقدار کو مستقبل میں ایک مقررہ تاریخ پر ایک مقررہ قیمت پر خریدنے یا بیچنے کے لیے آج کیا جانے والا ایک معاہدہ ہے۔ چار چیزوں کا پہلے سے فیصلہ کیا جاتا ہے اور ان میں سے کوئی بھی مبہم نہیں رہ جاتا۔ یہ درستگی پوری بات ہے، اور ایک بار جب آپ ان چار حصوں کو واضح طور پر دیکھتے ہیں، تو مستقبل پراسرار محسوس کرنا بند کر دیتا ہے۔</p>\n<h2 id=\"the-four-things-every-future-fixes\">چار چیزیں جو ہر مستقبل کو ٹھیک کرتی ہیں۔</h2>\n<p>ہر مستقبل کا معاہدہ، اس سے کوئی فرق نہیں پڑتا ہے کہ اس کے ارد گرد کی مارکیٹ کتنی ہی پیچیدہ نظر آتی ہے، چار سادہ حقائق کو پن کرتا ہے۔</p>\n<ul>\n<li>دی <strong>بنیادی</strong> کیا چیز تجارت کی جا رہی ہے؟ یہ اسٹاک ہو سکتا ہے جیسا کہ RELIANCE، ایک انڈیکس جیسا کہ NIFTY، یا خام تیل یا سونا جیسی کموڈٹی۔</li>\n<li>دی <strong>قیمت</strong> وہ شرح ہے جس پر آپ آج متفق ہیں۔ یہ وہ سطح ہے جس پر سودے کو بعد میں نوازا جائے گا، جو کچھ بھی مارکیٹ بیچ میں کرتی ہے۔</li>\n<li>دی <strong>بہت سائز</strong> مقررہ مقدار ہے۔ آپ فیوچر مارکیٹ میں RELIANCE کے ایک حصہ کی تجارت نہیں کر سکتے۔ آپ ایک معیاری بنڈل میں تجارت کرتے ہیں، اور RELIANCE کے لیے وہ بنڈل 500 شیئرز ہے۔</li>\n<li>دی <strong>میعاد ختم</strong> معاہدہ ہونے کی تاریخ ہے۔ RELIANCE اسٹاک فیوچرز کے لیے یہ ماہانہ ہے۔ ہمارے کام کی مثالوں میں معاہدہ 28 جولائی 2026 کو ختم ہو رہا ہے۔</li>\n</ul>\n<p>ہمارے کام شدہ RELIANCE معاہدے کے لیے بھرے گئے وہ چار حصے یہ ہیں، جس کی مثال ہم پورے کورس میں واپس کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>چار مقررہ حصے</th>\n<th>ہمارا RELIANCE معاہدہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیرِ نظر</td>\n<td>RELIANCE (حالیہ قریب قریب 1,318 روپے)</td>\n</tr>\n<tr>\n<td>قیمت</td>\n<td>1,320 روپے، آج کی قیمت کے قریب راؤنڈ ہڑتال</td>\n</tr>\n<tr>\n<td>لاٹ سائز</td>\n<td>500 شیئرز، تقریباً 6,59,000 روپے کا اسٹاک</td>\n</tr>\n<tr>\n<td>ختم</td>\n<td>28 جولائی 2026، تقریباً 32 دن باہر</td>\n</tr>\n</tbody></table>\n<p>ان کو ایک ساتھ رکھیں اور ایک جملہ ایک حقیقی معاہدے کی وضاحت کرتا ہے۔ آپ آج ہی 500 شیئرز 1,320 روپے میں خریدنے کے لیے متفق ہیں، جس کی ڈیل 28 جولائی 2026 کو ہونے والی ہے۔ 500 شیئرز کو تقریباً 1,318 روپے سے ضرب دیں اور ایک معاہدہ تقریباً 6,59,000 روپے کے اسٹاک کو کنٹرول کرتا ہے۔ وہ ایک لاٹ ہے۔ یہ ایک ہی معاہدے پر سوار ہونے والی رقم کی سنگین رقم ہے، یہی وجہ ہے کہ اس کورس کا باقی حصہ خطرہ پر اتنا وقت صرف کرتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مستقبل چار مقررہ حصوں کے ساتھ ایک وعدہ ہے: بنیادی، قیمت، لاٹ سائز، اور میعاد ختم ہونے کی تاریخ۔ ان چاروں کا فیصلہ کریں اور آپ نے معاہدہ کو مکمل طور پر بیان کیا ہے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-what-is-a-future.png\" alt=\"ہر فیوچر کنٹریکٹ کا ڈھانچہ خریدار اور بیچنے والے کے درمیان ایک ڈیل ہے جو بعد میں سیٹلمنٹ کے لیے بنیادی، متفقہ قیمت، لاٹ کا سائز اور آج ختم ہونے کی تاریخ طے کرتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ہر فیوچر کنٹریکٹ کا ڈھانچہ خریدار اور بیچنے والے کے درمیان ایک ڈیل ہے جو بعد میں سیٹلمنٹ کے لیے بنیادی، متفقہ قیمت، لاٹ کا سائز اور آج ختم ہونے کی تاریخ طے کرتا ہے۔</figcaption></figure>\n<h2 id=\"two-sides-and-both-are-obliged\">دو فریق، اور دونوں واجب ہیں۔</h2>\n<p>مستقبل کے معاہدے کے ہمیشہ دو رخ ہوتے ہیں۔ ایک تاجر خریدار ہے اور دوسرا بیچنے والا، اور یہاں وہ حصہ ہے جسے نئے آنے والوں کو کسی بھی چیز سے پہلے سمجھنا چاہیے۔ دونوں فریق معاہدے کے ساتھ گزرنے کے پابند ہیں۔</p>\n<p>دی <strong>خریدار</strong> مستقبل کا معاہدہ مقررہ قیمت پر انڈرلائننگ خریدنے پر رضامند ہو گیا ہے۔ ہم کہتے ہیں کہ یہ تاجر ہے۔ <strong>طویل</strong>. دی <strong>بیچنے والا</strong> اس مقررہ قیمت پر فروخت کرنے پر رضامندی ظاہر کی ہے۔ ہم کہتے ہیں کہ یہ تاجر ہے۔ <strong>مختصر</strong>. کوئی بھی فریق آسانی سے نہیں چل سکتا کیونکہ قیمت ان کے خلاف چلی گئی ہے۔ خریدار کو خریدنا چاہیے اور بیچنے والے کو بیچنا چاہیے، اس سطح پر جس پر وہ متفق ہوں، قطع نظر اس کے کہ مارکیٹ کیا کرتی ہے۔</p>\n<p>یہ ذمہ داری مستقبل اور ایک آپشن کے درمیان واحد سب سے بڑا فرق ہے، اور یہ آپ کے ذہن میں ابھی ٹھیک کرنے کے قابل ہے کیونکہ یہ بعد میں ہر چیز کو شکل دیتا ہے۔ ایک آپشن اپنے ہولڈر کو ایک انتخاب دیتا ہے۔ ہولڈر آپشن کو بیکار ختم ہونے دے سکتا ہے اور صرف وہ چھوٹا پریمیم کھو سکتا ہے جو اس نے ادا کیا تھا۔ مستقبل ایسا کوئی رحم نہیں کرتا۔ اگر آپ کا مستقبل طویل ہے اور قیمت گر جاتی ہے، تو آپ ابھی بھی مکمل اقدام کے لیے تیار ہیں۔ ترک کرنے کے لیے کوئی پریمیم نہیں ہے اور کوئی فرار ہیچ نہیں ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مستقبل ایک ذمہ داری ہے، انتخاب نہیں۔ خریدار اور بیچنے والے دونوں کو معاہدے کا احترام کرنا چاہیے۔ آپشن کے برعکس، آپ کھوتے ہوئے مستقبل کو صرف ختم ہونے کی اجازت دے کر اسے ترک نہیں کر سکتے، لہذا نقصان بہت زیادہ ہو سکتا ہے۔</p>\n</div></div>\n<h2 id=\"why-the-price-you-lock-matters\">آپ جس قیمت کو لاک کرتے ہیں وہ کیوں اہم ہے۔</h2>\n<p>قیمت کو مقفل کرنا بالکل مفید ہے کیونکہ کوئی نہیں جانتا کہ مستقبل کیا ہے۔ بیکر کے بارے میں دوبارہ سوچئے۔ اگر گندم بڑھ جاتی ہے تو نانبائی کم قیمت پر تالا لگا کر خوش ہوتا ہے۔ اگر گندم کریش ہو جاتی ہے، تو نانبائی زیادہ لاک ریٹ پر خریدنے میں پھنس جاتا ہے جبکہ باقی سب سستے خریدتے ہیں۔ تالا دونوں طریقوں سے کاٹتا ہے۔ یہ بے یقینی کو دور کرتا ہے، اور غیر یقینی صورتحال کو دور کرنا بعض اوقات ایک طوفان کو ترک کرنے کے قابل ہوتا ہے۔</p>\n<p>مالی مستقبل کے ذریعے بھی یہی منطق چلتی ہے۔ فرض کریں کہ آپ کو یقین ہے کہ اگلے مہینے میں RELIANCE بڑھ جائے گا۔ آپ براہ راست حصص خرید سکتے ہیں، لیکن اس سے پورے 6,59,000 روپے بنتے ہیں۔ اس کے بجائے آپ 1,320 روپے میں ایکRELIANCEمستقبل خریدیں۔ آپ نے اس سطح پر 500 شیئرز خریدنے کا حق اور فرض بند کر دیا ہے۔ اگر RELIANCE بڑھ کر 1,400 روپے تک پہنچ جاتا ہے، تو آپ کی 1,320 روپے کی لاک قیمت بہترین نظر آتی ہے، اور 500 شیئرز کا فائدہ بہت زیادہ ہے۔ اگر RELIANCE 1,250 روپے پر گرتا ہے، تو وہی لاک اب درد کرتا ہے، اور آپ نقصان کو پورا کرتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ 28 جولائی 2026 کی میعاد ختم ہونے کے لیے 1,320 روپے میں ایک RELIANCE مستقبل خریدتے ہیں۔ لاٹ 500 شیئرز ہے۔ ہر 1 روپے جو RELIANCE منتقل کرتا ہے وہ آپ کی پوزیشن پر 500 روپے ہے، کیونکہ 500 شیئرز گنا 1 روپے 500 ہے۔ آپ کے حق میں 20 روپے کی حرکت 10,000 روپے ہے۔ آپ کے خلاف بھی یہی اقدام 10,000 روپے کا نقصان ہے۔ معاہدہ بالکل یکساں ہے کہ یہ کس طریقے سے ادائیگی کرتا ہے۔</p>\n</div></div>\n<h2 id=\"how-a-reliance-stock-future-actually-works\">RELIANCE اسٹاک کا مستقبل دراصل کیسے کام کرتا ہے۔</h2>\n<p>OpenAlgo پلیٹ فارم اور تمام ہندوستانی تبادلے پر، اس RELIANCE معاہدے کا ایک درست نام ہے۔ علامت کی شکل بنیادی نام ہے، پھر دن، مہینہ اور سال کے طور پر لکھا گیا ایکسپائری، پھر حروف FUT۔ لہذا جولائی کا معاہدہ RELIANCE28JUL26FUT پڑھتا ہے۔ آپ کو ابھی فارمیٹ کو یاد کرنے کی ضرورت نہیں ہے۔ نقطہ یہ ہے کہ معاہدہ مکمل طور پر معیاری ہے، تاکہ کوئی بھی خریدار اور کوئی بھی بیچنے والا کہیں بھی بالکل وہی چیز ٹریڈ کر رہا ہو۔</p>\n<p>جب آپ ایک لاٹ کے لیے خرید آرڈر دیتے ہیں، تو ایکسچینج آپ کو بیچنے والے کے ساتھ ملاتا ہے۔ اس لمحے سے آپ مستقبل میں 500 حصص کے 500 شیئرز پر فائز ہیں۔ آپ نے 6,59,000 روپے ادا نہیں کئے۔ آپ نے صرف ایک مارجن، قدر کا ایک حصہ پوسٹ کیا، اور ہم بعد میں اس خیال کے لیے ایک پورا باب وقف کرتے ہیں کیونکہ یہ وہ جگہ ہے جہاں موقع اور خطرہ دونوں رہتے ہیں۔</p>\n<h2 id=\"almost-nobody-waits-for-delivery\">تقریباً کوئی بھی ڈیلیوری کا انتظار نہیں کرتا</h2>\n<p>ایک معقول مبتدی اب ایک سمجھدار سوال پوچھتا ہے۔ اگر آپ مستقبل میں ایک RELIANCE خریدتے ہیں، تو کیا 28 جولائی کو آپ کے اکاؤنٹ میں 500 حقیقی حصص آتے ہیں؟ عملی طور پر، تقریبا کبھی نہیں، اور دو وجوہات ہیں.</p>\n<p>سب سے پہلے، زیادہ تر تاجر میعاد ختم ہونے سے پہلے اپنی پوزیشن بند کر دیتے ہیں۔ بند کرنا آسان ہے۔ اگر آپ کا مستقبل ایک طویل ہے، تو آپ ایک ہی معاہدے کا ایک مستقبل بیچ دیتے ہیں، اور دونوں منسوخ ہو جاتے ہیں۔ آپ کی خرید قیمت اور آپ کی فروخت کی قیمت کے درمیان فرق آپ کا منافع یا نقصان ہے، نقد میں طے شدہ۔ اسے کہتے ہیں۔ <strong>squaring بند</strong>، اور فیوچر ٹریڈز کی اکثریت ختم ہونے کی تاریخ آنے سے بہت پہلے اس طرح ختم ہو جاتی ہے۔</p>\n<p>دوسرا، تصفیہ کے اصول بنیادی طور پر مختلف ہوتے ہیں۔ انڈیکس فیوچر جیسے کہ NIFTY اور BANKNIFTY ہیں۔ <strong>نقدی سے طے شدہ</strong>. ڈیلیور کرنے کے لیے حصص کی کوئی ٹوکری نہیں ہے، اس لیے ایکسپائر ہونے پر کوئی بھی اوپن پوزیشن حتمی انڈیکس لیول کے مقابلے میں صرف روپے میں طے کی جاتی ہے۔ سنگل اسٹاک فیوچر جیسے کہ RELIANCE ہندوستان میں فزیکل ڈیلیوری کے لیے جا سکتے ہیں اگر آپ ان کی میعاد ختم ہونے تک روکے ہوئے ہیں، جس کی ایک اور وجہ ہے کہ عام تاجر 500 شیئرز وصول کرنے یا ان کے حوالے کرنے کا بندوبست کرنے کے بجائے اچھے وقت میں اسکوائر کر دیتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اگر آپ کبھی یہ محسوس کرنا چاہتے ہیں کہ کوئی معاہدہ پیسے کو خطرے میں ڈالے بغیر کیسا برتاؤ کرتا ہے، سینڈ باکس ٹریڈنگ کا استعمال کریں ( OpenAlgo میں تجزیہ کار وضع)۔ آپ مستقبل میں ایک RELIANCE رکھ سکتے ہیں اور اسکوائر کر سکتے ہیں اور منافع اور نقصان کی حرکت کو دیکھ سکتے ہیں، بغیر کوئی حقیقی سرمایہ داؤ پر لگا ہوا ہے۔</p>\n</div></div>\n<p>آگے بڑھنے کا ذہنی ماڈل چھوٹا اور مضبوط ہے۔ مستقبل دو پابند فریقوں کے درمیان ایک مقفل معاہدہ ہے جو ایک مقررہ تاریخ پر ایک مقررہ قیمت پر ایک مقررہ مقدار کی تجارت کرتا ہے۔ خریدار لمبا ہے اور امید کرتا ہے کہ قیمت بڑھ جائے گی۔ بیچنے والا چھوٹا ہے اور امید کرتا ہے کہ یہ گر جائے گا۔ زیادہ تر پوزیشنیں ڈیلیوری تک پہنچنے سے پہلے ہی نقدی کے لیے بند کر دی جاتی ہیں۔ اس تصویر کو مضبوطی سے پکڑو، کیونکہ یہاں سے ہر باب براہ راست اس پر بنتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>فیوچر مارکیٹ اسٹاک ایکسچینج سے پرانی ہے۔ چاول کے معیاری معاہدے سترہویں صدی میں جاپان میں تجارت کر رہے تھے، اسی وجہ سے آج تاجر ان کا استعمال کرتے ہیں، غیر یقینی مستقبل کے خلاف قیمت کو بند کرنے کے لیے۔</p>\n</div></div>\n<p>اگلے باب میں ہم دیکھتے ہیں کہ یہ معاہدے کیوں موجود ہیں، اور آپ ان دو قسم کے لوگوں سے ملیں گے جو ان کی تجارت کرتے ہیں۔ ایک خطرے سے چھٹکارا پانے کی کوشش کر رہا ہے۔ دوسرا اسے لے کر خوش ہوتا ہے۔ مارکیٹ صرف کام کرتی ہے کیونکہ دونوں ظاہر ہوتے ہیں۔</p>\n","toc":[{"level":2,"text":"چار چیزیں جو ہر مستقبل کو ٹھیک کرتی ہیں۔","id":"the-four-things-every-future-fixes"},{"level":2,"text":"دو فریق، اور دونوں واجب ہیں۔","id":"two-sides-and-both-are-obliged"},{"level":2,"text":"آپ جس قیمت کو لاک کرتے ہیں وہ کیوں اہم ہے۔","id":"why-the-price-you-lock-matters"},{"level":2,"text":"RELIANCE اسٹاک کا مستقبل دراصل کیسے کام کرتا ہے۔","id":"how-a-reliance-stock-future-actually-works"},{"level":2,"text":"تقریباً کوئی بھی ڈیلیوری کا انتظار نہیں کرتا","id":"almost-nobody-waits-for-delivery"}],"imgCount":1,"hasContent":true},"2":{"html":"<p>جب آپ RELIANCE پر پیسہ لگانے کے لیے بازار میں جاتے ہیں، تو آپ کو ایک بھی ٹول نہیں دیا جاتا ہے۔ آپ کو ان کا ایک چھوٹا کنبہ سونپ دیا گیا ہے، اور وہ دور سے ایک جیسے نظر آتے ہیں لیکن جب پیسہ لائن پر ہوتا ہے تو بہت مختلف سلوک کرتے ہیں۔ آپ حصص خرید سکتے ہیں اور کمپنی کے حصہ کے مالک بن سکتے ہیں۔ آپ مستقبل خرید سکتے ہیں اور منسلک ذمہ داری کے ساتھ قیمت لاک کر سکتے ہیں۔ آپ ایک آپشن خرید سکتے ہیں اور اپنا خیال بدلنے کے حق کی ادائیگی کر سکتے ہیں۔ ہر ایک حقیقی، سمجھدار وجہ کے لیے ایک حقیقی، سمجھدار انتخاب ہے، اور سب سے بری غلطیاں جو ابتدائی طور پر ان چاروں میں سے ایک غلط کو منتخب کرنے سے ہوتی ہیں، اس کا احساس کیے بغیر کہ دوسرے موجود ہیں۔ لہذا اس سے پہلے کہ ہم مستقبل کی گہرائی میں جائیں، آئیے اس کے کزنز کے درمیان ایک مستقبل رکھیں اور دیکھیں کہ جب آپ اسے منتخب کرتے ہیں تو آپ کس چیز کا انتخاب کر رہے ہیں۔</p>\n<p>ہم جن چار آلات کا موازنہ کریں گے وہ ہیں۔ <strong>آگے</strong>, the <strong>مستقبل</strong>, the <strong>اختیار</strong>، اور سادہ <strong>نقد ایکوئٹی</strong>جس کا سیدھا سیدھا مطلب ہے حصہ کا مالک ہونا۔ وہ سب سے زیادہ غیر رسمی مصافحہ سے لے کر انتہائی رسمی، تبادلے کی پولیس والے معاہدے تک، اور خالص ملکیت سے لے کر خالص وقتی شرط تک ایک سپیکٹرم پر بیٹھتے ہیں۔</p>\n<h2 id=\"the-forward-a-private-custom-handshake\">فارورڈ: ایک نجی، اپنی مرضی کے مطابق مصافحہ</h2>\n<p>پہلے باب سے نانبائی اور کسان کو یاد رکھیں۔ وہ بیٹھ گئے، دو مہینوں میں گندم کی ترسیل کی قیمت پر اتفاق کیا، اور ہاتھ ملایا۔ وہ سودا ہے a <strong>آگے کا معاہدہ</strong>، اور یہ اس خاندان کا سب سے قدیم رکن ہے۔ فارورڈ مستقبل کی ایک مقررہ تاریخ پر ایک مقررہ قیمت پر کسی چیز کی تجارت کرنے کے لیے دو فریقوں کے درمیان ایک نجی معاہدہ ہے۔ اس کے بارے میں کچھ بھی معیاری نہیں ہے۔ نانبائی اور کسان کوئی بھی مقدار، گندم کا کوئی بھی معیار، کوئی بھی ترسیل کی تاریخ، کوئی بھی قیمت جو وہ دونوں قبول کرتے ہیں چن سکتے ہیں۔ یہ لچک حقیقی طور پر کارآمد ہے، کیونکہ ڈیل کو بالکل وہی شکل دی جا سکتی ہے جس کی ہر فریق کو ضرورت ہے۔</p>\n<p>لیکن لچک ایک بھاری قیمت پر آتی ہے، اور لاگت کا ایک نام ہے: <strong>ہم منصب کا خطرہ</strong>. ایک فارورڈ اتنا ہی اچھا ہے جتنا اس کے دوسری طرف والا شخص۔ اگر گندم کی قیمتیں گر جائیں اور کسان زیادہ مارکیٹ ریٹ پر کسی اور کو بیچے تو اسے خاموشی سے جانے سے کیا روکتا ہے؟ عدالتوں کے ذریعے اس کا پیچھا کرنے کی صلاحیت صرف نانبائی کی ہے۔ ان کے درمیان کوئی ریفری کھڑا نہیں ہے۔ اگر ایک فریق ادائیگی نہیں کر سکتا یا صرف انکار کر دیتا ہے، تو دوسرا وعدہ ٹوٹا ہوا چھوڑ دیتا ہے۔ ایک فارورڈ بھی غیر مائع ہے۔ چونکہ یہ دو مخصوص لوگوں کے لیے اپنی مرضی کے مطابق بنایا گیا تھا، اس لیے بیکر آدھے راستے میں کسی اجنبی کو اپنی ڈیل کا حصہ آسانی سے نہیں بیچ سکتا۔ وہ ڈیلیوری کی تاریخ تک اس میں پھنس گیا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>فارورڈ ایک نجی، گفت و شنید، یک طرفہ ڈیل ہے۔ یہ حیرت انگیز طور پر لچکدار ہے کیونکہ دونوں فریق اپنی اپنی شرائط لکھتے ہیں، لیکن یہ غیر قانونی ہے اور اس میں فریقین کے خلاف خطرہ ہوتا ہے، یہ خطرہ کہ دوسرا فریق معاہدے کا احترام کرنے میں ناکام رہتا ہے۔</p>\n</div></div>\n<h2 id=\"the-future-the-forward-cleaned-up-and-policed\">مستقبل: آگے، صاف اور پولیس</h2>\n<p>اے <strong>مستقبل</strong> وہی ہے جو آپ کو ملتا ہے جب آپ وہی فارورڈ آئیڈیا لیتے ہیں اور اسے ایکسچینج کے ذریعے چلاتے ہیں۔ ایکسچینج اس میں دو بدلنے والی چیزیں کرتا ہے۔</p>\n<p>سب سے پہلے، یہ <strong>معیارات</strong> معاہدہ حسب ضرورت مقدار کے بجائے، آپ فکسڈ لاٹ میں تجارت کرتے ہیں، 500 حصص ایک RELIANCE مستقبل کے لیے۔ اپنی پسند کی کسی بھی تاریخ کے بجائے، آپ مقررہ میعاد ختم ہونے کی تجارت کرتے ہیں، مہینے کے آخری منگل، جیسے کہ ہمارے کام شدہ معاہدے کے لیے 28 جولائی 2026۔ کیونکہ ہر RELIANCE مستقبل ہر دوسرے سے یکساں ہوتا ہے، ہزاروں خریدار اور بیچنے والے ایک ہی معاہدے کی تجارت کر سکتے ہیں۔ یہی مستقبل بناتا ہے۔ <strong>مائع</strong>: آپ آج داخل ہو سکتے ہیں اور کل سیکنڈوں میں آف سیٹنگ کنٹریکٹ ٹریڈ کر کے باہر نکل سکتے ہیں، ایسا کچھ جو بیکر اپنے مصافحہ سے کبھی نہیں کر سکتا تھا۔</p>\n<p>دوسرا، اور زیادہ اہم بات، تبادلے کا <strong>کلیئرنگ ہاؤس</strong> ہر تجارت کے وسط میں قدم رکھیں۔ جب آپ مستقبل میں RELIANCE خریدتے ہیں، تو آپ واقعی اس مخصوص شخص پر بھروسہ نہیں کر رہے ہوتے جس نے اسے آپ کو بیچا تھا۔ کلیئرنگ ہاؤس ہر بیچنے والے کا خریدار اور ہر خریدار کو بیچنے والا بن جاتا ہے۔ یہ معاہدے کی ضمانت دیتا ہے۔ اس وعدے کو محفوظ بنانے کے لیے، یہ دونوں اطراف سے مارجن اکٹھا کرتا ہے اور نفع و نقصان کا ہر ایک دن نقد میں تصفیہ کرتا ہے، ایک خیال جس کے لیے ہم بعد کا پورا باب وقف کرتے ہیں۔ نتیجہ یہ ہے کہ <strong>مخالف پارٹی کا خطرہ ہے لیکن غائب ہو جاتا ہے۔</strong>. آپ کو کبھی یہ سوچنے کی ضرورت نہیں ہے کہ آیا دوسری طرف کا اجنبی پیسے کے لیے اچھا ہے، کیونکہ کلیئرنگ ہاؤس اس کے پیچھے کھڑا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مستقبل محض ایک ایسا فارورڈ ہے جسے معیاری بنایا گیا ہے اور ایکسچینج ٹریڈ کیا گیا ہے، جس کے بیچ میں ایک کلیئرنگ ہاؤس ہے جو دونوں اطراف کی ضمانت دیتا ہے اور ہم منصبی کے خطرے کو دور کرتا ہے۔ آپ فارورڈ کی اپنی مرضی کے مطابق لچک کو ترک کر دیتے ہیں اور بدلے میں لیکویڈیٹی اور حفاظت حاصل کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-option-a-right-not-an-obligation\">اختیار: حق، ذمہ داری نہیں۔</h2>\n<p>دی <strong>اختیار</strong> کزن ہے جو حقیقی طور پر مختلف انداز میں برتاؤ کرتا ہے، اور فرق ایک لفظ ہے: انتخاب۔ مستقبل ایک فرض ہے۔ اگر آپ کا مستقبل طویل ہے تو آپ اس کے پابند ہیں، اور اگر قیمت گرتی ہے تو آپ بغیر کسی فرار کے پورا نقصان اٹھاتے ہیں۔ ایک آپشن اس کو پلٹتا ہے۔ کسی اختیار کا خریدار فیس ادا کرتا ہے، جسے پریمیم کہا جاتا ہے۔ <strong>حق ہے لیکن فرض نہیں۔</strong> ایک مقررہ قیمت پر خریدنا یا بیچنا۔ اگر تجارت اپنے راستے پر چلتی ہے تو وہ حق کا استعمال کرتے ہیں۔ اگر یہ ان کے خلاف جاتا ہے تو، وہ صرف آپشن کو ختم ہونے دیتے ہیں اور اس سے زیادہ کچھ نہیں کھو دیتے ہیں جو وہ پہلے سے ادا کر چکے ہیں۔</p>\n<p>یہ واحد فرق ادائیگی کی پوری شکل کو موڑ دیتا ہے۔ مستقبل کی ادائیگی ایک سیدھی لکیر ہے: ہر ایک روپے جو RELIANCE منتقل کرتا ہے آپ کی ون لاٹ پوزیشن کے لیے 500 روپے ہے، اوپر یا نیچے، بالکل ہم آہنگ، ایک خیال جسے ہم بعد کے باب میں مکمل طور پر دریافت کریں گے۔ آپشن کی ادائیگی سیدھی لائن نہیں ہے۔ یہ جھک جاتا ہے، کیونکہ خریدار کا نقصان پریمیم پر محدود ہوتا ہے جبکہ فائدہ بڑھتا رہتا ہے۔ خریدار نے برے نتائج سے دور رہنے کا حق خرید لیا ہے، اور یہ عدم توازن وہی ہے جس کے لیے وہ پریمیم ادا کرتے ہیں۔ مستقبل کے حامل کے پاس ایسی کوئی رحم نہیں ہے اور وہ ایسا کوئی پریمیم ادا نہیں کرتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>واضح فرق فرض ہے۔ ایک آپشن خریدار دور جا سکتا ہے اور صرف پریمیم کھو سکتا ہے، لہذا ادائیگی جھک جاتی ہے اور منفی پہلو محدود ہو جاتا ہے۔ مستقبل کے ہولڈر کو بند کر دیا گیا ہے، لہذا ادائیگی ایک سیدھی لائن ہے اور نقصان بہت زیادہ ہو سکتا ہے۔ دونوں کو کبھی الجھاؤ نہیں۔</p>\n</div></div>\n<h2 id=\"cash-equity-actually-owning-the-business\">کیش ایکویٹی: اصل میں کاروبار کا مالک ہونا</h2>\n<p>آخری سب سے زیادہ مانوس آلہ آتا ہے، اور وہ جو بالکل بھی مشتق نہیں ہے۔ جب آپ خریدتے ہیں۔ <strong>نقد ایکوئٹی</strong>، آپ صرف حصہ خریدتے ہیں۔ آپ اس کی پوری قیمت ادا کرتے ہیں، اور آپ کمپنی کے ایک حصہ کے مالک بن جاتے ہیں۔ آپ پر کوئی میعاد ختم ہونے کی تاریخ نہیں ہے۔ آپ حصہ ایک دن یا تیس سال تک رکھ سکتے ہیں۔ چونکہ آپ کاروبار کا ایک حقیقی ٹکڑا رکھتے ہیں، آپ وصول کرتے ہیں۔ <strong>منافع</strong> جب کمپنی انہیں ادائیگی کرتی ہے اور آپ کو مل جاتا ہے۔ <strong>ووٹنگ کے حقوق</strong> کمپنی کے فیصلوں میں باقی تینوں میں سے کوئی بھی آپ کو یہ نہیں دیتا۔</p>\n<p>تجارت بند ہے کہ نقد ایکوئٹی ہے <strong>کوئی بلٹ ان لیوریج نہیں۔</strong>. شیئرز کے ذریعے RELIANCE کے 6,59,000 روپے کو کنٹرول کرنے کے لیے، آپ پورے 6,59,000 روپے ادا کرتے ہیں، معمولی مارجن نہیں۔ آپ اسے وسعت دینے کے لیے قرض لے سکتے ہیں، لیکن یہ ایک الگ قرض ہے جس کا آپ بندوبست کرتے ہیں، خود آلہ کی خصوصیت نہیں۔ حصص کا مالک خاندان کا سب سے پرسکون، صبر کرنے والا فرد ہے۔ دیکھنے کے لیے کوئی روزمرہ کا بندوبست نہیں، رول کرنے کا کوئی معاہدہ نہیں، کوئی گھڑی کی ٹک ٹک نہیں ہے۔ آپ کاروبار کے مالک ہیں اور آپ انتظار کرتے ہیں۔</p>\n<h2 id=\"the-four-side-by-side\">چاروں طرف سے</h2>\n<p>یہاں پورا خاندان ایک نظر میں ہے۔ اسے ہر قطار میں پڑھیں اور ہر آلے کی شخصیت واضح ہو جاتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>فیچر</th>\n<th>آگے</th>\n<th>مستقبل</th>\n<th>آپشن</th>\n<th>کیش ایکویٹی</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ملکیت</td>\n<td>کوئی نہیں، صرف ایک وعدہ</td>\n<td>کوئی نہیں، ایک معاہدہ</td>\n<td>کوئی نہیں، ایک حق</td>\n<td>حصہ کی مکمل ملکیت</td>\n</tr>\n<tr>\n<td>ختم</td>\n<td>ایک مقررہ تاریخ جو آپ دونوں منتخب کرتے ہیں۔</td>\n<td>ایک مقررہ تبادلے کی تاریخ</td>\n<td>ایک مقررہ تبادلے کی تاریخ</td>\n<td>کوئی نہیں، ہمیشہ کے لیے پکڑو</td>\n</tr>\n<tr>\n<td>فائدہ اٹھانا</td>\n<td>نجی معاہدے کے ذریعے</td>\n<td>بلٹ ان، پوسٹ صرف مارجن</td>\n<td>بلٹ ان، صرف پریمیم ادا کریں۔</td>\n<td>کوئی نہیں جب تک آپ قرض نہ لیں۔</td>\n</tr>\n<tr>\n<td>فرض</td>\n<td>دونوں فریقوں کو پابند کیا گیا۔</td>\n<td>دونوں فریقوں کو پابند کیا گیا۔</td>\n<td>خریدار کا انتخاب کرتا ہے، بیچنے والا پابند ہے۔</td>\n<td>کوئی نہیں۔</td>\n</tr>\n<tr>\n<td>تصفیہ</td>\n<td>نجی طور پر، آخر میں</td>\n<td>روزانہ، کلیئرنگ ہاؤس کی طرف سے</td>\n<td>ورزش یا ختم ہونے پر</td>\n<td>خریداری پر، ایک بار</td>\n</tr>\n<tr>\n<td>کاؤنٹر پارٹی خطرہ</td>\n<td>اعلیٰ، کوئی ضامن نہیں۔</td>\n<td>کلیئرنگ ہاؤس کے ذریعے ہٹا دیا گیا۔</td>\n<td>کلیئرنگ ہاؤس کے ذریعے ہٹا دیا گیا۔</td>\n<td>کوئی نہیں، آپ کا حصہ ہے۔</td>\n</tr>\n<tr>\n<td>کون استعمال کرتا ہے۔</td>\n<td>اپنی مرضی کے مطابق ضرورت کے ساتھ دو کاروبار</td>\n<td>تاجر سرمائے سے موثر سمت چاہتے ہیں۔</td>\n<td>طے شدہ خطرے کی شرط کے خواہاں تاجر</td>\n<td>طویل مدتی مالکان اور سرمایہ کار</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-four-instruments.png\" alt=\"RELIANCE پر اسی نقطہ نظر نے چار طریقوں کا اظہار کیا، نجی فارورڈ ہینڈ شیک سے لے کر ایکسچینج ٹریڈڈ فیوچر اور غیر متناسب آپشن سے لے کر مکمل طور پر شیئر کی ملکیت، ہر ایک اپنی ذمہ داری، لیوریج اور ایکسپائری کے اپنے توازن کے ساتھ۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>RELIANCE پر اسی نظریے نے چار طریقوں کا اظہار کیا، نجی فارورڈ ہینڈ شیک سے لے کر ایکسچینج ٹریڈڈ فیوچر کے ذریعے اور غیر متناسب آپشن سے مکمل طور پر شیئر کی ملکیت، ہر ایک اپنی ذمہ داری، لیوریج اور ایکسپائری کے اپنے توازن کے ساتھ۔</figcaption></figure>\n<h2 id=\"so-which-one-should-a-beginner-pick\">تو ابتدائی طور پر کون سا انتخاب کرنا چاہئے؟</h2>\n<p>ایماندارانہ جواب یہ ہے کہ صحیح ٹول مکمل طور پر اس بات پر منحصر ہے کہ آپ اصل میں کیا کرنے کی کوشش کر رہے ہیں، اور اپنے حقیقی مقصد کا نام دینا آدھی جنگ ہے۔</p>\n<p>اگر آپ چاہتے ہیں <strong>ایک کاروبار کا مالک</strong> اور اس کی طویل مدتی ترقی میں حصہ لیں، اس کا منافع جمع کریں اور ووٹ حاصل کریں، آپ اسے خریدیں۔ <strong>شیئرز</strong>. لڑائی کی کوئی میعاد نہیں، کوئی روزمرہ کی تصفیہ نہیں، آپ کو اڑا دینے کا کوئی فائدہ نہیں۔ یہ وہ جگہ ہے جہاں سے زیادہ تر لوگوں کو شروع کرنا چاہئے اور جہاں زیادہ تر دولت خاموشی سے بنائی جاتی ہے۔</p>\n<p>اگر آپ چاہتے ہیں کہ ایک <strong>طے شدہ خطرے کی شرط</strong>، جہاں آپ کو پہلے سے معلوم ہوتا ہے کہ آپ کے ساتھ سب سے زیادہ برا ہو سکتا ہے، آپ ایک خریدتے ہیں۔ <strong>اختیار</strong>. خریدار کے طور پر آپ کا زیادہ سے زیادہ نقصان پریمیم ہے، جس کا فیصلہ آپ کے داخل ہونے سے پہلے کیا جاتا ہے، اور یہ محدود کمی بالکل وہی ہے جس کی آپ ادائیگی کر رہے ہیں۔</p>\n<p>اگر آپ چاہتے ہیں کہ ایک <strong>خالص، سرمائے سے موثر دشاتمک پوزیشن</strong> بنیادی مائع پر، آپ استعمال کرتے ہیں a <strong>مستقبل</strong>. آپ پورے 6,59,000 روپے کے بجائے صرف ایک مارجن پوسٹ کرتے ہیں، اس لیے 24,000 کے قریب ایک RELIANCE لاٹ یا 65 کا ایک NIFTY لاٹ آپ کو نقد رقم کے ایک حصے کے لیے مکمل نمائش فراہم کرتا ہے۔ اس کے بدلے میں آپ دو چیزوں کو پوری طرح سے قبول کرتے ہیں: ذمہ داری، جس کا مطلب ہے کہ نقصان سے دور نہیں رہنا ہے، اور روزانہ تصفیہ، جس کا مطلب ہے کہ پوزیشن ہر روز آپ کے خلاف نقد رقم میں نشان زد ہوتی ہے۔ دریں اثنا، فارورڈ واقعی ایک مخصوص اپنی مرضی کی ضرورت کے ساتھ کاروبار کے لیے ایک ٹول ہے، نہ کہ اسکرین ٹریڈر کے لیے، کیونکہ آپ اس کے بجائے صرف اس کے کلینر کزن، مستقبل کے ساتھ تجارت کرتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کوئی بھی تجارت کرنے سے پہلے، اونچی آواز میں کہو کہ آپ اصل میں کیا چاہتے ہیں: کسی کاروبار کا مالک ہونا، خطرے سے دوچار شرط لگانا، یا لیوریجڈ سمتاتی نظریہ لینا۔ جواب سیدھا حصص، آپشن، یا مستقبل کی طرف اشارہ کرتا ہے۔ سب سے مہنگی غلطیاں غلط آلے تک پہنچنے سے شروع ہوتی ہیں۔</p>\n</div></div>\n<p>اب آپ جانتے ہیں کہ مستقبل اپنے خاندان میں کہاں بیٹھتا ہے اور جب آپ اسے منتخب کرتے ہیں تو آپ کیا قبول کرتے ہیں۔ اگلے باب میں ہم دو قسم کے لوگوں سے ملتے ہیں جو اس بازار کو زندہ رکھتے ہیں، ایک ہیجر جو خطرہ مول لینا چاہتا ہے اور قیاس آرائی کرنے والا جو اسے لینے میں خوش ہے، اور ہم دیکھتے ہیں کہ دونوں میں سے کوئی بھی دوسرے کے بغیر کیوں کام نہیں کر سکتا۔</p>\n","toc":[{"level":2,"text":"فارورڈ: ایک نجی، اپنی مرضی کے مطابق مصافحہ","id":"the-forward-a-private-custom-handshake"},{"level":2,"text":"مستقبل: آگے، صاف اور پولیس","id":"the-future-the-forward-cleaned-up-and-policed"},{"level":2,"text":"اختیار: حق، ذمہ داری نہیں۔","id":"the-option-a-right-not-an-obligation"},{"level":2,"text":"کیش ایکویٹی: اصل میں کاروبار کا مالک ہونا","id":"cash-equity-actually-owning-the-business"},{"level":2,"text":"چاروں طرف سے","id":"the-four-side-by-side"},{"level":2,"text":"تو ابتدائی طور پر کون سا انتخاب کرنا چاہئے؟","id":"so-which-one-should-a-beginner-pick"}],"imgCount":1,"hasContent":true},"3":{"html":"<p>یہ سوچنا پرکشش ہے کہ مستقبل کی منڈیوں کا خواب ان تاجروں کے لیے جوئے بازی کے اڈوں کے طور پر دیکھا گیا تھا جو سنسنی پسند کرتے ہیں۔ وہ نہیں تھے۔ فیوچرز ایک بہت ہی عملی مسئلے سے پیدا ہوئے جس کا سامنا عام پروڈیوسر اور خریداروں کو اسکرینز اور ٹریڈنگ ایپس کے وجود سے بہت پہلے کرنا پڑا۔ ایک کسان جو موسم بہار میں فصل لگاتا ہے اسے اندازہ نہیں ہوتا ہے کہ فصل کاٹنے پر اس کی کیا قیمت ہوگی۔ ایک مل جس کو اس فصل کی ضرورت ہوتی ہے اسے اندازہ نہیں ہوتا کہ اس کی قیمت کیا ہوگی۔ ان دونوں کو ایک ایسے جھولے کا سامنا کرنا پڑتا ہے جسے وہ کنٹرول نہیں کر سکتے، اور دونوں خوشی خوشی اس غیر یقینی صورتحال کو ایک معروف، مقررہ قیمت کے لیے دور کریں گے۔ فیوچر مارکیٹ ان کو بالکل ایسا کرنے دینے کے لیے موجود ہے، اور ایک بار جب آپ ان دو کرداروں کو سمجھ لیں جو وہاں ملتے ہیں، تو مارکیٹ کا پورا مقصد اپنی جگہ پر کلک کر دیتا ہے۔</p>\n<h2 id=\"the-hedger-wants-to-get-rid-of-a-risk\">ہیجر خطرے سے چھٹکارا حاصل کرنا چاہتا ہے۔</h2>\n<p>اے <strong>ہیجر</strong> وہ شخص ہے جو پہلے سے ہی خطرہ اٹھاتا ہے اور چاہتا ہے کہ اسے ختم کردیا جائے۔ خطرہ ایسی چیز نہیں ہے جس کی وہ تلاش کر رہے تھے۔ یہ ان کے حقیقی کاروبار یا ان کے حقیقی پورٹ فولیو سے منسلک ہوتا ہے، اور یہ انہیں رات کو جاگتا رہتا ہے۔</p>\n<p>ممبئی میں ایک فنڈ مینیجر کی تصویر بنائیں جس کے پاس کلائنٹس کے لیے ہندوستانی حصص کی ایک بڑی ٹوکری ہے۔ پورٹ فولیو صحت مند ہے، لیکن مینیجر خبروں کو پڑھتا ہے اور اسے خدشہ ہے کہ آنے والے ایونٹ کی وجہ سے اگلے مہینے میں مارکیٹ تیزی سے گر سکتی ہے۔ پورے پورٹ فولیو کو فروخت کرنا مہنگا، سست، اور ٹیکس اور لین دین کے اخراجات کو متحرک کرے گا۔ مینیجر بیچنا نہیں چاہتا۔ مینیجر تحفظ چاہتا ہے، بازار گرنے کی صورت میں دھچکے کو نرم کرنے کا ایک طریقہ، احتیاط سے بنائی گئی ہر چیز کو ختم کیے بغیر۔</p>\n<p>یہ ایک جملے میں ہیجر کی صورتحال ہے۔ وہ کسی چیز کے مالک ہیں، وہ اس کے خلاف اقدام سے ڈرتے ہیں، اور وہ اس خوف کو دور کرنا چاہتے ہیں۔ وہ مستقبل کی تجارت پر امیر بننے کی کوشش نہیں کر رہے ہیں۔ وہ پرسکون رہنے کی کوشش کر رہے ہیں۔ ایک ہیجر کے لیے، ایک فیوچر پوزیشن جو مارکیٹ کے بڑھنے پر تھوڑا سا کھو دیتی ہے بالکل قابل قبول ہے، کیونکہ اس خوش کن صورت میں ان کی حقیقی ہولڈنگ بہرحال بڑھ رہی ہے۔ مستقبل انشورنس ہے، منافع کا انجن نہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک ہیجر پہلے سے ہی اپنے حقیقی ہولڈنگز یا کاروبار سے خطرہ رکھتا ہے۔ وہ اس خطرے کو دور کرنے کے لیے مستقبل کا استعمال کرتے ہیں، ذہنی سکون کے بدلے میں معلوم قیمت کو قبول کرتے ہیں، منافع کا پیچھا کرنے کے لیے نہیں۔</p>\n</div></div>\n<h2 id=\"the-speculator-is-willing-to-take-that-risk-on\">قیاس آرائی کرنے والا یہ خطرہ مول لینے کو تیار ہے۔</h2>\n<p>اب دوسرے کردار سے ملو۔ اے <strong>قیاس آرائی کرنے والا</strong> بنیادی کاروباری پریشانی کا مالک نہیں ہے۔ ان کے پاس حفاظت کے لیے کوئی فصل نہیں ہے اور نہ ہی کوئی پورٹ فولیو ہے جو انھیں رات کو زندہ رکھے۔ ان کے پاس ایک نظریہ ہے کہ قیمت کہاں جارہی ہے اور اس نظریہ کے پیچھے سرمایہ لگانے کی خواہش ہے۔ قیاس آرائی کرنے والا بہت زیادہ خطرہ مول لینے میں خوش ہوتا ہے جو ہیجر بہانے کے لیے بے چین ہے، کیونکہ خطرہ وہیں ہوتا ہے جہاں منافع کا موقع رہتا ہے۔</p>\n<p>ایک قیاس آرائی کرنے والا جو یقین رکھتا ہے کہ آنے والے مہینے میں RELIANCE میں اضافہ ہوگا وہ 28 جولائی 2026 کی میعاد ختم ہونے کے لیے 1,320 روپے میں مستقبل خرید سکتا ہے۔ وہ جان بوجھ کر 500 حصص پر قیمت کے خطرے کو قبول کر رہے ہیں، تقریباً 6,59,000 روپے، فائدہ کی امید میں۔ اگر وہ صحیح ہیں اور اسٹاک چڑھتا ہے، تو وہ منافع بخش ہیں. اگر وہ غلط ہیں، تو وہ ہار جاتے ہیں، اور چونکہ مستقبل کا فائدہ اٹھایا جاتا ہے، یہ نقصان شدید ہو سکتا ہے۔ ہم پورے کورس میں اس بارے میں دو ٹوک رہیں گے۔ زیادہ تر قیاس آرائی کرنے والے وقت کے ساتھ جیت نہیں پاتے، اور فائدہ عام طور پر اس کی وجہ ہوتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>قیاس آرائی مارکیٹ میں کوئی خامی نہیں ہے، یہ ایک ضروری کردار ہے، لیکن یہ حقیقی طور پر خطرناک ہے۔ ایک قیاس آرائی کرنے والا جان بوجھ کر قیمت کا خطرہ مول لیتا ہے، اور فائدہ اٹھانے والے سٹے بازوں کی اکثریت طویل مدت میں پیسہ کھو دیتی ہے۔ شروع سے ہی اس کا احترام کریں۔</p>\n</div></div>\n<h2 id=\"the-two-sides-need-each-other\">دونوں فریقوں کو ایک دوسرے کی ضرورت ہے۔</h2>\n<p>یہاں خوبصورت حصہ ہے. ہیجر خطرے کو دور کرنا چاہتا ہے۔ قیاس آرائی کرنے والا خطرہ مول لینا چاہتا ہے۔ وہ ایک بہترین میچ ہیں، اور مستقبل کا معاہدہ ان کے درمیان مصافحہ ہے۔ جب پریشان فنڈ مینیجر کسی پورٹ فولیو کی حفاظت کے لیے انڈیکس فیوچر فروخت کرتا ہے، تو کسی کو دوسری طرف ان فیوچرز کو خریدنا پڑتا ہے۔ اکثر یہ کہ کوئی قیاس آرائی کرنے والا ہوتا ہے کہ مارکیٹ برقرار رہے گی یا بڑھے گی۔ خطرہ ختم نہیں ہوتا۔ یہ صرف اس شخص کے کندھوں سے منتقل ہوتا ہے جو اسے نہیں چاہتا تھا اس شخص کے کندھوں تک جس نے اسے منتخب کیا تھا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-hedger-vs-speculator.png\" alt=\"فیوچر کنٹریکٹ وہ پل ہے جو قیمت کے خطرے کو ہیجر سے منتقل کرتا ہے، جو اس سے چھٹکارا حاصل کرنا چاہتا ہے، قیاس آرائی کرنے والے کو، جو خوشی سے اسے منافع کے حصول میں قبول کرتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>فیوچر کنٹریکٹ وہ پل ہے جو قیمت کے خطرے کو ہیجر سے منتقل کرتا ہے، جو اس سے چھٹکارا حاصل کرنا چاہتا ہے، قیاس آرائی کرنے والے کو، جو خوشی سے اسے منافع کے حصول میں قبول کرتا ہے۔</figcaption></figure>\n<p>یہ منتقلی مستقبل کے وجود کی گہری وجہ ہے۔ ایسا نہیں ہے کہ ایک فریق ہوشیار ہے اور دوسرا بے وقوف ہے۔ وہ صرف مخالف چیزیں چاہتے ہیں، اور مارکیٹ انہیں تبدیل کرنے دیتی ہے۔ انشورنس کی طرح اس کے بارے میں سوچو. آپ اپنے گھر کے جلنے کا خطرہ مول لینے کے لیے بیمہ کنندہ کو ادائیگی کرتے ہیں۔ آپ ہیجر ہیں، فکر سے نجات پا کر خوشی ہوئی۔ بیمہ کنندہ قیاس آرائی کرنے والا ہے، اس طرح کے بہت سے خطرات کو قبول کرتا ہے کیونکہ، صحیح قیمت پر، کاروبار وقت کے ساتھ منافع بخش ہوتا ہے۔ کسی بھی فریق کو دھوکہ نہیں دیا جا رہا۔ دونوں کو وہی ملتا ہے جس کے لیے وہ آئے تھے۔</p>\n<p>یہ دونوں کرداروں کو ساتھ ساتھ رکھنے میں مدد کرتا ہے، کیونکہ ایک ہی RELIANCE معاہدہ تاجر کے مقصد پر مکمل طور پر انحصار کرتے ہوئے دونوں میں سے کسی ایک کی خدمت کرسکتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>سوال</th>\n<th>ہیجر</th>\n<th>قیاس کرنے والا</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>کیا وہ پہلے ہی خطرے کے مالک ہیں؟</td>\n<td>ہاں، حقیقی ہولڈنگز سے</td>\n<td>نہیں، وہ اسے ڈھونڈتے ہیں۔</td>\n</tr>\n<tr>\n<td>وہ کیا چاہتے ہیں؟</td>\n<td>بے یقینی کو دور کرنے کے لیے</td>\n<td>منافع کا موقع</td>\n</tr>\n<tr>\n<td>ان کا مستقبل کیا ہے؟</td>\n<td>ایک اقدام کے خلاف انشورنس</td>\n<td>ایک اقدام پر شرط</td>\n</tr>\n<tr>\n<td>کیا وہ تھوڑا کھو کر خوش ہیں؟</td>\n<td>ہاں، اگر ان کی ہولڈنگز کو فائدہ ہوتا ہے۔</td>\n<td>نہیں، نقصان ایک نقصان ہے</td>\n</tr>\n<tr>\n<td>عام ہندوستانی مثال</td>\n<td>پورٹ فولیو کی حفاظت کرنے والا فنڈ</td>\n<td>ایک تاجر RELIANCE پر ایک نظریہ کی حمایت کر رہا ہے۔</td>\n</tr>\n</tbody></table>\n<p>دونوں کالم متضاد ہیں، اور یہی وجہ ہے کہ معاہدہ ہو سکتا ہے۔ اگر دونوں تاجر ایک ہی چیز چاہتے ہیں تو دوسری طرف لینے والا کوئی نہیں ہوگا۔ مارکیٹ صاف ہو جاتی ہے کیونکہ ان کے مقاصد مختلف سمتوں کی طرف اشارہ کرتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک فنڈ مینیجر کو ایک ماہ کی کمی کا خدشہ ہے اور وہ پورٹ فولیو کی حفاظت کے لیے NIFTY فیوچر فروخت کرتا ہے۔ ایک تاجر جو مارکیٹ کے بڑھنے کی توقع رکھتا ہے وہی مستقبل خریدتا ہے۔ اگر مارکیٹ گرتی ہے تو مینیجر کا فیوچر فائدہ اٹھاتا ہے اور پورٹ فولیو کے نقصان کو کم کرتا ہے، جبکہ تاجر کو نقصان ہوتا ہے۔ اگر مارکیٹ میں اضافہ ہوتا ہے، تو تاجر کا منافع ہوتا ہے اور مینیجر اپنے منافع میں سے تھوڑا سا واپس انشورنس کی لاگت کے طور پر دیتا ہے۔ ہر فریق کو معلوم تھا کہ معاہدہ ہو رہا ہے۔</p>\n</div></div>\n<h2 id=\"liquidity-and-price-discovery-the-quiet-gifts\">لیکویڈیٹی اور قیمت کی دریافت، خاموش تحائف</h2>\n<p>جب ہیجرز اور قیاس آرائی کرنے والے بڑی تعداد میں ظاہر ہوتے ہیں، تو دو قیمتی چیزیں تقریباً ایک ضمنی اثر کے طور پر ظاہر ہوتی ہیں، اور دونوں ہی مارکیٹ کو سب کے لیے بہتر بناتے ہیں، بشمول ابتدائی افراد۔</p>\n<p>پہلا ہے۔ <strong>لیکویڈیٹی</strong>. لیکویڈیٹی کا مطلب ہے کہ آپ قیمت کو زیادہ بڑھائے بغیر جلدی سے خرید یا فروخت کر سکتے ہیں، کیونکہ دوسری طرف ہمیشہ بہت سارے رضامند تاجر ہوتے ہیں۔ صرف ہیجرز سے بھرا بازار یک طرفہ اور پتلا ہوگا، جس میں ہر کوئی اسی گھبراہٹ کے وقت تحفظ بیچنا چاہتا ہے۔ قیاس آرائی کرنے والے خلا کو پُر کرتے ہیں اور تجارت کے لیے تیار رہتے ہیں، اس لیے آرڈرز آسانی سے مل جاتے ہیں۔ آپ کے لیے، لیکویڈیٹی سخت قیمتوں کے طور پر ظاہر ہوتی ہے اور یہ جان کر سکون ملتا ہے کہ جب آپ کو ضرورت ہو تو آپ کسی پوزیشن کو ختم کر سکتے ہیں۔</p>\n<p>دوسرا تحفہ ہے۔ <strong>قیمت کی دریافت</strong>. چونکہ بہت سارے باخبر شرکاء ہر اس چیز کی بنیاد پر خرید و فروخت کر رہے ہیں جو وہ جانتے ہیں اور اس کی توقع کرتے ہیں، فیوچر کی قیمت مستقبل کے بارے میں ایک مسلسل اپ ڈیٹ، اجتماعی بہترین اندازہ بن جاتی ہے۔ جب آپ دیکھتے ہیں کہ RELIANCE مستقبل کہاں ٹریڈ کر رہا ہے، تو آپ ہزاروں ہیجرز اور قیاس کرنے والوں کی مشترکہ رائے پڑھ رہے ہوں گے کہ اسٹاک کہاں جا رہا ہے۔ اس واحد نمبر میں بہت زیادہ معلومات ہوتی ہیں، اور یہ بازار دیکھنے والے ہر شخص کے لیے آزادانہ طور پر دستیاب ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>مستقبل کی قیمت اکثر ایسی ہوتی ہے جہاں نئی ​​معلومات پہلے ظاہر ہوتی ہیں۔ چونکہ فیوچر تیزی سے تجارت کرتے ہیں اور فائدہ اٹھاتے ہیں، اس لیے تاجر اکثر وہاں کی خبروں پر عمل کرتے ہیں اس سے پہلے کہ کیش مارکیٹ مکمل رد عمل ظاہر کرے، یہی وجہ ہے کہ تجزیہ کار انڈیکس فیوچر کو اتنی قریب سے دیکھتے ہیں۔</p>\n</div></div>\n<h2 id=\"where-you-fit-in\">جہاں آپ فٹ ہیں۔</h2>\n<p>جیسا کہ آپ سیکھتے ہیں، آپ ممکنہ طور پر ایک چھوٹے سے قیاس آرائی کرنے والے کے طور پر زندگی کا آغاز کریں گے، ایک نظریہ رکھتے ہوئے اور فائدہ کے موقع کے لیے خطرہ قبول کریں گے۔ اس میں کوئی حرج نہیں ہے، بشرطیکہ آپ مشکلات کے بارے میں ایماندار ہوں اور اپنے نقصانات کو کنٹرول کرنے میں بے رحم ہوں۔ بعد میں کورس میں آپ دیکھیں گے کہ اسی آلے کو ہیجر کے طریقے سے کس طرح استعمال کیا جا سکتا ہے، کسی چیز کی حفاظت کے لیے جو آپ کے پاس ہے نہ کہ سمت پر جوا کھیلنے کے۔ فیوچرز کے بارے میں قابل ذکر بات یہ ہے کہ ایک ہی RELIANCE معاہدہ ایک تاجر کے ہاتھ میں احتیاط کا اور دوسرے کے لیے جارحیت کا آلہ ہوسکتا ہے۔ معاہدے کی کوئی پرواہ نہیں ہے۔ آپ کا ارادہ اور آپ کا رسک کنٹرول یہ فیصلہ کرتا ہے کہ آلہ آپ کی خدمت کرتا ہے یا آپ کو ڈوبتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اس سے پہلے کہ آپ حقیقی رقم کا خطرہ مول لیں، سینڈ باکس ٹریڈنگ میں دونوں کرداروں کی مشق کریں ( OpenAlgo میں تجزیہ کار وضع)۔ RELIANCE فیوچرز میں ایک قیاس آرائی پر مبنی لانگ رکھیں، پھر ہولڈنگ کے خلاف حفاظتی شارٹ آزمائیں، اور دیکھیں کہ معاہدہ ایک جیسا ہونے کے باوجود دونوں کتنا مختلف محسوس کرتے ہیں۔</p>\n</div></div>\n<p>ٹیک وے آسان ہے اور اس کے بعد آنے والے ہر باب میں لے جانے کے قابل ہے۔ فیوچر جواریوں کے لیے ایجاد کردہ کھیل نہیں ہے۔ یہ ایک ایسا بازار ہے جہاں ایک شخص کا ناپسندیدہ خطرہ دوسرے شخص کا منتخب کردہ موقع بن جاتا ہے۔ ہیجر بہتر سوتا ہے۔ قیاس آرائی کرنے والے کو منافع پر شاٹ مل جاتا ہے۔ اور ہم میں سے باقی لوگوں کو ان دو اجنبیوں کو ملنے دینے کے انعام کے طور پر مائع بازار اور ایماندار قیمتیں ملتی ہیں۔ اگلے باب میں ہم کنٹریکٹ کو خود کھولتے ہیں اور اس کی تصریحات کو سطر سے پڑھتے ہیں، تاکہ آپ کو بخوبی معلوم ہو جائے کہ آپ خریدنے پر کلک کرنے سے پہلے کس چیز سے اتفاق کر رہے ہیں۔</p>\n","toc":[{"level":2,"text":"ہیجر خطرے سے چھٹکارا حاصل کرنا چاہتا ہے۔","id":"the-hedger-wants-to-get-rid-of-a-risk"},{"level":2,"text":"قیاس آرائی کرنے والا یہ خطرہ مول لینے کو تیار ہے۔","id":"the-speculator-is-willing-to-take-that-risk-on"},{"level":2,"text":"دونوں فریقوں کو ایک دوسرے کی ضرورت ہے۔","id":"the-two-sides-need-each-other"},{"level":2,"text":"لیکویڈیٹی اور قیمت کی دریافت، خاموش تحائف","id":"liquidity-and-price-discovery-the-quiet-gifts"},{"level":2,"text":"جہاں آپ فٹ ہیں۔","id":"where-you-fit-in"}],"imgCount":1,"hasContent":true},"4":{"html":"<p>جب آپ RELIANCE کا حصہ خریدتے ہیں، تو آپ ہر چیز کا فیصلہ کرتے ہیں۔ آپ منتخب کرتے ہیں کہ کتنے حصص ہیں، آپ قیمت ادا کرتے ہیں، اور آپ ایک حصہ یا دس ہزار خرید سکتے ہیں۔ مستقبل کا معاہدہ ان میں سے زیادہ تر انتخاب کو آپ سے دور کر دیتا ہے، اور یہ جان بوجھ کر کیا جاتا ہے۔ ہر مستقبل ہے۔ <strong>معیاری</strong>، یعنی ایکسچینج نے آپ کے آرڈر دینے سے پہلے ہی مقدار، میعاد ختم ہونے اور قیمت کا سب سے چھوٹا مرحلہ طے کر لیا ہے۔ پہلے تو یہ پابندی لگتی ہے۔ حقیقت میں یہ وہی چیز ہے جو مارکیٹ کو مائع اور منصفانہ بناتی ہے، کیونکہ ہر کوئی ایک جیسی، اچھی طرح سے طے شدہ مصنوعات کی تجارت کر رہا ہے۔ اس باب میں ہم ایک معاہدے کو پڑھتے ہیں جس طرح سے ایک محتاط تاجر کرتا ہے، قیاس کے لحاظ سے، جب تک کہ آرڈر اسکرین پر کوئی بھی چیز حیران کن نہ ہو۔</p>\n<h2 id=\"lot-size-the-quantity-is-fixed-for-you\">لاٹ سائز، مقدار آپ کے لیے مقرر ہے۔</h2>\n<p>دی <strong>بہت سائز</strong> ایک فیوچر کنٹریکٹ میں یونٹس کی مقررہ تعداد ہے۔ آپ آدھی لاٹ یا حسب ضرورت رقم نہیں خرید سکتے۔ آپ پوری لاٹ میں تجارت کرتے ہیں، اور ایکسچینج ہر ایک کے لیے لاٹ سیٹ کرتا ہے۔ RELIANCE کے لیے لاٹ 500 شیئرز ہے، اس لیے ایک معاہدہ ہمیشہ اسٹاک کے بالکل 500 شیئرز کی نمائندگی کرتا ہے، نہ زیادہ اور نہ کم۔</p>\n<p>لاٹ سائز فلو سے سب سے اہم نمبر جو ایک ابتدائی حساب کرنا سیکھ سکتا ہے، <strong>معاہدے کی قیمت</strong>. یہ صرف لاٹ سائز ہے جو بنیادی قیمت سے ضرب کیا جاتا ہے۔ RELIANCE کے ساتھ 1,318 روپے کے قریب، 500 شیئرز کا ایک معاہدہ تقریباً 6,59,000 روپے کا ہے۔ یہ وہ حقیقی معاشی نمائش ہے جسے آپ ایک لاٹ کے ساتھ لیتے ہیں، حالانکہ، جیسا کہ ہم مارجن کے باب میں دیکھیں گے، آپ اس رقم کے قریب کہیں بھی ادائیگی نہیں کرتے ہیں۔ معاہدے کی قیمت جاننا آپ کو اس بارے میں ایماندار رکھتا ہے کہ کتنی رقم حقیقی طور پر خطرے میں ہے۔</p>\n<p>مختلف بنیادی چیزوں میں بہت مختلف لاٹ ہوتے ہیں، اور ایکسچینج ان کا سائز اس طرح بناتا ہے کہ ایک لاٹ ایک معنی خیز لیکن مضحکہ خیز رقم نہیں ہے۔ یہاں سب سے زیادہ تجارت کیے جانے والے ہندوستانی معاہدوں کے لیے موجودہ لاٹ ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>زیرِ نظر</th>\n<th>لاٹ سائز</th>\n<th>فی لاٹ تقریباً کنٹرول کرتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>NIFTY</td>\n<td>65</td>\n<td>انڈیکس کا ایک بڑا ٹکڑا</td>\n</tr>\n<tr>\n<td>BANKNIFTY</td>\n<td>30</td>\n<td>بینکنگ انڈیکس کا ایک بڑا ٹکڑا</td>\n</tr>\n<tr>\n<td>FINNIFTY</td>\n<td>60</td>\n<td>مالیاتی خدمات انڈیکس کا ایک ٹکڑا</td>\n</tr>\n<tr>\n<td>MIDCPNIFTY</td>\n<td>120</td>\n<td>مڈ کیپ انڈیکس کا ایک ٹکڑا</td>\n</tr>\n<tr>\n<td>RELIANCE</td>\n<td>500</td>\n<td>تقریباً 6,59,000 روپے کا اسٹاک</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>لاٹ سائز ایکسچینج کے ذریعہ طے کیا جاتا ہے اور کبھی بھی اختیاری نہیں ہوتا ہے۔ معاہدے کی قیمت بنیادی قیمت کے لاٹ سائز کے برابر ہے۔ ایک RELIANCE لاٹ کے لیے، 500 شیئرز گنا تقریباً 1,318 روپے تقریباً 6,59,000 روپے حقیقی نمائش کے ہیں۔</p>\n</div></div>\n<p>نوٹ کریں کہ انڈیکس لاٹ روپے کے بجائے انڈیکس یونٹس میں درج ہیں، کیونکہ انڈیکس ایسی چیز نہیں ہے جسے آپ اپنے ہاتھ میں پکڑ سکتے ہیں۔ NIFTY لاٹ کی روپے کی قیمت انڈیکس کی سطح سے ضرب کردہ 65 کی لاٹ ہے۔ اصول RELIANCE سے مماثل ہے۔ بہت سائز کی قیمت آپ کو نمائش دیتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-contract-specs.png\" alt=\"ایک کنٹریکٹ تصریح کارڈ ایک نظر میں مستقبل کی مقررہ شرائط، بنیادی، لاٹ سائز، ایکسپائری ڈیٹ، اور ٹک سائز کو پیش کرتا ہے، اس لیے ہر تاجر بالکل اسی معیاری مصنوعات میں ڈیل کر رہا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک کنٹریکٹ تصریح کارڈ ایک نظر میں مستقبل کی مقررہ شرائط، بنیادی، لاٹ سائز، ایکسپائری ڈیٹ، اور ٹک سائز کو پیش کرتا ہے، اس لیے ہر تاجر بالکل اسی معیاری مصنوعات میں ڈیل کر رہا ہے۔</figcaption></figure>\n<h2 id=\"expiry-the-contract-has-a-deadline\">میعاد ختم، معاہدے کی آخری تاریخ ہے۔</h2>\n<p>ایک حصہ کے برعکس، جسے آپ ہمیشہ کے لیے رکھ سکتے ہیں، ہر مستقبل ایک کے ساتھ آتا ہے۔ <strong>میعاد ختم</strong>، معاہدہ کا وجود ختم ہونے کی تاریخ۔ میعاد ختم ہونے کے بعد معاہدہ طے پا جاتا ہے اور ختم ہو جاتا ہے، اور اگر آپ کوئی پوزیشن برقرار رکھنا چاہتے ہیں تو آپ کو بعد کے معاہدے پر جانا ہو گا، اس عمل کا احاطہ ہم رول اوور کے بعد کے باب میں کرتے ہیں۔</p>\n<p>ہندوستانی مستقبل دو وسیع تالوں میں آتے ہیں۔</p>\n<ul>\n<li><strong>ماہانہ</strong> معاہدے، جو سنگل اسٹاک فیوچر جیسے کہ RELIANCE کی پیروی کرتے ہیں۔ NSE فیوچر اینڈ آپشنز سیگمنٹ (NFO) پر، ماہانہ معاہدہ طے پاتا ہے۔ <strong>گزشتہ منگل</strong> میعاد ختم ہونے کے مہینے کے، لہذا ہماری مثالوں میں RELIANCE معاہدہ ہماری اینکر کی تاریخ سے تقریباً 32 دن بعد منگل 28 جولائی 2026 کو ختم ہو رہا ہے۔ قریب کا مہینہ، اگلا مہینہ، اور دور مہینہ کسی بھی وقت دستیاب ہے۔</li>\n<li><strong>ہفتہ وار</strong> معاہدوں، جو سب سے زیادہ فعال انڈیکس (فی الحال NIFTY ہفتہ وار) ماہانہ کے علاوہ پیش کرتا ہے، جو تاجروں کو تجارت کے لیے مختصر تاریخ کی میعاد ختم ہونے کی مستقل فراہمی فراہم کرتا ہے۔ یہ ہفتہ وار انڈیکس معاہدے بھی a پر طے پاتے ہیں۔ <strong>منگل</strong>.</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اپنے تصفیے کے دن کو جانیں، کیونکہ یہ بدل گیا ہے اور یہ تبادلے کے لحاظ سے مختلف ہے۔ NSE مشتقات (NFO سیگمنٹ)، جو NIFTY، BANKNIFTY اور سنگل اسٹاک فیوچر جیسے RELIANCE کا احاطہ کرتا ہے، اب طے پاتا ہے۔ <strong>منگل</strong>. BSE مشتقات (BFO سیگمنٹ)، جیسے SENSEX، طے پاتے ہیں <strong>جمعرات</strong>. اس کورس میں ہر مثال NSE کا آلہ استعمال کرتی ہے، اس لیے ہماری ایکسپائری منگل کو ہوتی ہے۔</p>\n</div></div>\n<p>ایک ابتدائی کے لیے عملی مشورہ سادہ ہے۔ قریب کے مہینے میں تجارت کریں۔ قریب کے مہینے کا معاہدہ وہ ہے جہاں حجم کا بڑا حصہ اور سخت ترین قیمتیں رہتی ہیں۔ دور مہینوں کے معاہدے موجود ہیں، لیکن ان کی بہت کم تجارت کی جاتی ہے، اور ان میں گھومنے والے کو اکثر قیمتیں اور باہر نکلنے میں پریشانی کا سامنا کرنا پڑتا ہے۔ جب ہم لیکویڈیٹی پر بات کریں گے تو ہم اس پر واپس جائیں گے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مستقبل خریدنے اور پکڑنے کا آلہ نہیں ہے۔ اس کی میعاد ختم ہو جاتی ہے۔ اگر آپ ایک کھلی پوزیشن کو ایکسپائری میں بھول جاتے ہیں تو یہ خود بخود طے ہو جائے گا، ممکنہ طور پر اسٹاک کے لیے فزیکل ڈیلیوری جیسے کہ RELIANCE، جس کا شاذ و نادر ہی کوئی چھوٹا تاجر ارادہ کرتا ہے۔ ہمیشہ اپنی میعاد ختم ہونے کی تاریخ جانیں۔</p>\n</div></div>\n<h2 id=\"tick-size-the-smallest-legal-step\">ٹک کا سائز، سب سے چھوٹا قانونی قدم</h2>\n<p>دی <strong>ٹک سائز</strong> وہ کم از کم رقم ہے جس کے ذریعے معاہدے کی قیمت تبدیل ہو سکتی ہے۔ زیادہ تر ہندوستانی اسٹاک کے لیے، بشمول RELIANCE، ٹک 0.05 روپے ہے۔ اس کا مطلب ہے کہ قیمت 1,318.00 روپے سے 1,318.05 روپے سے 1,318.10 روپے تک جا سکتی ہے، لیکن 1,318.03 روپے جیسی قیمت کے درمیان کبھی نہیں۔ ایکسچینج پوری مارکیٹ کو اس گرڈ میں لے جاتا ہے تاکہ قیمتیں صاف رہیں اور آرڈرز کو بغیر کسی ابہام کے ملایا جا سکے۔</p>\n<p>ٹک پہلے ظاہر ہونے سے زیادہ اہمیت رکھتا ہے، کیونکہ جب آپ لاٹ سے ضرب لگاتے ہیں تو ہر ٹک اصلی رقم ہوتی ہے۔ 500 حصص کے ایک RELIANCE لاٹ پر 0.05 روپے کا ایک ٹک 0.05 گنا 500 روپے ہے، جو کہ 25 روپے ہے۔ لہذا مستقبل میں سب سے چھوٹی ممکنہ جھلملاہٹ آپ کی پوزیشن کے لیے 25 روپے ہے۔ ایک پورے روپے کی چال، بیس ٹک، 500 روپے ہے۔ یہ وہی ون ٹو ون رشتہ ہے جس پر ہم بار بار جھکیں گے۔ ہر 1 روپے میں بنیادی چالیں 500 روپے فی RELIANCE لاٹ ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE فیوچرز میں 0.05 روپے کا اضافہ ہوا۔ بہت سارے 500 شیئرز پر اس سنگل ٹک کی قیمت 25 روپے ہے، کیونکہ 0.05 گنا 500 25 ہے۔ اگر قیمت دس ٹک پر چڑھتی ہے، تو یہ 0.50 روپے ہے، اور آپ کی لاٹ کو 250 روپے کا فائدہ ہوتا ہے۔ ٹک اسکرین پر چھوٹا لگتا ہے لیکن یہ لاٹ کے سائز کے ساتھ سیدھا ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"the-symbol-reading-the-contract-s-name\">علامت، معاہدے کا نام پڑھنا</h2>\n<p>ہر کنٹریکٹ میں مشین کے ذریعے پڑھنے کے قابل قطعی نام ہوتا ہے، اور اسے پڑھنا سیکھنا بہت سی ابتدائی الجھنوں کو دور کرتا ہے۔ OpenAlgo پر مستقبل کے لیے فارمیٹ بنیادی علامت ہے، پھر دن، مہینہ اور سال کے طور پر لکھا گیا ایکسپائری، پھر حروف FUT۔ ہمارا کام شدہ RELIANCE معاہدہ اس لیے RELIANCE28JUL26FUT لکھا گیا ہے۔</p>\n<p>اسے بائیں سے دائیں پڑھیں۔</p>\n<ul>\n<li><strong>RELIANCE</strong> بنیادی، بنیادی علامت ہے۔</li>\n<li><strong>28 جولائی26</strong> ایکسپائری، دن، تین حرفی مہینہ اور دو ہندسوں کا سال ہے۔</li>\n<li><strong>FUT</strong> اسے مستقبل کے معاہدے کے طور پر نشان زد کرتا ہے، جیسا کہ ایک آپشن کے برعکس، جس میں اسٹرائیک پرائس اور CE یا PE کے حروف ہوں گے۔</li>\n</ul>\n<p>ایک بار جب آپ علامت کو ڈی کوڈ کر لیتے ہیں، تو آپ کبھی بھی غلطی سے غلط مہینے کی تجارت نہیں کر سکتے یا کسی آپشن کے ساتھ مستقبل کو الجھ نہیں سکتے، کیونکہ نام ہی آپ کو بتاتا ہے کہ یہ کیا ہے۔ یہ آپ کے حق میں کام کرنے والی معیاری کاری ہے۔ ایک ہی RELIANCE مستقبل کا ہر اسکرین پر، ہر تاجر کے لیے، ہر جگہ ایک ہی نام ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ OpenAlgo میں کوئی معاہدہ لوڈ کرتے ہیں، تو آرڈر دینے سے پہلے پوری علامت کو بلند آواز میں پڑھیں۔ بیس، ایکسپائری مہینے، اور FUT ٹیگ کی تصدیق کریں۔ یہ تین سیکنڈ کی عادت حادثاتی طور پر دور مہینہ یا آپشن خریدنے کی کلاسک ابتدائی غلطی کو روکتی ہے۔</p>\n</div></div>\n<h2 id=\"why-standardisation-builds-a-liquid-market\">معیاری کاری ایک مائع مارکیٹ کیوں بناتی ہے۔</h2>\n<p>پیچھے ہٹیں اور دیکھیں کہ یہ تمام طے شدہ ڈھانچہ کیا حاصل کرتا ہے۔ کیونکہ لاٹ، ایکسپائری اور ٹک ہر شریک کے لیے یکساں ہیں، ایک شہر میں خریدار اور دوسرے شہر میں بیچنے والے بالکل ایک ہی آلے کی تجارت کر رہے ہیں۔ مقدار یا معیار پر کوئی ہنگامہ نہیں ہے۔ معاہدہ لفظی طور پر ایک معلوم مقدار ہے۔ یہی یکسانیت ہزاروں آرڈرز کو ایک گہری، مائع مارکیٹ میں جمع کرنے دیتی ہے جہاں آپ مناسب قیمتوں پر تیزی سے داخل اور باہر نکل سکتے ہیں۔</p>\n<p>اس کا موازنہ پہلے باب کے نانبائی اور کسان سے کریں، جنہیں اپنی نجی ڈیل کی ہر ٹرم پر آمنے سامنے بات چیت کرنی تھی۔ نجی معاہدہ لچکدار لیکن غیر قانونی ہے۔ آپ اپنی مرضی کے مطابق مصافحہ کا آدھا حصہ کسی اجنبی کو آسانی سے نہیں بیچ سکتے۔ ایک معیاری ایکسچینج ٹریڈڈ مستقبل مقصد کے مطابق اس لچک کو دور کر دیتا ہے، اور بدلے میں آپ ایک ایسی مارکیٹ حاصل کرتے ہیں جہاں آپ کی پوزیشن سیکنڈوں میں بند ہو سکتی ہے کیونکہ دوسری طرف والا شخص بالکل وہی معیاری چیز خرید رہا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>معیاری کاری ہر مائع فیوچر مارکیٹ کا پوشیدہ انجن ہے۔ ایکسچینج بورنگ تفصیلات، لاٹ، ایکسپائری اور ٹک کو ٹھیک ٹھیک ٹھیک کرتا ہے تاکہ تاجروں کے لیے بحث کرنے کے لیے صرف دلچسپ تفصیل، قیمت ہی رہ جائے۔</p>\n</div></div>\n<p>اب آپ جانتے ہیں کہ ایک روپیہ کا خطرہ مول لینے سے پہلے کسی معاہدے کو کیسے پڑھنا ہے۔ اپنی حقیقی نمائش تلاش کرنے کے لیے لاٹ چیک کریں، ایکسپائری چیک کریں تاکہ ڈیڈ لائن آپ پر کبھی حملہ نہ کرے، یہ جاننے کے لیے ٹک چیک کریں کہ قیمت کے ہر قدم کی کیا قیمت ہے، اور علامت کو پڑھیں تاکہ آپ ٹھیک ٹھیک ٹھیک اسی معاہدے کی تجارت کریں جس کا آپ ارادہ رکھتے ہیں۔ اگلے باب میں ہم اس خصوصیت کا سامنا کریں گے جو مستقبل کو سنسنی خیز اور خطرناک دونوں بناتا ہے، یہ حقیقت کہ آپ RELIANCE کے تمام 6,59,000 روپے کو کنٹرول کرتے ہیں جبکہ اس کا صرف ایک ٹکڑا مارجن کے طور پر پوسٹ کرتے ہیں۔</p>\n","toc":[{"level":2,"text":"لاٹ سائز، مقدار آپ کے لیے مقرر ہے۔","id":"lot-size-the-quantity-is-fixed-for-you"},{"level":2,"text":"میعاد ختم، معاہدے کی آخری تاریخ ہے۔","id":"expiry-the-contract-has-a-deadline"},{"level":2,"text":"ٹک کا سائز، سب سے چھوٹا قانونی قدم","id":"tick-size-the-smallest-legal-step"},{"level":2,"text":"علامت، معاہدے کا نام پڑھنا","id":"the-symbol-reading-the-contract-s-name"},{"level":2,"text":"معیاری کاری ایک مائع مارکیٹ کیوں بناتی ہے۔","id":"why-standardisation-builds-a-liquid-market"}],"imgCount":1,"hasContent":true},"5":{"html":"<p>آپ مستقبل میں سے ایک لاٹ خریدنے کا فیصلہ کرتے ہیں۔ آپ خرید کے بٹن کو تھپتھپاتے ہیں، اور ایک سیکنڈ کے ایک حصے کے بعد آپ 500 شیئرز کے مالک ہوتے ہیں۔ ایک ابتدائی کے لیے یہ ایک وینڈنگ مشین پر بٹن دبانے کی طرح محسوس ہوتا ہے۔ یہ نہیں ہے. اس ایک نل کے پیچھے ایک مصروف، منظم نیلامی بیٹھتی ہے جہاں آپ کا آرڈر دوسری طرف کے ایک حقیقی شخص کے خلاف، ایک حقیقی قیمت پر، ایسے اصولوں کے تحت ملتا ہے جو کبھی نہیں جھکتے ہیں۔ ایک بار جب آپ سمجھ جاتے ہیں کہ اس لمحے میں کیا ہوتا ہے، آرڈر اسکرین ڈرانا بند کر دیتی ہے اور ایک ٹول بن جاتی ہے جسے آپ ارادے سے استعمال کر سکتے ہیں۔ یہ باب ڈھکن کھولتا ہے اور آپ کو مشینری دکھاتا ہے۔</p>\n<h2 id=\"the-order-book-where-buyers-and-sellers-meet\">آرڈر بک، جہاں خریدار اور بیچنے والے ملتے ہیں۔</h2>\n<p>ہر تجارتی معاہدے کے دل میں ہے <strong>آرڈر بک</strong>, ہر ایک جو خریدنا چاہتا ہے اور ہر وہ شخص جو بیچنا چاہتا ہے، قیمت کے لحاظ سے ترتیب دی گئی فہرست کو مسلسل اپ ڈیٹ کرتی ہے۔ اس کے دو رخ ہیں۔</p>\n<ul>\n<li>دی <strong>بولی</strong> طرف خریداروں کو رکھتا ہے۔ ہر بولی ایک قیمت ہوتی ہے جو کوئی ادا کرنے کو تیار ہوتا ہے، اور وہ مقدار جو وہ چاہتے ہیں۔ سب سے زیادہ بولی ہے <strong>بہترین بولی</strong>, سب سے زیادہ کوئی بھی فی الحال ادائیگی کرنے کی پیشکش کر رہا ہے۔</li>\n<li>دی <strong>پوچھنا</strong> طرف، جسے پیشکش بھی کہا جاتا ہے، بیچنے والوں کو رکھتا ہے۔ ہر سوال ایک قیمت ہے جس پر کوئی فروخت کرنے کو تیار ہے۔ سب سے کم سوال ہے <strong>بہترین پوچھنا</strong>، سب سے سستا کوئی بھی اس وقت فروخت کرنے کو تیار ہے۔</li>\n</ul>\n<p>1,318 روپے کے قریب RELIANCE مستقبل کی تصویر بنائیں۔ بہترین بولی دو لاٹوں کے لیے 1,317.95 روپے ہو سکتی ہے، اور بہترین بولی تین لاٹوں کے لیے 1,318.05 روپے ہو سکتی ہے۔ ان کے درمیان چھوٹا سا فرق، یہاں 0.10 روپے، ہے۔ <strong>پھیلاؤ</strong>، سب سے زیادہ خریدار اور سب سے کم بیچنے والے کے درمیان نو مینز لینڈ۔ یاد رکھیں کہ 500 حصص کی ایک لاٹ پر 0.05 روپے کی ایک ٹک کی قیمت 25 روپے ہے، تو یہ اسپریڈ دو ٹک ہے، تقریباً 50 روپے۔ بعد کا ایک باب ایک حقیقی قیمت کے طور پر پھیلاؤ کا مطالعہ کرتا ہے۔ ابھی کے لیے اسے صرف قدرتی خلا کے طور پر دیکھیں جو آرڈر بک ہمیشہ رکھتا ہے۔</p>\n<p>بہترین بولی کے نیچے اور تھوڑی بدتر قیمتوں پر بیٹھ کر مزید آرڈر مانگیں، طلب اور رسد کے انتظار کی سیڑھی میں سجا دیے گئے۔ جب آپ آرڈر بھیجتے ہیں، تو آپ اس کتاب میں قدم رکھتے ہیں، یا تو قطار میں انتظار کرنے کے لیے یا اس کے پار پہنچنے اور اس میں پہلے سے موجود کسی کے خلاف تجارت کرنے کے لیے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-order-book.png\" alt=\"آرڈر بک خریداروں کو بولی کی طرف اور بیچنے والوں کو اسپریڈ پر بہترین بولی اور بہترین پوچھنے والی میٹنگ کے ساتھ اسٹیک کرتی ہے، لہذا آپ جو بھی آرڈر بھیجتے ہیں وہ یا تو قطار میں شامل ہوتا ہے یا مخالف طرف سے آرام کرنے والے آرڈر کے خلاف تجارت کرتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>آرڈر بک خریداروں کو بولی کی طرف اور بیچنے والوں کو اسپریڈ پر بہترین بولی اور بہترین پوچھنے والی میٹنگ کے ساتھ اسٹیک کرتی ہے، لہذا آپ جو بھی آرڈر بھیجتے ہیں وہ یا تو قطار میں شامل ہوتا ہے یا مخالف طرف سے آرام کرنے والے آرڈر کے خلاف تجارت کرتا ہے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آرڈر بک صرف دو ترتیب شدہ قطاریں ہیں، خریدار بولی کی طرف اور بیچنے والے پوچھنے والے طرف۔ بہترین بولی وہ سب سے زیادہ قیمت ہے جو خریدار ادا کرے گا، بہترین پوچھنا سب سے کم قیمت ہے جسے بیچنے والا قبول کرے گا، اور ان کے درمیان فرق پھیلاؤ ہے۔</p>\n</div></div>\n<h2 id=\"a-market-order-certain-fill-uncertain-price\">مارکیٹ آرڈر، کچھ بھرنے، غیر یقینی قیمت</h2>\n<p>خریدنے کا سب سے آسان طریقہ ہے a <strong>مارکیٹ آرڈر</strong>، جو بھی بہترین دستیاب قیمت ہے اس پر ابھی تجارت کرنے کی ہدایت۔ آپ قیمت کا نام نہیں لے رہے ہیں۔ آپ کہہ رہے ہیں کہ مجھے فوراً اندر لے جائیں، اور آپ جو بھی آرڈر بک پیش کرتے ہیں اسے قبول کریں۔</p>\n<p>جب آپ کا خرید بازار کا آرڈر آتا ہے، تو ایکسچینج اس سے کتاب میں بیٹھے ہوئے سب سے کم پوچھے جانے سے مماثل ہوتا ہے۔ اگر آپ ایک لاٹ چاہتے ہیں اور 1,318.05 روپے میں تین لاٹ پیش کیے جاتے ہیں، تو آپ فوری طور پر 1,318.05 روپے میں بھر جاتے ہیں۔ مائع کنٹریکٹ میں بھرنے کی بنیادی طور پر ضمانت دی جاتی ہے، کیونکہ وہاں تقریباً ہمیشہ کوئی نہ کوئی دوسری طرف آرام کرتا ہے۔</p>\n<p>جس چیز کا مارکیٹ آرڈر وعدہ نہیں کرتا ہے وہ قیمت ہے۔ آپ کو بھرنے کے بعد ہی صحیح قیمت معلوم ہوتی ہے۔ قریبی مہینہ NIFTY یا RELIANCE مستقبل میں یہ مشکل سے اہمیت رکھتا ہے، کیونکہ پھیلاؤ ایک یا دو ٹک ہے۔ لیکن ایک بڑی مارکیٹ آرڈر کو ایک پتلی کتاب میں فائر کریں اور آپ بہترین سوال کے ذریعے کھا سکتے ہیں، پھر اگلا، ہر ایک آخری سے بدتر، لہذا آپ کی اوسط قیمت وہاں سے ہٹ جاتی ہے جہاں سے آپ نے اسے دیکھا تھا۔ آپ کی متوقع قیمت اور آپ کو ملنے والی قیمت کے درمیان یہ فرق ہے۔ <strong>پھسلنا</strong>، اور بعد کا ایک پورا باب اس کے لیے وقف ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>مارکیٹ آرڈر کا استعمال کریں جب جلدی سے اندر یا باہر نکلنا آخری چند پیسوں سے زیادہ اہمیت رکھتا ہے، اور صرف مائع کے قریب مہینے کے معاہدے میں۔ کسی بھی پتلی چیز میں اس کے ساتھ احترام کے ساتھ برتاؤ کریں، کیونکہ مارکیٹ کا آرڈر قیمت کو سیڑھی تک لے جائے گا۔</p>\n</div></div>\n<h2 id=\"a-limit-order-your-price-uncertain-fill\">ایک حد آرڈر، آپ کی قیمت، غیر یقینی بھرنا</h2>\n<p>اے <strong>حد حکم</strong> تجارت کو پلٹ دیتا ہے۔ یہاں آپ صحیح قیمت کا نام دیتے ہیں جو آپ ادا کرنے کو تیار ہیں، یا اس سے بہتر، اور آپ انتظار کریں۔ 1,317.50 روپے پر خریداری کی حد کہتی ہے کہ میں 1,317.50 روپے یا اس سے کم پر خریدوں گا، لیکن ایک پیسہ زیادہ نہیں۔</p>\n<p>اگر مارکیٹ پہلے سے ہی آپ کی حد پر یا اس سے نیچے ہے، تو آپ ایک ساتھ تجارت کرتے ہیں۔ اگر یہ اوپر ہے، تو آپ کا حکم ختم نہیں ہوتا ہے۔ یہ آرڈر بک کے بولی والے حصے میں شامل ہوتا ہے اور آپ کی قیمت پر قطار میں انتظار کرتا ہے۔ جس لمحے کوئی بیچنے والا آپ سے وہاں ملنے کو تیار ہوتا ہے، آپ بھر جاتے ہیں۔ اس وقت تک آپ بیٹھ کر انتظار کریں، اور اگر قیمت آپ کے پاس واپس نہ آئے تو آپ ہمیشہ کے لیے انتظار کر سکتے ہیں۔</p>\n<p>لہذا ایک حد آرڈر آپ کو قیمت کا یقین دیتا ہے اور بھرنے کی یقین دہانی دیتا ہے۔ آپ کبھی بھی اپنی حد سے بدتر ادائیگی نہیں کریں گے، لیکن ہو سکتا ہے آپ بالکل بھی تجارت نہ کریں۔ یہ مارکیٹ آرڈر کے برعکس سودا ہے، اور ان کے درمیان انتخاب کرنا ٹریڈنگ کی پہلی حقیقی مہارتوں میں سے ایک ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>مارکیٹ آرڈر</th>\n<th>حکم کی حد</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>آپ کنٹرول کریں۔</td>\n<td>رفتار</td>\n<td>قیمت</td>\n</tr>\n<tr>\n<td>بھرنا</td>\n<td>تقریباً یقینی</td>\n<td>ضمانت نہیں ہے۔</td>\n</tr>\n<tr>\n<td>قیمت</td>\n<td>ضمانت نہیں ہے۔</td>\n<td>آپ کی حد یا اس سے بہتر پر محدود</td>\n</tr>\n<tr>\n<td>بہترین استعمال کیا جاتا ہے جب</td>\n<td>آپ کو ابھی اندر یا باہر جانا ہوگا۔</td>\n<td>آپ اپنی قیمت کا انتظار کر سکتے ہیں۔</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-order-types.png\" alt=\"مارکیٹ آرڈر بہترین دستیاب قیمت پر فوری طور پر تجارت کرتا ہے جبکہ ایک حد آرڈر آپ کی قیمت کا نام دیتا ہے اور قطار میں انتظار کرتا ہے، لہذا قیمت کنٹرول کے خلاف دو آرڈر کی تجارت کی رفتار کی اقسام۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>مارکیٹ آرڈر بہترین دستیاب قیمت پر فوری طور پر تجارت کرتا ہے جبکہ ایک حد آرڈر آپ کی قیمت کا نام دیتا ہے اور قطار میں انتظار کرتا ہے، لہذا قیمت کنٹرول کے خلاف دو آرڈر کی تجارت کی رفتار کی اقسام۔</figcaption></figure>\n<h2 id=\"stop-orders-the-level-that-protects-you\">آرڈرز بند کرو، وہ سطح جو آپ کی حفاظت کرتی ہے۔</h2>\n<p>تیسرا ٹول جس کی ہر فیوچر ٹریڈر کو ضرورت ہوتی ہے۔ <strong>روکنے کا حکم</strong>, کبھی کبھی ایک سٹاپ نقصان کہا جاتا ہے. اسٹاپ ایک ایسا آرڈر ہے جو اس وقت تک غیر فعال رہتا ہے جب تک قیمت آپ کی منتخب کردہ سطح کو چھو نہیں لیتی، اور تب ہی یہ بیدار ہوتا ہے اور عمل کرتا ہے۔ اس کا روزمرہ کا کام یہ ہے کہ آپ اس پوزیشن پر خسارے کو کم کریں جس پر آپ پہلے سے موجود ہیں۔</p>\n<p>فرض کریں کہ آپ 1,318 روپے سے ایک RELIANCE لاٹ ہیں اور آپ فیصلہ کرتے ہیں کہ آپ 1,300 روپے سے زیادہ گراوٹ کو برداشت نہیں کریں گے۔ آپ 1,300 روپے میں ٹرگر کے ساتھ فروخت کے لیے ایک اسٹاپ لگاتے ہیں۔ جب کہ RELIANCE اس سطح سے اوپر رہتا ہے، کچھ نہیں ہوتا ہے۔ جیسے ہی قیمت 1,300 روپے تک گر جاتی ہے، آپ کا اسٹاپ اٹھ جاتا ہے اور آپ کی پوزیشن کو بند کرنے کے لیے سیل آرڈر بھیجتا ہے۔ آپ کو اسکرین دیکھنے کی ضرورت نہیں ہے۔ ایکسچینج آپ کے لیول کو دیکھتا ہے۔</p>\n<p>دو عام ذائقے ہیں۔</p>\n<ul>\n<li>اے <strong>سٹاپ لاس مارکیٹ</strong> آرڈر آپ کی سطح پر متحرک ہوتا ہے اور پھر جو بھی قیمت دستیاب ہو اسے لے کر مارکیٹ میں فروخت ہوتا ہے۔ باہر نکلنا یقینی ہے لیکن تیزی سے پھسل سکتا ہے۔</li>\n<li>اے <strong>روکنے کے نقصان کی حد</strong> آرڈر آپ کی سطح پر ٹرگر کرتا ہے اور پھر آپ کی مقرر کردہ قیمت پر ایک حد لگاتا ہے، لہذا آپ اس بدترین قیمت کو کنٹرول کرتے ہیں جسے آپ قبول کریں گے، لیکن اگر مارکیٹ کا فرق آپ کی حد سے آگے نکل جاتا ہے تو اسے پُر نہ ہونے کا خطرہ ہے۔</li>\n</ul>\n<p>اسٹاپ ایک نظم و ضبط شدہ تاجر کی سیٹ بیلٹ ہے، جو پہلے سے اور جذبات کے بغیر فیصلہ کرتا ہے کہ جس مقام پر تجارت غلط ثابت ہوئی ہے۔ ایماندار ہو، تاہم، اس کے بارے میں جو یہ نہیں کر سکتا۔ راتوں رات کے وقفے میں قیمت آپ کی سطح سے صاف چھلانگ لگا سکتی ہے اس سے پہلے کہ کوئی بھی آرڈر کام کر سکے، ایک خطرہ جو خلا کے بعد کا باب قریب سے جانچتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک سٹاپ نقصان عام حالات میں آپ کے نقصان کو محدود کرتا ہے، لیکن یہ طاقت کا میدان نہیں ہے۔ اگر RELIANCE رات بھر میں 1,318 روپے سے 1,280 روپے تک کا فرق ہوتا ہے، تو 1,300 روپے کا سٹاپ 1,300 روپے پر نہیں بھر سکتا، کیونکہ اس قیمت کی کبھی تجارت نہیں ہوئی۔ آپ کم بھرے ہوئے ہیں، اور آپ کا نقصان منصوبہ بندی سے زیادہ ہے۔ اس امکان کے لیے اپنی پوزیشن کا سائز بنائیں۔</p>\n</div></div>\n<h2 id=\"how-your-buy-actually-matches-a-sale\">آپ کی خریداری دراصل فروخت سے کیسے ملتی ہے۔</h2>\n<p>یہ خود میچ کے بارے میں ٹھوس ہونے کے قابل ہے، کیونکہ یہ وینڈنگ مشین کے بھرم کو دور کرتا ہے۔ تبادلہ ایک چلتا ہے۔ <strong>آرڈر سے مماثل انجن</strong> جو آنے والے آرڈر کو آرام کرنے والوں کے ساتھ سخت قوانین کے ساتھ جوڑتا ہے، سب سے پہلے بہترین قیمت، اور برابر قیمتوں کے لیے، جو بھی جلد قطار میں کھڑا ہو۔ جب آپ کی خرید ایک ہی قیمت پر آرام کی فروخت سے ملتی ہے، تو ایک تجارت جنم لیتی ہے، اور کلیئرنگ ہاؤس آپ کے درمیان گارنٹر کے طور پر آتا ہے، لہذا کسی بھی فریق کو دوسرے ڈیفالٹ ہونے کی فکر نہیں ہوتی ہے۔</p>\n<p>یہ ہر مستقبل کی تجارت کی خاموش سچائی ہے۔ آپ کے لیے لمبا سفر کرنے کے لیے، اس قیمت پر، کوئی اس لمحے میں کہیں کم ہو گیا۔ آپ کا حکم کہیں سے پوزیشن طلب نہیں کرتا ہے۔ اسے کتاب میں ایک ہم منصب ملتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہر فیوچر کنٹریکٹ میں خریدار اور بیچنے والا ایک ہی لمحے میں تخلیق ہوتا ہے۔ جب آپ ایک RELIANCE لاٹ خریدتے ہیں، تو ایک حقیقی ہم منصب نے آپ کو ایک لاٹ بیچا، اور کلیئرنگ ہاؤس دونوں طرف کی ضمانت دیتا ہے۔ کوئی تجارت نہیں ہے بغیر کسی کے مخالف نقطہ نظر.</p>\n</div></div>\n<h2 id=\"intraday-or-carryforward-the-product-type-decision\">انٹرا ڈے یا کیری فارورڈ، پروڈکٹ کی قسم کا فیصلہ</h2>\n<p>آرڈر بھیجنے سے پہلے، OpenAlgo ایک اور چیز پوچھتا ہے، <strong>مصنوعات کی قسم</strong>، اور یہ تبدیل کرتا ہے کہ پوزیشن کیسے برتاؤ کرتی ہے۔</p>\n<ul>\n<li><strong>انٹرا ڈے</strong> اس کا مطلب ہے کہ آپ ایک ہی تجارتی دن کے اندر کھولنے اور بند کرنے کا ارادہ رکھتے ہیں۔ اگر آپ پہلے سے باہر نہیں نکلے ہیں تو پوزیشن خود بخود بند ہو جاتی ہے، اور یہ اکثر ہلکے مارجن کے لیے اہل ہوتا ہے کیونکہ خطرہ صرف گھنٹوں تک رہتا ہے۔ یہ راتوں رات نمائش سے گریز کرتا ہے، لیکن یہ اوور ٹریڈنگ کو آمادہ کرتا ہے۔</li>\n<li><strong>کیری فارورڈ</strong>، جسے پوزیشنل یا نارمل بھی کہا جاتا ہے، اس کا مطلب ہے کہ آپ رات بھر اور اس سے آگے پوزیشن پر فائز رہنے کا ارادہ رکھتے ہیں۔ یہ معاہدے کے لیے درکار پورے مارجن کا مطالبہ کرتا ہے، کیونکہ خطرہ اب اگلے سیشن تک کے وقفے کو پھیلا دیتا ہے، اور یہ اس نقطہ نظر کے مطابق ہوتا ہے جس کو ختم ہونے میں دنوں یا ہفتوں کی ضرورت ہوتی ہے۔</li>\n</ul>\n<p>مارجن پر ایک پہلے باب میں بتایا گیا ہے کہ رات بھر کی پوزیشن کو زیادہ نقد رقم کی ضرورت کیوں ہے۔ یہاں نکتہ یہ ہے کہ انٹرا ڈے یا کیری فارورڈ کا انتخاب کرنا اس بارے میں جان بوجھ کر فیصلہ ہے کہ آپ کتنی دیر تک رکنا چاہتے ہیں، ماضی پر کلک کرنے کی ترتیب نہیں۔</p>\n<h2 id=\"the-life-of-an-order-and-where-you-watch-it\">ایک آرڈر کی زندگی، اور آپ اسے کہاں دیکھتے ہیں۔</h2>\n<p>جس لمحے سے آپ آرڈر دیتے ہیں یہ ایک مختصر، اچھی طرح سے طے شدہ سفر سے گزرتا ہے۔ <strong>آرڈر لائف سائیکل</strong>، اور OpenAlgo آپ کو ظاہر کرتا ہے کہ یہ کہاں ہے۔</p>\n<ul>\n<li><strong>زیر التواء</strong>کھلے کے طور پر بھی دکھایا گیا ہے، کا مطلب ہے کہ آرڈر ایکسچینج تک پہنچ گیا ہے اور کتاب میں بیٹھا انتظار کر رہا ہے۔ آرام کی حد کا آرڈر یہاں اس وقت تک رہتا ہے جب تک کہ یہ بھر نہ جائے یا آپ اسے منسوخ نہ کر دیں۔</li>\n<li><strong>مکمل</strong>, جسے executed یا filled بھی کہا جاتا ہے، اس کا مطلب ہے کہ یہ میچ ہو گیا ہے اور تجارت ہو گئی ہے۔</li>\n<li><strong>مسترد</strong> اس کا مطلب ہے کہ ایکسچینج یا آپ کے بروکر نے اس سے انکار کر دیا، شاید ناکافی مارجن، غلط قیمت بینڈ، یا بند مارکیٹ کی وجہ سے۔ مسترد شدہ حکم کتاب تک کبھی نہیں پہنچا۔</li>\n<li><strong>منسوخ</strong> اس کا مطلب ہے کہ آپ، یا ایک خودکار اصول نے، آرڈر کو بھرنے سے پہلے ہی واپس لے لیا۔</li>\n</ul>\n<p>آپ ان سب کو دو جگہوں پر ٹریک کرتے ہیں۔ دی <strong>آرڈر بک</strong> OpenAlgo میں آپ کے دیے گئے ہر آرڈر اور اس کی موجودہ حیثیت، زیر التواء، مکمل، مسترد یا منسوخ کی فہرست ہے۔ دی <strong>تجارتی کتاب</strong> اصل بھرنے کی قیمتوں کے ساتھ صرف ان آرڈرز کی فہرست دیتا ہے جن پر عمل کیا گیا تھا۔ آرڈر بک آپ کے ارادوں کی کہانی ہے؛ تجارتی کتاب اس کا ریکارڈ ہے کہ واقعی کیا ہوا۔ ہر عمل کے بعد دونوں کی طرف دیکھنے کی عادت ڈالیں، اس لیے مسترد شدہ حکم یا جزوی بھرا کبھی کسی کا دھیان نہیں جاتا۔</p>\n<p>OpenAlgo آپ کو کتاب پر سادہ طریقوں سے عمل کرنے، آرڈر دینے، کسی زیر التواء میں ترمیم کرنے یا منسوخ کرنے، یا ایک سمارٹ آرڈر بھیجنے کی اجازت دیتا ہے جو پوزیشن کے سائز کو نشانہ بناتا ہے، یعنی آپ اسے وہ پوزیشن بتاتے ہیں جو آپ رکھنا چاہتے ہیں اور یہ اس بات کا تعین کرتا ہے کہ وہاں جانے کے لیے خریدنا یا بیچنا ہے۔ عمل کچھ بھی ہو، یہ پھر بھی اسی زندگی کے چکر میں ایک داخلے کے طور پر ختم ہوتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>دو اسکرینیں، دو نوکریاں۔ آرڈر بک ہر آرڈر اور اس کی حیثیت کو ظاہر کرتی ہے۔ تجارتی کتاب صرف وہی بھرتی ہے جو ہوا، قیمتوں پر۔ آپ کچھ بھی رکھنے کے بعد، آرڈر بک کو چیک کریں تاکہ اس بات کی تصدیق کی جا سکے کہ اسے قبول کیا گیا تھا، پھر بھرنے کی تصدیق کرنے کے لیے تجارتی کتاب۔</p>\n</div></div>\n<p>اب آپ جانتے ہیں کہ وہ ایک نل حرکت میں کیا سیٹ کرتا ہے۔ آپ کا آرڈر دو طرفہ کتاب میں داخل ہوتا ہے، مارکیٹ کی قیمت لیتا ہے یا آپ کی حد پر انتظار کرتا ہے، اور کلیئرنگ ہاؤس کی گارنٹی کے تحت ایک حقیقی ہم منصب کے خلاف میچ کیا جاتا ہے، جب کہ ایک اسٹاپ آپ کے منفی پہلو پر نظر رکھتا ہے۔ مارکیٹ یا حد کا انتخاب کریں کہ آیا رفتار یا قیمت زیادہ اہمیت رکھتی ہے، انٹرا ڈے کا انتخاب کریں یا اس حساب سے کیری فارورڈ کریں کہ آپ کتنی دیر تک رکھنا چاہتے ہیں، اور آرڈر بک اور ٹریڈ بک دیکھیں تاکہ معلوم ہو سکے کہ ہر آرڈر کہاں کھڑا ہے۔ اگلا باب پھیلاؤ اور ایک پتلی مارکیٹ کو عبور کرنے کی لاگت پر سخت نظر آتا ہے۔</p>\n","toc":[{"level":2,"text":"آرڈر بک، جہاں خریدار اور بیچنے والے ملتے ہیں۔","id":"the-order-book-where-buyers-and-sellers-meet"},{"level":2,"text":"مارکیٹ آرڈر، کچھ بھرنے، غیر یقینی قیمت","id":"a-market-order-certain-fill-uncertain-price"},{"level":2,"text":"ایک حد آرڈر، آپ کی قیمت، غیر یقینی بھرنا","id":"a-limit-order-your-price-uncertain-fill"},{"level":2,"text":"آرڈرز بند کرو، وہ سطح جو آپ کی حفاظت کرتی ہے۔","id":"stop-orders-the-level-that-protects-you"},{"level":2,"text":"آپ کی خریداری دراصل فروخت سے کیسے ملتی ہے۔","id":"how-your-buy-actually-matches-a-sale"},{"level":2,"text":"انٹرا ڈے یا کیری فارورڈ، پروڈکٹ کی قسم کا فیصلہ","id":"intraday-or-carryforward-the-product-type-decision"},{"level":2,"text":"ایک آرڈر کی زندگی، اور آپ اسے کہاں دیکھتے ہیں۔","id":"the-life-of-an-order-and-where-you-watch-it"}],"imgCount":2,"hasContent":true},"6":{"html":"<p>ٹریڈنگ میں ایک قیمت ہوتی ہے جو کبھی بھی آپ کے کنٹریکٹ نوٹ پر ظاہر نہیں ہوتی، پھر بھی یہ آپ کی ہر پوزیشن پر خاموشی سے جھک جاتی ہے۔ یہ بروکریج نہیں ہے، یہ ٹیکس نہیں ہے، اور یہ آپ کے خلاف چلنے والی قیمت نہیں ہے۔ یہ ایک سادہ سی حقیقت ہے کہ جس قیمت پر آپ خرید سکتے ہیں اور جس قیمت پر آپ بیچ سکتے ہیں کبھی بھی بالکل یکساں نہیں ہوتے ہیں، اور یہ کہ کسی معاہدے میں داخل ہونا اور باہر جانا خود ایک خرچ ہے۔ ابتدائی افراد صحیح سمت کا انتخاب کرنے کا جنون رکھتے ہیں اور اس پوشیدہ ٹول کو پوری طرح بھول جاتے ہیں۔ ہنر مند تاجر ایک بھی آرڈر دینے سے پہلے اس کے بارے میں سوچیں۔ اس باب میں ہم اس پوشیدہ قیمت کو کھولتے ہیں اور اسے اس طرح دیکھنا سیکھتے ہیں جس طرح مارکیٹ اسے دیکھتی ہے، لیکویڈیٹی، بولی مانگنے کے پھیلاؤ، مارکیٹ کی گہرائی، اور پھسلن کے ذریعے۔</p>\n<h2 id=\"liquidity-how-easily-you-can-get-in-and-out\">لیکویڈیٹی، آپ کتنی آسانی سے اندر اور باہر جا سکتے ہیں۔</h2>\n<p><strong>لیکویڈیٹی</strong> اس باب میں واحد سب سے اہم لفظ ہے۔ اس کا مطلب ہے کہ آپ کتنی آسانی سے کسی پوزیشن میں داخل یا باہر نکل سکتے ہیں بغیر آپ کے اپنے آرڈر کے قیمت کو آپ کے خلاف منتقل کیا جائے۔ مائع کنٹریکٹ میں خریداروں اور بیچنے والوں کا ہجوم تقریباً ہر قیمت پر تیار کھڑا ہوتا ہے، اس لیے جب آپ خریدنا چاہتے ہیں، ایک تیار بیچنے والا وہیں ہوتا ہے، اور جب آپ بیچنا چاہتے ہیں، تو ایک رضامند خریدار فوری طور پر ظاہر ہوتا ہے، یہ تمام قیمتوں کے بالکل قریب جہاں معاہدہ صرف ٹریڈ کر رہا تھا۔</p>\n<p>ایک پتلا، یا <strong>غیر مائع</strong>، معاہدہ اس کے برعکس ہے۔ بہت کم لوگ اس کی تجارت کر رہے ہیں، آرڈرز بہت کم ہیں، اور جس لمحے آپ کسی بھی حقیقی سائز کو خریدنے یا بیچنے کی کوشش کرتے ہیں آپ کو معلوم ہوتا ہے کہ آپ کی مطلوبہ قیمت پر کوئی بھی انتظار نہیں کر رہا ہے۔ آپ یا تو پُر کرنے میں ناکام رہتے ہیں یا آپ زیادہ خراب قیمت پر بھرتے ہیں کیونکہ آپ کو کاؤنٹر پارٹی تلاش کرنے کے لیے بہت اوپر یا نیچے کی سیڑھی تک پہنچنا پڑتا ہے۔</p>\n<p>اسے ایک مصروف شہر میں مشہور فلیٹ بیچنے اور دور دراز کی زمین بیچنے میں فرق سمجھیں۔ فلیٹ کے بہت سے شوقین خریدار ہیں، لہذا آپ مناسب قیمت پر جلدی فروخت کر سکتے ہیں۔ پلاٹ مہینوں تک بیٹھ سکتا ہے، اور اسے بیچنے کے لیے آپ کو اپنی مانگی ہوئی قیمت میں تیزی سے کمی کرنی پڑ سکتی ہے۔ فلیٹ مائع ہے۔ پلاٹ غیر قانونی ہے۔ فیوچرز کنٹریکٹ اس سپیکٹرم کے ساتھ ملتے ہیں، اور یہ جاننا کہ آپ جس کی تجارت کرنے والے ہیں وہ کہاں گرتا ہے بقا کی ایک بنیادی مہارت ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>لیکویڈیٹی یہ ہے کہ آپ قیمت کو منتقل کیے بغیر کتنی آسانی سے داخل یا باہر نکل سکتے ہیں۔ مائع معاہدے میں بہت سے خریدار اور بیچنے والے قریبی قیمتوں پر تیار ہوتے ہیں، لہذا آپ تیزی سے اور منصفانہ تجارت کرتے ہیں۔ ایک پتلا معاہدہ آپ کو اس وقت سزا دیتا ہے جب آپ اندر یا باہر جانے کی کوشش کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-bid-ask-spread-a-toll-on-every-round-trip\">بولی مانگنے کا سلسلہ پھیل گیا، ہر دور کے سفر پر ایک ٹول</h2>\n<p>کوئی بھی معاہدہ کھولیں اور آپ کو قطار کے سامنے دو قیمتیں نظر آئیں گی۔ دی <strong>بولی</strong> سب سے زیادہ قیمت ہے جو فی الحال کوئی بھی خریدنے کے لیے تیار ہے۔ دی <strong>پوچھنا</strong>، جسے کبھی کبھی پیشکش بھی کہا جاتا ہے، وہ سب سے کم قیمت ہے جو فی الحال کوئی بھی فروخت کرنے کو تیار ہے۔ ان کے درمیان فاصلہ ہے۔ <strong>بولی پوچھنا پھیلاؤ</strong>، اور یہ لیکویڈیٹی کا سب سے واضح واحد پیمانہ ہے جسے آپ کبھی دیکھیں گے۔</p>\n<p>یہاں یہ ہے کہ پھیلاؤ ایک حقیقی قیمت ہے نہ کہ صرف ایک نمبر۔ اگر آپ ابھی مارکیٹ آرڈر کے ساتھ مستقبل خریدتے ہیں، تو آپ اس سے زیادہ قیمت ادا کرتے ہیں۔ اگر آپ مڑتے ہیں اور اسے فوری طور پر کسی دوسرے مارکیٹ آرڈر کے ساتھ بیچ دیتے ہیں، تو آپ کو کم قیمت پر بولی ملے گی۔ قیمت بڑھے بغیر آپ اسپریڈ کو کھو دیں گے۔ اس لیے اسپریڈ وہ ٹول ہے جسے آپ ہر بار ادا کرتے ہیں جب آپ کسی پوزیشن میں اور باہر مکمل چکر لگاتے ہیں۔</p>\n<p>آئیے ہم اس پر RELIANCE کا استعمال کرتے ہوئے روپے ڈالیں۔ معاہدے کے چشمی کے ایک پہلے باب سے، یاد کریں کہ ٹک کا سائز، قانونی قیمت کا سب سے چھوٹا مرحلہ ہے <strong>0.05 روپے</strong>اور یہ کہ بہت سارے 500 شیئرز پر ایک ٹک کی قیمت 0.05 گنا 500 روپے ہے، جو کہ <strong>25 روپے</strong>. اب تصور کریں کہ RELIANCE مستقبل میں 1,319.95 روپے کی بولی اور 1,320.00 روپے کی طلب ظاہر ہوتی ہے۔ یہ ایک ٹک کا پھیلاؤ ہے، 0.05 روپے۔ اگر آپ پوچھنے پر خریدتے ہیں اور فوری طور پر بولی پر فروخت کرتے ہیں، تو آپ بالکل ایک ٹک نیچے ہیں، جو کہ ایک ہی لاٹ پر 25 روپے ہے، اس سے پہلے کہ مارکیٹ کچھ کر لے۔ اگر اسپریڈ دو ٹکس تھے، 0.10 روپے، تو اسی راؤنڈ ٹرپ پر آپ کو 50 روپے بہت زیادہ لاگت آتی ہے۔ پھیلاؤ جتنا وسیع ہوگا، ٹول اتنا ہی بھاری ہوگا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-bid-ask-spread.png\" alt=\"بولی بہترین قیمت ہے جو خریدار ادا کرے گا اور پوچھنا بہترین قیمت ہے جسے بیچنے والا قبول کرے گا، اور ان کے درمیان فرق وہ ہے جو آپ ہر بار داخل ہونے اور باہر نکلنے پر عبور کرتے ہیں، ایک حقیقی اعادی لاگت جو ٹِکس اور روپے میں ماپا جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>بولی بہترین قیمت ہے جو خریدار ادا کرے گا اور پوچھنا بہترین قیمت ہے جسے بیچنے والا قبول کرے گا، اور ان کے درمیان فرق وہ ہے جو آپ ہر بار داخل ہونے اور باہر نکلنے پر عبور کرتے ہیں، ایک حقیقی اعادی لاگت جو ٹِکس اور روپے میں ماپا جاتا ہے۔</figcaption></figure>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE مستقبل، بولی 1,319.95 روپے، پوچھیں 1,320.00 روپے۔ اسپریڈ 0.05 روپے کا ایک ٹک ہے۔ بہت سارے 500 شیئرز پر جو کہ 25 روپے ہے۔ مانگنے پر خریدیں اور بولی پر ایک ہی سانس میں بیچیں اور آپ نے 25 روپے بہت زیادہ ادا کیے ہیں سوائے اسپریڈ کو عبور کرنے کا اعزاز۔ یہ بروکریج اور ٹیکسوں سے الگ ہے، جس کا اخراجات کے بارے میں بعد کے باب میں مکمل احاطہ کیا گیا ہے۔</p>\n</div></div>\n<p>تقریباً 6,59,000 روپے کے معاہدے کے مقابلے میں ایک 25 روپے معمولی لگتا ہے۔ یہ ہے. خطرہ ایک کراسنگ نہیں ہے، یہ تکرار ہے. ایک تاجر جو دن میں دس بار چھلانگ لگاتا ہے وہ اس ٹول کو بیس گنا ادا کر رہا ہے، اور چوڑے یا پتلے معاہدے پر ٹول کہیں زیادہ ہے۔ مریض کے لیے پھیلاؤ چھوٹا اور بے چین کے لیے مہنگا ہے۔</p>\n<h2 id=\"market-depth-the-five-level-ladder\">مارکیٹ کی گہرائی، پانچ درجے کی سیڑھی۔</h2>\n<p>بولی اور پوچھنا صرف ایک لمبی قطار کے سامنے ہے۔ <strong>مارکیٹ کی گہرائی</strong> مکمل تصویر ہے، جسے عام طور پر ایک سیڑھی کے طور پر دکھایا جاتا ہے جس میں ایک طرف خرید آرڈر کے پانچ درجے اور دوسری طرف فروخت کے آرڈر کے پانچ درجے ہوتے ہیں۔ ہر سطح ایک قیمت اور مقدار، معاہدوں کی تعداد، اس قیمت پر باقی ظاہر کرتی ہے۔</p>\n<p>گہرائی کو پڑھنا آپ کو نہ صرف یہ بتاتا ہے کہ بہترین قیمتیں کہاں ہیں، بلکہ ان کے پیچھے کتنا سائز ہے۔ ایک گہرا، مائع معاہدہ ظاہر کرتا ہے کہ ہر سطح پر بڑی مقدار کو ایک دوسرے کے قریب رکھا ہوا ہے۔ ایک پتلا معاہدہ کچھ بکھرے ہوئے آرڈر دکھاتا ہے جس میں قیمتوں اور ہر ایک کی چھوٹی مقدار کے درمیان فرق ہوتا ہے۔ گہرائی کی سیڑھی ایکس رے ہے جو ظاہر کرتی ہے کہ آیا کوئی معاہدہ آپ کے آرڈر کو جذب کر سکتا ہے یا اس پر دم گھٹ جائے گا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-market-depth.png\" alt=\"پانچ سطحی مارکیٹ کی گہرائی کی سیڑھی خرید و فروخت کی قطار کے ہر قدم پر قیمت اور آرام کی مقدار کو ظاہر کرتی ہے، لہذا آپ تجارت کرنے سے پہلے یہ فیصلہ کر سکتے ہیں کہ آیا قیمت کو گھسیٹے بغیر آپ کے آرڈر کو پُر کرنے کے لیے کافی سائز کا انتظار ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>پانچ سطحی مارکیٹ کی گہرائی کی سیڑھی خرید و فروخت کی قطار کے ہر قدم پر قیمت اور آرام کی مقدار کو ظاہر کرتی ہے، لہذا آپ تجارت کرنے سے پہلے یہ فیصلہ کر سکتے ہیں کہ آیا قیمت کو گھسیٹے بغیر آپ کے آرڈر کو پُر کرنے کے لیے کافی سائز کا انتظار ہے۔</figcaption></figure>\n<p>یہ سب سے زیادہ اہمیت رکھتا ہے جب آپ کا آرڈر بہترین قیمت پر دستیاب مقدار سے بڑا ہوتا ہے۔ فرض کریں کہ 1,320.00 روپے کی مانگ پر صرف 200 شیئرز پیش کیے جاتے ہیں، لیکن آپ 500 کی پوری لاٹ خریدنا چاہتے ہیں۔ آپ کا آرڈر تمام 200 روپے 1,320.00 میں لے لیتا ہے، پھر بقیہ 300 کو بھرنے کے لیے اگلے درجے پر چڑھ جاتا ہے، شاید 1,320.10 روپے یا اس سے زیادہ پر۔ آپ کی خرید کی اوسط قیمت اس قیمت سے بھی بدتر ہوتی ہے جو آپ نے کلک کرنے پر دیکھی تھی۔ یہ وہ گہرائی کی سیڑھی ہے جو آپ کو ایک مشکل سبق سکھاتی ہے جب آپ اسے فوراً نظر انداز کر دیتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>مارکیٹ آرڈر بھیجنے سے پہلے، گہرائی کی سیڑھی پر نظر ڈالیں۔ اگر صحت مند سائز اوپر کی چند سطحوں پر بیٹھتا ہے اور قیمتیں مضبوطی سے بھری ہوئی ہیں، تو معاہدہ آپ کے آرڈر کو صاف طور پر لے سکتا ہے۔ اگر سطحیں پتلی ہیں اور دور دور تک پھیلی ہوئی ہیں، تو رفتار کم کریں، حد کا حکم استعمال کریں، یا چھوٹے سائز کی تجارت کریں۔</p>\n</div></div>\n<h2 id=\"slippage-and-impact-cost\">پھسلن اور اثر کی قیمت</h2>\n<p>جب آپ کو اصل میں بھری ہوئی قیمت اس قیمت سے بدتر ہوتی ہے جس کی آپ نے آرڈر دیتے وقت توقع کی تھی، تو فرق کہا جاتا ہے۔ <strong>پھسلنا</strong>. یہ ایک ایسی کتاب کو عبور کرنے کا قدرتی نتیجہ ہے جو اتنی گہری نہیں ہے کہ ایک قیمت پر آپ کے آرڈر کو پورا کر سکے۔ آپ کا مقصد 1,320.00 روپے تھا اور مارکیٹ نے آپ کو اوسطاً 1,320.12 روپے دیا۔ وہ بارہ پیسے کی پھسلن، 500 کے لاٹ پر، 60 روپے ہیں جو کتاب کے پتلے پن میں غائب ہو گئے۔</p>\n<p>گہرا تعلق ہے۔ <strong>اثر لاگت</strong>، یہ خیال کہ ایک بڑا آرڈر دینے کا عمل ہی قیمت کو آپ سے دور کر دیتا ہے۔ ایک چھوٹا حکم بمشکل گہری مارکیٹ کو پریشان کرتا ہے۔ ایک پتلی مارکیٹ میں ایک بڑا آرڈر سیڑھی کی کئی سطحوں سے گزرتا ہے، اور آپ جتنی گہرائی تک بھرتے ہیں، آپ کی اوسط قیمت اتنی ہی خراب ہوتی جاتی ہے۔ امپیکٹ لاگت اس سائز کے ساتھ بڑھتی ہے جس کی آپ دستیاب لیکویڈیٹی کے مقابلے میں تجارت کرنے کی کوشش کر رہے ہیں۔ وہی آرڈر جو قریب کے مہینے میں صاف طور پر بھرتا ہے NIFTY مستقبل کے چھوٹے سنگل اسٹاک میں قیمت کو نمایاں طور پر منتقل کر سکتا ہے۔</p>\n<p>وہ آلہ جو آپ کو پھسلنے کے لیے بے نقاب کرتا ہے۔ <strong>مارکیٹ آرڈر</strong>، جو کہتا ہے کہ جو بھی قیمت دستیاب ہے مجھے ابھی بھریں۔ یہ بھرنے کی ضمانت دیتا ہے لیکن قیمت نہیں۔ اس کا ساتھی، <strong>حد حکم</strong>, اس بدترین قیمت کا نام دیتا ہے جسے آپ قبول کریں گے اور آپ کو پھسلنے سے بچاتا ہے، ممکنہ طور پر بالکل بھی نہ بھرنے کی قیمت پر۔ گہرے مائع معاہدے میں پھیلاؤ اتنا سخت ہوتا ہے کہ بازار کا آرڈر عام طور پر ٹھیک ہوتا ہے۔ ایک پتلے معاہدے میں ایک لاپرواہ مارکیٹ آرڈر یہ ہے کہ کس طرح ابتدائی افراد مفت رقم مارکیٹ کو دیتے ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک پتلی کتاب میں مارکیٹ آرڈر کلاسک ابتدائی ٹریپ ہے۔ آپ کو لگتا ہے کہ آپ اسکرین پر قیمت پر خرید رہے ہیں، لیکن آپ کا آرڈر کئی گہرائیوں سے چبا جاتا ہے اور اس سے کہیں زیادہ خراب ہوتا ہے۔ پہلے گہرائی کی جانچ کیے بغیر کبھی بھی مارکیٹ آرڈر کو غیر قانونی معاہدے میں نہ لگائیں۔ جب شک ہو، تو حد کا حکم استعمال کریں اور قبول کریں کہ شاید آپ پُر نہ کریں۔</p>\n</div></div>\n<h2 id=\"the-india-rule-live-in-the-near-month\">ہندوستان کی حکمرانی، قریب کے مہینے میں رہتے ہیں۔</h2>\n<p>اب عملی حصہ، وہ قاعدہ جو ایک ابتدائی کو ہندوستانی مارکیٹ میں سب سے زیادہ پھیلنے اور پھسلنے والی پریشانی سے دور رکھتا ہے۔ لیکویڈیٹی تمام معاہدوں میں یکساں طور پر نہیں پھیلتی ہے۔ یہ بہت زیادہ مرتکز ہے، اور آپ تجارت کرنا چاہتے ہیں جہاں یہ پول ہے۔</p>\n<p>دی <strong>قریب مہینہ</strong> NIFTY اور BANKNIFTY انڈیکس فیوچرز ملک کے سب سے زیادہ مائع آلات میں سے ہیں۔ ان کے پھیلاؤ معمول کے مطابق صرف ایک یا دو ٹک ہوتے ہیں، ان کی گہرائی کی سیڑھیاں سائز کے ساتھ اسٹیک ہوتی ہیں، اور آپ بمشکل کسی پھسلن کے ساتھ بامعنی پوزیشنوں میں داخل اور باہر نکل سکتے ہیں۔ یہ تالاب کا گہرا اختتام ہے، اور بالکل وہی جگہ ہے جہاں ایک ابتدائی کو تیرنا چاہیے۔</p>\n<p>اس سے دور بھٹکتے ہیں اور پانی تیزی سے خطرناک ہو جاتا ہے۔ <strong>دور مہینہ</strong> کنٹریکٹس، جن کی میعاد دو یا تین مہینوں میں ختم ہو رہی ہے، وسیع پھیلاؤ اور کم گہرائی کے ساتھ مقبول انڈر لائنز پر بھی بہت کم تجارت کی جاتی ہے۔ چھوٹا <strong>سنگل اسٹاک فیوچر</strong>, کم مشہور نام، پتلے اور سزا دینے والے بھی ہو سکتے ہیں، کئی ٹکوں کے پھیلاؤ کے ساتھ اور ہر سطح پر تقریباً کچھ بھی باقی نہیں رہتا۔ وہی RELIANCE مستقبل جو قریب کے مہینے میں صاف ستھرا تجارت کرتا ہے ایک دور مہینے میں غیر آرام دہ طور پر غیر مائع ہوسکتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>انڈین فیوچرز میں لیکویڈیٹی قریب کے مہینے کے انڈیکس کنٹریکٹس اور سب سے زیادہ فعال سنگل اسٹاک کے ناموں میں مرکوز ہوتی ہے۔ قریب کا مہینہ حجم اور سخت ترین قیمتیں رکھتا ہے۔ دور مہینوں اور چھوٹے اسٹاک فیوچرز وہ ہیں جہاں پھیلاؤ وسیع ہوتا ہے اور پھسل جاتا ہے۔ ایک مبتدی جو مہینے کے قریب مائع میں رہتا ہے وہ کچھ بھی ہوشیاری کیے بغیر اس قیمت کا زیادہ تر حصہ بچاتا ہے۔</p>\n</div></div>\n<p>تو نظم و ضبط آسان ہے۔ قریب کے مہینے میں تجارت کریں۔ جب آپ سیکھ رہے ہوں تو گہری مائع انڈیکس فیوچر کی حمایت کریں۔ اور اس سے پہلے کہ آپ کوئی بھی مارکیٹ آرڈر بھیجیں، گہرائی کی سیڑھی کو پڑھنے کی دو سیکنڈ کی عادت ڈالیں تاکہ اس بات کی تصدیق کی جا سکے کہ ٹچ کے قریب حقیقی سائز کا انتظار ہے۔ لیکویڈیٹی ہر تجارت کے تحت نظر نہ آنے والی منزل ہے۔ جب یہ ٹھوس ہوتا ہے تو آپ اسے بمشکل محسوس کرتے ہیں۔ جب یہ غائب ہوتا ہے تو، پھیلاؤ اور پھسلن راستے میں آپ کو ایک کاٹ لیتی ہے اور دوسرے راستے میں، اس سے بہت پہلے کہ آپ سمت کے بارے میں صحیح یا غلط تھے۔</p>\n","toc":[{"level":2,"text":"لیکویڈیٹی، آپ کتنی آسانی سے اندر اور باہر جا سکتے ہیں۔","id":"liquidity-how-easily-you-can-get-in-and-out"},{"level":2,"text":"بولی مانگنے کا سلسلہ پھیل گیا، ہر دور کے سفر پر ایک ٹول","id":"the-bid-ask-spread-a-toll-on-every-round-trip"},{"level":2,"text":"مارکیٹ کی گہرائی، پانچ درجے کی سیڑھی۔","id":"market-depth-the-five-level-ladder"},{"level":2,"text":"پھسلن اور اثر کی قیمت","id":"slippage-and-impact-cost"},{"level":2,"text":"ہندوستان کی حکمرانی، قریب کے مہینے میں رہتے ہیں۔","id":"the-india-rule-live-in-the-near-month"}],"imgCount":2,"hasContent":true},"7":{"html":"<p>بازار میں آنے والے زیادہ تر لوگ خریداری کے دوران ایک ذہنی عادت رکھتے ہیں: آپ کوئی سستی چیز خریدتے ہیں، اس کے عزیز ہونے کا انتظار کرتے ہیں، اور منافع پر فروخت کرتے ہیں۔ کم خریدیں، زیادہ بیچیں۔ ایسا لگتا ہے کہ پیسہ کمانے کا واحد طریقہ ہے۔ فیوچر خاموشی سے اس مفروضے کو آدھے حصے میں توڑ دیتے ہیں۔ فیوچر مارکیٹ میں آپ اتنی ہی آسانی سے کسی ایسی چیز کو بیچ کر شروع کر سکتے ہیں جو آپ کے پاس نہیں ہے، اور قیمت گرنے پر منافع حاصل کر سکتے ہیں۔ حکم الٹ ہے۔ پہلے زیادہ بیچیں، بعد میں کم خریدیں۔ ایک مبتدی کے لیے یہ جذب کرنے کے لیے سب سے عجیب اور طاقتور خیالات میں سے ایک ہے، تو آئیے اسے آہستہ آہستہ لیتے ہیں۔</p>\n<p>ہر فیوچر ٹریڈ پوائنٹس دو سمتوں میں سے ایک میں۔ آپ یا تو ہیں۔ <strong>طویل</strong> یا <strong>مختصر</strong>. لانگ واقف سمت ہے، شرط لگانا قیمت بڑھے گی۔ مختصر آئینے کی تصویر ہے، شرط لگانا قیمت گر جائے گی۔ دونوں کو سمجھنا، اور یہ حقیقت کہ فیوچر ان کے ساتھ برابری کا سلوک کرتے ہیں، وہی چیز ہے جو تاجر کو پیسہ کمانے دیتی ہے چاہے مارکیٹ چڑھ رہی ہو یا ڈوب رہی ہو۔</p>\n<h2 id=\"going-long-the-familiar-direction\">لمبا جانا: واقف سمت</h2>\n<p>کو <strong>لمبا جانا</strong> سب سے پہلے فیوچر کنٹریکٹ خریدنا ہے کیونکہ آپ توقع کرتے ہیں کہ انڈرلائننگ کی قیمت بڑھے گی۔ آپ ایک قیمت پر درج کرتے ہیں، اور اگر مستقبل میں چڑھتا ہے، تو آپ اسے زیادہ سے زیادہ واپس بیچ سکتے ہیں اور فرق کو جیب میں ڈال سکتے ہیں۔ یہ وہ سمت ہے جو روزمرہ کے وجدان سے میل کھاتی ہے، اس لیے اسے عام طور پر بہت کم وضاحت کی ضرورت ہوتی ہے۔</p>\n<p>ہماری چلتی ہوئی مثال لیں۔ RELIANCE ارد گرد تجارت کرتا ہے۔ <strong>1,318 روپے</strong>، اور مستقبل پر گول سطح ہے <strong>1320</strong>. اگر آپ کو لگتا ہے کہ اگلے چند ہفتوں میں RELIANCE اوپر کی طرف بڑھ رہا ہے، تو آپ 1320 میں مستقبل کا ایک لاٹ خریدیں گے۔ <strong>500 شیئرز</strong>لہذا مستقبل میں ہر ایک روپے کا اضافہ آپ کے لیے 500 روپے کا ہے۔ اگر مستقبل 1360 پر چڑھتا ہے، تو یہ 40 پوائنٹ کا اضافہ ہے، جو کہ 40 گنا 500، یا لاگت سے پہلے منافع میں 20,000 روپے ہے۔</p>\n<ul>\n<li>جب قیمت آپ کے اندراج سے بڑھ جاتی ہے تو آپ کو فائدہ ہوتا ہے۔</li>\n<li>جب قیمت آپ کے اندراج سے نیچے آتی ہے تو آپ ہار جاتے ہیں۔</li>\n<li>یہ جتنا آگے بڑھتا ہے، آپ اتنا ہی زیادہ بناتے ہیں، بغیر کسی مقررہ حد کے۔</li>\n</ul>\n<p>یہ لمبا ہو رہا ہے۔ پہلے خریدیں، بعد میں فروخت کریں، اضافہ سے منافع۔ جس نے حصہ خریدا ہے اس کے لیے یہاں کچھ بھی ناواقف نہیں ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>طویل سفر کا مطلب ہے کہ آپ پہلے مستقبل خریدیں اور قیمت بڑھنے پر منافع حاصل کریں۔ یہ معیاری خریدنا کم ہے، اعلیٰ تجارت بیچنا ہے، حصص کی بجائے خود ایک معاہدے کے ساتھ کیا جاتا ہے۔</p>\n</div></div>\n<h2 id=\"going-short-profiting-from-a-fall\">مختصر جانا: زوال سے فائدہ اٹھانا</h2>\n<p>کو <strong>مختصر جاؤ</strong> کسی بھی چیز کی ملکیت کے بغیر، سب سے پہلے ایک فیوچر معاہدہ فروخت کرنا ہے، کیونکہ آپ توقع کرتے ہیں کہ قیمت گر جائے گی۔ آپ ایک قیمت پر فروخت کرکے داخل ہوتے ہیں، اور اگر مستقبل میں کمی آتی ہے، تو آپ پوزیشن کو بند کرنے کے لیے اسے واپس خریدتے ہیں۔ آپ کی زیادہ فروخت کی قیمت اور آپ کی کم قیمت خرید کے درمیان فرق آپ کا منافع ہے۔</p>\n<p>یہ وہ حصہ ہے جو شروع کرنے والوں کو حیران کر دیتا ہے۔ آپ ایسی چیز کیسے بیچ سکتے ہیں جو آپ کے پاس نہیں ہے؟ فیوچر مارکیٹ میں یہ بالکل فطری ہے، کیونکہ مستقبل کوئی ایسی چیز نہیں ہے جو آپ کے پاس ہے، یہ ایک معاہدہ ہے۔ جب آپ مستقبل کو بیچتے ہیں تو آپ صرف متفقہ قیمت پر ڈیلیور کرنے کی ذمہ داری اٹھا رہے ہوتے ہیں۔ آپ بعد میں ایک مساوی معاہدہ واپس خرید کر اس ذمہ داری کو منسوخ کر سکتے ہیں۔ پہلے کچھ بھی ادھار نہیں لینا پڑتا۔</p>\n<p>RELIANCE پر واپس جائیں۔ فرض کریں کہ آپ کو لگتا ہے کہ اسٹاک بہت دور چلا گیا ہے اور پھسلنے والا ہے۔ آپ مستقبل کا ایک لاٹ 1320 پر بیچتے ہیں۔ اگر مستقبل 1280 پر آتا ہے، تو یہ 40 پوائنٹ کی کمی ہے۔ چونکہ آپ نے زیادہ فروخت کی اور اب کم خرید سکتے ہیں، آپ وہ 40 پوائنٹس حاصل کرتے ہیں، جو کہ 40 گنا 500، یا 20,000 روپے ہے۔ قیمت کم ہوگئی اور آپ نے پیسہ کمایا، جو کہ مختصر ہونے کا پورا نقطہ ہے۔</p>\n<ul>\n<li>جب قیمت آپ کے اندراج سے نیچے آتی ہے تو آپ کو فائدہ ہوتا ہے۔</li>\n<li>جب قیمت آپ کے اندراج سے بڑھ جاتی ہے تو آپ ہار جاتے ہیں۔</li>\n<li>یہ جتنا نیچے جاتا ہے، اتنا ہی زیادہ آپ بناتے ہیں، پورے راستے میں صفر تک پہنچ جاتے ہیں۔</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/payoff-short-future.png\" alt=\"ایک مختصر فیوچر پوزیشن منافع کے طور پر قیمت گرتی ہے اور اس کے بڑھنے کے ساتھ ہی کھو جاتی ہے، 1320 کی انٹری لیول پر بریک ایون کے ساتھ، لمبے جانے کی آئینہ دار تصویر۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایک مختصر فیوچر پوزیشن منافع کے طور پر قیمت گرتی ہے اور اس کے بڑھنے کے ساتھ ہی کھو جاتی ہے، 1320 کی انٹری لیول پر بریک ایون کے ساتھ، لمبے جانے کی آئینہ دار تصویر۔</figcaption></figure>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک تاجر قائل ہے کہ RELIANCE گر جائے گا مستقبل کی ایک لاٹ 1320 پر فروخت کرتا ہے۔ اسٹاک 1280 پر گرتا ہے، تاجر مستقبل کو واپس خریدتا ہے، اور 40 پوائنٹ کی کمی سنگل لاٹ پر 20,000 روپے کا منافع بن جاتی ہے۔ مختصر جانے نے گرتی ہوئی قیمت کو فائدے میں بدل دیا۔</p>\n</div></div>\n<h2 id=\"why-shorting-futures-is-easy-when-shorting-shares-is-hard\">فیوچر کو مختصر کرنا آسان کیوں ہے جب شیئرز کو شارٹ کرنا مشکل ہے۔</h2>\n<p>اگر آپ نے کبھی عام حصص کو مختصر کرنے کی کوشش کی ہے، تو آپ جانتے ہیں کہ یہ عجیب ہے۔ ایسے حصص کو بیچنے کے لیے جو آپ کے پاس نہیں ہیں، آپ کو عام طور پر انہیں پہلے کسی سے ادھار لینا پڑتا ہے، قرض کے لیے فیس ادا کرنا پڑتا ہے، اور بعد میں انہیں واپس کرنا پڑتا ہے، اور ہندوستانی کیش مارکیٹ میں ایک ریٹیل شارٹ کو عام طور پر اسی دن کے آخر تک بند کرنا پڑتا ہے۔ یہ فضول، محدود اور قلیل المدتی ہے۔</p>\n<p>فیوچرز اس سب کو دور کر دیتے ہیں۔ کیونکہ مستقبل قرضے کے حصص کے ڈھیر کے بجائے ایک معاہدہ ہے، <strong>مختصر فروخت</strong> فیوچرز میں کسی قرضے کی ضرورت نہیں، نہ اسٹاک قرضے کی فیس، اور دن کے آخر میں بند ہونے کے لیے کوئی جلدی نہیں۔ مستقبل کو بیچنا میکانکی طور پر ایک خریدنے کے مترادف ہے۔ آپ خرید آرڈر کے بجائے کھولنے کے لیے صرف فروخت کا آرڈر دیتے ہیں۔ آپ اس مختصر پوزیشن کو دنوں یا ہفتوں تک، میعاد ختم ہونے تک برقرار رکھ سکتے ہیں، بالکل اسی طرح جیسے آپ ایک لمبی پوزیشن پر فائز ہوں گے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>طویل مستقبل</th>\n<th>مختصر مستقبل</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>آپ شروع کریں۔</td>\n<td>معاہدہ خریدنا</td>\n<td>معاہدہ فروخت کرنا</td>\n</tr>\n<tr>\n<td>جب آپ کو فائدہ ہوتا ہے۔</td>\n<td>قیمت بڑھ جاتی ہے۔</td>\n<td>قیمت گر جاتی ہے۔</td>\n</tr>\n<tr>\n<td>تم قریب کرو</td>\n<td>بعد میں بیچنا</td>\n<td>بعد میں خریدنا</td>\n</tr>\n<tr>\n<td>قرض لینے کی ضرورت ہے۔</td>\n<td>کوئی نہیں۔</td>\n<td>کوئی نہیں۔</td>\n</tr>\n<tr>\n<td>ختم ہونے تک روک سکتے ہیں۔</td>\n<td>جی ہاں</td>\n<td>جی ہاں</td>\n</tr>\n</tbody></table>\n<p>یہ ہم آہنگی مستقبل کی وضاحتی خصوصیات میں سے ایک ہے۔ مارکیٹ مایوسیوں کے مقابلے میں امید پرستوں کے حق میں نہیں ہے۔ گرتی ہوئی منڈی اتنی ہی قابل تجارت ہے جتنی کہ بڑھتی ہوئی مارکیٹ، اور شارٹ کو لمبے سے زیادہ رکھنا مشکل نہیں ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>کیش مارکیٹ میں، شیئر کم کرنے کا مطلب عام طور پر اسے ادھار لینا اور دن کے آخر میں بند کرنا ہوتا ہے۔ مستقبل میں، مختصر جانا صرف کھولنے کے لئے فروخت کرنا ہے۔ کوئی ادھار نہیں، کوئی خاص اجازت نہیں، اور جب تک معاہدہ زندہ ہے آپ اسے روک سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"reading-a-long-versus-short-decision-on-the-real-chart\">حقیقی چارٹ پر ایک طویل بمقابلہ مختصر فیصلہ پڑھنا</h2>\n<p>نظریہ حقیقی ہو جاتا ہے جب آپ اسے اصل قیمت کی تاریخ کے خلاف رکھتے ہیں۔ یہ ہے اپنے آخری 120 سیشنز میں RELIANCE، 1,318 روپے کے قریب بند ہوا۔ آج کی قیمت پر، اس چارٹ کے دائیں کنارے پر کھڑے ہوں، اور طویل بمقابلہ مختصر انتخاب صرف یہ سوال ہے کہ آپ کے خیال میں اگلا اقدام کس طرف جاتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/chart-reliance-daily.png\" alt=\"RELIANCE گزشتہ 120 سیشنز میں روزانہ کینڈلز، 1,318 روپے کے قریب بند ہوتی ہیں، وہ نقطہ آغاز جہاں سے ایک تاجر فیصلہ کرتا ہے کہ لمبا جانا ہے یا چھوٹا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>RELIANCE گزشتہ 120 سیشنز میں روزانہ کینڈلز، 1,318 روپے کے قریب بند ہو رہی ہیں، وہ نقطہ آغاز جہاں سے ایک تاجر فیصلہ کرتا ہے کہ لمبا جانا ہے یا چھوٹا۔</figcaption></figure>\n<p>اگر آپ چارٹ کا مطالعہ کرتے ہیں اور یہ نتیجہ اخذ کرتے ہیں کہ رجحان اب بھی اوپر کی طرف ہے، ہر ڈپ کے خریدے جانے کے ساتھ، آپ لمبا جھک جائیں گے۔ آپ 1320 میں مستقبل خریدتے ہیں اور آپ ان موم بتیوں کو بلند ہوتے دیکھنا چاہتے ہیں، کیونکہ ہر ایک روپیہ آپ کے حق میں 500 روپے ہے۔</p>\n<p>اگر اس کے بجائے آپ چارٹ کو تھکے ہوئے، پھیلے ہوئے، یا گھومتے ہوئے پڑھتے ہیں، تو آپ مختصر جھک جائیں گے۔ آپ مستقبل کو 1320 پر بیچتے ہیں اور آپ چاہتے ہیں کہ موم بتیاں گر جائیں، کیونکہ اب ہر روپیہ نیچے آنے پر آپ کے حق میں 500 روپے ہیں۔ ایک ہی چارٹ، وہی ابتدائی قیمت، دو مخالف تجارت۔ کون سا صحیح ہے پہلے سے کبھی بھی یقینی نہیں ہوتا ہے، اور یہ غیر یقینی صورتحال بالکل اسی وجہ سے ہے کہ خطرے پر قابو پانے کی اتنی اہمیت ہے۔</p>\n<h2 id=\"both-directions-carry-real-risk\">دونوں سمتوں میں حقیقی خطرہ ہے۔</h2>\n<p>یہ محسوس کرنا پرکشش ہے کہ مختصر کرنا ایک چالاک چال ہے جو آپ کے امکانات کو دوگنا کر دیتی ہے۔ یہ مفت دوپہر کا کھانا نہیں ہے۔ لمبا اور چھوٹا دونوں بڑے، فائدہ اٹھانے والے خطرے کو لے کر جاتے ہیں، اور خطرہ ہر ایک کے لیے مختلف جگہوں پر ہوتا ہے۔</p>\n<p>جب آپ لمبے ہوتے ہیں، تو قیمت گرنے کے ساتھ ہی آپ کا نقصان بڑھتا ہے، اور سب سے بری صورت یہ ہے کہ اسٹاک صفر تک جا رہا ہے۔ یہ ایک بڑا نقصان ہے، لیکن یہ ایک پابند ہے. جب آپ چھوٹے ہوتے ہیں تو تصویر زیادہ خوفناک ہوتی ہے۔ قیمت بڑھنے کے ساتھ ہی آپ کا نقصان بڑھتا ہے، اور قیمت بغیر کسی قدرتی حد کے بڑھ سکتی ہے۔ ایک اسٹاک اچھی خبر پر دوگنا یا تین گنا ہوسکتا ہے، اور ایک چھوٹا بیچنے والا محسوس کرتا ہے کہ اس چڑھائی کا ہر روپیہ لاٹ سے ضرب ہوتا ہے۔ وہ ریاضی جو موسم خزاں میں شارٹنگ کو پرکشش بناتا ہے اسے تیز ریلی میں سفاک بنا دیتا ہے۔</p>\n<ul>\n<li>اگر مارکیٹ گرتی ہے تو لمبا نقصان ہوتا ہے، نقصان صرف اسٹاک کے صفر تک پہنچنے سے ہوتا ہے۔</li>\n<li>اگر بازار بڑھتا ہے تو شارٹ ہار جاتا ہے، اور اس نقصان کی کوئی مقررہ حد نہیں ہوتی۔</li>\n<li>دونوں کو بیعانہ کے ذریعے بڑھایا جاتا ہے، اس لیے آپ کے خلاف ایک معمولی اقدام آپ کے مارجن کے لیے بڑا نقصان ہے۔</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مختصر کرنا طویل سفر سے زیادہ محفوظ نہیں ہے، اور ایک طرح سے یہ زیادہ خطرناک ہے۔ بڑھتی ہوئی قیمت کی کوئی اوپری حد نہیں ہوتی، اس لیے ایک غیر ہیجڈ شارٹ اس سے زیادہ کھو سکتا ہے جس کا آپ نے کبھی تصور بھی نہیں کیا تھا۔ ہر شارٹ پر سٹاپ کا استعمال کریں، اور اس بات کا احترام کریں کہ سب سے زیادہ تکلیف دہ نقصان اکثر ایسی مارکیٹ کے خلاف شرط لگانے سے ہوتا ہے جو چڑھتی رہتی ہے۔</p>\n</div></div>\n<h2 id=\"when-a-trader-chooses-each\">جب ایک تاجر ہر ایک کا انتخاب کرتا ہے۔</h2>\n<p>تو آپ کب لمبے عرصے تک پہنچیں گے اور کب مختصر؟ سادہ الفاظ میں، جب آپ مارکیٹ، رجحان، خبروں، وسیع تر موڈ کے بارے میں ایماندارانہ پڑھتے ہیں تو آپ بہت آگے جاتے ہیں۔ جب وہی پڑھنا کم کہتا ہے تو آپ مختصر ہوجاتے ہیں۔ ہنر مند تاجر بھی شارٹس کا دفاعی طور پر استعمال کرتے ہیں، اپنے اپنے پورٹ فولیو کی حفاظت کے لیے انڈیکس فیوچر فروخت کرتے ہیں، جس کا استعمال ہم بعد میں اس کورس میں کرتے ہیں۔</p>\n<p>دیرپا ٹیک اپ ذمہ داری کے ساتھ آزادی ہے۔ فیوچرز آپ کو دونوں سمتوں میں منافع بخشنے دیتے ہیں، جس کا مطلب ہے کہ گرتی ہوئی مارکیٹ دیوار کی بجائے ایک موقع ہے۔ لیکن اگر حرکت دوسری طرف جاتی ہے تو ہر سمت آپ کو بری طرح نقصان پہنچا سکتی ہے، اور فائدہ اٹھانے سے اس کو تیزی سے تکلیف پہنچتی ہے۔ حقیقی تجزیہ سے اپنی سمت کا فیصلہ کریں، پوزیشن کا سائز بنائیں تاکہ غلط کال بچ سکے، اور داخل ہونے سے پہلے ہمیشہ اپنے باہر نکلنے کو جان لیں۔</p>\n","toc":[{"level":2,"text":"لمبا جانا: واقف سمت","id":"going-long-the-familiar-direction"},{"level":2,"text":"مختصر جانا: زوال سے فائدہ اٹھانا","id":"going-short-profiting-from-a-fall"},{"level":2,"text":"فیوچر کو مختصر کرنا آسان کیوں ہے جب شیئرز کو شارٹ کرنا مشکل ہے۔","id":"why-shorting-futures-is-easy-when-shorting-shares-is-hard"},{"level":2,"text":"حقیقی چارٹ پر ایک طویل بمقابلہ مختصر فیصلہ پڑھنا","id":"reading-a-long-versus-short-decision-on-the-real-chart"},{"level":2,"text":"دونوں سمتوں میں حقیقی خطرہ ہے۔","id":"both-directions-carry-real-risk"},{"level":2,"text":"جب ایک تاجر ہر ایک کا انتخاب کرتا ہے۔","id":"when-a-trader-chooses-each"}],"imgCount":2,"hasContent":true},"8":{"html":"<p>اگر آپ نے کبھی آپشن چارٹ پر نظر ڈالی ہے، تو آپ نے وہ جھکی ہوئی، ہاکی اسٹک کی شکلیں دیکھی ہیں جنہیں پڑھنے کے لیے ڈگری کی ضرورت محسوس ہوتی ہے۔ تقابل کے لحاظ سے فیوچر ایک ریلیف ہیں۔ فیوچر پوزیشن کس طرح پیسہ کماتی یا کھوتی ہے اس کی تصویر تمام ٹریڈنگ میں سب سے آسان ہے: ایک سیدھی لائن پینتالیس ڈگری پر جھکی ہوئی ہے۔ کوئی موڑ نہیں ہے، کوئی کنک نہیں ہے، کوئی فلیٹ اسٹریچ نہیں ہے جہاں کچھ نہیں ہوتا ہے۔ قیمت کچھ بھی ہو، آپ کا نفع یا نقصان اس کے ساتھ بالکل یکساں، متوقع انداز میں چلتا ہے۔ یہ باب آپ کو اس لائن کو پڑھنا سکھاتا ہے، کیونکہ ایک بار جب آپ اسے دیکھ لیتے ہیں، تو آپ بالکل سمجھ جاتے ہیں کہ مستقبل آپ کے اکاؤنٹ کے ساتھ کسی بھی قیمت پر کیا کرے گا۔</p>\n<p>نفع اور نقصان کا خاکہ، جسے عام طور پر a کہا جاتا ہے۔ <strong>ادائیگی کا خاکہ</strong>، صرف پلاٹ جہاں آپ کی پوزیشن بنیادی قیمتوں کی ایک حد میں کھڑی ہے۔ افقی محور RELIANCE کی قیمت ہے۔ عمودی محور مرکز لائن کے اوپر آپ کا منافع اور اس کے نیچے آپ کا نقصان ہے۔ مستقبل کے لیے، جو شکل ابھرتی ہے وہ سیدھی ترچھی ہوتی ہے، اور وہ سیدھا ایک گہرا معنی رکھتا ہے۔</p>\n<h2 id=\"the-straight-line-and-what-it-means\">سیدھی لکیر اور اس کا کیا مطلب ہے۔</h2>\n<p>مستقبل کی وضاحتی خصوصیت یہ ہے کہ اس کی ادائیگی a ہے۔ <strong>سیدھی لائن</strong>. RELIANCE کی ہر ممکنہ قیمت پر اپنا منافع پلاٹ کریں اور نقطے ایک غیر منقطع اخترن پر پڑیں۔ یہ مارکیٹ میں سب سے زیادہ ایماندارانہ ادائیگی ہے، کیونکہ اس میں کوئی چیز چھپی ہوئی نہیں ہے۔ قیمت کا کوئی خطہ نہیں ہے جہاں پوزیشن مختلف طریقے سے برتاؤ کرتی ہے، کوئی ایسا وکر نہیں ہے جو تیز ہو یا رک جائے۔ ایک مستحکم ڈھلوان، پورے راستے میں۔</p>\n<p>یہ سیدھا پن معاہدے کی نوعیت سے آتا ہے۔ مستقبل ایک مقررہ قیمت پر خریدنے یا فروخت کرنے کا ایک فلیٹ معاہدہ ہے، جس میں کوئی اختیار نہیں ہے اور نہ ہی کوئی پریمیم ہے جو ختم ہو جاتا ہے۔ لہذا آپ کا فائدہ یا نقصان صرف موجودہ قیمت اور آپ کے اندراج کے درمیان فرق ہے، جس کو لاٹ سے ضرب دیا گیا ہے۔ ایک سادہ فرق، مستقل سے ضرب، ہمیشہ ایک سیدھی لکیر کھینچتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/payoff-long-future.png\" alt=\"لانگ فیوچر پے آف ایک واحد سیدھی لکیر ہے جو نیچے بائیں سے اوپری دائیں طرف بڑھتی ہے، 1320 کی انٹری لیول پر صفر کو عبور کرتی ہے، اوپر منافع اور نیچے نقصان۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>لانگ فیوچر پے آف ایک واحد سیدھی لکیر ہے جو نیچے بائیں سے اوپری دائیں طرف بڑھتی ہے، 1320 کی انٹری لیول پر صفر کو عبور کرتی ہے، اوپر منافع اور نیچے نقصان۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مستقبل میں تجارت میں سب سے آسان ادائیگی ہوتی ہے، سیدھی پینتالیس ڈگری لائن۔ آپ کا منافع یا نقصان صرف آپ کے اندراج سے قیمت کی منتقلی ہے جس کو لاٹ سے ضرب دیا جاتا ہے، لہذا یہ ایک مستحکم شرح پر بدلتا ہے چاہے قیمت کہیں بھی جاتی ہو۔</p>\n</div></div>\n<h2 id=\"breakeven-sits-exactly-at-your-entry\">Breakeven بالکل آپ کے داخلے پر بیٹھتا ہے۔</h2>\n<p>یہ لکیر صفر کو کہاں سے عبور کرتی ہے، وہ نقطہ جس پر آپ نے نہ تو کچھ بنایا اور نہ ہی کھویا؟ مستقبل کے لیے جواب خوبصورتی سے آسان ہے۔ دی <strong>breakeven</strong> بالکل آپ کے داخلے کی قیمت پر بیٹھتا ہے، جو ہماری چل رہی مثال میں ہے۔ <strong>1320</strong>.</p>\n<p>کیوں کے بارے میں سوچو. جس لمحے آپ 1320 میں ایک طویل مستقبل میں داخل ہوں گے، آپ نہ آگے ہوں گے اور نہ پیچھے ہوں گے۔ اگر قیمت 1320 پر رہتی ہے تو کچھ بھی نہیں بدلا ہے اور آپ کا منافع صفر ہے۔ ایک روپیہ 1320 سے اوپر لے جائیں اور آپ منافع میں ہیں۔ ایک روپیہ نیچے لے جائیں اور آپ خسارے میں ہیں۔ لائن صفر سے عین اس قیمت پر گزرتی ہے جہاں آپ داخل ہوئے تھے۔</p>\n<p>یہ اختیارات سے زیادہ صاف ہے، جہاں آپ کو بریک ایون تلاش کرنے کے لیے ادا کردہ پریمیم کو شامل یا گھٹانا ہوگا۔ مستقبل میں کوئی پریمیم نہیں ہے، لہذا بنانے کے لئے کوئی ایڈجسٹمنٹ نہیں ہے۔ آپ نے داخل ہونے والے لمحے کو بھی توڑ دیا، اور وہاں سے ہر ٹک سیدھا آپ کے حق میں یا آپ کے خلاف ہے۔</p>\n<ul>\n<li>1320 پر ایک طویل مستقبل درج کریں، اور 1320 آپ کا بریک ایون ہے۔</li>\n<li>1320 سے اوپر آپ منافع میں ہیں، 1320 سے نیچے آپ نقصان میں ہیں۔</li>\n<li>پہلے وصولی کے لیے کوئی پریمیم نہیں ہے، کسی اختیار کے برعکس۔</li>\n</ul>\n<h2 id=\"one-to-one-with-the-underlying\">بنیادی کے ساتھ ایک سے ایک</h2>\n<p>لکیر کی ڈھلوان آپ کو بتاتی ہے کہ آپ کا پیسہ کتنی تیزی سے حرکت کرتا ہے، اور مستقبل کے لیے وہ ڈھلوان ہے <strong>ایک سے ایک</strong> بنیادی کے ساتھ. RELIANCE میں ہر ایک روپے کی حرکت آپ کی پوزیشن میں ایک مقررہ، مساوی تبدیلی پیدا کرتی ہے۔ ڈھلوان کے اندر کوئی بیعانہ چھپا ہوا نہیں ہے اور نہ ہی کوئی گیلا ہونا۔ مستقبل روپے کے لیے اسٹاک روپے کو ٹریک کرتا ہے۔</p>\n<p>اس کے اوپر لاٹ کا سائز لگائیں اور روپیہ کا فگر ظاہر ہوتا ہے۔ RELIANCE لاٹ ہے۔ <strong>500 شیئرز</strong>لہذا اسٹاک میں ایک روپیہ کی حرکت آپ کی پوزیشن پر 500 روپے ہے۔ اگر RELIANCE 10 روپے بڑھتا ہے، تو ایک لمبی لاٹ 10 گنا 500 حاصل کرتی ہے، جو کہ 5000 روپے ہے۔ اگر یہ 10 روپے گرتا ہے تو وہی لمبی لاٹ 5,000 روپے کھو دیتی ہے۔ رشتہ متوازی اور مستقل ہے۔ وہی 500 روپے فی روپیہ لاگو ہوتا ہے چاہے قیمت 1280 پر ہو یا 1380 پر۔</p>\n<table>\n<thead>\n<tr>\n<th>RELIANCE میں منتقل کریں۔</th>\n<th>ایک طویل لاٹ کے لیے تبدیلی (500 شیئرز)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1 روپے کا اضافہ</td>\n<td>علاوہ 500 روپے</td>\n</tr>\n<tr>\n<td>20 روپے اوپر</td>\n<td>اس کے علاوہ 10,000 روپے</td>\n</tr>\n<tr>\n<td>1 روپے کی کمی</td>\n<td>مائنس 500 روپے</td>\n</tr>\n<tr>\n<td>20 روپے نیچے</td>\n<td>مائنس 10,000 روپے</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE 1320 سے 1340 تک منتقل ہوتا ہے، 20 پوائنٹ کا اضافہ۔ 500 شیئرز کی ایک لمبی لاٹ سے 20 گنا 500 کا فائدہ ہوتا ہے جو کہ 10,000 روپے ہے۔ اگر یہ 20 پوائنٹس گر کر 1300 پر آ جاتا تو اسی لاٹ میں بالکل 10,000 روپے کا نقصان ہوتا۔ ڈھال دونوں سمتوں میں یکساں ہے۔</p>\n</div></div>\n<h2 id=\"the-short-payoff-is-the-same-line-mirrored\">مختصر ادائیگی ایک ہی لائن ہے، آئینہ دار</h2>\n<p>اوپر کی ہر چیز ایک لمبی پوزیشن کو بیان کرتی ہے، جہاں لکیر نیچے بائیں سے اوپری دائیں طرف اٹھتی ہے۔ اے <strong>مختصر</strong> پوزیشن صرف اس تصویر کو پلٹ دیتی ہے۔ اس کی ادائیگی ایک ہی سیدھی لائن ہے، لیکن دوسرے راستے سے ڈھلوان، اوپری بائیں سے نیچے دائیں طرف گرتی ہے۔ مختصر منافع جب قیمت گرتی ہے اور جب بڑھتی ہے تو نقصان ہوتا ہے، لمبے کا عین مطابق آئینہ۔</p>\n<p>نمبر ایک جیسے ہیں، صرف الٹ۔ 1320 پر داخل ہونے والے شارٹ کے لیے بریک ایون اب بھی 1320 ہے۔ ڈھلوان اب بھی ون ٹو ون ہے، پھر بھی 500 کی لاٹ پر 500 روپے فی روپیہ ہے۔ فرق صرف نشان کا ہے۔ 20 پوائنٹ کی کمی جس کی قیمت 10,000 روپے لمبی ہے اور مختصر 10,000 روپے، اور 20 پوائنٹ کا اضافہ اس کے برعکس کرتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/payoff-short-future.png\" alt=\"شارٹ فیوچر کی ادائیگی آئینہ کی لکیر ہے، دائیں جانب نیچے کی طرف ڈھلتی ہے، جب قیمت 1320 سے نیچے آتی ہے تو منافع حاصل ہوتا ہے اور جب اس کے اوپر چڑھتا ہے تو نقصان ہوتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>شارٹ فیوچر کی ادائیگی آئینہ کی لکیر ہے، دائیں جانب نیچے کی طرف ڈھلتی ہے، جب قیمت 1320 سے نیچے آتی ہے تو منافع حاصل ہوتا ہے اور جب اس کے اوپر چڑھتا ہے تو نقصان ہوتا ہے۔</figcaption></figure>\n<p>دونوں خاکوں کو ساتھ ساتھ رکھیں اور آپ کو مستقبل کی پوری حقیقت ایک نظر میں نظر آئے گی۔ 1320 پر دو سیدھی لائنیں کراس کرتی ہیں، ایک اٹھتی اور ایک گرتی، ایک دوسرے کے کامل عکاسی کرتی ہے۔ ایک فریق کو جو کچھ حاصل ہوتا ہے، دوسری طرف کا نقصان ہوتا ہے، روپے کے بدلے روپے۔ یہی وجہ ہے کہ ہر لمبے عرصے کے لیے ایک مختصر ہوتا ہے، اور فیوچر مارکیٹ دونوں کے درمیان پیسے کی صاف منتقلی کیوں ہوتی ہے۔</p>\n<h2 id=\"both-profit-and-loss-are-effectively-unlimited\">نفع اور نقصان دونوں مؤثر طریقے سے لامحدود ہیں۔</h2>\n<p>یہاں وہ حصہ ہے جو احترام کا مطالبہ کرتا ہے۔ چونکہ لائن سیدھی ہوتی ہے اور کبھی چپٹی نہیں ہوتی، مستقبل دونوں سمتوں میں کوئی بلٹ ان تحفظ فراہم نہیں کرتا ہے۔ نفع اور نقصان دونوں مؤثر طریقے سے ہیں۔ <strong>لامحدود</strong>.</p>\n<p>لمبی پوزیشن پر، جب تک قیمت بڑھتی ہے لائن بڑھتی رہتی ہے، اور اسٹاک کی قیمت پر کوئی قدرتی حد نہیں ہوتی، اس لیے منافع کی کوئی مقررہ حد نہیں ہوتی۔ لیکن نقصان تقریباً دور تک چلتا ہے۔ قیمت گرنے کے ساتھ ہی لائن گرتی رہتی ہے، اس وقت تک جب تک اسٹاک صفر تک نہیں پہنچ جاتا۔ ہمارے RELIANCE کے لیے طویل عرصے سے 1320 پر داخل ہوا، سب سے خراب صورت یہ ہے کہ اسٹاک صفر پر جا رہا ہے، 1320 پوائنٹس کی کمی۔ 500 کی لاٹ سے ضرب کریں اور زیادہ سے زیادہ نقصان تقریبا ہے۔ <strong>6,60,000 روپے</strong> فی لاٹ یہ نقصان کے نیچے واحد منزل ہے، اور یہ ایک طویل راستہ ہے.</p>\n<p>مختصراً خطرہ اس سے بھی بڑا ہے۔ قیمت گرنے کے ساتھ ہی ایک مختصر منافع، صرف صفر تک پہنچ جانے سے، دوبارہ تقریباً 6,60,000 روپے۔ لیکن اس کا نقصان قیمت میں اضافے سے ہوتا ہے، اور قیمت بغیر کسی حد کے بڑھ سکتی ہے۔ غیر ہیجڈ شارٹ پر ہونے والے نقصان کی کوئی نظریاتی حد نہیں ہے۔</p>\n<ul>\n<li>قیمت بڑھنے پر ایک مقررہ کیپ کے بغیر ایک طویل مستقبل کا منافع۔</li>\n<li>ایک لمبا مستقبل سٹاک کے صفر تک پہنچنے پر کھو جاتا ہے، یہاں تقریباً 6,60,000 روپے فی لاٹ۔</li>\n<li>ایک مختصر مستقبل کا منافع صفر تک گر جاتا ہے، تقریباً 6,60,000 روپے، اور قیمت بڑھنے پر بغیر کسی مقررہ حد کے کھو جاتا ہے۔</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>براہ راست ادائیگی کا مطلب ہے کہ مستقبل کبھی بھی اپنے آپ کو کھونے سے باز نہیں آتا ہے۔ ایسی کوئی سطح نہیں ہے جہاں نقصان ختم ہو جائے سوائے صفر تک پہنچنے والے اسٹاک کے، ایک RELIANCE لاٹ پر تقریباً 6,60,000 روپے، اور مختصر طور پر نقصان کی کوئی حد نہیں ہے۔ صرف حقیقی تحفظ ایک اسٹاپ ہے جسے آپ سیٹ کرتے ہیں اور اس پوزیشن کا سائز جو آپ منتخب کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"why-this-matters-before-you-meet-options\">آپ کو اختیارات ملنے سے پہلے یہ کیوں اہمیت رکھتا ہے۔</h2>\n<p>سیدھی لکیر اس کے ساتھ بیٹھنے کے قابل ہے، کیونکہ اگلے آلات جن کا آپ مطالعہ کریں گے وہ اس جیسا کچھ نظر نہیں آئے گا۔ ایک آپشن ادائیگی ہے۔ <strong>جھکا</strong>. یہ ایک طرف سے چپٹا ہو جاتا ہے، اس لیے ایک آپشن خریدار صرف ادا شدہ پریمیم کھو سکتا ہے، اس سے کوئی فرق نہیں پڑتا ہے کہ مارکیٹ کتنی ہی دور غلط طریقے سے چلتی ہے۔ یہ کنک بالکل وہی ہے جو آپشنز کو خریدار کے لیے زیادہ محفوظ محسوس کرتی ہے اور بالکل وہی چیز ہے جو انہیں قیمت اور تجارت میں مزید پیچیدہ بناتی ہے۔</p>\n<p>مستقبل میں ایسی کوئی کنک نہیں ہے۔ اس کی ہم آہنگی اس کی ایمانداری ہے۔ آپ اپنے حق میں مکمل اقدام کرتے ہیں اور آپ کے خلاف مکمل اقدام کرتے ہیں، بغیر کسی نرمی کے۔ کھونے کے لیے کوئی پریمیم نہیں ہے، آپ کے خلاف کوئی زوال نہیں ہے، اور معمے کو ختم کرنے کے لیے کوئی وکر نہیں ہے۔ جو کچھ آپ چارٹ پر دیکھتے ہیں وہی آپ کو اپنے اکاؤنٹ میں ملتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اس سے پہلے کہ آپ مستقبل کی تجارت کریں، اپنے حقیقی اندراج اور اس پر نشان زد لاٹ کے ساتھ اس کے سیدھے معاوضے کو ڈرا یا تصویر بنائیں۔ اپنے بریک ایون اور روپے فی پوائنٹ کو ایک نظر میں جاننا فیوچر میں سب سے آسان ڈسپلن ہے، اور سب سے زیادہ ابتدائی لوگ اسے چھوڑ دیتے ہیں۔</p>\n</div></div>\n<p>مستقبل کی ادائیگی ایک واحد سیدھی لائن ہے۔ Breakeven آپ کے 1320 کے اندراج پر بیٹھتا ہے، لاٹ پر 500 روپے فی روپیہ کے حساب سے ڈھلوان ون ٹو ون ہے، اور لائن نفع اور نقصان دونوں کے ساتھ دونوں سمتوں میں چلتی ہے مؤثر طریقے سے لامحدود، نقصان صرف سٹاک کے 6,60,000 روپے کے قریب صفر تک پہنچنے سے ہوتا ہے۔ اس تصویر کو اپنے سر پر رکھیں اور آپ کو ہمیشہ معلوم ہو جائے گا کہ مستقبل کہاں کھڑا ہے۔</p>\n","toc":[{"level":2,"text":"سیدھی لکیر اور اس کا کیا مطلب ہے۔","id":"the-straight-line-and-what-it-means"},{"level":2,"text":"Breakeven بالکل آپ کے داخلے پر بیٹھتا ہے۔","id":"breakeven-sits-exactly-at-your-entry"},{"level":2,"text":"بنیادی کے ساتھ ایک سے ایک","id":"one-to-one-with-the-underlying"},{"level":2,"text":"مختصر ادائیگی ایک ہی لائن ہے، آئینہ دار","id":"the-short-payoff-is-the-same-line-mirrored"},{"level":2,"text":"نفع اور نقصان دونوں مؤثر طریقے سے لامحدود ہیں۔","id":"both-profit-and-loss-are-effectively-unlimited"},{"level":2,"text":"آپ کو اختیارات ملنے سے پہلے یہ کیوں اہمیت رکھتا ہے۔","id":"why-this-matters-before-you-meet-options"}],"imgCount":2,"hasContent":true},"9":{"html":"<p>یہ وہ حقیقت ہے جو زیادہ تر لوگوں کو مستقبل کی طرف کھینچتی ہے، اور وہی حقیقت جو ان میں سے بہت سے لوگوں کو برباد کر دیتی ہے۔ تقریباً 6,59,000 روپے کے اسٹاک کے ایک لاٹ کو کنٹرول کرنے کے لیے، آپ کو 6,59,000 روپے کی ضرورت نہیں ہے۔ آپ کو اس کا صرف ایک حصہ درکار ہے، شاید ایک لاکھ سے کچھ زیادہ، بطور ڈپازٹ رکھا جائے۔ رقم کے تقریباً چھٹے حصے کے ساتھ آپ پوری پوزیشن حاصل کرتے ہیں۔ یہ ایک تحفہ کی طرح لگتا ہے، اور احتیاط سے استعمال کیا جاتا ہے یہ ایک طاقتور ٹول ہے۔ لاپرواہی سے استعمال کیا گیا یہ سب سے تیز ترین طریقہ ہے جو ایک ابتدائی نے اپنے مقصد سے زیادہ کھونے کا پایا ہے۔ یہ باب ڈپازٹ کی وضاحت کرتا ہے، اس سے پیدا ہونے والے جادوئی ضرب، اور اسے غلط ہونے کی ایماندارانہ قیمت۔</p>\n<h2 id=\"margin-the-deposit-you-actually-post\">مارجن، وہ ڈپازٹ جو آپ اصل میں پوسٹ کرتے ہیں۔</h2>\n<p>جب آپ مستقبل کی تجارت کرتے ہیں، تو آپ معاہدے کی مکمل قیمت ادا نہیں کرتے ہیں۔ آپ پوسٹ a <strong>مارجن</strong>, ایک نیک نیتی ڈپازٹ جسے ایکسچینج آپ کی پوزیشن پر ہونے والے ممکنہ نقصانات کو پورا کرنے کے لیے رکھتا ہے۔ مارجن کنٹریکٹ ویلیو کا ایک حصہ ہے، اور انڈیکس اور بڑے اسٹاک فیوچرز کے لیے یہ اکثر تقریباً 15 سے 20 فیصد ہوتا ہے، حالانکہ صحیح اعداد و شمار اس بات کے ساتھ بدل جاتے ہیں کہ کس قدر غیر مستحکم ہے۔ ایک جمپیئر اسٹاک زیادہ موٹے مارجن کا مطالبہ کرتا ہے۔</p>\n<p>آئیے RELIANCE معاہدے پر حقیقی نمبر ڈالیں۔ معاہدے کی قیمت تقریباً 6,59,000 روپے ہے، جو کہ 1,318 روپے کے قریب 500 شیئرز ہیں۔ اس کے 15 سے 20 فیصد کے علاقے میں مارجن تقریباً 1,00,000 روپے سے 1,30,000 روپے بنتا ہے۔ اس لیے کہیں کہیں آپ کی اپنی رقم کے تقریباً 1,10,000 روپے مارجن کے طور پر بندھے ہوئے ہیں، آپ RELIANCE کے پورے 6,59,000 روپے کو کنٹرول کرتے ہیں۔ باقی آپ نے کسی ظاہری قرض میں نہیں لیا ہے۔ معاہدے کا ڈھانچہ صرف ایک چھوٹے سے ڈپازٹ کو ایک بڑی پوزیشن کی حمایت کرنے دیتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مارجن ایک ڈپازٹ ہے، ادائیگی نہیں۔ آپ RELIANCE کے تقریباً 6,59,000 روپے کو کنٹرول کرنے کے لیے تقریباً 1,00,000 سے 1,30,000 روپے تک پوسٹ کرتے ہیں۔ بقیہ ایکسپوژر خود کنٹریکٹ کے ذریعے لیا جاتا ہے، یہی وجہ ہے کہ آپ کے فائدے اور نقصان کا حساب ڈپازٹ پر نہیں، پوری قیمت پر کیا جاتا ہے۔</p>\n</div></div>\n<h2 id=\"where-the-margin-number-comes-from-span-plus-exposure\">مارجن نمبر کہاں سے آتا ہے، SPAN پلس ایکسپوزر</h2>\n<p>آپ کو اعداد و شمار کا اندازہ لگانے کی ضرورت نہیں ہے۔ ایکسچینج ایک متعین خطرے کے ماڈل کا استعمال کرتے ہوئے ہر معاہدے کے مارجن کا حساب لگاتا ہے، اور یہ ہمیشہ دو حصوں میں آتا ہے جو ایک ساتھ سفر کرتے ہیں۔</p>\n<ul>\n<li><strong>SPAN مارجن</strong> اس کا بنیادی حصہ ہے. SPAN ایکسچینج کا رسک سسٹم ہے، اور یہ مارجن وہ رقم ہے جسے یہ آپ کی پوزیشن میں ایک دن کے بدترین اقدام کو پورا کرنے کے لیے ضروری سمجھتا ہے۔ یہ دونوں حصوں میں بڑا ہوتا ہے، اور جب زیریں حصہ زیادہ غیر مستحکم ہو جاتا ہے تو یہ چڑھتا ہے۔</li>\n<li><strong>نمائش کا مارجن</strong> ایک اضافی بفر ہے جو ایکسچینج SPAN کے اوپر جوڑتا ہے، جو کہ ایک غیر معمولی پرتشدد اقدام کے خلاف دوسرا کشن ہے۔ یہ SPAN سے چھوٹا ہے، لیکن یہ اختیاری نہیں ہے۔</li>\n</ul>\n<p>دونوں کو ایک ساتھ شامل کریں اور آپ کے پاس ہے۔ <strong>کل مارجن درکار ہے۔</strong>, اصل ڈپازٹ جو تجارت کے گزرنے سے پہلے آپ کے اکاؤنٹ میں مفت ہونا ضروری ہے۔ ہمارے ایک RELIANCE لاٹ کے لیے جو کہ کل 1,10,000 سے 1,30,000 روپے کے علاقے میں ہے، اس کا بڑا حصہ SPAN کی نمائش کے پتلے ٹکڑے کے ساتھ ہے۔</p>\n<p>چونکہ درست تعداد ہر روز اتار چڑھاؤ کے ساتھ بدلتی رہتی ہے، اس لیے جب حقیقی رقم داؤ پر لگی ہو تو آپ کو کبھی بھی ہاتھ سے اس کا اندازہ نہیں لگانا چاہیے۔ OpenAlgo میں شامل ہے۔ <strong>مارجن کیلکولیٹر</strong> بالکل اس کے لئے. آپ اسے کنٹریکٹ دیتے ہیں، جس طرف آپ لینا چاہتے ہیں اور مقدار، اور یہ سیدھے تین نمبر واپس کرتا ہے: SPAN مارجن، ایکسپوزر مارجن، اور کل مارجن درکار ہے۔ آرڈر دینے سے پہلے اسے چیک کرنے کا مطلب ہے کہ ڈپازٹ کبھی بھی حیرت کی بات نہیں ہے، اور آپ ایک ہی وقت میں دیکھ سکتے ہیں کہ کیا پوزیشن آپ کے پاس موجود سرمائے کے مطابق ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہر فیوچر آرڈر سے پہلے مارجن کیلکولیٹر کو مرحلہ وار بنائیں۔ معاہدہ اور مقدار درج کریں، مطلوبہ کل مارجن کو پڑھیں، اور تصدیق کریں کہ یہ آپ کے مفت فنڈز کے اندر آرام سے بیٹھا ہے تاکہ ہم اگلے باب میں روزانہ ہونے والے نقصانات کو پورا کرسکیں۔ ایک ایسی پوزیشن جس کو آپ کسی کھردرے پیچ کے ذریعے فنڈ نہیں دے سکتے ہیں وہ ہے آپ کو اس کو رکھنے سے پہلے اس کا سائز کم کرنا چاہیے۔</p>\n</div></div>\n<h2 id=\"leverage-the-multiplier-hiding-in-the-deposit\">لیوریج، جمع میں چھپا ہوا ضرب</h2>\n<p>چھوٹی جمع اور بڑی نمائش کے درمیان اس فرق کا ایک نام ہے، اور یہ اس پورے کورس میں سب سے اہم لفظ ہے۔ یہ ہے <strong>بیعانہ</strong>. لیوریج اس قدر کے درمیان تناسب ہے جسے آپ کنٹرول کرتے ہیں اور جو رقم آپ جمع کرتے ہیں۔ تقریباً 1,10,000 روپے کے ساتھ 6,59,000 روپے کو کنٹرول کرنا چھ گنا لیوریج کے قریب ہے۔ آپ کے سرمائے کا ہر روپیہ تقریباً چھ کا کام کر رہا ہے۔</p>\n<p>لیوریج آپ کی واپسی کے لیے کچھ مخصوص اور ناقابل معافی کام کرتا ہے۔ یہ آپ کے چھوٹے مارجن کے خلاف پیمائش کرتے ہوئے آپ کے نفع اور نقصان کو مکمل معاہدے کی قیمت پر شمار کرتا ہے۔ یہ وہ جگہ ہے جہاں اسٹاک میں ایک معمولی حرکت آپ کے اکاؤنٹ میں ایک ڈرامائی حرکت بن جاتی ہے۔</p>\n<p>اس کے ذریعے کام کریں۔ فرض کریں RELIANCE 5 فیصد بڑھتا ہے، تقریباً 1,318 روپے سے تقریباً 1,384 روپے تک، جب کہ آپ کا مستقبل ایک طویل ہے۔ ایکسپوزر 6,59,000 روپے ہے، تو اس پر 5 فیصد کا فائدہ تقریباً 33,000 روپے ہے۔ لیکن آپ نے مارجن کے تقریباً 1,10,000 روپے پوسٹ کیے ہیں۔ 1,10,000 روپے پر 33,000 روپے کا منافع آپ کے پیسے پر تقریباً 30 فیصد کا فائدہ ہے۔ اسٹاک 5 فیصد بڑھ گیا۔ آپ کا سرمایہ تقریباً 30 فیصد منتقل ہوا۔ وہ چھ گنا ضرب لیوریج اپنا کام کر رہا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-leverage.png\" alt=\"لیوریج ایک چھوٹے مارجن ڈپازٹ کو ایک بہت بڑی کنٹریکٹ ویلیو کو کنٹرول کرنے دیتا ہے، جو ایک ہی ملٹیپل کے ذریعے کسی بھی اقدام سے فائدہ اور نقصان دونوں کو بڑھاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>لیوریج ایک چھوٹے مارجن ڈپازٹ کو ایک بہت بڑی کنٹریکٹ ویلیو کو کنٹرول کرنے دیتا ہے، جو ایک ہی ملٹیپل کے ذریعے کسی بھی اقدام سے فائدہ اور نقصان دونوں کو بڑھاتا ہے۔</figcaption></figure>\n<p>اب اس مثال کو ایک لفظ بدل کر دوبارہ پڑھیں، کیونکہ ضرب کی کوئی وفاداری نہیں ہے۔ فرض کریں RELIANCE اس کے بجائے 5 فیصد گر کر تقریباً 1,252 روپے پر آ جاتا ہے۔ 6,59,000 روپے کی نمائش کا نقصان دوبارہ تقریباً 33,000 روپے ہے، اور آپ کے 1,10,000 روپے کے مارجن کے مقابلے میں جو آپ کے سرمائے کا تقریباً 30 فیصد نقصان ہے۔ اسٹاک میں ہلکی 5 فیصد کمی ہوئی۔ آپ نے جو رقم آپ کی ہے اس کا تقریباً ایک تہائی کھو دیا ہے۔ لیوریج نقصانات کو بالکل اسی ضرب سے ضرب دیتا ہے جو کہ منافع کو بڑھاتا ہے۔ یہ حقیقی طور پر دوہرا ہے، اور دونوں کناروں کی لمبائی ایک جیسی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>لیوریج متوازی ہے اور اسے اس بات کی پرواہ نہیں ہے کہ قیمت کس طرف جاتی ہے۔ وہی تقریباً چھ گنا ضرب جو 5 فیصد اضافے کو 30 فیصد نفع میں بدل دیتا ہے، 5 فیصد کمی کو 30 فیصد نقصان میں بدل دیتا ہے۔ اسٹاک چارٹ پر چھوٹا نظر آنے والا اقدام آپ کے مارجن پر بہت زیادہ ہو سکتا ہے۔</p>\n</div></div>\n<p>یہاں ایک کمپیکٹ ٹیبل میں وہی آئیڈیا ہے، جس میں مکمل 6,59,000 روپے کی نمائش کے مقابلے میں تقریباً 1,10,000 روپے مارجن کے ساتھ ایک RELIANCE لاٹ دکھایا گیا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>RELIANCE میں منتقل کریں۔</th>\n<th>نمائش کی قیمت میں تبدیلی</th>\n<th>آپ کے مارجن پر اثر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>2 فیصد تک</td>\n<td>تقریباً 13,000 روپے کا فائدہ</td>\n<td>تقریبا 12 فیصد اضافہ</td>\n</tr>\n<tr>\n<td>5 فیصد تک</td>\n<td>تقریباً 33,000 روپے کا فائدہ</td>\n<td>تقریبا 30 فیصد فائدہ</td>\n</tr>\n<tr>\n<td>2 فیصد نیچے</td>\n<td>تقریباً 13000 روپے کا نقصان</td>\n<td>تقریباً 12 فیصد نقصان</td>\n</tr>\n<tr>\n<td>5 فیصد نیچے</td>\n<td>تقریباً 33 ہزار روپے کا نقصان</td>\n<td>تقریباً 30 فیصد نقصان</td>\n</tr>\n<tr>\n<td>17 فیصد نیچے</td>\n<td>تقریباً 1,10,000 روپے کا نقصان</td>\n<td>آپ کا پورا مارجن ختم ہو گیا ہے۔</td>\n</tr>\n</tbody></table>\n<p>وہ آخری قطار ایک طویل وقفے کی مستحق ہے۔ RELIANCE میں تقریباً 17 فیصد کی کمی، جو کہ کسی بھی اسٹاک کے لیے ایک برا لیکن مکمل طور پر ممکن مہینہ ہے، آپ کے پورے ڈپازٹ کو ختم کردے گا۔ اسٹاک اب بھی اس کی زیادہ تر قیمت کے قابل ہے۔ آپ کا اکاؤنٹ صفر پر ہے۔ یہ فائدہ اٹھانے کی حقیقت ہے جو چاپلوسی کے بغیر بیان کی گئی ہے۔</p>\n<h2 id=\"initial-margin-and-maintenance-margin\">ابتدائی مارجن اور دیکھ بھال کا مارجن</h2>\n<p>دو مارجن کے اعداد و شمار ہیں جو ایک تاجر کو معلوم ہونا چاہیے، اور وہ مختلف کام کرتے ہیں۔</p>\n<ul>\n<li><strong>ابتدائی مارجن</strong> وہ رقم ہے جو آپ کو پہلی جگہ پر پوزیشن کھولنے کے لیے پوسٹ کرنا ہوگی۔ یہ تقریباً 1,00,000 روپے سے 1,30,000 روپے ہے جو ہم ایک RELIANCE لاٹ کے لیے استعمال کر رہے ہیں۔ کوئی ابتدائی مارجن، کوئی تجارت نہیں۔</li>\n<li><strong>بحالی کا مارجن</strong> نچلی حد ہے جب پوزیشن کھلی ہے تو آپ کا اکاؤنٹ اوپر رہنا چاہیے۔ چونکہ آپ کی پوزیشن دن بہ دن پیسے کھوتی ہے، آپ کا قابل استعمال مارجن سکڑتا جاتا ہے۔ بحالی کی سطح وہ لائن ہے جو ایکسچینج آپ کو نیچے نہیں آنے دے گی۔</li>\n</ul>\n<p>دو سطحوں کی وجہ یہ ہے کہ فیوچرز ہر ایک دن طے پاتے ہیں، ایک ایسا عمل جسے مارک ٹو مارکیٹ کہا جاتا ہے جس کا اگلا باب ہوتا ہے۔ ہر دن کا نقصان درحقیقت آپ کے مارجن اکاؤنٹ سے ڈیبٹ کیا جاتا ہے، اس لیے آپ کی پوزیشن پر کیش بیکنگ واقعی گر جاتی ہے کیونکہ تجارت آپ کے خلاف جاتی ہے۔ مینٹیننس مارجن وہ حفاظتی منزل ہے جو آپ کے ڈیفالٹ کے مقابلے میں ایکسچینج کو پورا کرنے کے لیے کافی ڈپازٹ رکھتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ابتدائی مارجن آپ کو دروازے پر لے جاتا ہے۔ بحالی کا مارجن آپ کو کمرے میں رکھتا ہے۔ چونکہ نقصانات روزانہ طے کیے جاتے ہیں اور براہ راست آپ کے ڈپازٹ سے نکالے جاتے ہیں، آپ کا مارجن بیلنس ایک زندہ نمبر ہے جو حقیقی وقت میں گرتا ہے جب تجارت آپ کے خلاف حرکت کرتی ہے۔</p>\n</div></div>\n<h2 id=\"the-margin-call\">مارجن کال</h2>\n<p>جب روزانہ نقصانات آپ کے مارجن بیلنس کو دیکھ بھال کی سطح سے نیچے لے جاتے ہیں، تو آپ کو ایک موصول ہوتا ہے۔ <strong>مارجن کال</strong>. مارجن کال آپ کے اکاؤنٹ کو مطلوبہ سطح پر واپس اوپر کرنے کا مطالبہ ہے، عام طور پر جلدی۔ یہ مارکیٹ کا یہ کہنے کا طریقہ ہے کہ آپ کا ڈپازٹ اب اتنا بڑا نہیں ہے کہ آپ اس خطرے کو واپس لے سکیں جو آپ لے رہے ہیں۔</p>\n<p>کال آنے پر آپ کے پاس دو انتخاب ہوتے ہیں، اور صرف دو۔ مارجن کو بحال کرنے کے لیے آپ تازہ فنڈز شامل کر سکتے ہیں، یا آپ پوزیشن کو کم یا بند کر سکتے ہیں تاکہ کم مارجن درکار ہو۔ اگر آپ بروقت ایسا نہیں کرتے ہیں، تو آپ کا بروکر آپ کے لیے پوزیشن کو بند کرنے کا حقدار ہے، مارکیٹ جو بھی قیمت پیش کرتا ہے، خود کو اور ایکسچینج کی حفاظت کے لیے۔ یہ زبردستی باہر نکلنا اکثر بدترین ممکنہ لمحے پر اترتا ہے، جب مارکیٹ آپ کے خلاف سب سے زیادہ پرتشدد ہوتی ہے تو نقصان کا سامنا کرنا پڑتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مارجن کال ایک شائستہ یاد دہانی نہیں ہے، یہ ایک آخری تاریخ ہے۔ اسے نظر انداز کریں اور آپ کی پوزیشن خراب قیمت پر آپ کے لیے بند ہو سکتی ہے، کاغذی نقصان کو مستقل میں بدل سکتا ہے۔ تیز رفتار حرکت کے دوران بہت سے اڑا دیئے گئے اکاؤنٹس ایک ہی نظر انداز کردہ مارجن کال پر واپس آتے ہیں۔</p>\n</div></div>\n<h2 id=\"respecting-the-double-edged-sword\">دو دھاری تلوار کا احترام کرنا</h2>\n<p>اس میں سے کوئی بھی مطلب برائی نہیں ہے۔ یہ ایک ٹول ہے، اور ایک قابل ذکر، جو معمولی سرمائے کے ساتھ تاجر کو بامعنی پوزیشن لینے دیتا ہے۔ خطرہ خود کبھی بھی آلہ نہیں ہوتا ہے۔ خطرہ اس سے زیادہ استعمال کر رہا ہے جتنا آپ زندہ رہ سکتے ہیں۔ ایک تاجر جو ایک RELIANCE لاٹ کو یوں سمجھتا ہے جیسے یہ 1,10,000 روپے کی شرط ہو، خود کو بیوقوف بنا رہا ہے۔ یہ 6,59,000 روپے کی پوزیشن ہے، اور یہ ایک کی طرح آگے بڑھے گی۔</p>\n<p>ایماندارانہ ڈھانچہ، جو تاجروں کو اچھا حاصل کرنے کے لیے کافی دیر تک زندہ رکھتا ہے، یہ ہے کہ آپ اپنی پوزیشن کو مکمل نمائش اور جو نقصان آپ اٹھا سکتے ہیں، اس سے آپ کو کبھی بھی چھوٹے مارجن سے نہیں مل سکتا۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>حقیقی سرمائے کو خطرے میں ڈالنے سے پہلے، سینڈ باکس ٹریڈنگ میں لیوریجڈ پوزیشن کھولیں (اونالائزر موڈ OpenAlgo میں) اور قیمت کے بدلتے ہوئے اپنے مارجن کو دیکھیں۔ 5 فیصد سٹاک کی منتقلی کو آپ کے ڈپازٹ پر 30 فیصد جھول بنتے دیکھنا، جس میں کوئی رقم داؤ پر نہیں لگائی گئی، مارکیٹ کی مرضی سے کہیں زیادہ سستا سبق سکھاتا ہے۔</p>\n</div></div>\n<p>ٹیک وے ایک جملہ ہے جو آپ کو ہر مستقبل میں لے جانا چاہئے جو آپ کبھی بھی تجارت کرتے ہیں۔ مارجن وہ ہے جسے آپ پوسٹ کرتے ہیں، لیوریج وہ ہے جسے آپ کنٹرول کرتے ہیں، اور ضرب آپ کو انعام دیتا ہے اور آپ کو بالکل مساوی پیمانے پر سزا دیتا ہے۔ اس بات کا احترام کریں کہ ہم آہنگی اور مستقبل آپ کے ہاتھوں میں ایک سنجیدہ آلہ بن جاتے ہیں۔ اسے بھول جائیں، اور وہی آلہ آپ کو اپنے انتخاب کے دن یاد دلائے گا کہ آپ ہمیشہ پورے 6,59,000 روپے کا خطرہ مول لے رہے تھے نہ کہ اس آرام دہ ڈپازٹ کا جو آپ نے سوچا تھا۔ اگلے باب میں ہم بخوبی دیکھتے ہیں کہ مارک ٹو مارکیٹ کہلانے والے میکانزم کے ذریعے روزانہ کے فوائد اور نقصانات آپ کے اکاؤنٹ کو کس طرح متاثر کرتے ہیں۔</p>\n","toc":[{"level":2,"text":"مارجن، وہ ڈپازٹ جو آپ اصل میں پوسٹ کرتے ہیں۔","id":"margin-the-deposit-you-actually-post"},{"level":2,"text":"مارجن نمبر کہاں سے آتا ہے، SPAN پلس ایکسپوزر","id":"where-the-margin-number-comes-from-span-plus-exposure"},{"level":2,"text":"لیوریج، جمع میں چھپا ہوا ضرب","id":"leverage-the-multiplier-hiding-in-the-deposit"},{"level":2,"text":"ابتدائی مارجن اور دیکھ بھال کا مارجن","id":"initial-margin-and-maintenance-margin"},{"level":2,"text":"مارجن کال","id":"the-margin-call"},{"level":2,"text":"دو دھاری تلوار کا احترام کرنا","id":"respecting-the-double-edged-sword"}],"imgCount":1,"hasContent":true},"10":{"html":"<p>آپ نے کل ایک RELIANCE مستقبل کھولا جس کے پیچھے بیٹھے مفت نقد کے آرام دہ کشن کے ساتھ۔ آج صبح، آپ کے ایک نیا آرڈر دینے سے پہلے، آپ کا بروکر آپ کو وہی پوزیشن بتاتا ہے جو اب کھلے رہنے کے لیے مزید رقم کی ضرورت ہے۔ تم نے کچھ نہیں کیا۔ اسٹاک بمشکل منتقل ہوا ہے۔ پھر بھی آپ کی تجارت کے خلاف ڈیپازٹ کا مطالبہ راتوں رات خاموشی سے بڑھ گیا ہے۔ یہ کوئی خرابی نہیں ہے اور یہ غیر منصفانہ نہیں ہے۔ یہ مارجن سسٹم بالکل وہی کر رہا ہے جو اسے کرنے کے لیے بنایا گیا تھا، اور اسے سمجھنا ہی ایک تاجر کے درمیان فرق ہے جو کبھی کم نہیں پکڑا جاتا اور جو بدترین ممکنہ لمحے پر مجبور ہو جاتا ہے۔ پہلے کے ایک باب میں ڈپازٹ اور اس سے پیدا ہونے والے لیوریج کو متعارف کرایا گیا تھا۔ یہ باب نمبر کے نیچے جاتا ہے یہ بتانے کے لیے کہ یہ کیسے بنایا گیا ہے، یہ کیوں بدلتا ہے، اور آپ خالص نقدی کے بجائے حصص کے ساتھ اسے کیسے بیک کرسکتے ہیں۔</p>\n<h2 id=\"a-quick-recap-span-plus-exposure\">ایک فوری ریکاپ:SPANپلس ایکسپوزر</h2>\n<p>آپ پہلے ہی ان دو ٹکڑوں سے مل چکے ہیں جو فیوچر مارجن بناتے ہیں، لہذا ہم مختصر ہو جائیں گے اور پھر ان کو ماضی میں بنائیں گے۔</p>\n<p>آپ کی جمع کا بڑا حصہ ہے <strong>SPAN مارجن</strong>. SPAN ایکسچینج کا رسک انجن ہے، اور یہ حصہ وہ رقم ہے جو اسے ایک ہی تجارتی دن میں آپ کی پوزیشن کو ہونے والے بدترین نقصان کو پورا کرنے کے لیے ضروری قرار دیتی ہے۔ یہ قیمت اور اتار چڑھاؤ کی ایک پوری رینج کا نمونہ بناتا ہے اور سب سے زیادہ سزا دینے والا قابل احترام لیتا ہے۔ اس کے اوپر بیٹھا ہے۔ <strong>نمائش مارجن</strong>، ایک چھوٹا سا اضافی بفر ایکسچینج کسی اقدام کے خلاف تحفظ کے لیے جوڑتا ہے جو کہ بدترین صورت SPAN سے بھی زیادہ پرتشدد اقدام ہے۔ کوئی بھی حصہ اختیاری نہیں ہے، اور ایک ساتھ ملا کر وہ دیتے ہیں۔ <strong>کل مارجن درکار ہے۔</strong>، اصل نقد جو آرڈر کے گزرنے سے پہلے آپ کے اکاؤنٹ میں مفت ہونا ضروری ہے۔</p>\n<p>ایک RELIANCE لاٹ کے لیے، تقریباً 6,59,000 روپے کے اسٹاک کو کنٹرول کرتے ہوئے، جو کہ کل زمین کہیں 1,10,000 روپے کے قریب ہے، اس میں سے زیادہ تر SPAN کے اوپر ایک پتلی نمائش کے ساتھ۔ 24,000 کے قریب 65 کے ایک NIFTY کی ساخت ایک جیسی ہے، بس مختلف نمبر۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-span-exposure.png\" alt=\"فیوچر پوزیشن پر کل مارجن ایک بڑے SPAN جزو سے بنایا گیا ہے جس میں ایک دن کے بدترین نقصان کے علاوہ ایک چھوٹا ایکسپوژر بفر شامل کیا گیا ہے، اور یہ دونوں مل کر وہ ہیں جو آپ کے اکاؤنٹ میں مفت ہونا چاہیے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>فیوچر پوزیشن پر کل مارجن ایک بڑے SPAN جزو سے بنایا گیا ہے جس میں ایک دن کے بدترین نقصان کے علاوہ ایک چھوٹا ایکسپوژر بفر شامل کیا گیا ہے، اور یہ دونوں مل کر وہ ہیں جو آپ کے اکاؤنٹ میں خالی ہونا چاہیے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>SPAN ایک دن کا سب سے برا خطرہ ہے اور آپ کے ڈپازٹ کا بڑا حصہ بناتا ہے۔ نمائش ایک اضافی بفر ہے جو اس کے اوپر سجا ہوا ہے۔ SPAN پلس ایکسپوژر اس کل مارجن کے برابر ہے جو آپ کو پوسٹ کرنا ہوگا، اور وہ واحد نمبر ہے جو OpenAlgo مارجن کیلکولیٹر آپ کو تجارت سے پہلے دیتا ہے۔</p>\n</div></div>\n<h2 id=\"margins-are-not-fixed\">مارجن مقرر نہیں ہیں۔</h2>\n<p>یہ وہ خیال ہے جو زیادہ تر ابتدائی افراد کبھی نہیں آتے، اور یہ اس باب کا دل ہے۔ معاہدے پر مارجن ہے۔ <strong>ایک مقررہ نمبر نہیں</strong>. اس کا دوبارہ حساب کیا جاتا ہے، اور جب بھی یہ فیصلہ کرتا ہے کہ خطرہ بڑھ گیا ہے تو ایکسچینج اسے بڑھا سکتا ہے۔</p>\n<p>یاد رکھیں SPAN کس چیز کی پیمائش کر رہا ہے: ایک دن کا بدترین نقصان۔ جب کوئی سٹاک یا انڈیکس زیادہ اتار چڑھاؤ کا شکار ہو جاتا ہے، تو اس کا ایک دن کا ممکنہ اقدام بڑا ہو جاتا ہے، اس لیے بدترین صورت میں ہونے والا نقصان زیادہ ہو جاتا ہے، اس لیے اسے پورا کرنے کے لیے درکار مارجن قدم قدم پر چڑھ جاتا ہے۔ ایک پرسکون مارکیٹ میں ایک دبلا مارجن ہوتا ہے۔ ایک اچھلتا ہوا، خوفزدہ بازار ایک موٹا ہوتا ہے۔ زیریں کے اتار چڑھاؤ کے ساتھ جمع سانس لیتا ہے۔</p>\n<p>ایکسچینج معروف واقعات سے پہلے مارجن بھی بڑھاتا ہے۔ قومی بجٹ، مرکزی بینک کی شرح کے فیصلے، عام انتخابات کے نتائج یا کسی کمپنی کی آمدنی سے پہلے، ہر کوئی دیکھ سکتا ہے کہ کوئی بڑا اقدام ممکن ہے۔ ایکسچینج حیران ہونے کا انتظار نہیں کرتا. یہ پہلے سے مارجن کو اٹھا لیتا ہے تاکہ ایونٹ کے اترنے سے پہلے ہر کھلی پوزیشن کو بہتر طور پر کشن کیا جائے۔ یہی وجہ ہے کہ آپ نے ایک پُرسکون ہفتے میں جو پوزیشن کھولی ہے وہ کسی بڑے اعلان سے ایک رات پہلے اچانک نمایاں طور پر زیادہ نقدی کا مطالبہ کر سکتی ہے، حالانکہ قیمت بالکل بھی نہیں بڑھی ہے۔</p>\n<p>عملی ڈنک ٹائمنگ ہے۔ مارجن میں اضافہ عین اس وقت ہوتا ہے جب مارکیٹ گھبراہٹ کا شکار ہو، جو بالکل اس وقت ہوتا ہے جب آپ کی اپنی پوزیشن پہلے سے دباؤ میں ہو۔ اگر آپ کے اکاؤنٹ کو بالکل کنارے تک فنڈ کیا جاتا ہے، تو راتوں رات ہونے والا اضافہ آپ کو ایک کمی کی طرف اشارہ کر سکتا ہے اور آپ کو تیزی سے رقم شامل کرنے یا پوزیشن کو تراشنے پر مجبور کر سکتا ہے۔ تاجر جس نے بفر چھوڑا ہے وہ اسے جذب کرتا ہے اور سو جاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>آج کا آرام دہ مارجن کل کے آرام دہ مارجن کی ضمانت نہیں ہے۔ جب اتار چڑھاؤ بڑھتا ہے یا کوئی بڑا واقعہ قریب آتا ہے تو ایکسچینج ضرورت کو راتوں رات بڑھا سکتا ہے، اس لیے کسی حد تک فنڈ کی گئی پوزیشن آپ کے مقابلے میں ایک روپیہ بڑھائے بغیر قیمت کم ہو سکتی ہے۔</p>\n</div></div>\n<h2 id=\"the-expiry-week-spike-on-stock-futures\">سٹاک فیوچرز پر ایکسپائری ویک اسپائک</h2>\n<p>مارجن میں ایک اور اضافہ ہے، اور یہ بڑا، طے شدہ، اور سنگل اسٹاک فیوچر جیسے RELIANCE کے لیے منفرد ہے۔ جیسے جیسے معاہدہ اپنے آخری دنوں کے قریب آتا ہے، ایکسچینج مارجن کو تیزی سے بڑھانا شروع کر دیتا ہے۔ <strong>جسمانی تصفیہ ہفتہ</strong>.</p>\n<p>وجہ یہ ہے کہ اسٹاک کا مستقبل، انڈیکس کے مستقبل کے برعکس، حصص کی حقیقی ترسیل پر ختم ہوسکتا ہے۔ اگر آپ کے پاس اب بھی RELIANCE مستقبل ہے جب اس کی میعاد ختم ہو جاتی ہے، تو آپ 500 حقیقی حصص دینے یا لینے کے پابند ہو سکتے ہیں، جس کی ضرورت اس پتلے مارجن سے کہیں زیادہ ہے جو آپ کو شرط لگانے دیتا ہے۔ اس بات کو یقینی بنانے کے لیے کہ کوئی بھی اپنے پیچھے بہت کم رقم کے ساتھ حادثاتی طور پر ڈیلیوری میں نہ جائے، ایکسچینج ایکسپائری ہفتے کے دوران مارجن کو مسلسل بڑھاتا ہے، اور اسے کسی ایسے شخص کے لیے مکمل معاہدہ کی قیمت کی طرف دھکیلتا ہے جو ابھی تک بند نہیں ہوا ہے۔</p>\n<p>ہم فزیکل سیٹلمنٹ کو بعد میں اس کا اپنا مکمل باب دیتے ہیں، اس لیے ابھی کے لیے صرف انتباہ کو پکڑیں۔ ایک اسٹاک مستقبل جو پورے مہینے لے جانے کے لیے سستا تھا، اس کے آخری دنوں میں رکھنا بہت مہنگا ہو سکتا ہے، خالصتاً اس طے شدہ اسپائیک کی وجہ سے۔ ایک مبتدی جو صرف ایک لیوریجڈ ڈائریکشنل شرط چاہتا تھا اسے اس ہفتے کے آنے سے پہلے اسٹاک مستقبل کو بند کرنا چاہیے یا اسے رول کرنا چاہیے، بجائے اس کے کہ اچانک کئی گنا بڑھ جانے والے مارجن کی طلب سے حیران ہوں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>انڈیکس فیوچر جیسے کہ NIFTY اور BANKNIFTY نقد میں طے پاتے ہیں اور کوئی ڈیلیوری نہیں ہوتی ہے، اس لیے وہ اس ایکسپائری ہفتہ کی بڑھتی ہوئی تعداد کو نہیں دیکھتے ہیں۔ آخری دنوں میں تیز ریمپ ایک اسٹاک-مستقبل کی خصوصیت ہے، جو جسمانی ترسیل کے خطرے سے چلتی ہے، اور یہ ایک اور وجہ ہے کہ ابتدائی افراد اکثر انڈیکس کو ترجیح دیتے ہیں۔</p>\n</div></div>\n<h2 id=\"collateral-and-pledging-backing-margin-with-holdings\">کولیٹرل اور پلیجنگ: ہولڈنگز کے ساتھ بیکنگ مارجن</h2>\n<p>اب تک ہم نے اس طرح بات کی ہے جیسے مارجن نقد ہونا ضروری ہے۔ یہ سب ہونا ضروری نہیں ہے۔ اگر آپ کے پاس پہلے سے ہی شیئرز، ایکسچینج ٹریڈڈ فنڈز، یا گورنمنٹ بانڈز ہیں، تو آپ انہیں بطور کام کر سکتے ہیں۔ <strong>ضمنی</strong> بڑی رقم کو نقدی میں چھوڑنے کے بجائے۔ میکانزم کہا جاتا ہے۔ <strong>عہد کرنا</strong>.</p>\n<p>جب آپ ہولڈنگ گروی رکھتے ہیں، تو آپ اسے فروخت نہیں کرتے۔ آپ اسے باضابطہ طور پر اپنے تجارتی اکاؤنٹ کے خلاف سیکیورٹی کے طور پر نشان زد کرتے ہیں، اور بدلے میں بروکر آپ کو ایک کریڈٹ دیتا ہے۔ <strong>کولیٹرل مارجن</strong> جسے آپ اپنی مستقبل کی پوزیشنوں پر مارجن کو پورا کرنے کے لیے استعمال کر سکتے ہیں۔ آپ کے حصص آپ کے ہی رہتے ہیں، آپ ان کے طویل مدتی اور کسی بھی منافع کو برقرار رکھتے ہیں، اور وہی سرمایہ اب ایک ساتھ دو کام کر رہا ہے۔</p>\n<p>ایک کیچ ہے، اور یہ اہم ہے۔ آپ جو وعدہ کرتے ہیں اس کی پوری مارکیٹ ویلیو کے برابر مارجن نہیں ملتا۔ نظام لاگو ہوتا ہے a <strong>بال کٹوانے</strong>آپ کو کریڈٹ دینے سے پہلے، ایک جان بوجھ کر کمی۔ اگر آپ 1,00,000 روپے کے حصص گروی رکھتے ہیں اور بال کٹوانے کا تخمینہ لگ بھگ 15 فیصد ہے، تو آپ کو تقریباً 85,000 روپے قابل استعمال مارجن ملے گا، پورے لاکھ نہیں۔ بال کٹوانے کا طریقہ موجود ہے کیونکہ گروی رکھے ہوئے حصص کی قیمت میں خود کمی آسکتی ہے، اس لیے ایکسچینج ہولڈنگ کی قیمت اور اس کے مقابلے میں آپ کو کیا قرض دے گا کے درمیان حفاظت کا ایک فرق رکھتا ہے۔ ایک بڑے انڈیکس فنڈ یا سرکاری بانڈ کی طرح ایک مستحکم ہولڈنگ ایک چھوٹے بال کٹوانے کے ساتھ ہوتا ہے۔ ایک غیر مستحکم واحد اسٹاک ایک بڑا رکھتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-pledge-collateral.png\" alt=\"گروی رکھنے سے حصص، ETFs یا بانڈز کو قابل استعمال مارجن میں بدل دیا جاتا ہے، لیکن بال کٹوانے کا مطلب ہے کہ آپ کو ہولڈنگ کی قیمت سے کم مارجن ملتا ہے، اور نقد جزو کے اصول کے مطابق آپ کے مارجن کا تقریباً نصف حقیقی نقد ہونا ضروری ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>گروی رکھنے سے حصص، ETFs یا بانڈز کو قابل استعمال مارجن میں بدل دیا جاتا ہے، لیکن بال کٹوانے کا مطلب ہے کہ آپ کو ہولڈنگ کی قیمت سے کم مارجن ملتا ہے، اور نقد جزو کے اصول کے مطابق آپ کے مارجن کا تقریباً نصف حقیقی نقد ہونا ضروری ہے۔</figcaption></figure>\n<h2 id=\"the-cash-component-rule\">نقد جزو کا اصول</h2>\n<p>یہ ہمیں اس اصول پر لے آتا ہے جو مفت لنچ بننے سے عہد کرنا بند کر دیتا ہے۔ آپ صرف گروی رکھے ہوئے حصص پر فیوچر اکاؤنٹ نہیں چلا سکتے۔ ایکسچینج نافذ کرتا ہے a <strong>نقد جزو</strong>، یعنی آپ کے کل مارجن کا کم از کم حصہ، تقریباً نصف، اصل نقد یا نقد کے مساوی آلات جیسے مائع فنڈز سے پورا ہونا چاہیے، نہ کہ گروی رکھی ہوئی ایکویٹی کے ساتھ۔</p>\n<p>منطق براہ راست مارک سے مارکیٹ تک چلتی ہے۔ آپ کے یومیہ نقصانات کو ہر ایک دن اصلی نقدی میں ڈیبٹ کیا جاتا ہے۔ نقصان کی ادائیگی کے لیے گروی رکھے ہوئے حصص کو ہر شام تھوڑا سا منڈوایا نہیں جا سکتا، اس لیے ایکسچینج کا اصرار ہے کہ ان روزانہ ڈیبٹ کو حل کرنے کے لیے ایک ٹھوس کیش بیس ہمیشہ موجود رہتا ہے۔ اگر آپ کا نقد حصہ آپ کے گروی رکھے ہوئے ضمانت کے مقابلے میں بہت پتلا ہے، تو بروکر شارٹ فال پر سود وصول کر سکتا ہے یا اس وقت تک نئی پوزیشنوں سے انکار کر سکتا ہے جب تک کہ آپ بیلنس بحال نہ کر لیں۔</p>\n<p>لہذا گروی رکھنے کو بیکار ہولڈنگز کو مفید بنانے کے طریقے کے طور پر سمجھا جاتا ہے، نہ کہ نقد کی ضرورت سے بچنے کے طریقے کے طور پر۔ ایک حقیقت پسندانہ فیوچر اکاؤنٹ روزانہ سیٹلمنٹ اور مارجن میں اضافے کو پورا کرنے کے لیے ایک صحت مند نقد بیلنس رکھتا ہے، اور اپنی صلاحیت کو اس بنیاد سے آگے بڑھانے کے لیے گرویدہ ضمانت کا استعمال کرتا ہے، اسے کبھی نہیں بدلتا۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>گروی رکھے ہوئے حصص کو نقد کے ضمیمہ کے طور پر سمجھیں، کبھی بھی متبادل نہیں۔ اپنے مارجن کے تقریباً نصف کو حقیقی نقد ہونے کے لیے منصوبہ بنائیں کیونکہ روزانہ ہونے والے نقصانات کا تصفیہ نقد میں ہوتا ہے، اور ایک فالتو کیش کشن کو اوپر رکھیں تاکہ مارجن میں اضافہ یا کھونے والے دنوں کی دوڑ آپ کو کسی برے وقت پر قرض اتارنے اور فروخت کرنے پر مجبور نہ کرے۔</p>\n</div></div>\n<h2 id=\"putting-it-to-work-before-every-trade\">ہر تجارت سے پہلے اسے کام پر لگانا</h2>\n<p>اس باب کے دھاگے ایک سادہ عادت سے جڑے ہوئے ہیں۔ فیوچر آرڈر دینے سے پہلے، OpenAlgo مارجن کیلکولیٹر کھولیں، ٹھیک ٹھیک معاہدہ، سائیڈ، اور مقدار درج کریں، اور SPAN، ایکسپوژر، اور کل مارجن کو پڑھیں جیسا کہ وہ ابھی کھڑے ہیں۔ یہ تعداد پہلے سے ہی آج کے اتار چڑھاؤ اور کسی بھی واقعہ سے چلنے والے اضافے کی عکاسی کرتی ہے، اس لیے یہ آپ کو سچ بتاتا ہے کہ اس وقت اس پوزیشن کی قیمت کیا ہے، نہ کہ پچھلے ہفتے اس کی قیمت کتنی ہے۔</p>\n<p>پھر جان بوجھ کر سستی کے ساتھ فنڈ کریں۔ اپنے مفت سرمائے کو مارجن سے بالکل مماثل نہ بنائیں، کیونکہ مارجن راتوں رات بڑھ سکتا ہے، ایکسپائری ہفتہ اسٹاک کے مستقبل کو تیزی سے بڑھا سکتا ہے، اور آپ کے یومیہ نقصانات نقد میں سامنے آتے ہیں۔ ایک تاجر جو ہر پوزیشن کے پیچھے ایک حقیقی نقد بفر رکھتا ہے وہ تینوں کو بغیر ڈرامے کے جذب کر لیتا ہے۔ آخری روپے تک فنڈ فراہم کرنے والا تاجر ان میں سے ہر ایک کو ہنگامی طور پر پورا کرتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>زیادہ تر لیوریجڈ فیوچر ٹریڈرز پیسے کھو دیتے ہیں، اور سمجھے جانے والے ایگزٹ کے بجائے مارجن کی کمی کے باعث مجبور ہونا ایک عام طریقوں میں سے ایک ہے۔ علاج غیر مہذب ہے۔ ہر بار کیلکولیٹر کی جانچ پڑتال کریں، اضافے کے لیے نقد رقم محفوظ رکھیں، اور اس مارجن کو کبھی بھی الجھائیں جو آپ آج اس مارجن کے ساتھ کھرچ سکتے ہیں جو کل ایکسچینج مانگ سکتا ہے۔</p>\n</div></div>\n<p>ٹیک وے مختصر ہے۔ SPAN پلس ایکسپوژر ڈپازٹ ہے، لیکن یہ ڈپازٹ ایک متحرک ہدف ہے جسے ایکسچینج اٹھا لیتا ہے جب اتار چڑھاؤ بڑھتا ہے، بڑے واقعات سے پہلے، اور اسٹاک مستقبل کے ایکسپائری ہفتہ کے ذریعے۔ آپ حصص، ETFs، یا بانڈز کو گروی رکھ کر، استحقاق کے لیے بال کٹوانے کو قبول کر کے اس کا کچھ حصہ واپس کر سکتے ہیں، لیکن نقد جزو کے اصول کا مطلب ہے کہ حقیقی رقم ہمیشہ نیچے بیٹھنی چاہیے۔ موونگ نمبر کا احترام کریں، نقد رقم ہاتھ میں رکھیں، اور مارجن سسٹم آپ کی دوڑ کو ختم کرنے والی چیز کے بجائے کاروبار کرنے کی قابل انتظام لاگت بن جاتا ہے۔</p>\n","toc":[{"level":2,"text":"ایک فوری ریکاپ:SPANپلس ایکسپوزر","id":"a-quick-recap-span-plus-exposure"},{"level":2,"text":"مارجن مقرر نہیں ہیں۔","id":"margins-are-not-fixed"},{"level":2,"text":"سٹاک فیوچرز پر ایکسپائری ویک اسپائک","id":"the-expiry-week-spike-on-stock-futures"},{"level":2,"text":"کولیٹرل اور پلیجنگ: ہولڈنگز کے ساتھ بیکنگ مارجن","id":"collateral-and-pledging-backing-margin-with-holdings"},{"level":2,"text":"نقد جزو کا اصول","id":"the-cash-component-rule"},{"level":2,"text":"ہر تجارت سے پہلے اسے کام پر لگانا","id":"putting-it-to-work-before-every-trade"}],"imgCount":2,"hasContent":true},"11":{"html":"<p>تصور کریں کہ آپ اور ایک دوست کرکٹ میچ پر شرط لگاتے ہیں، لیکن سیٹل ہونے کے لیے آخری گیند تک انتظار کرنے کے بجائے، آپ ہر ایک اوور کے اختتام پر ایک دوسرے کو پیسے دینے پر راضی ہو جاتے ہیں۔ اگر آپ کی ٹیم آگے بڑھتی ہے تو، آج رات آپ کے پاس پیسہ منتقل ہوتا ہے۔ اگر یہ پیچھے پڑ جاتا ہے، تو آپ آج رات پیسے دے دیں گے۔ میچ ختم ہونے تک، طے کرنے کے لیے تقریباً کچھ بھی نہیں بچا ہے، کیونکہ آپ پورے راستے میں اکاؤنٹس کو مربع کرتے رہے ہیں۔ یہ، ایک تصویر میں، یہ ہے کہ مستقبل کی پوزیشن کیسے کام کرتی ہے۔ یہ کوئی خاموش وعدہ نہیں ہے جو ختم ہونے تک اچھوت بیٹھا ہے۔ یہ ہر تجارتی دن کے اختتام پر نقد رقم میں طے ہوتا ہے، اور رقم واقعی آپ کے اکاؤنٹ میں اور باہر منتقل ہوتی ہے۔</p>\n<p>اس روزمرہ کی رسم کو کہتے ہیں۔ <strong>مارک ٹو مارکیٹ</strong>، اکثر مختصر کرکے MTM۔ یہ فیوچر ٹریڈنگ میں سب سے اہم آئیڈیاز میں سے ایک ہے اور ایک ایسا آئیڈیا جسے شروع کرنے والے تقریباً ہمیشہ کم سمجھتے ہیں۔ ایک بار جب آپ یہ سمجھ لیں کہ آپ کی کھلی پوزیشن کی قدر کی جا رہی ہے اور ہر شام کو طے کیا جا رہا ہے، مارجن، مارجن کالز اور راتوں رات خطرے کے بارے میں بہت سے راز غائب ہو جاتے ہیں۔</p>\n<h2 id=\"what-mark-to-market-actually-means\">مارک ٹو مارکیٹ کا اصل مطلب کیا ہے۔</h2>\n<p>کو <strong>مارکیٹ کو نشان زد کریں</strong> موجودہ مارکیٹ کی قیمت پر اپنی پوزیشن کا از سر نو جائزہ لینا اور انتظار کرنے کے بجائے، نقد میں، منافع یا نقصان کو ابھی پہچاننا ہے۔ ایکسچینج مستقبل کی باضابطہ اختتامی قیمت لیتا ہے، جسے کہا جاتا ہے۔ <strong>تصفیہ کی قیمت</strong>، اس کا موازنہ اس قیمت سے کرتا ہے جس پر آپ کی پوزیشن کی آخری قدر کی گئی تھی، اور آپ کے اکاؤنٹ اور آپ کی تجارت کے دوسری طرف جو بھی ہے اس کے اکاؤنٹ کے درمیان فرق کو منتقل کرتا ہے۔</p>\n<p>اگر دن آپ کے راستے پر چلا گیا تو، فائدہ ہے <strong>کریڈٹ</strong> اس شام آپ کے مارجن اکاؤنٹ میں۔ اگر دن آپ کے خلاف گیا تو نقصان ہے۔ <strong>ڈیبٹ</strong> اسی شام آپ کے مارجن اکاؤنٹ سے۔ کوئی IOU نہیں، کوئی میعاد ختم ہونے کا انتظار نہیں، بعد میں کوئی راؤنڈنگ نہیں ہے۔ نقد اصلی ہے اور یہ اگلی صبح تک آپ کے اکاؤنٹ سے نکل چکا ہے یا داخل ہو چکا ہے۔</p>\n<p>دو جملے ایک ہی خیال کو بیان کرتے ہیں، لہذا دونوں کو ذہن میں رکھیں:</p>\n<ul>\n<li><strong>روزانہ تصفیہ</strong> ہر سیشن کے اختتام پر ان اختلافات کو ادا کرنے اور جمع کرنے کا تبادلہ عمل ہے۔</li>\n<li><strong>مارک ٹو مارکیٹ منافع یا نقصان</strong> آپ کی مخصوص پوزیشن کے لیے رقم ہے، آج کی سیٹلمنٹ قیمت اور کل کی قیمت کے درمیان فرق۔</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>فیوچر پوزیشن ہر تجارتی دن نقد میں طے کی جاتی ہے، نہ صرف ختم ہونے پر۔ آپ کا کاغذی منافع یا نقصان ہر سیشن کے اختتام پر آپ کے مارجن اکاؤنٹ میں حقیقی رقم بن جاتا ہے۔</p>\n</div></div>\n<h2 id=\"a-two-day-reliance-example\">دو روزہ RELIANCE مثال</h2>\n<p>نمبرز اس کو ٹھوس بناتے ہیں، تو آئیے ہم مستقبل میں سے ایک بہت زیادہ تجارت کریں۔ لاٹ کا سائز ہے۔ <strong>500 شیئرز</strong>اور ہم لمبے عرصے تک جائیں گے، یعنی ہم پہلے خریدتے ہیں کیونکہ ہمیں توقع ہے کہ قیمت بڑھے گی۔ فرض کریں کہ ہم گول سطح پر داخل ہوتے ہیں۔ <strong>1320</strong>.</p>\n<p>اس ایک لاٹ کو رکھنے کے لیے ایکسچینج جو ابتدائی مارجن مانگتا ہے وہ تقریباً 1,30,000 روپے ہے، اس طرح جس دن ہم داخل ہوتے ہیں اس دن ہمارے مارجن اکاؤنٹ میں موجود کیش ہے۔ اب دیکھیں کہ اگلے دو تجارتی دنوں میں سیٹلمنٹ کی قیمت بڑھنے پر کیا ہوتا ہے۔</p>\n<p>پہلا دن 1335 پر بند ہوتا ہے۔ مستقبل ہماری 1320 کی انٹری سے 15 پوائنٹس بڑھ گیا۔ 500 شیئرز کی لاٹ سے ضرب کریں اور فائدہ 15 گنا 500 ہے جو کہ 7,500 روپے ہے۔ وہ 7,500 روپے شام تک ہمارے اکاؤنٹ میں جمع ہو جاتے ہیں۔</p>\n<p>دوسرا دن 1326 پر بند ہوتا ہے۔ دیکھیں کہ موازنہ کل کے 1335 کے تصفیے سے ہے، ہماری اصل اندراج نہیں۔ مستقبل 1335 سے 1326 پر 9 پوائنٹس گر گیا۔ 500 سے ضرب کریں اور نقصان 9 گنا 500 ہے جو کہ 4,500 روپے ہے۔ وہ 4,500 روپے اسی شام ہمارے اکاؤنٹ سے ڈیبٹ ہو گئے۔</p>\n<p>یہاں ایک میز کے طور پر ایک ہی کہانی ہے.</p>\n<table>\n<thead>\n<tr>\n<th>دن</th>\n<th>تصفیہ کی قیمت</th>\n<th>منتقل بمقابلہ پچھلے قریب</th>\n<th>روزانہ MTM (لاٹ 500)</th>\n<th>مارجن اکاؤنٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>داخلہ</td>\n<td>1320</td>\n<td>حوالہ قیمت</td>\n<td>صفر</td>\n<td>1,30,000 روپے</td>\n</tr>\n<tr>\n<td>دن 1</td>\n<td>1335</td>\n<td>15 پوائنٹس بڑھ گئے۔</td>\n<td>علاوہ 7,500 روپے</td>\n<td>1,37,500 روپے</td>\n</tr>\n<tr>\n<td>دن 2</td>\n<td>1326</td>\n<td>9 پوائنٹس نیچے</td>\n<td>مائنس 4500 روپے</td>\n<td>1,33,000 روپے</td>\n</tr>\n</tbody></table>\n<p>دو دن کے بعد مستقبل 1326 پر بیٹھتا ہے، جو کہ ہمارے 1320 کے اندراج سے 6 پوائنٹس زیادہ ہے۔ چھ پوائنٹس گنا 500 شیئرز 3,000 روپے ہیں، اور یقینی طور پر اکاؤنٹ 1,30,000 روپے سے بڑھ کر 1,33,000 روپے ہو گیا ہے، بالکل 3,000 روپے کا خالص فائدہ۔ روزانہ کی بستیاں ہمیشہ کل حرکت میں اضافہ کرتی ہیں۔ مارک ٹو مارکیٹ یہ تبدیل نہیں کرتا کہ آپ آخر میں کتنا کماتے یا کھوتے ہیں۔ یہ وقت بدلتا ہے، ایک بڑی تصفیہ کو کئی چھوٹے روزانہ میں توڑ دیتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>پہلے دن ہماری لمبی لاٹ نے 7,500 روپے کمائے اور اسی شام اکاؤنٹ میں نقد رقم آ گئی۔ ہمیں اسے جمع کرنے کے لیے تجارت کو بند کرنے کی ضرورت نہیں تھی۔ اسی طرح، دوسرے دن کا 4,500 روپے کا نقصان اسی شام نکال لیا گیا، چاہے ہمیں یہ پسند آئے یا نہ لگے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-mark-to-market.png\" alt=\"روزانہ سیٹلمنٹ تین سیشنز میں کیسے چلتی ہے، جس میں منافع جمع کیا جاتا ہے اور نقصان ختم ہونے کا انتظار کرنے کی بجائے ہر دن کے اختتام پر مارجن اکاؤنٹ میں ڈیبٹ ہوتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>روزانہ سیٹلمنٹ تین سیشنز میں کیسے چلتی ہے، جس میں منافع جمع کیا جاتا ہے اور نقصان ختم ہونے کا انتظار کرنے کی بجائے ہر دن کے اختتام پر مارجن اکاؤنٹ میں ڈیبٹ ہوتا ہے۔</figcaption></figure>\n<h2 id=\"why-the-exchange-insists-on-daily-settlement\">ایکسچینج روزانہ تصفیہ پر اصرار کیوں کرتا ہے</h2>\n<p>جب آپ کے اکاؤنٹ سے راتوں رات نقصان نکالا جاتا ہے تو مارک ٹو مارکیٹ مداخلت محسوس کر سکتا ہے، لیکن یہ آپ کی حفاظت کے لیے موجود ہے جتنا کسی کی بھی۔ یہ دیکھنے کے لیے کہ کیوں، اس کے بغیر دنیا کی تصویر بنائیں۔</p>\n<p>فرض کریں کہ نقصانات ایک ماہ کے لیے خاموشی سے جمع ہوئے اور صرف میعاد ختم ہونے پر جمع کیے گئے۔ ہارنے والی طرف کا تاجر اپنے جمع کردہ نقدی سے کہیں زیادہ نقصان اٹھا سکتا ہے، پھر بس چلا جاتا ہے اور ادائیگی سے انکار کر سکتا ہے۔ جیتنے والے فریق کے پاس ایسا منافع باقی رہ جائے گا جو صرف کاغذ پر موجود ہے اور کوئی بھی اسے عزت دینے کے قابل نہیں ہوگا۔ پوری مارکیٹ بھروسے پر قائم رہے گی، اور اعتماد ٹوٹ جائے گا۔</p>\n<p>روزانہ تصفیہ نقصانات کو کبھی بھی کسی کا دھیان نہیں بڑھنے دے کر اس خطرے کو دور کرتا ہے۔ ہر شام، حسابات مربع ہوتے ہیں۔ چھوٹے نقصانات کو جمع کیا جاتا ہے اس سے پہلے کہ وہ ان رقموں میں سنوبال کریں جو تاجر ادا نہیں کر سکتا۔ اس طرح ایکسچینج اور اس کی کلیئرنگ کارپوریشن اس بات کی ضمانت دیتی ہے کہ فاتح کو ہمیشہ ادائیگی کی جاتی ہے۔</p>\n<ul>\n<li>یہ ایک دن کے اقدام تک کتنا کریڈٹ رسک بنا سکتا ہے۔</li>\n<li>یہ تاجروں کو مجبور کرتا ہے کہ وہ اپنی پوزیشن واپس لینے کے لیے اپنے اکاؤنٹ میں کافی رقم رکھیں۔</li>\n<li>اس کا مطلب ہے کہ آپ کی تجارت کے دوسری طرف کا شخص ہمیشہ مکمل ہو جاتا ہے، کیونکہ تبادلہ درمیان میں ہوتا ہے۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>وہ ادارہ جو اس روزانہ تصفیہ کو انجام دیتا ہے اور دونوں فریقوں کی ضمانت دیتا ہے وہ کلیئرنگ کارپوریشن ہے۔ آپ کبھی بھی اس سے براہ راست ڈیل نہیں کرتے ہیں، لیکن یہی وجہ ہے کہ آپ کی تجارت کے دوسری طرف کوئی اجنبی آپ کو کبھی بھی بلا معاوضہ نہیں چھوڑ سکتا۔</p>\n</div></div>\n<h2 id=\"margin-top-ups-and-the-margin-call\">مارجن ٹاپ اپس اور مارجن کال</h2>\n<p>روزانہ تصفیہ سیدھے مارجن سے منسلک ہوتا ہے۔ یاد رکھیں کہ آپ نے پوزیشن کھولنے کے لیے ابتدائی مارجن پوسٹ کیا تھا۔ چونکہ مارک ٹو مارکیٹ نقصانات شام کے بعد شام کو ڈیبٹ کیے جاتے ہیں، یہ کشن سکڑ جاتا ہے۔ ایکسچینج ایک نچلی حد مقرر کرتا ہے جسے کہا جاتا ہے۔ <strong>بحالی مارجن</strong>. اگر آپ کے اکاؤنٹ کا بیلنس اس سے نیچے آتا ہے، تو آپ کو کیش بیک شامل کرنے کا مطالبہ موصول ہوتا ہے، اور وہ مطالبہ ہے۔ <strong>مارجن کال</strong>.</p>\n<p>ہماری مثال کو جاری رکھتے ہوئے، تصور کریں کہ RELIANCE ٹھیک ہونے کے بجائے گرتا رہتا ہے۔ ہر شام ایک اور نقصان ڈیبٹ کیا جاتا ہے۔ تیسرا دن مستقبل کو 1300 تک لے جاتا ہے، دوسرے دن کے 1326 سے 26 پوائنٹ گرا، جو 26 گنا 500، یا 13,000 روپے کا نقصان ہے۔ اکاؤنٹ، پہلے ہی 1,33,000 روپے پر، گر کر 1,20,000 روپے پر آ گیا ہے۔ اس طرح کے کچھ اور سرخ دن اور توازن دیکھ بھال کی سطح کے نیچے کھسک جاتا ہے۔ اس وقت بروکر آپ سے مارجن کو اوپر کرنے کو کہتا ہے، اکثر اگلی صبح تک۔</p>\n<p>اگر آپ نقد رقم شامل نہیں کرتے ہیں، تو بروکر آپ کے لیے آپ کی پوزیشن کو بند کرنے کا حقدار ہے، نقصان کو بند کر کے چاہے آپ باہر نکلنا چاہتے ہیں یا نہیں۔ یہ دلال سخت نہیں ہے۔ یہ وہی روزانہ تصفیہ کی منطق ہے جو ہر کسی کو ایسے تاجر سے بچاتی ہے جو اب اپنی پوزیشن کو فنڈ نہیں دے سکتا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مارجن کال اختیاری نہیں ہے۔ اگر آپ وقت پر فنڈز شامل نہیں کر سکتے ہیں یا نہیں کر سکتے ہیں، تو بروکر آپ کی پوزیشن کو بدترین ممکنہ لمحے میں ختم کر سکتا ہے۔ فالتو کیش کو ہمیشہ کم از کم مارجن سے آگے رکھیں تاکہ چند برے دن آپ کو باہر کرنے پر مجبور نہ کر سکیں۔</p>\n</div></div>\n<h2 id=\"why-you-can-never-ignore-an-open-position\">کیوں آپ کبھی بھی کھلی پوزیشن کو نظر انداز نہیں کر سکتے</h2>\n<p>مارک ٹو مارکیٹ کا سب سے گہرا سبق یہ ہے کہ مستقبل کی پوزیشن زندہ ہے۔ یہ کوئی سرٹیفکیٹ نہیں ہے جسے آپ ہٹا کر بھول جاتے ہیں۔ ہر تجارتی دن اس کا دوبارہ جائزہ لیا جاتا ہے، اور حقیقی رقم حرکت میں آتی ہے۔ یہ ایک شیئر کے مالک ہونے سے بہت مختلف ہے، جو آپ کے اکاؤنٹ میں سالوں تک بیٹھ سکتا ہے جب تک کہ آپ اسے نظر انداز کر دیتے ہیں، جب تک آپ فروخت کرنے کا انتخاب نہیں کرتے، نقصان کاغذ پر ہی رہتا ہے۔</p>\n<p>مستقبل کی پوزیشن شائستگی سے انتظار نہیں کرے گی۔ کھوئے ہوئے دنوں کا ایک دوڑ خاموشی سے آپ کا مارجن ختم کر دیتا ہے، اور اگر آپ نہیں دیکھ رہے ہیں، تو مارجن کال یا زبردستی باہر نکلنے کا وقت آ سکتا ہے جب کہ آپ کا دھیان کہیں اور ہو۔ فلپ سائیڈ بھی اتنا ہی سچ ہے۔ منافع آپ کو روزانہ کیش میں دیا جاتا ہے، جو کہ فیوچر کو فعال تاجروں کے لیے پرکشش بنانے کا حصہ ہے۔</p>\n<ul>\n<li>ہر ایک تجارتی دن اپنی کھلی پوزیشنوں اور مارجن بیلنس کو چیک کریں۔</li>\n<li>نقد رقم کا بفر رکھیں تاکہ عام کھونے کی وجہ مارجن کال کو متحرک نہ کرے۔</li>\n<li>یاد رکھیں کہ تصفیہ کی قیمت، وہ قیمت نہیں جو آپ نے دن کے دوران دیکھی، شام کی نقدی کی نقل و حرکت کا فیصلہ کرتی ہے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اس سے پہلے کہ آپ حقیقی مستقبل کی پوزیشن لیں، دیکھیں کہ سینڈ باکس ٹریڈنگ میں مارک ٹو مارکیٹ کیسا برتاؤ کرتا ہے ( OpenAlgo میں تجزیہ کار وضع)۔ پیسے کو خطرے میں ڈالے بغیر روزانہ کریڈٹ اور ڈیبٹ دیکھنا روزانہ کی تصفیہ کی تال کو واضح کرتا ہے۔</p>\n</div></div>\n<p>مارک ٹو مارکیٹ فیوچر مارکیٹ کے دل کی دھڑکن ہے۔ یہ ہر شام آپ کی پوزیشن کی قدر کرتا ہے، حقیقی نقد رقم منتقل کرتا ہے، ایکسچینج کو ڈیفالٹ سے بچاتا ہے، اور مطالبہ کرتا ہے کہ آپ کھلی تجارت کے لیے جاگتے رہیں۔ اس تال میں مہارت حاصل کریں اور باقی فیوچر ٹریڈنگ، مارجن سے لے کر لیوریج تک، سمجھ میں آنے لگتی ہے۔</p>\n","toc":[{"level":2,"text":"مارک ٹو مارکیٹ کا اصل مطلب کیا ہے۔","id":"what-mark-to-market-actually-means"},{"level":2,"text":"دو روزہ RELIANCE مثال","id":"a-two-day-reliance-example"},{"level":2,"text":"ایکسچینج روزانہ تصفیہ پر اصرار کیوں کرتا ہے","id":"why-the-exchange-insists-on-daily-settlement"},{"level":2,"text":"مارجن ٹاپ اپس اور مارجن کال","id":"margin-top-ups-and-the-margin-call"},{"level":2,"text":"کیوں آپ کبھی بھی کھلی پوزیشن کو نظر انداز نہیں کر سکتے","id":"why-you-can-never-ignore-an-open-position"}],"imgCount":1,"hasContent":true},"12":{"html":"<p>آپ ایک NIFTY مستقبل خریدتے ہیں، مارکیٹ آپ کے راستے کو دس پوائنٹس تک لے جاتی ہے، آپ اپنے آپ سے خوش ہوکر تجارت بند کردیتے ہیں، اور پھر بھی آپ کا اکاؤنٹ دس پوائنٹس کے ایک سادہ فائدہ سے تھوڑا چھوٹا ہے۔ کچھ بھی غلط نہیں ہوا۔ آپ نے ابھی خاموش سچائی کو پورا کیا ہے جو ہر فیوچر ٹریڈر کو جلد سیکھنا پڑتا ہے: ایک راؤنڈ ٹرپ کبھی بھی مفت نہیں ہوتا ہے۔ جس لمحے آپ خریدتے ہیں اور بیچتے ہیں اس لمحے کے درمیان، چارجز کا ایک چھوٹا سا ڈھیر نکال لیا جاتا ہے، اور سال کے آخر میں ٹیکس ڈیپارٹمنٹ کے ساتھ ایک الگ حساب کا انتظار ہوتا ہے۔ دونوں میں سے کوئی بھی اتنا بڑا نہیں ہے کہ آپ کو ڈرا سکے، لیکن دونوں ہی اتنے بڑے ہیں کہ اگر آپ انہیں نظر انداز کرتے ہیں تو آپ کو برباد کر دیتے ہیں۔ یہ باب پہلے اصل تصدیق شدہ نمبروں کے ساتھ لاگت کے اسٹیک سے گزرتا ہے، اور پھر اس کے ذریعے کہ ہندوستان آپ کی بنائی ہوئی چیزوں پر کس طرح ٹیکس لگاتا ہے۔</p>\n<h2 id=\"the-costs-hiding-inside-every-trade\">ہر تجارت کے اندر چھپے ہوئے اخراجات</h2>\n<p>جب آپ مستقبل کی تجارت کرتے ہیں، تو کئی مختلف فریق ایک چھوٹا سا ٹکڑا لیتے ہیں۔ آپ کا بروکر آرڈر پر عمل درآمد کرنے کے لیے فیس لیتا ہے۔ حکومت ٹرانزیکشن ٹیکس اور سٹیمپ ڈیوٹی وصول کرتی ہے۔ اس کے مماثل نظام کے استعمال کے لیے ایکسچینج چارجز۔ مارکیٹ ریگولیٹر کو ایک sliver لیتا ہے. اور ان میں سے کچھ کے اوپر، سامان اور خدمات ٹیکس لاگو ہوتا ہے۔ ان میں سے کوئی بھی بے ایمانی میں پوشیدہ نہیں ہے، لیکن یہ اتنی ساری لکیروں میں پھیلے ہوئے ہیں کہ کوئی ابتدائی شخص انہیں اس وقت تک شامل نہیں کرتا جب تک کہ وہ کاٹ نہ لیں۔</p>\n<p>سمجھنے کی واحد سب سے اہم بات یہ ہے کہ ان میں سے زیادہ تر چارجز a ہیں۔ <strong>کاروبار کا فیصد</strong>، فلیٹ فیس نہیں۔ یہاں ٹرن اوور کا مطلب ہے روپیہ کی قیمت جس کی آپ تجارت کرتے ہیں، خرید اور فروخت دونوں کو شمار کرتے ہیں۔ ایک عام ڈسکاؤنٹ بروکر پر صرف بروکریج فلیٹ ہے۔ باقی سب کچھ آپ کے تجارتی سائز اور معاہدے کی قیمت بڑھنے کے ساتھ بڑھتا ہے۔</p>\n<p>یہاں NSE فیوچر ٹریڈ کے اجزاء ہیں، صاف الفاظ میں:</p>\n<ul>\n<li><strong>دلالی۔</strong> ایک عام ڈسکاؤنٹ بروکر تقریباً 20 روپے فی عمل شدہ آرڈر کی فلیٹ فیس لیتا ہے۔ راؤنڈ ٹرپ دو آرڈرز ہیں، ایک داخل ہونے کے لیے اور ایک باہر نکلنے کے لیے، اس طرح کل تقریباً 40 روپے بنتے ہیں۔ نوٹ کریں کہ یہ تبدیل نہیں ہوتا ہے چاہے آپ 24,000 کے قریب ایک لاٹ کی تجارت کریں یا اس سے کہیں زیادہ قیمت والا معاہدہ۔ یہ ایک مقررہ فیس ہے، فیصد نہیں۔</li>\n<li><strong>سیکیورٹیز ٹرانزیکشن ٹیکس (STT)۔</strong> صرف تجارت کی سیل سائیڈ ویلیو پر 0.05% چارج کیا جاتا ہے۔ آپ اسے اس وقت ادا کرتے ہیں جب آپ لمبا بند کرتے ہیں یا شارٹ کھولتے ہیں، اس بیچنے والی ٹانگ کی روپے کی قیمت پر۔</li>\n<li><strong>ایکسچینج ٹرانزیکشن چارجز۔</strong> ٹرن اوور کا تقریباً 0.0019%، آپ کے آرڈر کی مماثلت کے بدلے ایکسچینج کو ادا کیا گیا۔</li>\n<li><strong>SEBI چارجز۔</strong> ٹرن اوور کا ایک چھوٹا 0.0001%، جو مارکیٹ ریگولیٹر کو ادا کیا جاتا ہے۔</li>\n<li><strong>سٹیمپ ڈیوٹی</strong> 0.002% صرف خریداری کی طرف، ریاستی حکومت کے ذریعہ جمع کیا گیا ہے۔</li>\n<li><strong>GST۔</strong> سامان اور خدمات پر 18% ٹیکس، لیکن صرف بروکریج کے علاوہ ایکسچینج ٹرانزیکشن چارجز کے علاوہ SEBI چارجز پر چارج کیا جاتا ہے۔ یہ سروس فیس پر ٹیکس ہے، آپ کے پورے کاروبار پر نہیں۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اخراجات کے لیے ٹرن اوور کا مطلب ہے دونوں ٹانگوں کی قدر ایک ساتھ شامل کی گئی ہے۔ 24,000 کے قریب 65 کے ایک لاٹ کی قیمت تقریباً 15,60,000 روپے ہے، اس لیے ایک بار خرید و فروخت پر تقریباً 31,20,000 روپے کا کاروبار ہوتا ہے۔ یہی وجہ ہے کہ ایک چکر کا سفر بھی اصلی روپوں میں اضافہ کرتا ہے۔</p>\n</div></div>\n<h2 id=\"one-nifty-lot-start-to-finish\">ایک NIFTY لاٹ، ختم کرنا شروع کریں۔</h2>\n<p>نمبرز اسے فہرست سے سبق میں بدل دیتے ہیں۔ ہمارا معیاری NIFTY اینکر لیں: 65 کا ایک لاٹ، 24,000 کے قریب خریدا اور فروخت ہوا۔ ہر ٹانگ کی قیمت تقریباً 15,60,000 روپے ہے، لہذا راؤنڈ ٹرپ ٹرن اوور تقریباً 31,20,000 روپے ہے۔ یہاں بالکل وہی ہے جو سامنے آتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>چارج</th>\n<th>ایک NIFTY لاٹ، 24,000 کے قریب خریدا اور فروخت ہوا۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ٹرن اوور (دونوں ٹانگیں)</td>\n<td>تقریباً 31,20,000 روپے</td>\n</tr>\n<tr>\n<td>دلالی</td>\n<td>40 روپے</td>\n</tr>\n<tr>\n<td>STT</td>\n<td>780 روپے</td>\n</tr>\n<tr>\n<td>ایکسچینج ٹرانزیکشن چارجز</td>\n<td>57.10 روپے</td>\n</tr>\n<tr>\n<td>GST</td>\n<td>18.04 روپے</td>\n</tr>\n<tr>\n<td>SEBI چارجز</td>\n<td>3.12 روپے</td>\n</tr>\n<tr>\n<td>سٹیمپ ڈیوٹی</td>\n<td>31 روپے</td>\n</tr>\n<tr>\n<td><strong>راؤنڈ ٹرپ کی کل لاگت</strong></td>\n<td><strong>تقریباً 929 روپے</strong></td>\n</tr>\n<tr>\n<td><strong>پوائنٹس کو توڑنے کے لیے مستقبل کو آگے بڑھنا چاہیے۔</strong></td>\n<td><strong>تقریباً 14.3 پوائنٹس</strong></td>\n</tr>\n</tbody></table>\n<p>اس آخری لائن کے ساتھ بیٹھیں، کیونکہ یہ باب کا پورا نقطہ ہے۔ اس سے پہلے کہ آپ ایک روپیہ منافع کمائیں، NIFTY کو صرف ایک لاٹ ٹریڈنگ کی لاگت کو پورا کرنے کے لیے آپ کے حق میں تقریباً 14 پوائنٹس کو منتقل کرنا ہوگا۔ اگر مستقبل صرف دس پوائنٹس اوپر جاتا ہے اور آپ بند ہوجاتے ہیں، تو قیمتیں فائدہ اٹھاتی ہیں اور آپ تھوڑا سا نیچے ختم ہوجاتے ہیں حالانکہ آپ کی سمت درست تھی۔ مارکیٹ آپ کو ان 14 پوائنٹس کا مقروض نہیں ہے۔ تجارت کے برابر ہونے سے پہلے آپ کو انہیں کمانا ہوگا۔</p>\n<p>یہ بھی دیکھیں کہ کون سا چارج غالب ہے۔ STT 780 روپے میں اب تک کا سب سے بڑا ٹکڑا ہے، اور یہ فروخت کی قیمت کا سیدھا فیصد ہے۔ 40 روپے کا فلیٹ بروکریج تقابل کے لحاظ سے تقریباً سوچا سمجھا ہے۔ یہی وجہ ہے کہ فی صد چارجز، بروکر کی فیس نہیں، زیادہ تر تجارتوں پر آپ کی اصل قیمت کا فیصلہ کرتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-cost-stack.png\" alt=\"ایک NIFTY راؤنڈ ٹرپ پر لگائے گئے سات چارجز، یہ ظاہر کرتے ہیں کہ فیصد کی بنیاد پر STT فلیٹ بروکریج کو بونا کرتا ہے اور یہ کہ وہ مل کر تقریباً 929 روپے تک کا اضافہ کرتے ہیں، تقریباً 14 پوائنٹس جو مستقبل کو کوئی بھی منافع شروع ہونے سے پہلے منتقل ہونا چاہیے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک NIFTY راؤنڈ ٹرپ پر لگائے گئے سات چارجز، یہ ظاہر کرتے ہیں کہ فیصد پر مبنی STT فلیٹ بروکریج کو بونا کرتا ہے اور یہ کہ وہ مل کر تقریباً 929 روپے تک کا اضافہ کرتے ہیں، تقریباً 14 پوائنٹس جو مستقبل کو کوئی بھی منافع شروع ہونے سے پہلے منتقل ہونا چاہیے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>لاگت ایک رکاوٹ ہے جسے آپ منافع شروع ہونے سے پہلے صاف کرتے ہیں۔ ایک NIFTY لاٹ کو آپ کے حق میں تقریباً 14 پوائنٹس کو صرف بریک ایون کرنے کے لیے منتقل کرنا چاہیے۔ اپنے اندراجات اور اہداف کی منصوبہ بندی کریں یہ جانتے ہوئے کہ پہلے 14 پوائنٹس لاگت کے اسٹیک سے تعلق رکھتے ہیں، آپ کے نہیں۔</p>\n</div></div>\n<h2 id=\"costs-grow-with-turnover\">ٹرن اوور کے ساتھ اخراجات بڑھتے ہیں۔</h2>\n<p>چونکہ زیادہ تر اسٹیک ایک فیصد ہے، اس لیے آپ کی قیمتیں یا تو معاہدے کی قیمت یا حصص کی تعداد میں اضافے کے ساتھ بڑھ جاتی ہیں۔ بروکریج فلیٹ رہتا ہے، لیکن STT اور ایکسچینج، SEBI اور اسٹامپ چارجز تمام ٹرن اوور کے ساتھ بڑھ جاتے ہیں۔ اسٹاک مستقبل کی دو مثالیں اس کو واضح کرتی ہیں۔</p>\n<p>1,000 روپے کے قریب 500 حصص کی تجارت کا سنگل اسٹاک مستقبل لیں۔ راؤنڈ ٹرپ کی لاگت تقریباً 330 روپے بنتی ہے، جو کہ 500 شیئرز پر صرف 0.66 پوائنٹس ہے۔ مستقبل کو توڑنے کے لیے آپ کے حق میں بمشکل دو تہائی روپیہ منتقل کرنا ہوگا۔</p>\n<p>اب وہی 500 شیئرز لیں، لیکن 10,000 روپے کے قریب اسٹاک ٹریڈنگ پر۔ کاروبار دس گنا بڑا ہے، اور لاگت تقریباً 2,875 روپے تک پہنچ جاتی ہے، جو کہ 500 حصص میں تقریباً 5.75 پوائنٹس ہے۔ ایک ہی مقدار، وہی فلیٹ بروکریج، لیکن فی صد چارجز تقریباً نو گنا بڑھ گئے ہیں کیونکہ تجارت کی روپے کی قدر دس ​​گنا زیادہ ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>معاہدہ</th>\n<th>راؤنڈ ٹرپ لاگت</th>\n<th>پوائنٹس میں لاگت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1000 روپے کے قریب 500 شیئرز</td>\n<td>تقریباً 330 روپے</td>\n<td>تقریباً 0.66 پوائنٹس</td>\n</tr>\n<tr>\n<td>10,000 روپے کے قریب 500 شیئرز</td>\n<td>تقریباً 2,875 روپے</td>\n<td>تقریباً 5.75 پوائنٹس</td>\n</tr>\n<tr>\n<td>24,000 کے قریب ایک NIFTY لاٹ</td>\n<td>تقریباً 929 روپے</td>\n<td>تقریباً 14.3 پوائنٹس</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اصل خطرہ ایک تجارت نہیں ہے، یہ بہت سے ہیں۔ ایک تاجر جو دن میں دس چکر لگاتا ہے وہ اس لاگت کو دس گنا ادا کرتا ہے۔ NIFTY لاٹ پر جو کہ ایک دن میں تقریباً 9,000 روپے کی لاگت ہے، جیتیں یا ہاریں۔ اوور ٹریڈنگ خاموشی سے اکاؤنٹ کو خراب کرتی ہے یہاں تک کہ جب زیادہ تر کالیں درست ہوں، کیونکہ اخراجات یقینی ہیں اور منافع نہیں ہیں۔</p>\n</div></div>\n<p>اس سے بچنے کی کوئی تدبیر نہیں، صرف نظم و ضبط۔ کم تجارت کریں، بہتر تجارت کریں، اور اپنے ہدف کو سائز دیں تاکہ یہ لاگت کی رکاوٹ کو آرام سے صاف کر دے۔ OpenAlgo جیسے ٹولز آپ کو اپنے فلز کو دیکھنے اور آرڈر بک اور ٹریڈ بک کا جائزہ لینے دیتے ہیں، لہذا سیشن کے اخراجات وہ ہیں جو آپ دیکھ سکتے ہیں اور حساب کر سکتے ہیں، مہینے کے آخر میں کوئی ناگوار حیرت نہیں۔</p>\n<h2 id=\"how-futures-profits-are-taxed\">مستقبل کے منافع پر ٹیکس کیسے لگایا جاتا ہے۔</h2>\n<p>لاگت تجارت کے ذریعہ تجارت سے باہر آتی ہے۔ ٹیکس سال میں ایک بار آتا ہے، اور یہ فیوچر کے ساتھ بہت مختلف سلوک کرتا ہے اس سے کہ یہ حصص کے ساتھ کیا سلوک کرتا ہے۔ یہ حصہ ہندوستان کے لیے مخصوص ہے اور اس کی اہمیت ہے۔</p>\n<p>ٹریڈنگ فیوچر سے آمدنی ہے۔ <strong>غیر قیاس آرائی پر مبنی کاروباری آمدنی</strong>. اس جملے میں وزن ہے۔ ایکویٹی شیئرز کی انٹرا ڈے خرید و فروخت کو سمجھا جاتا ہے۔ <em>قیاس آرائی پر مبنی</em> کاروباری آمدنی، لیکن ایک تسلیم شدہ اسٹاک ایکسچینج میں تجارت کی جانے والی فیوچرز اور آپشنز کو خاص طور پر انکم ٹیکس ایکٹ (سیکشن 43(5) کا شرط) کے ذریعے قیاس آرائی کے زمرے سے نکالا جاتا ہے، اس لیے ان کا شمار غیر قیاس آرائی پر مبنی کاروباری آمدنی کے طور پر کیا جاتا ہے جس طرح بھی وہ طے کرتے ہیں۔ چونکہ یہ کاروباری آمدنی ہے، آپ اس کی اطلاع دیں۔ <strong>ITR-3</strong>کاروبار اور پیشہ ورانہ آمدنی کے لیے واپسی کا فارم، نہ کہ کیپیٹل گین کے طور پر۔</p>\n<p>عملی نتیجہ سادہ اور قدرے مایوس کن ہے۔ آپ کے مستقبل کے منافع کو سال کے لیے آپ کی دیگر تمام آمدنیوں میں شامل کیا جاتا ہے، جیسے تنخواہ، سود یا کرایہ، اور کل آپ کے معمول پر ٹیکس لگایا جاتا ہے۔ <strong>سلیب کی شرح</strong>. فیوچرز کے لیے کوئی خاص کم شرح نہیں ہے جس طرح کچھ طویل مدتی کیپیٹل گینز کے لیے ہے، اور STT جو آپ نے راستے میں ادا کیے ہیں وہ آپ کو ٹیکس کے خلاف کوئی چھوٹ نہیں دیتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>قیاس آرائی پر مبنی بمقابلہ غیر قیاس آرائی اس بارے میں نہیں ہے کہ تجارت کتنی خطرناک محسوس ہوتی ہے۔ یہ ٹیکس کی درجہ بندی ہے۔ انٹرا ڈے ایکویٹی قیاس آرائی پر مبنی ہے، مستقبل اور اختیارات غیر قیاس آرائی پر مبنی کاروباری آمدنی ہیں۔ لیبل فیصلہ کرتا ہے کہ کون سے نقصانات کو پورا کر سکتے ہیں کون سے فوائد، یہ وہ جگہ ہے جہاں یہ واقعی شمار ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"setting-off-losses-and-the-audit-question\">نقصانات اور آڈٹ کا سوال طے کرنا</h2>\n<p>کاروبار میں ہونے والے نقصانات ضائع نہیں ہوتے، اور یہ وہ جگہ ہے جہاں غیر قیاس آرائی پر مبنی لیبل اپنی برقراری حاصل کرتا ہے۔ غیر قیاس آرائی پر مبنی کاروباری نقصان ہو سکتا ہے۔ <strong>اسی سال میں زیادہ تر دیگر آمدنی کے سربراہوں کے خلاف شروع کیا</strong>تنخواہ کی اہم رعایت کے ساتھ۔ لہذا مستقبل میں ایک خراب سال آپ کے دوسرے کاروبار یا کرایہ کی آمدنی پر اس سال ٹیکس کو کم کر سکتا ہے۔</p>\n<p>اگر نقصان اس سے زیادہ ہے جو آپ اسی سال میں جذب کر سکتے ہیں، تو غیر جذب شدہ حصہ ہو سکتا ہے <strong>آٹھ سال تک آگے بڑھا</strong> اور مستقبل کے کاروباری منافع کے خلاف شروع کر دیا. ایک پختہ شرط ہے: آپ کو وقت پر اپنا ریٹرن فائل کرنا ہوگا۔ فائل کرنے کی آخری تاریخ ختم ہو جاتی ہے اور آپ اس نقصان کو آگے بڑھانے کا حق کھو دیتے ہیں، جو کہ لاپرواہی کا ایک مہنگا ٹکڑا ہو سکتا ہے۔</p>\n<p>دو اور خیالات جو آپ کو کم از کم پہچاننے چاہئیں:</p>\n<ul>\n<li><strong>ٹیکس آڈٹ ٹیسٹ کے لیے ٹرن اوور۔</strong> یہ ٹرن اوور وہ کنٹریکٹ ویلیو نہیں ہے جس کی آپ نے تجارت کی۔ فیوچرز اور آپشنز کے لیے اس کا شمار آپ کے مطلق منافع اور نقصانات کے مجموعے کے طور پر کیا جاتا ہے، ہر نفع اور ہر نقصان کے سائز کو شامل کرتے ہوئے نشانی سے قطع نظر۔ ایک چارٹرڈ اکاؤنٹنٹ کو آپ کے اکاؤنٹس کا آڈٹ کرنے کی ضرورت ہو سکتی ہے اگر یہ ٹرن اوور مقررہ حد سے تجاوز کرتا ہے، یا اگر آپ قانون کی توقع سے کم منافع کا اعلان کرتے ہیں۔ آیا آڈٹ لاگو ہوتا ہے یا نہیں اس کا انحصار آپ کے درست اعداد و شمار پر ہوتا ہے، اس لیے اندازہ لگانے کے بجائے کسی پیشہ ور سے بات کرنا ایک سوال ہے۔</li>\n<li><strong>ایڈوانس ٹیکس۔</strong> ٹیکس نہ صرف سال کے آخر میں ادا کیا جاتا ہے۔ اگر سال کے لیے آپ کا کل ٹیکس ایک چھوٹی سی حد سے زیادہ ہے، تو یہ قابل ادائیگی ہے۔ <strong>سال بھر کی قسطیں</strong>، قواعد کے ذریعہ مقرر کردہ تاریخوں پر۔ ان اقساط کو چھوڑنا سود کو مدعو کرتا ہے، اس لیے ایک فعال تاجر ایک بار میں یکمشت اور جرمانے کا سامنا کرنے کے بجائے ایڈوانس ٹیکس کے لیے بجٹ بناتا ہے۔</li>\n</ul>\n<p>میں نے جان بوجھ کر درست سلیب فیصد، حد یا قسط کی تاریخوں کا حوالہ نہیں دیا ہے، کیونکہ یہ بجٹ میں سال بہ سال تبدیل ہوتے رہتے ہیں۔ ڈھانچہ جانیں، جو مستحکم ہے: کاروباری آمدنی، ITR-3، سلیب ریٹ، سیٹ آف، کیری فارورڈ، آڈٹ ٹیسٹ، ایڈوانس ٹیکس۔ موجودہ اعداد و شمار دیکھیں، یا اپنے اکاؤنٹنٹ کو ہر سال فراہم کرنے کو کہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ٹیکس کے قوانین ہر سال تبدیل ہوتے ہیں اور آپ کی مکمل مالی صورتحال، آپ کی دوسری آمدنی، آپ کی رہائش اور تازہ ترین بجٹ پر منحصر ہوتے ہیں۔ اس باب کو نظام کے کام کرنے کے نقشے کے طور پر سمجھیں، فائلنگ ایڈوائس کے طور پر نہیں۔ فائل کرنے سے پہلے، ایک قابل چارٹرڈ اکاؤنٹنٹ سے مشورہ کریں جو موجودہ قانون کو آپ کے اصل نمبروں پر لاگو کر سکے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-futures-tax.png\" alt=\"مستقبل کا نتیجہ ہندوستانی ٹیکس کے نظام کے ذریعے کیسے نکلتا ہے: منافع 100X0-3 میں غیر قیاس آرائی پر مبنی کاروباری آمدنی کے طور پر رپورٹ کیا جاتا ہے، دوسری آمدنی میں شامل کیا جاتا ہے اور سلیب کی شرح پر ٹیکس لگایا جاتا ہے، جب کہ نقصان دوسرے سروں کے خلاف طے ہوتا ہے یا آٹھ سال کے لیے آگے بڑھایا جاتا ہے اگر ریٹرن وقت پر جمع کرایا جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>مستقبل کا نتیجہ ہندوستانی ٹیکس نظام کے ذریعے کیسے نکلتا ہے: منافع 102X0-3 میں غیر قیاس آرائی پر مبنی کاروباری آمدنی کے طور پر رپورٹ کیا جاتا ہے، دوسری آمدنی میں شامل کیا جاتا ہے اور سلیب کی شرح پر ٹیکس لگایا جاتا ہے، جب کہ نقصان دوسرے سروں کے خلاف طے کیا جاتا ہے یا آٹھ سال کے لیے آگے بڑھایا جاتا ہے اگر ریٹرن وقت پر جمع کرایا جاتا ہے۔</figcaption></figure>\n<p>دونوں حصوں سے ٹیک وے ایک ہی قسم کی سنجیدگی ہے۔ فی تجارت کے اخراجات چھوٹے ہیں لیکن یقینی اور بار بار ہوتے ہیں، اس لیے وہ صبر کا بدلہ دیتے ہیں اور منتھن کو سزا دیتے ہیں۔ ٹیکس اس کاروبار پر عام ٹیکس ہے جسے آپ اسکرین سے چلاتے ہیں، تاجروں کے لیے کوئی خاص احسان نہیں۔ کم اور بہتر تجارت کریں، ہر فل کا صاف ریکارڈ رکھیں، وقت پر فائل کریں، اور ایک اچھے چارٹرڈ اکاؤنٹنٹ کو باقی کام سنبھالنے دیں۔</p>\n","toc":[{"level":2,"text":"ہر تجارت کے اندر چھپے ہوئے اخراجات","id":"the-costs-hiding-inside-every-trade"},{"level":2,"text":"ایک NIFTY لاٹ، ختم کرنا شروع کریں۔","id":"one-nifty-lot-start-to-finish"},{"level":2,"text":"ٹرن اوور کے ساتھ اخراجات بڑھتے ہیں۔","id":"costs-grow-with-turnover"},{"level":2,"text":"مستقبل کے منافع پر ٹیکس کیسے لگایا جاتا ہے۔","id":"how-futures-profits-are-taxed"},{"level":2,"text":"نقصانات اور آڈٹ کا سوال طے کرنا","id":"setting-off-losses-and-the-audit-question"}],"imgCount":2,"hasContent":true},"13":{"html":"<p>کوٹ اسکرین پرRELIANCEکو دیکھیں اور آپ کو ایک ایسی چیز نظر آئے گی جو ہر نئے آنے والے کو حیران کردیتی ہے۔ شیئر خود ایک قیمت دکھاتا ہے، تقریباً 1,318 روپے، جب کہ آنے والی میعاد ختم ہونے کے لیے RELIANCE کا مستقبل قدرے مختلف قیمت دکھاتا ہے، شاید 1,326 روپے۔ ایک ہی کمپنی، وہی دن، ایک ہی لمحہ، ابھی تک دو قیمتیں۔ کسی نے غلطی نہیں کی۔ مستقبل کو اسپاٹ پرائس سے دور تجارت کرنا ہے، اور ان کے درمیان چھوٹا سا فرق پوری مارکیٹ میں سب سے زیادہ معلوماتی نمبروں میں سے ایک ہے۔ اس فرق کو پڑھنا سیکھیں اور آپ کو فنانسنگ کے اخراجات، وقت، اور دوسرے تاجروں کے مزاج کے بارے میں ایک پرسکون ونڈو ملے۔</p>\n<p>اس خلا کا ایک نام ہے، <strong>بنیاد</strong>اور جو قوت اسے تخلیق کرتی ہے اس کا بھی ایک نام ہے، <strong>لے جانے کی قیمت</strong>. کسی بھی خیال کے لیے سادہ ریاضی سے آگے کسی ریاضی کی ضرورت نہیں ہے، اور دونوں گہرائی سے سمجھنے کے قابل ہیں۔ وہ بتاتے ہیں کہ مستقبل کی قیمت اس طرح کیوں رکھی جاتی ہے، کیوں کہ قیمت ختم ہونے کے قریب آتے ہی اس جگہ کی طرف بڑھ جاتی ہے، اور پریمیم یا رعایت خاموشی سے آپ کو کیا بتا رہی ہے۔</p>\n<h2 id=\"a-future-rarely-trades-at-spot\">مستقبل شاذ و نادر ہی جگہ پر تجارت کرتا ہے۔</h2>\n<p>اس وقت انڈر لائنگ کی قیمت، وہ قیمت جس پر آپ اس وقت اصل حصہ خرید یا بیچ سکتے ہیں، کہلاتا ہے <strong>جگہ کی قیمت</strong>. RELIANCE کے لیے جو کہ تقریباً 1,318 روپے ہے۔ مستقبل ہماری مثال میں، مستقبل میں ایک مقررہ تاریخ پر اسی حصہ کو طے کرنے کا معاہدہ ہے۔ <strong>28 جولائی 2026</strong>تقریباً 32 دن کی دوری پر۔</p>\n<p>کیونکہ مستقبل بعد میں طے ہوتا ہے، یہ تقریباً کبھی بھی بالکل جگہ کی قیمت پر تجارت نہیں کرتا ہے۔ ایک معقول وجہ ہے۔ اگلے 32 دنوں کے لیے مستقبل کا مالک ہونا اگلے 32 دنوں کے لیے شیئر کا مالک ہونا بالکل ویسا نہیں ہے، اور مارکیٹ کی قیمتیں جن میں فرق ہے۔ کبھی کبھی یہ تھوڑا نیچے تجارت کرتا ہے۔ سب سے پہلے جذب کرنے کا نقطہ صرف یہ ہے: مستقبل اور جگہ کے درمیان ایک چھوٹا سا فاصلہ معمول اور متوقع ہے، کوئی خرابی نہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اسپاٹ قیمت وہ ہے جو اس وقت بنیادی قیمت ہے۔ فیوچر کی قیمت وہی ہے جو یہ ختم ہونے پر طے کرے گی۔ وہ تقریبا کبھی ایک جیسے نہیں ہوتے ہیں، اور ان کے درمیان فرق حقیقی معنی رکھتا ہے.</p>\n</div></div>\n<h2 id=\"the-basis-is-the-gap\">بنیاد خلا ہے۔</h2>\n<p>دی <strong>بنیاد</strong> صرف مستقبل کی قیمت اور اسپاٹ قیمت کے درمیان فرق ہے۔ اگر مستقبل 1326 پر ٹریڈ کرتا ہے جبکہ اسپاٹ 1318 پر بیٹھتا ہے، بنیاد 8 پوائنٹس ہے۔ کنونشنز میں اس بات پر اختلاف ہے کہ کس طرح منہا کرنا ہے، اور کچھ تاجر اس کا حوالہ دوسری طرف دیتے ہیں، لیکن خیال دونوں سمتوں میں یکساں ہے: بنیاد اس بات کی پیمائش کرتی ہے کہ مستقبل کیش مارکیٹ سے کتنا دور ہے۔</p>\n<p>دو الفاظ ان دو حالات کی وضاحت کرتے ہیں جن سے آپ ملیں گے:</p>\n<ul>\n<li>جب مستقبل اسپاٹ کے اوپر تجارت کرتا ہے، تو مارکیٹ ایک پر ہوتی ہے۔ <strong>پریمیم</strong>. ہماری مثال میں 8 پوائنٹ کا فرق 8 پوائنٹس کا پریمیم ہے۔</li>\n<li>جب مستقبل اسپاٹ سے نیچے تجارت کرتا ہے تو مارکیٹ ایک پر ہوتی ہے۔ <strong>رعایت</strong>. مستقبل میں 1310 پر 1318 کی جگہ کے مقابلے میں 8 پوائنٹس کی چھوٹ ہوگی۔</li>\n</ul>\n<p>زیادہ تر ہندوستانی اسٹاک اور انڈیکس فیوچرز کے لیے، عام حالات میں، ایک پریمیم معمول کی حالت ہے۔ اس لیے RELIANCE مستقبل کو دیکھ کر شیئر کے اوپر مٹھی بھر پوائنٹس بالکل وہی ہے جس کی آپ توقع کریں گے۔ دلچسپ سوالات یہ ہیں کہ وہ پریمیم کیوں موجود ہے اور اس کا کیا مطلب ہے جب خلا غیر معمولی طور پر بڑا، غیر معمولی طور پر چھوٹا ہو، یا ڈسکاؤنٹ میں پلٹ جائے۔</p>\n<table>\n<thead>\n<tr>\n<th>بنیاد ریاست</th>\n<th>مستقبل بمقابلہ جگہ</th>\n<th>یہ عام طور پر کیا عکاسی کرتا ہے</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>پریمیم</td>\n<td>مستقبل اوپر کی جگہ</td>\n<td>لے جانے کی عام قیمت، قدرے تیز پوزیشننگ سے پرسکون</td>\n</tr>\n<tr>\n<td>رعایت</td>\n<td>مستقبل نیچے کی جگہ</td>\n<td>ایک بڑا آنے والا ڈیویڈنڈ، یا بیئرش شارٹ پوزیشننگ</td>\n</tr>\n<tr>\n<td>صفر کے قریب</td>\n<td>مستقبل جگہ کے قریب</td>\n<td>میعاد ختم ہونے کو ہے، کیری تقریباً ختم ہو چکی ہے۔</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-basis.png\" alt=\"فیوچر کی قیمت عام طور پر اس جگہ کے اوپر بیٹھتی ہے، جس کی بنیاد دو لائنوں کے درمیان فرق ہوتا ہے، اور یہ فرق اس وقت تک کم ہوتا جاتا ہے جب تک کہ دونوں قیمتیں ختم نہ ہو جائیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>فیوچر کی قیمت عام طور پر اس جگہ کے اوپر بیٹھتی ہے، جس کی بنیاد دو لائنوں کے درمیان فرق ہوتا ہے، اور یہ فرق اس وقت تک کم ہوتا جاتا ہے جب تک کہ دونوں قیمتیں ختم نہ ہو جائیں۔</figcaption></figure>\n<h2 id=\"cost-of-carry-why-a-future-trades-at-a-premium\">لے جانے کی قیمت: مستقبل پریمیم پر کیوں تجارت کرتا ہے۔</h2>\n<p>مستقبل میں عام طور پر جگہ سے اوپر تجارت کرنے کی وجہ یہ ہے۔ <strong>لے جانے کی قیمت</strong>، ختم ہونے تک انڈرلائننگ رکھنے کی لاگت۔ کسی ایسے شخص کا تصور کریں جو میعاد ختم ہونے پر RELIANCE شیئرز کا مالک بننا چاہتا ہے۔ ان کے پاس دو راستے ہیں۔ وہ آج حصص خرید سکتے ہیں اور انہیں 32 دن تک روک سکتے ہیں، یا وہ مستقبل خرید سکتے ہیں اور بعد میں طے کر سکتے ہیں۔ ان دونوں راستوں کو ایک دوسرے کے مقابلے میں مناسب قیمت بنانے کے لیے، مستقبل کو اس بات کا حساب دینا ہوگا کہ حصص رکھنے کی اصل قیمت کیا ہے۔</p>\n<p>اس لاگت کا سب سے بڑا حصہ ہے۔ <strong>فنانسنگ</strong>. آج حصص خریدنے کے لیے استعمال ہونے والی رقم وہ رقم ہے جو دوسری صورت میں سود کمانے کے لیے بیٹھ سکتی ہے، یا ایسی رقم جو سود کی شرح پر ادھار لینی پڑتی ہے۔ اسے 32 دنوں کے لیے حصص میں باندھنے کی ایک قیمت ہوتی ہے، اور یہ لاگت مستقبل کی قیمت میں شامل ہوتی ہے۔ میعاد ختم ہونے میں جتنا لمبا وقت ہوگا اور سود کی شرح جتنی زیادہ ہوگی، کیری اتنی ہی زیادہ ہوگی اور اسی طرح پریمیم بھی اتنا ہی بڑا ہوگا۔</p>\n<p>آپ بغیر کسی کوڈ کے سائز کا خاکہ بنا سکتے ہیں۔ 1318 پر RELIANCE اسپاٹ لیں، ایک سال میں سات فیصد کے علاقے میں فنانسنگ کی شرح، اور میعاد ختم ہونے میں 32 دن۔ 1318 کو پورے سال کے لیے سات فیصد تقریباً 92 پوائنٹس ہوں گے، لیکن آپ صرف 32 دن کے لیے لے جا رہے ہیں، جو تقریباً ایک سال کا بارہواں حصہ ہے، اس لیے کیری 8 پوائنٹس کے قریب کام کرتی ہے۔ یہی وجہ ہے کہ تقریباً 1326 کا مستقبل منصفانہ نظر آتا ہے۔ پریمیم صرف اسپاٹ قیمت کے علاوہ اسے ختم ہونے تک رکھنے کی قیمت ہے۔</p>\n<ul>\n<li>میعاد ختم ہونے میں زیادہ وقت کا مطلب ہے لے جانے کے زیادہ دن، لہذا ایک وسیع پریمیم۔</li>\n<li>اعلی فنانسنگ ریٹ کا مطلب ہے زیادہ مہنگی کیری، لہذا ایک وسیع پریمیم۔</li>\n<li>جیسے جیسے میعاد ختم ہوتی ہے، لے جانے کے کم دن رہ جاتے ہیں، اس لیے پریمیم قدرتی طور پر سکڑ جاتا ہے۔</li>\n</ul>\n<p>ایک تفصیل کیری کو دوسرے طریقے سے تراشتی ہے۔ اگر انڈرلائننگ میعاد ختم ہونے سے پہلے ڈیویڈنڈ ادا کرتا ہے، تو اصل حصص کے حامل کو وہ نقدی ملتی ہے جبکہ فیوچر ہولڈر کو نہیں ملتی، جس سے حصص لے جانے کی خالص لاگت کم ہوجاتی ہے۔ ایک بڑا آنے والا ڈیویڈنڈ اس وجہ سے پریمیم کو سکڑ سکتا ہے، اور بھاری ڈیویڈنڈ کے ارد گرد مستقبل سمت کے بارے میں کسی نظریے کے بجائے آواز، میکانی وجوہات کی بنا پر رعایت میں بھی پھسل سکتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE 1318 پر اسپاٹ، ایک سال میں سات فیصد کے قریب فنانسنگ لاگت، اور 28 جولائی 2026 کی میعاد ختم ہونے سے 32 دن تک تقریباً 8 پوائنٹس ملتے ہیں۔ اس کو اسپاٹ میں شامل کریں اور ایک منصفانہ فیوچر قیمت 1326 کے قریب پہنچ جائے، جو بالکل اسی قسم کا پریمیم ہے جسے آپ اسکرین پر دیکھتے ہیں۔</p>\n</div></div>\n<h2 id=\"what-a-discount-can-signal\">رعایت کس چیز کا اشارہ دے سکتی ہے۔</h2>\n<p>اگر پریمیم عام حالت ہے، a <strong>رعایت</strong>، جہاں مستقبل اسپاٹ کے نیچے تجارت کرتا ہے، باہر کھڑا ہے۔ کبھی کبھی یہ خالصتاً مکینیکل ہوتا ہے، ڈیویڈنڈ اثر ابھی بیان کیا گیا ہے۔ لیکن جب اس کی وضاحت کرنے کے لیے کوئی بڑا منافع نہیں ہوتا ہے تو، رعایت اکثر جذبات کے بارے میں پیغام دیتی ہے۔</p>\n<p>مستقبل میں رعایت اس وقت پڑتی ہے جب بیچنے والے مستقبل کو نقد قیمت سے کم فروخت کرنے کے لیے تیار ہوتے ہیں، جس کا عام طور پر مطلب یہ ہوتا ہے کہ تاجر مندی کا جھکاؤ رکھتے ہیں اور مستقبل میں مختصر پوزیشن کو دبا رہے ہیں۔ فیوچر مارکیٹ، جس کا فائدہ اٹھایا جاتا ہے اور مختصر سے آسان ہوتا ہے، اکثر ایسا ہوتا ہے جہاں ایک منفی نقطہ نظر پہلے ظاہر ہوتا ہے۔ اس لیے اسٹاک یا انڈیکس کا مستقبل ڈسکاؤنٹ کی طرف بڑھتا ہے، یا ایک پریمیم جو اچانک منہدم ہو جاتا ہے، یہ ابتدائی اشارہ ہو سکتا ہے کہ تاجر کمزوری کی توقع کرتے ہیں، یہاں تک کہ اسپاٹ پرائس اب بھی پرسکون نظر آتی ہے۔</p>\n<p>سگنل کبھی بھی یقینی نہیں ہے، اور اسے کبھی بھی خود سے تجارت نہیں کرنا چاہئے۔ لیکن ایک بنیاد جو عجیب و غریب سلوک کرتی ہے قابل توجہ ہے۔ ایک پریمیم کو تیزی سے وسیع کرنے سے پتہ چلتا ہے کہ شوقین خریدار لیوریجڈ ایکسپوژر کی ادائیگی کر رہے ہیں۔ ایک پریمیم سکڑنا یا رعایت پر پلٹ جانا یہ بتاتا ہے کہ مخالف مزاج اندر داخل ہو رہا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>فیوچر پریمیم زیادہ تر ہندوستانی اسٹاکس اور انڈیکس کے لیے عام حالت ہے۔ ایک مستقل رعایت جس کی کوئی ڈیویڈنڈ وضاحت نہیں کرسکتا اکثر مندی کی پوزیشن کی عکاسی کرتا ہے، تاجر مستقبل کو نقد قیمت سے کم کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"convergence-the-basis-must-vanish-at-expiry\">کنورجنسی: بنیاد ختم ہونے پر ختم ہو جانا چاہیے۔</h2>\n<p>یہاں وہ اینکر ہے جو پورے خیال کو آپس میں جوڑتا ہے۔ آج کی بنیاد کتنی ہی وسیع ہے، اسے ختم ہونے کے بعد صفر تک سکڑ جانا چاہیے۔ اسے کہتے ہیں۔ <strong>ہم آہنگی</strong>، اور یہ کوئی رجحان یا امکان نہیں ہے۔ یہ معاہدہ میں شامل ایک یقینی بات ہے۔</p>\n<p>وجہ سادہ ہے۔ میعاد ختم ہونے کی تاریخ پر مستقبل مستقبل کے بارے میں ایک وعدہ بن کر رک جاتا ہے اور اس دن کی اصل قیمت پر تصفیہ بن جاتا ہے۔ اس آخری لمحے میں لے جانے کے لیے کوئی وقت نہیں بچا، کوئی مالیاتی لاگت شامل کرنے کے لیے، کوئی دن باقی نہیں بچا۔ لہذا مستقبل صرف اسپاٹ قیمت پر ہی طے ہوسکتا ہے۔ الگ الگ شروع ہونے والی دو لائنیں ملنے پر مجبور ہیں۔ آج ایک 8 پوائنٹ پریمیم اگلے 32 دنوں میں کچھ بھی نہیں پگھل جائے گا، جیسے ہی کیری کم ہو جائے گی۔</p>\n<p>یہ ہم آہنگی ہے جو بنیاد کو ایک پیمائش کے طور پر قابل اعتماد بناتی ہے۔ آپ بے ترتیب ہلچل نہیں دیکھ رہے ہیں۔ آپ ایک ایسے خلا کو دیکھ رہے ہیں جس کی ایک معلوم تاریخ پر صفر کی منزل معلوم ہوتی ہے، جیسے جیسے میعاد ختم ہوتی ہے اس کی طرف بڑھ رہی ہو۔</p>\n<ul>\n<li>جب ایکسپائری بہت دور ہو اور سب سے زیادہ کیری باقی رہ جائے تو پریمیم سب سے زیادہ چوڑا ہوتا ہے۔</li>\n<li>دن گننے کے ساتھ ساتھ یہ بتدریج کم ہوتا جاتا ہے۔</li>\n<li>ایکسپائری پر مستقبل اور جگہ کی قیمت ایک ہی ہے، بنیاد صفر ہے۔</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>سٹاک گرنے کے لیے روزمرہ کے پریمیم کو کم کرنے کی غلطی نہ کریں۔ جیسے جیسے ایکسپائری قریب آتی ہے، ایک لمبی فیوچر پوزیشن کنورجنسی میں تھوڑا سا کھو دیتی ہے یہاں تک کہ اگر اسپاٹ پرائس بالکل مستحکم ہو، صرف اس وجہ سے کہ آپ نے جو پریمیم خریدا ہے وہ صفر کی طرف گر رہا ہے۔ آپ جو کمانے کی توقع رکھتے ہیں اس کی بنیاد کو فیکٹر کریں۔</p>\n</div></div>\n<h2 id=\"what-the-basis-tells-you\">بنیاد آپ کو کیا بتاتی ہے۔</h2>\n<p>دھاگوں کو ایک ساتھ کھینچیں اور بنیاد فیوچر ٹریڈر کے لیے ایک چھوٹا انسٹرومنٹ پینل بن جاتا ہے۔ پریمیم کا سائز آپ کو بتاتا ہے کہ لے جانے کی کتنی قیمت ہے، جو وقت اور شرح سود پر منحصر ہے۔ سمت آپ کو مزاج کے بارے میں بتاتی ہے۔ ایک صحت مند پریمیم نارمل، قدرے تیز پوزیشننگ کا اشارہ دیتا ہے۔ سکڑتا ہوا پریمیم یا غیر واضح رعایت احتیاط یا مندی کا اشارہ دیتی ہے۔ اور کنورجنسی آپ کو یاد دلاتا ہے کہ آج جو بھی خلا ہے، وہ معیاد ختم ہونے پر صفر تک کی ضمانت کے راستے پر ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ کسی مستقبل کا اس کے مقام سے موازنہ کرتے ہیں تو صرف اعداد کو نوٹ نہ کریں۔ پوچھیں کہ فرق کیوں ہے جس کا سائز ہے۔ کیا یہ باقی دنوں کے لیے عام کیری ہے، آنے والا منافع، یا جذبات میں تبدیلی؟ یہ ایک ہی عادت تجسس کی بنیاد کو مارکیٹ میں حقیقی پڑھنے میں بدل دیتی ہے۔</p>\n</div></div>\n<p>لے جانے کی بنیاد اور قیمت اس بات کی وضاحت کرتی ہے کہ مستقبل کیوں اپنی جگہ سے چند پوائنٹس کے فاصلے پر رہتا ہے، وہ فاصلہ عام طور پر پریمیم کیوں ہوتا ہے، کیوں رعایت مندی کا اشارہ دے سکتی ہے، اور کیوں وقفہ ختم ہونے پر ہمیشہ صفر پر بند ہو جاتا ہے۔ اس میں سے کسی کو بھی سمجھنے کے لیے کسی فارمولے کی ضرورت نہیں۔ اسے صرف دو قیمتوں کی تصویر درکار ہوتی ہے، جو وقت کے ساتھ انڈرلائننگ رکھنے کی لاگت سے الگ ہوتی ہے، اور وقت ختم ہونے کے ساتھ ساتھ واپس کھینچ لی جاتی ہے۔</p>\n","toc":[{"level":2,"text":"مستقبل شاذ و نادر ہی جگہ پر تجارت کرتا ہے۔","id":"a-future-rarely-trades-at-spot"},{"level":2,"text":"بنیاد خلا ہے۔","id":"the-basis-is-the-gap"},{"level":2,"text":"لے جانے کی قیمت: مستقبل پریمیم پر کیوں تجارت کرتا ہے۔","id":"cost-of-carry-why-a-future-trades-at-a-premium"},{"level":2,"text":"رعایت کس چیز کا اشارہ دے سکتی ہے۔","id":"what-a-discount-can-signal"},{"level":2,"text":"کنورجنسی: بنیاد ختم ہونے پر ختم ہو جانا چاہیے۔","id":"convergence-the-basis-must-vanish-at-expiry"},{"level":2,"text":"بنیاد آپ کو کیا بتاتی ہے۔","id":"what-the-basis-tells-you"}],"imgCount":1,"hasContent":true},"14":{"html":"<p>کسی بھی کوٹ اسکرین کا فیوچر سیکشن کھولیں اور آفر پر RELIANCE معاہدوں کو قریب سے دیکھیں۔ آپ کو ایک مستقبل نظر نہیں آئے گا۔ آپ تین دیکھیں گے، ہر ایک کے نام پر مختلف تاریخ کی مہر لگی ہوئی ہے، ہر ایک قدرے مختلف قیمت پر ٹریڈنگ کرتا ہے۔ ان میں سے ایک مصروف ہے، احکامات کی پرواز کے ساتھ۔ اگلا خاموش ہے۔ تیسرا بمشکل حرکت کرتا ہے۔ یہ بے ترتیبی نہیں ہے اور یہ کوئی انتخاب نہیں ہے جس کا تبادلہ بے ترتیب ہو جائے۔ یہ ایک تال ہے، ایک کیلنڈر ہے جو مہینوں کے بعد بدلتا رہتا ہے، اور ایک بار جب آپ اس کی دھڑکن کو سمجھ لیں گے تو آپ دوبارہ کبھی ختم ہونے کی تاریخ پر حیران نہیں ہوں گے یا ایسا معاہدہ پکڑے ہوئے نہیں ہوں گے جو ختم ہونے والا ہے۔</p>\n<p>یہ باب اس تال کے بارے میں ہے۔ کسی پوزیشن کو رول کرنے کا عمل نہیں، جس کا احاطہ پہلے کے باب میں کیا گیا ہے، بلکہ خود کیلنڈر: کون سے معاہدے کسی بھی لمحے موجود ہیں، وہ کیسے پیدا ہوتے ہیں اور کیسے مرتے ہیں، بالکل کب ختم ہوتے ہیں، اور کیوں کسی معاہدے کا آخری دن ہر دوسرے دن سے مختلف برتاؤ کرتا ہے۔ کیلنڈر کو اپنی ہڈیوں میں داخل کریں اور باقی فیوچر ٹریڈنگ بہت کم پراسرار محسوس ہوتی ہے۔</p>\n<h2 id=\"three-contracts-trade-at-once\">ایک ساتھ تین معاہدوں کی تجارت</h2>\n<p>کسی بھی لمحے ہندوستانی مارکیٹ کی فہرست بن جاتی ہے۔ <strong>تین ماہانہ مستقبل</strong> دیئے گئے بنیادی پر. وہ تین مختلف مصنوعات نہیں ہیں۔ وہ ایک ہی بنیادی پر ایک ہی معاہدہ ہیں، صرف اس وقت سے الگ ہوتے ہیں جب وہ طے پاتے ہیں۔</p>\n<ul>\n<li>دی <strong>قریب مہینہ</strong> معاہدہ ختم ہونے کے قریب ترین ہے۔ RELIANCE کے لیے آج جو جولائی کا مستقبل ہے، طے ہو رہا ہے۔ <strong>28 جولائی 2026</strong>. یہ وہ جگہ ہے جہاں تقریباً تمام ٹریڈنگ ہوتی ہے۔ اسپریڈ سخت ہیں، حجم بھاری ہے، اور اندر اور باہر جانا آسان ہے۔</li>\n<li>دی <strong>اگلے مہینے</strong> اگست کا مستقبل ہے۔ یہ معقول طور پر تجارت کی جاتی ہے لیکن قریب کے مہینے سے کہیں زیادہ پرسکون ہوتی ہے، اور یہ بنیادی طور پر رول اوور ونڈو کے دوران زندہ ہو جاتا ہے جب ہجوم اس طرف بڑھنا شروع کر دیتا ہے۔</li>\n<li>دی <strong>دور مہینہ</strong> تیسرا، ستمبر کا مستقبل ہے۔ یہ حقیقی طور پر پتلا ہے۔ کئی دنوں میں صرف مٹھی بھر معاہدے ہی ہاتھ بدلتے ہیں، خرید و فروخت کی قیمت کے درمیان فاصلہ وسیع ہوتا ہے، اور ایک حکم ہی قیمت کو ادھر ادھر ہلا سکتا ہے۔</li>\n</ul>\n<p>تو تین دروازے ہمیشہ کھلے رہتے ہیں: جولائی، اگست، ستمبر۔ ہر ایک کے پیچھے بالکل ایک ہی RELIANCE ایکسپوژر ہے، صرف ایک مختلف تاریخ کو ڈیلیور کیا گیا ہے۔ قیمت ان کے درمیان تھوڑا سا مختلف ہے کیونکہ، جیسا کہ بنیادی باب کی وضاحت کی گئی ہے، ایک معاہدہ جو مزید طے کرتا ہے اس میں زیادہ دنوں کی مالی امداد ہوتی ہے، اس لیے یہ عام طور پر جگہ پر قدرے وسیع پریمیم پر بیٹھتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>کسی بھی بنیادی پر، تین ماہانہ فیوچرز ایک ساتھ تجارت کریں: قریب کا مہینہ (سب سے زیادہ مائع)، اگلا مہینہ، اور دور مہینہ (پتلا)۔ وہ ایک ہی بنیادی پر ایک ہی معاہدہ ہیں، صرف ان کی تصفیہ کی تاریخ سے الگ۔</p>\n</div></div>\n<h2 id=\"the-cycle-rolls-forward-forever\">سائیکل ہمیشہ کے لیے آگے بڑھتا ہے۔</h2>\n<p>یہ وہ حصہ ہے جو جامد تصویر کو زندہ کیلنڈر میں بدل دیتا ہے۔ تینوں معاہدے طے نہیں رہتے۔ وہ لاک اسٹپ میں آگے بڑھتے ہیں، ہر ماہ ایک قدم، اور مشینری کبھی نہیں رکتی۔</p>\n<p>جب قریب کا مہینہ اپنی میعاد ختم ہونے پر پہنچ جاتا ہے اور بس جاتا ہے تو یہ بس بورڈ سے گر جاتا ہے۔ جولائی کا مستقبل، ایک بار 28 جولائی گزر جانے کے بعد، اب موجود نہیں ہے۔ اس وقت جو اگلا مہینہ تھا وہ نیا قریب کا مہینہ بن جاتا ہے اور جو مہینہ دور تھا وہ اگلا مہینہ بن جاتا ہے۔ پیشکش پر تین معاہدوں کو برقرار رکھنے کے لیے، ایکسچینج ایک بالکل نیا دور کا مہینہ پیش کرتا ہے۔</p>\n<p>چنانچہ جولائی کی میعاد ختم ہونے کے بعد صبح بورڈ اگست، ستمبر، اکتوبر پڑھتا ہے۔ اگست اب مصروف ترین مہینہ ہے، ستمبر بڑھ کر اگلا مہینہ بن گیا ہے، اور اکتوبر تازہ ترین درج شدہ دور کا مہینہ ہے جس میں ابھی تک تقریباً کوئی بھی تجارت نہیں کر رہا ہے۔ ایک ماہ بعد پھر وہی کچھ ہوتا ہے۔ ستمبر قریب آتا ہے، اکتوبر اگلا ہوتا ہے، نومبر پیچھے ہوتا ہے۔ سائیکل ہمیشہ کے لیے آگے بڑھتا ہے، سامنے کا معاہدہ ختم کرتا ہے اور عقب میں ایک نیا بڑھتا ہے، مہینے کے بعد مہینے، سال بہ سال۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-contract-cycle.png\" alt=\"تین کنٹریکٹ سائیکل حرکت میں: ہر ماہ قریب ختم ہونے والا معاہدہ سامنے سے گر جاتا ہے، اگلے اور دور مہینے آگے بڑھتے ہیں، اور پیچھے سے ایک تازہ دور کا مہینہ متعارف کرایا جاتا ہے، لہذا وہی تین دروازوں والا ڈھانچہ بغیر کسی اختتام کے آگے بڑھتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>تین کنٹریکٹ سائیکل حرکت میں: ہر ماہ قریب ختم ہونے والا معاہدہ سامنے سے گر جاتا ہے، اگلے اور دور مہینے آگے بڑھتے ہیں، اور پیچھے سے ایک تازہ دور کا مہینہ متعارف کرایا جاتا ہے، لہذا وہی تین دروازوں والا ڈھانچہ بغیر کسی اختتام کے آگے بڑھتا ہے۔</figcaption></figure>\n<p>یہی وجہ ہے کہ فیوچر ویو کو غیر معینہ مدت تک لے جایا جا سکتا ہے حالانکہ کوئی ایک معاہدہ چند مہینوں سے زیادہ نہیں چلتا ہے۔ کنویئر بیلٹ کے طور پر تین معاہدوں کے بارے میں سوچئے۔ ہر ماہ سامنے والا کنارے سے گر جاتا ہے، باقی اپنی جگہ کو پُر کرنے کے لیے آگے بڑھتے ہیں، اور پیچھے سے ایک نیا لاد دیا جاتا ہے۔ پٹی کبھی خالی نہیں ہوتی اور یہ کبھی نہیں رکتی۔ میعاد ختم ہونے کے پیچھے ہمیشہ ایک نئے معاہدے کا انتظار ہوتا ہے، اس لیے انسٹرومنٹ کی تاریخ ہوتی ہے لیکن اس میں مارکیٹ دائمی ہے۔</p>\n<h2 id=\"the-last-tuesday-when-the-monthly-contract-expires\">آخری منگل: جب ماہانہ معاہدہ ختم ہوتا ہے۔</h2>\n<p>کیلنڈر صرف اس صورت میں مفید ہے جب آپ کو صحیح تاریخوں کا علم ہو، لہذا اس اصول کو یاد رکھیں۔ NSE پر، جہاں اس کورس کی ہر مثال تجارت کرتی ہے، <strong>ماہانہ ایکسپائری معاہدے کے مہینے کے آخری منگل کو ہوتی ہے۔</strong>. جولائی 2026 سائیکل کے لیے جو کہ 28 جولائی 2026 ہے، جو واقعی مہینے کا آخری منگل ہے۔ اگست کا معاہدہ پھر اگست کے آخری منگل کو، ستمبر کے آخری منگل کو، اور اسی طرح کنویئر بیلٹ کے نیچے ختم ہو جائے گا۔</p>\n<p>یہ ہندوستانی مشتقات میں ہر جگہ اپنے ساتھ لے جانے کے قابل تصفیہ کے دن کا اصول ہے:</p>\n<ul>\n<li>NSE مشتقات، جس میں NIFTY اور BANKNIFTY انڈیکس اور اسٹاک فیوچرز جیسے RELIANCE شامل ہیں، طے پاتے ہیں۔ <strong>منگل</strong>.</li>\n<li>BSE مشتقات، جیسے SENSEX، طے پاتے ہیں <strong>جمعرات</strong>.</li>\n</ul>\n<p>چونکہ اس کورس میں ہر آلہ ایک NSE آلہ ہے، اس لیے آپ کی یہاں ملنے والی ہر ایکسپائری منگل کو آتی ہے۔ اگر طے شدہ منگل کو تجارتی تعطیل ہوتی ہے تو، ایکسپائری صرف پچھلے تجارتی دن پر منتقل ہو جاتی ہے، لیکن یاد رکھنے کے لیے پہلے سے طے شدہ مہینے کا آخری منگل ہوتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ایکسپائری ہفتہ کا دن ایکسچینج کے ذریعہ مقرر کیا جاتا ہے، اسٹاک کے ذریعہ نہیں۔ ایک RELIANCE مستقبل اور NIFTY مستقبل دونوں منگل کو طے پاتے ہیں کیونکہ دونوں NSE پروڈکٹس ہیں۔ BSE مشتق کے ذریعے درج وہی کمپنی اس کی بجائے جمعرات کو طے کرے گی۔</p>\n</div></div>\n<h2 id=\"weekly-expiries-short-dated-contracts-on-the-index\">ہفتہ وار معیاد: انڈیکس پر مختصر تاریخ کے معاہدے</h2>\n<p>ماہانہ معاہدے اسٹاک فیوچرز جیسے RELIANCE کی پوری کہانی ہیں۔ لیکن سب سے زیادہ فعال انڈیکس اوپر ایک اضافی پرت رکھتا ہے۔ بینچ مارک انڈیکس مستقبل بھی پیش کرتا ہے۔ <strong>ہفتہ وار میعاد ختم ہوتی ہے۔</strong>، ایک تازہ مختصر تاریخ کا معاہدہ جو مہینے کے صرف آخری منگل کے بجائے ہر منگل کو طے ہوتا ہے۔</p>\n<p>لہذا ماہانہ NIFTY مستقبل کے ساتھ ساتھ آپ کو ہفتہ وار NIFTY معاہدے ملیں گے جو ہر ایک میں صرف چند دنوں کے لیے رہتے ہیں۔ جولائی 2026 میں، NIFTY ہفتہ وار مہینے میں آنے والے منگل، 7ویں، 14ویں، 21ویں اور آخر میں 28 کو طے ہو جائیں گے، جو اس سائیکل کے لیے ماہانہ ختم ہونے کے طور پر دگنا ہو جاتا ہے۔ ہر ہفتہ وار معاہدہ پیدا ہوتا ہے، اپنے مٹھی بھر دنوں کے لیے تجارت کرتا ہے، اور طے پاتا ہے، جبکہ ماہانہ معاہدہ نیچے جاری رہتا ہے۔</p>\n<p>یہ مختصر تاریخ والے معاہدے موجود ہیں کیونکہ مطالبہ موجود ہے۔ بہت سارے تاجر کسی معروف واقعہ کے ارد گرد صرف چند دنوں کے لیے نمائش چاہتے ہیں، اور ہفتہ وار معاہدہ انہیں پورے مہینے کا عہد کیے بغیر ایک تنگ، قلیل المدتی پوزیشن لینے دیتا ہے۔ تجارت بند یہ ہے کہ ہفتہ وار زوال پذیر اور تیزی سے آگے بڑھتے ہیں، اور ان کی میعاد ختم ہونے کا ہفتہ اچھل سکتا ہے۔ ایک ابتدائی کے لیے ہفتہ وار تال بنیادی طور پر ایک چیز ہے جس کے بارے میں آگاہ ہونا چاہیے، تاکہ کسی چیز کا پیچھا کرنے کے بجائے ایکسپائری آپ پر کبھی نہ چھپے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>بینچ مارک انڈیکس ہفتہ وار دل کی دھڑکن پر چلتا ہے: ایک نیا معاہدہ ہر منگل کو طے ہوتا ہے۔ مہینے کا آخری منگل خاص ہوتا ہے کیونکہ ہفتہ وار ایکسپائری اور ماہانہ ایکسپائری ایک ہی دن ہوتی ہے، جو عام طور پر سائیکل کا سب سے زیادہ فعال اور سب سے زیادہ اتار چڑھاؤ والا سیشن ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"expiry-day-higher-volatility-and-the-final-settlement-price\">ختم ہونے کا دن: زیادہ اتار چڑھاؤ اور حتمی تصفیہ کی قیمت</h2>\n<p>ایکسپائری ڈے ایک عام تجارتی دن کی طرح محسوس نہیں ہوتا، اور آپ کو اس کی توقع کرنی چاہیے۔ جیسا کہ معاہدہ اپنے آخری اوقات کے قریب آتا ہے، ہر تاجر کو اب بھی یہ فیصلہ کرنا ہوتا ہے: بند کرو، آگے بڑھو، یا اسے طے ہونے دو۔ اس ساری سرگرمی کا ہجوم آخری سیشنز تک پہنچ جاتا ہے، جلد بازی میں پوزیشنیں خالی ہوتی ہیں، اور قیمت معمول سے زیادہ تیزی سے بدل سکتی ہے۔ معیاد ختم ہونے والے دن زیادہ اتار چڑھاؤ معمول ہے، استثناء نہیں، خاص طور پر آخری منگل کو جب ہفتہ وار اور ماہانہ معاہدہ ایک ساتھ ختم ہوتا ہے۔</p>\n<p>ایکسپائری ڈے کے بارے میں ایک تکنیکی تفصیل ہے جو حقیقی طور پر اہمیت رکھتی ہے، کیونکہ یہ فیصلہ کرتی ہے کہ آپ کے نفع یا نقصان کو کس نمبر سے ماپا جاتا ہے۔ تصفیہ کی دو قیمتیں الگ رکھیں۔ ہر عام تجارتی دن پر آپ کا مارک ٹو مارکیٹ استعمال کرتا ہے۔ <strong>روزانہ تصفیہ کی قیمت</strong> مستقبل کے معاہدے سے ماخوذ۔ 3 اگست 2026 سے ایکویٹی ڈیریویٹوز سیشن 15:40 تک چلتا ہے، اور معاہدے کی اختتامی قیمت اس کے آخری 30 منٹ کے VWAP، اب 15:10-15:40 استعمال کرتی ہے۔</p>\n<p>میعاد ختم ہونے پر معاہدہ کے خلاف بند کر دیا جاتا ہے۔ <strong>حتمی تصفیہ کی قیمت</strong>، جو فیوچر کنٹریکٹ کے بجائے بنیادی سے آتا ہے۔ سنگل اسٹاک کے مستقبل کے لیے، بنیادی شیئر کا آفیشل کلوز اب عام طور پر ہے۔ <strong>اختتامی نیلامی سیشن (CAS) توازن کی قیمت</strong>، کیونکہ F&amp;O- اہل اسٹاک پہلا CAS مرحلہ ہے۔ 15:00-15:15 نقد VWAP صرف CAS حوالہ قیمت اور فال بیک ہے اگر کوئی متوازن قیمت دریافت نہیں ہوتی ہے۔ انڈیکس کے مستقبل کے لیے جیسے کہ NIFTY، حتمی تصفیہ انڈیکس کی آفیشل کلوزنگ ویلیو کا استعمال کرتا ہے۔ انڈیکس کو الگ سے نیلام نہیں کیا جاتا ہے، لیکن اس کی قدر CAS اجزاء کے لیے نیلامی بند ہونے کی عکاسی کرتی ہے اور VWAP غیر CAS اجزاء کے لیے بند ہوتی ہے۔</p>\n<p>یہ فرق اہمیت رکھتا ہے: اخذ کنٹریکٹ کی بندش VWAP اب بھی موجود ہے، لیکن پرانا بیان کہ ہر زیرِ ذیل اسٹاک کا فائنل کلوزنگ ونڈو VWAP اب درست نہیں ہے۔ سیٹلمنٹ کا درست طریقہ کار تبادلے سے متعین رہتا ہے، اس لیے اس پر انحصار کرنے سے پہلے موجودہ NSE سیٹلمنٹ سرکلر کی تصدیق کریں۔</p>\n<p>ایک آخری پرنٹ کے بجائے، بنیادی کے اختتامی ونڈو اوسط کا استعمال، حتمی تصفیہ کی قیمت کو مضبوط بناتا ہے۔ کوئی ایک آرڈر اسے جھٹکا نہیں دے سکتا، اور وہ اعداد و شمار جو ہر کھلے معاہدے کو بند کر دیتا ہے اس بات کا منصفانہ عکاسی کرتا ہے کہ معاہدہ کے ختم ہونے کے بعد مارکیٹ حقیقی طور پر کہاں تھی۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ختم ہونے پر آپ کا نفع یا نقصان وزنی-اوسط بند ہونے والی قیمت کے خلاف مقرر کیا جاتا ہے، نہ کہ آخری ٹک جو آپ کو اسکرین پر فلیش دیکھنے کے لیے ہوا تھا۔ یہ مت سمجھیں کہ آپ نے جس آخری نمبر کو دیکھا ہے وہی قیمت ہے جس پر آپ نے طے کیا ہے۔ آفیشل سیٹلمنٹ ویلیو وہ اوسط اعداد و شمار ہے جسے ایکسچینج اختتامی سیشن کے لیے شائع کرتا ہے۔</p>\n</div></div>\n<h2 id=\"the-beginner-s-rule-live-in-the-near-month-know-your-date\">ابتدائی اصول: قریب کے مہینے میں رہیں، اپنی تاریخ جانیں۔</h2>\n<p>کیلنڈر کو ایک ساتھ کھینچیں اور عملی رہنمائی مختصر اور قابل استثنیٰ ہے۔</p>\n<p>پہلے، <strong>قریب مہینے میں رہتے ہیں</strong>. یہ وہ جگہ ہے جہاں لیکویڈیٹی ہے، جہاں اسپریڈ سخت ہیں اور فلز صاف ہیں۔ اگلا مہینہ ایکسپائری کے قریب آنے کے لیے ہے، اور ایک خاص وجہ کے ساتھ تجربہ کار تاجروں کے لیے پتلا دور مہینہ بہترین چھوڑ دیا جاتا ہے۔ مصروف فرنٹ کنٹریکٹ کی تجارت آپ کو ڈیلنگ کی پوشیدہ لاگت سے بچاتی ہے جہاں تقریباً کوئی نہیں ہے۔</p>\n<p>دوسرا، اور یہ وہ ہے جو ابتدائیوں کے حقیقی پیسے بچاتا ہے، <strong>ہمیشہ اپنی میعاد ختم ہونے کی تاریخ جانیں۔</strong>. ہر معاہدہ جو آپ کھولتے ہیں اس کے نام پر تصفیہ کی تاریخ کی مہر لگی ہوتی ہے، اور وہ تاریخ ایک مشکل آخری تاریخ ہے۔ کیلنڈر کو سمجھنے کا پورا نکتہ یہ ہے کہ آپ کی کوئی بھی حیثیت خود بخود حیرت سے طے نہیں ہوتی ہے۔ داخل ہوتے ہی آخری منگل کو اپنے کیلنڈر پر نشان زد کریں۔ ٹھیک ہے اس کے آنے سے پہلے، جان بوجھ کر فیصلہ کریں کہ آیا آپ اس پوزیشن کو بند کر دیں گے، اسے کیش سیٹل کرنے دیں گے، یا اسے اگلے مہینے میں رول کریں گے۔ ایک میعاد ختم ہونے کی طرف بڑھنا جس کے بارے میں آپ بھول گئے ہیں یہ ہے کہ کس طرح لاپرواہ تاجروں کو ایک ایسے نتیجے میں گھسیٹا جاتا ہے جس کا وہ کبھی ارادہ نہیں کرتے تھے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ RELIANCE جولائی کے مستقبل میں سے ایک لاٹ خریدتے ہیں۔ نام ہی آپ کو آخری تاریخ بتاتا ہے: 28 جولائی 2026، مہینے کا آخری منگل۔ جس دن آپ داخل ہوتے ہیں، آپ اس تاریخ کو نوٹ کرتے ہیں اور اس کے ارد گرد اپنے باہر نکلنے کا منصوبہ بناتے ہیں۔ آپ میعاد ختم ہونے پر حیران نہیں ہیں، کیونکہ آپ نے خریدنے پر دبانے سے پہلے کیلنڈر پڑھ لیا ہے۔</p>\n</div></div>\n<p>معاہدہ سائیکل تمام ٹریڈنگ میں سب سے زیادہ قابل اعتماد ڈھانچے میں سے ایک ہے۔ تین دروازے ہمیشہ کھلے رہتے ہیں، سامنے والا ہر مہینے بند ہوتا ہے جب کہ پیچھے سے ایک نیا کھلتا ہے، اور پوری بیلٹ ہر مہینے کے آخری منگل کو NSE پر آگے بڑھتی ہے۔ جانیں کہ آپ کس مہینے میں ہیں، جانیں کہ منگل کو آپ کا معاہدہ ختم ہو جاتا ہے، اور کیلنڈر ایک ایسا دوست بن جاتا ہے جو آپ کو ایک ایسے جال کے بجائے آپ پر مبنی رکھتا ہے جو آپ کو پکڑتا ہے۔</p>\n","toc":[{"level":2,"text":"ایک ساتھ تین معاہدوں کی تجارت","id":"three-contracts-trade-at-once"},{"level":2,"text":"سائیکل ہمیشہ کے لیے آگے بڑھتا ہے۔","id":"the-cycle-rolls-forward-forever"},{"level":2,"text":"آخری منگل: جب ماہانہ معاہدہ ختم ہوتا ہے۔","id":"the-last-tuesday-when-the-monthly-contract-expires"},{"level":2,"text":"ہفتہ وار معیاد: انڈیکس پر مختصر تاریخ کے معاہدے","id":"weekly-expiries-short-dated-contracts-on-the-index"},{"level":2,"text":"ختم ہونے کا دن: زیادہ اتار چڑھاؤ اور حتمی تصفیہ کی قیمت","id":"expiry-day-higher-volatility-and-the-final-settlement-price"},{"level":2,"text":"ابتدائی اصول: قریب کے مہینے میں رہیں، اپنی تاریخ جانیں۔","id":"the-beginner-s-rule-live-in-the-near-month-know-your-date"}],"imgCount":1,"hasContent":true},"15":{"html":"<p>ہر فیوچر معاہدہ اس کے نام پر مہر ختم ہونے کی تاریخ رکھتا ہے۔ اس سائیکل کا مستقبلRELIANCE<strong>28 جولائی 2026</strong>، اور اس دن معاہدے کا وجود ختم ہوجاتا ہے۔ لیکن ایک تاجر کی رائے شائستگی سے مہینے کے آخری منگل کو ختم نہیں ہوتی۔ آپ کو یقین ہو سکتا ہے کہ RELIANCE اگلے تین مہینوں میں اوپر کی طرف بڑھ رہا ہے، پھر بھی جو معاہدہ آپ کے پاس ہے اس کی زندگی کے صرف چند ہفتے باقی ہیں۔ تو جب معاہدہ ختم ہوجاتا ہے تو آپ کے خیال کا کیا ہوتا ہے؟ آپ اسے آگے بڑھائیں۔ اس اقدام کا ایک نام ہے، اور اسے صاف ستھرا کرنا سیکھنا ان پرسکون مہارتوں میں سے ایک ہے جو ایک تیار تاجر کو پریشان ہونے والے سے الگ کرتی ہے۔</p>\n<p>اس اقدام کو کہا جاتا ہے۔ <strong>رول اوور</strong>، اور یہ میعاد ختم ہونے والے مہینے سے اگلے مہینے تک کھلی پوزیشن لے جانے کے علاوہ کچھ نہیں ہے تاکہ آپ کا مارکیٹ کا نظارہ ایک ہی معاہدے سے آگے بڑھ سکے۔ تقریباً ہر پوزیشن کا تاجر جو کچھ ہفتوں سے زیادہ کے لیے فیوچر رکھتا ہے وہ رولنگ ختم کر دیتا ہے، اس لیے اسے یہ سمجھنے کے لیے ادائیگی ہوتی ہے کہ آپ کیا کر رہے ہیں، اس کی قیمت کیا ہے، اور ہجوم کا رولنگ رویہ آپ کو خاموشی سے کیا بتا رہا ہے۔</p>\n<h2 id=\"contracts-expire-but-views-do-not\">معاہدوں کی میعاد ختم ہو جاتی ہے، لیکن ویوز ختم نہیں ہوتے</h2>\n<p>مستقبل ایک تاریخ کا وعدہ ہے۔ ہندوستانی مارکیٹ ہمیشہ ایک ساتھ کئی مہینوں کی فہرست بناتی ہے۔ ابھی آپ جولائی کے معاہدے، اگست کے معاہدے، اور عام طور پر ستمبر کے معاہدے کی بھی تجارت کر سکتے ہیں۔ دی <strong>قریب مہینہ</strong> ہماری مثال میں جولائی، میعاد ختم ہونے کے قریب ترین ہے، اور یہ وہ جگہ ہے جہاں تقریباً تمام ٹریڈنگ ہوتی ہے۔ دی <strong>اگلے مہینے</strong> اگست ہے، اور <strong>دور مہینہ</strong> ستمبر ہے.</p>\n<p>جب جولائی کی میعاد 28 جولائی 2026 کو آتی ہے، تو ہر کھلی جولائی کی پوزیشن کو طے کرنا ضروری ہے۔ اگر آپ اب بھی اپنی تجارت پر یقین رکھتے ہیں، تو آپ اگلی صبح بغیر کسی پوزیشن کے فلیٹ نہیں ہونا چاہتے۔ اس کے بجائے آپ اگست کے معاہدے میں وہی نمائش چاہتے ہیں۔ رولنگ اوور یہ ہے کہ جب ایک کنٹریکٹ کے لیے میوزک رک جاتا ہے تو آپ اپنی سیٹ میز پر کیسے رکھتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>رول اوور کا مطلب ختم ہونے والے معاہدے میں اپنی پوزیشن کو بند کرنا اور اگلے مہینے میں اسی پوزیشن کو کھولنا ہے۔ آپ کا مارکیٹ کا نقطہ نظر کسی ایک معاہدے کی میعاد ختم ہونے سے بچ جاتا ہے۔</p>\n</div></div>\n<h2 id=\"what-a-rollover-actually-involves\">رول اوور میں اصل میں کیا شامل ہوتا ہے۔</h2>\n<p>رولنگ دو تجارتیں ہیں جو ایک دوسرے کے قریب ہوتی ہیں، مثالی طور پر ایک ہی لمحے میں۔ فرض کریں کہ آپ RELIANCE جولائی کے مستقبل میں سے ایک بہت طویل ہیں، جو کہ ہے۔ <strong>500 شیئرز</strong>. اگست تک رول کرنے کے لیے آپ دو چیزیں کرتے ہیں:</p>\n<ul>\n<li>آپ اپنا جولائی لانگ بیچ دیتے ہیں تاکہ اسے ختم ہونے سے پہلے بند کر دیں۔</li>\n<li>اسی طویل نمائش کو دوبارہ کھولنے کے لیے آپ اگست کے مستقبل کا ایک لاٹ خریدتے ہیں۔</li>\n</ul>\n<p>ان دو تجارتوں کے بعد آپ کے پاس جولائی کا کوئی مستقبل اور اگست کا ایک لاٹ نہیں ہے۔ آپ کی سمت میں کوئی تبدیلی نہیں ہے، آپ کے سائز میں کوئی تبدیلی نہیں ہوئی، صرف ایکسپائری کا مہینہ آگے بڑھا ہے۔ اگر آپ اس کے بجائے مختصر ہوتے تو آپ جولائی کا شارٹ واپس خریدیں گے اور اگست کا مستقبل بیچیں گے، آئینے کی تصویر میں وہی خیال۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-rollover.png\" alt=\"ایک رول اوور ایکسپائر ہونے والے مہینے کے معاہدے کو بند کر دیتا ہے اور اگلے مہینے میں اسی پوزیشن کو کھولتا ہے، بغیر کسی فلیٹ کے آپ کے مارکیٹ کے نقطہ نظر کو ایکسپائری کے دوران آگے لے جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک رول اوور ایکسپائر ہونے والے مہینے کے معاہدے کو بند کر دیتا ہے اور اگلے مہینے میں اسی پوزیشن کو کھولتا ہے، بغیر کسی فلیٹ کے آپ کے مارکیٹ کے نقطہ نظر کو ایکسپائری کے دوران آگے لے جاتا ہے۔</figcaption></figure>\n<p>زیادہ تر تجارتی پلیٹ فارمز آپ کو دونوں ٹانگیں تقریباً ایک ساتھ رکھنے دیتے ہیں تاکہ آپ کو ان کے درمیان کے فرق میں قیمتوں میں زبردست تبدیلی کا سامنا نہ ہو۔ آپ اسے جتنا صاف کرتے ہیں، اتنا ہی کم آپ پھسلن میں ادا کرتے ہیں اور آپ کو اتنا ہی کم پسینہ آتا ہے۔</p>\n<h2 id=\"the-rollover-cost-the-spread-you-pay\">رول اوور لاگت: اسپریڈ جو آپ ادا کرتے ہیں۔</h2>\n<p>رولنگ مفت نہیں ہے۔ جولائی اور اگست کے معاہدے قدرے مختلف قیمتوں پر تجارت کرتے ہیں، اور یہ فرق ہے۔ <strong>رول اوور لاگت</strong>، جسے کبھی کبھی رول اسپریڈ کہا جاتا ہے۔ باب سے اس بنیاد پر یاد رکھیں کہ مستقبل عام طور پر لے جانے کی لاگت کی وجہ سے اسپاٹ کے لئے ایک پریمیم پر تجارت کرتا ہے، اور ایک معاہدے کی میعاد ختم ہونے میں مزید دن ہوتے ہیں، لہذا یہ عام طور پر وسیع تر پریمیم پر بیٹھتا ہے۔</p>\n<p>حقیقت پسندانہ اعداد کی تصویر بنائیں۔ RELIANCE اسپاٹ کے بارے میں ہے۔ <strong>1,318 روپے</strong>. جولائی کا مستقبل، میعاد ختم ہونے کے قریب، 1322 کے قریب تجارت کر سکتا ہے۔ اگست کا مستقبل، پورے اضافی مہینے کے ساتھ، 1334 کے قریب تجارت کر سکتا ہے۔ طویل عرصے کے لیے آپ جولائی کو 1322 پر فروخت کرتے ہیں اور اگست کو 1334 پر خریدتے ہیں۔ وہ 12 پوائنٹ کا فرق آپ کی رول اوور لاگت ہے۔ 500 شیئرز کی ایک لاٹ پر جو کہ 12 گنا 500 ہے، جو کہ اسی لمبی پوزیشن کو ایک ماہ آگے لے جانے کے لیے 6,000 روپے ادا کیے جاتے ہیں۔</p>\n<p>یہ لاگت کوئی جرمانہ یا فیس نہیں ہے، یہ ایک اضافی مہینے کے لے جانے کی قیمت ہے، وہی فنانسنگ منطق جس کی بنیاد آپ کو ملتی ہے۔ لیکن یہ حقیقی رقم ہے، اس لیے ایک تاجر جو ہر ماہ طویل عرصے تک گھومتا ہے ہر بار مستقل طور پر پریمیم ادا کر رہا ہوتا ہے۔ ایک شارٹ رول کرنے والا تاجر دوسری طرف ہے اور اس پھیلاؤ کو مؤثر طریقے سے جمع کرتا ہے۔ کسی بھی طرح سے، آپ کو رول کے پھیلاؤ کو فیکٹر کرنا چاہیے جس کی آپ پوزیشن حاصل کرنے کی توقع کرتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ لمبے ہیں RELIANCE جولائی لاٹ۔ رول کرنے کے لیے، آپ جولائی کو 1322 پر فروخت کرتے ہیں اور اگست کو 1334 پر خریدتے ہیں۔ 12 پوائنٹ اسپریڈ کی قیمت 12 گنا 500، یا 6,000 روپے ہے، اگلے مہینے تک اسی طویل نمائش کو لے جانے کے لیے۔ یہ 28 جولائی 2026 کو آپ کے نظریہ کو زندہ رکھنے کی قیمت ہے۔</p>\n</div></div>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>رول اسپریڈ کو نظر انداز کرنا آسان ہے کیونکہ یہ کبھی بھی الگ چارج کے طور پر ظاہر نہیں ہوتا ہے۔ یہ دو قیمتوں کے اندر چھپ جاتا ہے۔ ہمیشہ اس قیمت کا موازنہ کریں جو آپ اگلے مہینے میں داخل ہونے والی قیمت سے قریب کے مہینے سے باہر نکلتے ہیں، اور اس فرق کو اپنے نقطہ نظر کو زیادہ دیر تک رکھنے کی حقیقی قیمت کے طور پر سمجھیں۔</p>\n</div></div>\n<h2 id=\"rollover-percentage-as-a-sentiment-signal\">ایک جذباتی سگنل کے طور پر رول اوور فیصد</h2>\n<p>یہ وہ جگہ ہے جہاں رول اوور میکانکس سے آگے دلچسپ ہو جاتے ہیں۔ میعاد ختم ہونے والے دنوں میں، پوری مارکیٹ ایک ساتھ گھوم رہی ہے، اور ایکسچینج ڈیٹا آپ کو یہ دیکھنے دیتا ہے کہ کھلی دلچسپی کا کتنا حصہ بند ہونے کے بجائے آگے بڑھایا جا رہا ہے۔ یہ عام طور پر a کے طور پر ظاہر ہوتا ہے۔ <strong>رول اوور فیصد</strong>: تقریباً ختم ہونے والے معاہدے کی پوزیشنوں کا حصہ جو اگلے مہینے میں اسکوائر آف اور ترک کرنے کے بجائے منتقل ہو جاتا ہے۔</p>\n<p>آپ کو خود اس کی گنتی کرنے کی ضرورت نہیں ہے، لیکن آپ کو یہ جاننا چاہیے کہ اسے کیسے پڑھنا ہے۔</p>\n<ul>\n<li>اے <strong>اعلی رول اوور فیصد</strong> اس کا مطلب ہے کہ زیادہ تر تاجر اپنی پوزیشن کو آگے بڑھا رہے ہیں۔ ان کے خیال سے کام نہیں کیا جاتا، وہ ایک اور مہینہ چاہتے ہیں۔ ہائی رولز کو عام طور پر سزا کے طور پر پڑھا جاتا ہے، یہ ایک نشانی ہے کہ مروجہ رجحان میں مومنین اندر رہنے کے لیے کیری ادا کرنے کو تیار ہیں۔</li>\n<li>اے <strong>کم رول اوور فیصد</strong> اس کا مطلب ہے کہ بہت ساری پوزیشنیں صرف بند ہو رہی ہیں اور تجدید نہیں کی جا رہی ہیں۔ تاجر دوسرے مہینے کے لیے عہد کرنے کے بجائے ایک طرف ہٹ رہے ہیں، جو ہچکچاہٹ یا حمایت کھونے کے رجحان کا اشارہ دے سکتا ہے۔</li>\n</ul>\n<p>تجزیہ کار فیصد کے ساتھ ساتھ پھیلاؤ کو بھی دیکھتے ہیں۔ ایک بھرپور پریمیم پر ایک اعلی رول اوور شوقین، پراعتماد خواہشات کی نشاندہی کرتا ہے۔ شارٹ سائیڈ پر بھاری رولنگ، یا ڈسکاؤنٹ پر ہونے والے رولز، دوسری طرف اشارہ کرتے ہیں۔ اس میں سے کوئی بھی کرسٹل گیند نہیں ہے، اور سگنل شور والا ہے، لیکن رول اوور ڈیٹا ایک اور ایماندار ونڈو ہے کہ مبصرین کیا کہہ رہے ہیں اس کے بجائے وسیع تر ہجوم اصل میں حقیقی پیسے کے ساتھ کیا کر رہا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>رول اوور فیصد اس بات کا اندازہ لگاتا ہے کہ میعاد ختم ہونے والے معاہدے کی کھلی دلچسپی کا کتنا حصہ اگلے مہینے میں لیا جاتا ہے۔ اعلی رول اوور بتاتے ہیں کہ تاجر موجودہ رجحان میں یقین رکھتے ہیں۔ کم رول اوور تجویز کرتے ہیں کہ وہ ایک طرف ہٹ رہے ہیں۔ اسے ایک اشارہ کے طور پر پڑھیں، کبھی بھی یقین کے طور پر۔</p>\n</div></div>\n<h2 id=\"expiry-day-mechanics\">ایکسپائری ڈے میکینکس</h2>\n<p>اگر آپ کبھی بھی رول نہیں کرتے اور کسی معاہدے کو اس کے آخری سیشن میں صرف کرتے ہیں، تو آپ کو سمجھنا چاہیے کہ کیا ہوتا ہے۔ ہندوستانی کے لیے <strong>اسٹاک فیوچر</strong> RELIANCE کی طرح، معاہدوں کو فزیکل ڈیلیوری کے ذریعے طے کیا جاتا ہے اگر آپ انہیں میعاد ختم ہونے تک لے جاتے ہیں۔ اس کا مطلب ہے کہ اگر آپ ابھی بھی آخری گھنٹی پر ایک لاٹ لمبے ہیں، تو آپ 500 اصل RELIANCE حصص کی ڈیلیوری لینے اور پوری قیمت ادا کرنے کے پابند ہو سکتے ہیں، تقریباً 6,59,000 روپے، آپ کے پوسٹ کردہ چھوٹے مارجن کی نہیں۔ یہ لاپرواہ ابتدائیوں کو بری طرح پکڑتا ہے۔</p>\n<p>کے لیے <strong>انڈیکس فیوچر</strong> جیسے کہ NIFTY اور BANKNIFTY، ڈیلیور کرنے کے لیے کوئی فزیکل شیئر نہیں ہے، اس لیے وہ ہیں <strong>نقدی سے طے شدہ</strong>. آپ کی پوزیشن صرف آخری سیٹلمنٹ قیمت پر بند ہو جاتی ہے اور نفع یا نقصان کو نقد میں ایڈجسٹ کیا جاتا ہے۔ کوئی ڈیلیوری، کوئی سرپرائز شیئر کی خریداری نہیں۔</p>\n<p>عملی سبق دونوں کے لیے یکساں ہے۔ میعاد ختم ہونے والے ہفتے سے پہلے فیصلہ کریں کہ آیا آپ پوزیشن کو بند کر رہے ہیں، اسے نقد رقم کی ادائیگی کر رہے ہیں، یا اسے آگے بڑھا رہے ہیں۔ کسی ایسی کھلی پوزیشن کے ساتھ سٹاک کے مستقبل کے آخری گھنٹے میں نہ جائیں جس کا آپ نے کبھی ڈیلیوری لینا نہیں چاہا۔ یا تو اسے مربع کریں یا اچھے وقت میں رول کریں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اسٹاک کے مستقبل کے لیے، میعاد ختم ہونے کی تاریخ کو سخت ڈیڈ لائن سمجھیں۔ ٹھیک ہے 28 جولائی 2026 سے پہلے، پوزیشن کو بند کرنے یا اگست تک رول کرنے کا فیصلہ کریں۔ اسٹاک مستقبل کو حتمی تصفیہ میں رکھنے سے آپ کو آپ کے پوسٹ کردہ مارجن سے کہیں زیادہ، لاکھوں روپے کی فزیکل ڈیلیوری ذمہ داری مل سکتی ہے۔</p>\n</div></div>\n<h2 id=\"why-beginners-should-stay-in-the-near-month\">ابتدائیوں کو قریب کے مہینے میں کیوں رہنا چاہئے۔</h2>\n<p>آپ سوچ سکتے ہیں کہ کیوں نہ صرف اگست یا ستمبر کے معاہدے کو براہ راست تجارت کریں اور رولنگ کو چھوڑ دیں۔ جواب ہے <strong>لیکویڈیٹی</strong>. تقریباً تمام حجم قریب کے مہینے میں بیٹھتا ہے۔ دور کا مہینہ اکثر باریک تجارت کرتا ہے، قیمت خرید اور فروخت کی قیمت کے درمیان وسیع فرق کے ساتھ۔ اس وسیع پھیلاؤ کا مطلب ہے کہ آپ اندر جانے کے لیے زیادہ اور باہر نکلنے کے لیے زیادہ ادائیگی کرتے ہیں، اور ایک بڑا آرڈر قیمت کو آپ کے خلاف لے جا سکتا ہے۔</p>\n<ul>\n<li>قریب ترین مہینہ سب سے زیادہ مائع ہوتا ہے، جس میں سخت ترین اسپریڈز اور سب سے آسان اندراجات اور اخراج ہوتے ہیں۔</li>\n<li>اگلا مہینہ بنیادی طور پر رول اوور ہفتے کے دوران مائع ہو جاتا ہے کیونکہ ہجوم اس پار منتقل ہوتا ہے۔</li>\n<li>دور کا مہینہ عام طور پر پتلا ہوتا ہے اور اسے کسی خاص وجہ کے ساتھ تجربہ کار تاجروں کے لیے چھوڑ دیا جاتا ہے۔</li>\n</ul>\n<p>ایک ابتدائی کے لیے رہنمائی آسان ہے۔ قریب کے مہینے میں تجارت کریں، جہاں مارکیٹ گہری اور منصفانہ ہو، اور جب ایکسپائری قریب آ جائے، اپنی پوزیشن کو رول اوور ونڈو کے دوران اگلے مہینے تک لے جائیں جب لیکویڈیٹی وہاں منتقل ہو جائے۔ یہ آپ کو ہر مرحلے پر مائع معاہدوں میں رکھتا ہے اور آپ کو تجارت کی پوشیدہ لاگت سے بچاتا ہے جہاں تقریباً کوئی نہیں ہوتا۔</p>\n<p>فائدہ یہ ہے کہ ایکسپائری تجارت کا خاتمہ نہیں ہے، صرف ایک معاہدے کا خاتمہ ہے۔ ایک رول اوور مہینے سے مہینہ ایک حقیقی نظارے کی سواری کی اجازت دیتا ہے۔ اسے صاف ستھرا کریں، اس پھیلاؤ کو شمار کریں جو آپ ادا کرتے ہیں ایک حقیقی قیمت کے طور پر، ہجوم کے رول اوور رویے کو ایک نرم جذباتی اشارے کے طور پر پڑھیں، اور کبھی بھی اسٹاک مستقبل کو اس کے حتمی تصفیے میں لاپرواہی سے بڑھنے نہ دیں۔</p>\n","toc":[{"level":2,"text":"معاہدوں کی میعاد ختم ہو جاتی ہے، لیکن ویوز ختم نہیں ہوتے","id":"contracts-expire-but-views-do-not"},{"level":2,"text":"رول اوور میں اصل میں کیا شامل ہوتا ہے۔","id":"what-a-rollover-actually-involves"},{"level":2,"text":"رول اوور لاگت: اسپریڈ جو آپ ادا کرتے ہیں۔","id":"the-rollover-cost-the-spread-you-pay"},{"level":2,"text":"ایک جذباتی سگنل کے طور پر رول اوور فیصد","id":"rollover-percentage-as-a-sentiment-signal"},{"level":2,"text":"ایکسپائری ڈے میکینکس","id":"expiry-day-mechanics"},{"level":2,"text":"ابتدائیوں کو قریب کے مہینے میں کیوں رہنا چاہئے۔","id":"why-beginners-should-stay-in-the-near-month"}],"imgCount":1,"hasContent":true},"16":{"html":"<p>ہر قیمت جو آپ تجارت کرتے ہیں کسی نے مقرر کی تھی۔ جب آپ شیئر سے چند پوائنٹ اوپر ایک RELIANCE مستقبل خریدتے ہیں، تو وہ پریمیم حادثاتی طور پر ظاہر نہیں ہوتا تھا۔ ایک پیشہ ور ڈیسک نے پہلے ہی اسٹاک کو ختم ہونے تک رکھنے کی لاگت کا وزن کیا ہے اور فیصلہ کیا ہے کہ فرق مناسب ہے، اور اگر یہ کبھی بھی منصفانہ سے بہت دور ہو جاتا ہے، تو وہی ڈیسک اس میں قدم رکھتا ہے اور اسے واپس تجارت کرتا ہے۔ یہ باب اس بات کا ڈھکن اٹھاتا ہے کہ وہ پیشہ ور افراد اصل میں اس کیری کے ساتھ کیا کرتے ہیں جو آپ کو پہلے ابواب میں ملے تھے۔ یہ کورس کا سب سے جدید مواد ہے، اور ہو سکتا ہے کہ آپ ان تجارتوں کو خود کبھی نہ کریں۔ لیکن ان کو سمجھنا آپ کو بتاتا ہے کہ آپ جن قیمتوں کے خلاف تجارت کرتے ہیں ان کا تعین کون کرتا ہے، اور کیوں مستقبل اس کے حصے سے دور نہیں بھٹک سکتا ہے۔</p>\n<p>ہم دو پیشہ ورانہ چالوں کو دیکھیں گے۔ پہلا ہے <strong>کیلنڈر پھیلاؤ</strong>، جہاں آپ مارکیٹ کی سمت کے بجائے دو ایکسپائری مہینوں کے درمیان فرق کو تجارت کرتے ہیں۔ دوسرا ہے۔ <strong>بنیاد تجارت</strong>کیش فیوچر ثالثی جو خاموشی سے ہر مستقبل کو اس کی مناسب قیمت سے جوڑتا ہے۔ دونوں براہ راست لے جانے کی لاگت سے بڑھتے ہیں، لہذا اس خیال کو بنیادی باب سے قریب رکھیں۔</p>\n<h2 id=\"trading-the-spread-not-the-direction\">پھیلاؤ کی تجارت، سمت نہیں۔</h2>\n<p>اب تک آپ نے جس بھی پوزیشن کا مطالعہ کیا ہے اس کی ایک سمت رہی ہے۔ لمبے عرصے تک جائیں اور قیمت بڑھنے پر آپ کو فائدہ ہوگا۔ مختصر جاؤ اور اگر یہ گرتا ہے تو آپ کو فائدہ ہوتا ہے۔ ایک کیلنڈر پھیلاؤ مختلف ہے، اور فرق وہ ہے جو اسے آگے بڑھاتا ہے۔</p>\n<p>اے <strong>کیلنڈر پھیلاؤ</strong> اس کا مطلب ہے ایک ہی وقت میں ایک ایکسپائری کا لمبا اور دوسری ایکسپائری کا مختصر ہونا۔ آپ اگست کے مستقبل میں سے ایک لاٹ خرید سکتے ہیں اور جولائی کے مستقبل میں سے ایک لاٹ بیچ سکتے ہیں۔ نوٹ کریں کہ آپ اب کیا مالک ہیں۔ آپ ایک مہینے میں لمبے RELIANCE اور دوسرے مہینے میں مختصر RELIANCE ہیں۔ اگر RELIANCE بحیثیت کمپنی سختی سے چلتی ہے، تو دونوں ٹانگیں ایک ساتھ حرکت کرتی ہیں، لمبا فائدہ اور شارٹ نقصان تقریباً ایک ہی مقدار میں ہوتا ہے، اور دونوں منسوخ ہوجاتے ہیں۔ اگر RELIANCE گر جاتا ہے، تو پھر سے دونوں ٹانگیں ایک ساتھ حرکت کرتی ہیں اور دوبارہ تقریباً منسوخ ہوجاتی ہیں۔ آپ نے اسٹاک کی سمت کو تقریبا مکمل طور پر پوزیشن سے ہٹا دیا ہے۔</p>\n<p>تو کیا فائدہ بچا ہے؟ دی <strong>پھیلاؤ</strong> دو ماہ کے درمیان. آپ اب شرط نہیں لگا رہے ہیں کہ RELIANCE کہاں جاتا ہے۔ آپ شرط لگا رہے ہیں کہ آیا جولائی کی قیمت اور اگست کی قیمت کے درمیان فرق بڑھتا ہے یا کم ہوتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک کیلنڈر کا پھیلاؤ طویل ہوتا ہے جس کی ایک میعاد ختم ہوتی ہے اور دوسری مختصر ہوتی ہے، اس لیے آپ بازار کی سمت کے بجائے دو مہینوں کے درمیان فرق کی تجارت کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"why-the-spread-is-the-cost-of-carry\">کیوں پھیلاؤ لے جانے کی قیمت ہے۔</h2>\n<p>بنیادی باب سے یاد کریں کہ مستقبل اس جگہ سے اوپر کیوں تجارت کرتا ہے۔ پریمیم لے جانے کی لاگت ہے، وقت کے ذریعے بنیادی کو رکھنے کی فنانسنگ لاگت۔ ایک معاہدہ جس کی میعاد مزید دور ہو جاتی ہے اس میں زیادہ دن ہوتے ہیں، لہذا یہ عام طور پر قریبی معاہدے سے زیادہ وسیع پریمیم پر بیٹھتا ہے۔</p>\n<p>یہی وجہ ہے کہ دو مہینے مختلف قیمتوں پر تجارت کرتے ہیں۔ RELIANCE اسپاٹ کے قریب <strong>1,318 روپے</strong>، جولائی کا مستقبل 1322 کے قریب اور اگست کا مستقبل، پورے اضافی مہینے کے ساتھ، 1334 کے قریب بیٹھ سکتا ہے۔ ان کے درمیان تقریباً 12 پوائنٹ کا فرق بے ترتیب نہیں ہے۔ یہ ایک اضافی مہینہ ہے جس کی قیمت مزید معاہدے میں ہے۔ جب آپ کیلنڈر اسپریڈ لگاتے ہیں، تو آپ کی پوزیشن کی قدر ہوتی ہے کہ کیری، اور جس چیز پر آپ واقعی ایک نظریہ لے رہے ہیں وہ یہ ہے کہ آیا مارکیٹ کی فنانسنگ لاگت اور جذبات آپ کے بند ہونے سے پہلے 12 پوائنٹ کے فرق کو بڑھائیں گے یا سکڑیں گے۔</p>\n<p>کیونکہ دونوں ٹانگیں اسٹاک کے ساتھ مل کر چلتی ہیں، اس لیے پوزیشن بہت دور ہے۔ <strong>کم تغیر</strong> بالکل طویل یا مختصر کے مقابلے میں۔ RELIANCE میں 40 پوائنٹ کا جھول بمشکل کیلنڈر اسپریڈ کو چھوتا ہے، جبکہ یہ 500 شیئرز کی ایک لاٹ پر 20,000 روپے کا جھول ہوگا۔ پھیلاؤ ایک تنگ بینڈ میں آہستہ سے سانس لیتا ہے جو کیری کے ذریعے سیٹ کیا جاتا ہے، نہ کہ سٹاک کی جنگلی روزانہ چالوں سے۔ یہ کم تغیر خاص طور پر یہی وجہ ہے کہ پیشہ ورانہ ڈیسک اسے پسند کرتے ہیں۔ وہ سمت پر جوا کھیلنے کے بجائے ایک چھوٹی، اچھی طرح سے سمجھی جانے والی مقدار کاٹ رہے ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>کیلنڈر اسپریڈ کی قدر بنیادی طور پر دو میعاد ختم ہونے کے درمیان لے جانے کی قیمت ہے۔ چونکہ دونوں ٹانگیں اسٹاک کے ساتھ حرکت کرتی ہیں، اس لیے سمت ختم ہو جاتی ہے اور صرف مہینوں کے درمیان پھیلاؤ ہی آپ کے نفع یا نقصان کو آگے بڑھاتا ہے، جو اسے ایک واضح مستقبل کے مقابلے میں بہت کم تغیر والی پوزیشن بناتا ہے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-calendar-spread.png\" alt=\"ایک کیلنڈر اسپریڈ ایک ایکسپائری میں لمبی پوزیشن رکھتا ہے اور اسی انڈر لائننگ کی دوسری میعاد میں مختصر پوزیشن رکھتا ہے، اس لیے اسٹاک کی سمت دونوں ٹانگوں کے درمیان کینسل ہو جاتی ہے اور مہینوں کے درمیان صرف لے جانے والا فاصلہ ہی منافع یا نقصان کو بڑھانے کے لیے باقی رہ جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک کیلنڈر اسپریڈ ایک ایکسپائری میں لمبی پوزیشن رکھتا ہے اور اسی انڈر لائننگ کی دوسری میعاد میں مختصر پوزیشن رکھتا ہے، اس لیے اسٹاک کی سمت دونوں ٹانگوں کے درمیان کینسل ہو جاتی ہے اور مہینوں کے درمیان صرف لے جانے والا فاصلہ ہی منافع یا نقصان کو بڑھانے کے لیے باقی رہ جاتا ہے۔</figcaption></figure>\n<h2 id=\"the-rollover-you-already-know-is-a-calendar-spread\">آپ جو رول اوور پہلے سے جانتے ہیں وہ ایک کیلنڈر اسپریڈ ہے۔</h2>\n<p>یہ وہ حصہ ہے جس میں کچھ کلک کرنا چاہئے۔ آپ پہلے ہی اس کا نام بتائے بغیر ایک کیلنڈر اسپریڈ سے مل چکے ہیں۔ یہ تھا <strong>رول اوور</strong>.</p>\n<p>جب آپ جولائی سے اگست تک ایک طویل RELIANCE پوزیشن رول کرتے ہیں، تو آپ جولائی کے مستقبل کو بند کرنے کے لیے فروخت کرتے ہیں اور اگست کے مستقبل کو دوبارہ کھولنے کے لیے خریدتے ہیں۔ ایک لمحے کے لیے، جولائی کی ٹانگ ختم ہونے سے پہلے، آپ بیک وقت مختصر جولائی اور طویل اگست ہیں۔ یہ بالکل ایک کیلنڈر پھیلاؤ ہے. فرق صرف نیت کا ہے۔ رول اوور ایک کیلنڈر اسپریڈ ہے جو کیری کی کٹائی کے لیے نہیں بلکہ ایکسپائری کے دوران ایک سمتاتی منظر کو آگے لے جانے کے لیے کیا جاتا ہے۔</p>\n<p>اور اس رول اوور کی قیمت، اسپریڈ جو آپ ادا کرتے ہیں، خود ہی کیلنڈر اسپریڈ ہے۔ پہلے کی مثال میں آپ نے جولائی کو 1322 میں فروخت کیا اور اگست کو 1334 میں خریدا، اپنی لمبی عمر کو مزید ایک مہینہ زندہ رکھنے کے لیے 12 پوائنٹس ادا کر کے۔ وہ 12 پوائنٹس بہت سارے 500 شیئرز پر 6000 روپے تھے۔ آج کے لینز سے دیکھا جائے تو، رول اوور لاگت صرف دو مہینوں کے درمیان پھیلے ہوئے کیلنڈر کی قیمت ہے۔ ہر مہینے ایک لمبا رول کریں اور آپ ہر مہینے اس پھیلاؤ کو ادا کرتے ہیں۔ ایک مختصر رول کریں اور آپ دوسری طرف ہیں، مؤثر طریقے سے اسے جمع کر رہے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>جولائی سے اگست تک ایک لمبا RELIANCE لاٹ رول کرنے کا مطلب ہے 1322 کے قریب جولائی بیچنا اور 1334 کے قریب اگست خریدنا۔ ایک لمحے کے لیے آپ کے پاس ایک ساتھ جولائی اور لمبا اگست ہے، جو کہ ایک کیلنڈر اسپریڈ ہے۔ 12 پوائنٹ کا فرق، 500 شیئرز پر 6,000 روپے، اس اسپریڈ کی قیمت اور آپ کے نظریے کو آگے لے جانے کی حقیقی قیمت ہے۔</p>\n</div></div>\n<p>یہی وجہ ہے کہ پیشہ ور رول اوور کی سرگرمی کو بہت قریب سے دیکھتے ہیں۔ رول اوور ہفتے کے دوران پوری مارکیٹ ایک ہی وقت میں کیلنڈر اسپریڈز پر ڈال رہی ہے، اور جس قیمت پر وہ اسپریڈ ٹریڈ کرتا ہے اس سے یہ ظاہر ہوتا ہے کہ مارکیٹ کا اپنا نظریہ ایک اور مہینے تک لے جانے کی خواہش ہے۔</p>\n<h2 id=\"basis-trading-locking-the-carry\">بیس ٹریڈنگ: کیری کو لاک کرنا</h2>\n<p>دوسرا پیشہ ورانہ اقدام اس بات کی وضاحت کرتا ہے کہ بنیاد بالکل کیوں برتاؤ کرتی ہے۔ اسے کہا جاتا ہے۔ <strong>بنیاد تجارت</strong>، یا کیش فیوچر آربیٹریج، اور یہ وہ طریقہ کار ہے جو مستقبل کو ایماندار رکھتا ہے۔</p>\n<p>تصور کریں کہ RELIANCE مستقبل ایک بھرپور پریمیم تک چلا گیا ہے، اس سے کہیں زیادہ کہ لے جانے کی عام قیمت کا جواز پیش کیا جائے گا۔ کہتے ہیں کہ کیری کی قیمت تقریباً 8 پوائنٹس ہونی چاہیے، لیکن بے چین خریداروں نے مستقبل کو 20 پوائنٹس اوور اسپاٹ کے پریمیم کی طرف دھکیل دیا ہے۔ ایک پیشہ ور اس خلا میں مفت رقم دیکھتا ہے۔ وہ ایک ہی وقت میں دو کام کرتے ہیں۔ وہ <strong>کیش مارکیٹ میں اصل حصہ خریدیں۔</strong> 1,318 روپے پر، اور وہ <strong>مستقبل کو فروخت کریں</strong> امیر 1338 پر۔ اب وہ 500 حقیقی حصص کے مالک ہیں اور ان کے مقابلے میں ایک مختصر مستقبل ہے۔</p>\n<p>اس لمحے سے وہ اس بات سے لاتعلق ہیں کہ RELIANCE کہاں جاتا ہے۔ اگر اسٹاک بڑھتا ہے تو، وہ حصص جو ان کے پاس ہیں فائدہ اور مختصر مستقبل اسی رقم سے کھو جاتا ہے۔ اگر یہ کریش ہو جاتا ہے تو حصص کھو جاتے ہیں اور مستقبل میں مختصر فائدہ ہوتا ہے۔ سمت بند ہے۔ انہوں نے جو کچھ حاصل کیا اور لاک ان کیا ہے وہ 20 پوائنٹ پریمیم ہے، جو انہوں نے ادا کی گئی سستی نقد قیمت اور ان کی بیچی ہوئی بھرپور فیوچر قیمت کے درمیان فرق ہے۔</p>\n<p>اب یاد کرو <strong>ہم آہنگی</strong> بنیاد باب سے. میعاد ختم ہونے پر مستقبل کو اسپاٹ قیمت پر طے کرنا چاہیے، اس لیے ایک معلوم تاریخ پر بنیاد کو سکڑ کر صفر ہونا چاہیے۔ یہی یقین ہے جو اس تجارت کو کام کرتا ہے۔ پیشہ ور صرف ختم ہونے کے لئے دونوں ٹانگیں رکھتا ہے۔ انہوں نے جو 20 پوائنٹ پریمیم بیچا وہ معاہدہ کے بدلتے ہی صفر پر پگھل جاتا ہے، اور یہ پورا فرق، ان کی حقیقی لاگت کو کم کر کے، ان کا منافع ہے۔ وہ اسٹاک کی پیش گوئی نہیں کر رہے تھے۔ وہ ایک پریمیم کاٹ رہے تھے جس کے غائب ہونے کی ضمانت تھی۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>چونکہ ایک مستقبل کو ایکسپائری کے وقت جگہ پر اکٹھا ہونا ضروری ہے، اس لیے ایک پریمیم جو بہت زیادہ امیر ہے اسے شیئر خرید کر اور مستقبل کو بیچ کر منافع کے لیے بند کیا جا سکتا ہے۔ یہ ثالثی وہ قوت ہے جو زیادہ پھیلے ہوئے مستقبل کو واپس منصفانہ قدر کی طرف کھینچتی ہے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-basis-arb.png\" alt=\"جب کوئی مستقبل منصفانہ کیری سے زیادہ امیر پریمیم پر تجارت کرتا ہے، تو ایک ثالث نقد مارکیٹ میں حصہ خریدتا ہے اور مستقبل کو بیچتا ہے، اس خلا کو مقفل کرتا ہے، اور کیونکہ بنیاد ختم ہونے پر صفر تک پہنچنا چاہیے اس لیے مقفل پریمیم ان کا منافع بن جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>جب کوئی مستقبل منصفانہ کیری سے زیادہ امیر پریمیم پر تجارت کرتا ہے، تو ایک ثالث نقد مارکیٹ میں حصہ خریدتا ہے اور مستقبل کو بیچتا ہے، اس خلا کو مقفل کرتا ہے، اور کیونکہ بنیاد ختم ہونے پر صفر تک پہنچنا چاہیے اس لیے مقفل پریمیم ان کا منافع بن جاتا ہے۔</figcaption></figure>\n<h2 id=\"why-this-keeps-the-future-tethered\">یہ مستقبل کو کیوں باندھ کر رکھتا ہے۔</h2>\n<p>بیس ٹریڈنگ کی خوبصورتی یہ ہے کہ آپ کو اپنی حفاظت کے لیے اسے کرنے کی ضرورت نہیں ہے۔ محض حقیقت یہ ہے کہ پیشہ ور میزیں کسی بھی امیر پریمیم پر جھپٹنے کے لیے تیار ہیں اس کا مطلب ہے کہ پریمیم کبھی بھی پہلے مقام پر بہت زیادہ امیر نہیں ہو سکتا۔ فوری طور پر مستقبل منصفانہ کیری سے بہت زیادہ بڑھ جاتا ہے، ثالث مستقبل کو بیچ دیتے ہیں اور حصص خریدتے ہیں، اور ان کی فروخت مستقبل کو واپس مناسب قیمت کی طرف دھکیل دیتی ہے۔ وہی ریورس میں کام کرتا ہے. اگر مستقبل میں بلا جواز رعایت آتی ہے، تو میزیں سستا مستقبل خریدتے ہیں اور حصص فروخت کرتے ہیں، اسے واپس اوپر اٹھاتے ہیں۔</p>\n<p>یہ اس سوال کا اصل جواب ہے جو آپ نے بنیادی باب کے بعد سے اٹھایا ہوگا۔ مستقبل جہاں تاجروں کو لگتا ہے وہاں جانے کے لیے آزاد کیوں نہیں ہے؟ کیونکہ اچھی طرح سے سرمایہ دار ثالثوں کی فوج کسی بھی غیر منصفانہ فرق کو واپس منصفانہ قیمت پر تجارت کرنے کے لئے کھڑی ہے۔ مستقبل کو کیری کے ذریعے حصص سے جوڑا جاتا ہے، اور تجارت کی بنیاد رسی ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اس سے فائدہ اٹھانے کے لیے آپ کو کبھی بھی ثالثی کو چلانے کی ضرورت نہیں ہے۔ کسی بھی غیر منصفانہ پریمیم یا رعایت کو دور کرنے کے لیے پیشہ ورانہ میزوں کی تیاری بالکل وہی ہے جو مستقبل کو ایک تنگ، کیری ڈیفائنڈ بینڈ کے اندر اس کی بنیادی باتوں سے باخبر رکھتی ہے۔</p>\n</div></div>\n<h2 id=\"why-a-beginner-does-not-run-pure-arbitrage\">ایک مبتدی خالص ثالثی کیوں نہیں چلاتا</h2>\n<p>آپ کو یہ سوچ کر رخصت کرنا بے ایمانی ہوگی کہ یہ آسان خوردہ رقم ہے۔ خالص کیش فیوچر آربیٹریج ایک پیشہ ور کا کھیل ہے جو مناسب وجوہات کی بنا پر ہے۔</p>\n<ul>\n<li>اس کی ضرورت ہے۔ <strong>پیمانہ</strong>. فیئر کیری اور مارکیٹ پریمیم کے درمیان فرق عام طور پر چھوٹا ہوتا ہے، اکثر مٹھی بھر پوائنٹس، لہذا آپ کو ایک قابل قدر روپے کی رقم حاصل کرنے کے لیے بڑے سائز کی تجارت کرنی چاہیے۔</li>\n<li>اس کی ضرورت ہے۔ <strong>بہت کم اخراجات</strong>. ہر ٹانگ حصص خریدتے وقت اور مستقبل بیچتے وقت، اور دوبارہ کھولنے کے لیے، بروکریج، ٹیکس، اور بولی مانگنے کے پھیلاؤ کو ادا کرتی ہے۔ خوردہ لاگت کا اسٹیک ایک چھوٹی سی غلط قیمت کو زندہ کھا جاتا ہے۔</li>\n<li>اس کی ضرورت ہے۔ <strong>حصص کے لئے مکمل نقد</strong>. آپ 500 اصل RELIANCE شیئرز خرید رہے ہیں، تقریباً 6,59,000 روپے، ایک چھوٹا مارجن پوسٹ نہیں کر رہے ہیں۔ آپ کی مدد کرنے میں کوئی فائدہ نہیں ہے، کیونکہ سارا نقطہ خطرے کو دور کرنا ہے، اسے بڑھانا نہیں۔</li>\n</ul>\n<p>ایک ساتھ رکھیں، ان تین مطالبات کا مطلب یہ ہے کہ کنارے کا تعلق میزوں سے ہے جس میں سستے سرمائے، چھوٹے اخراجات اور کچھ پوائنٹس کو قابل قدر بنانے کا سائز ہے۔ خوردہ لاگت کے ساتھ 4 پوائنٹ پریمیم کا پیچھا کرنے والا ایک ابتدائی فرد صرف چارجز میں اسے ادا کرے گا۔ یہ ایماندارانہ فیصلہ ہے، اور اسی پیمانے اور لاگت کے تقاضے خالص کیلنڈر پھیلانے والی تجارت کو بھی ایک پیشہ ورانہ تعاقب بناتے ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک ابتدائی کے طور پر نقد فیوچر ثالثی کی کوشش نہ کریں۔ غلط قیمت کم ہے، لاگتیں حقیقی ہیں، اور آپ کو بغیر لیوریج کے حصص کی پوری قیمت کے لیے فنڈ کرنا چاہیے۔ تجارت کو سمجھنا قیمتی ہے۔ اسے خوردہ اکاؤنٹ پر چلانے کی کوشش کرنا اپنے بروکر کو اپنی لاگت دینے کا ایک پرسکون طریقہ ہے۔</p>\n</div></div>\n<p>تو یہ سب کیوں سیکھیں اگر آپ تجارت نہیں کریں گے؟ کیونکہ یہ جواب دیتا ہے کہ آپ کس کے خلاف تجارت کر رہے ہیں اور قیمتیں وہیں کیوں بیٹھتی ہیں جہاں وہ کرتے ہیں۔ آپ کے مستقبل کا پریمیم ان کیلنڈرز اور آربیٹریجز کو چلانے والے ڈیسکوں کے ذریعے مقرر کیا جاتا ہے۔ بنیاد پیش گوئی کے ساتھ برتاؤ کرتی ہے کیونکہ وہ اسے نافذ کرتے ہیں۔ اور مستقبل اس کے حصہ سے جڑا رہتا ہے کیونکہ پیشہ ور افراد جب بھی پیسہ کماتے ہیں جب بھی ایسا نہیں ہوتا ہے۔ اب آپ کیری کو نہ صرف اپنی اسکرین پر ایک نمبر کے طور پر سمجھتے ہیں بلکہ ایک ایسی چیز کے طور پر سمجھتے ہیں جس کا زندہ لوگ فعال طور پر انتظام کرتے ہیں۔ عملی راستہ شائستہ اور مفید ہے۔ قریب کے مہینے میں تجارت کی سمت، ہوشیار سرمائے کی طرف سے مقرر کردہ منصفانہ قیمت کے طور پر بنیاد کا احترام کریں، اور اپنی رول اوور لاگت کو صحیح معنوں میں سمجھیں، ایک کیلنڈر پھیلاؤ جسے آپ اپنے نظریے کو زندہ رکھنے کے لیے ادا کر رہے ہیں۔</p>\n","toc":[{"level":2,"text":"پھیلاؤ کی تجارت، سمت نہیں۔","id":"trading-the-spread-not-the-direction"},{"level":2,"text":"کیوں پھیلاؤ لے جانے کی قیمت ہے۔","id":"why-the-spread-is-the-cost-of-carry"},{"level":2,"text":"آپ جو رول اوور پہلے سے جانتے ہیں وہ ایک کیلنڈر اسپریڈ ہے۔","id":"the-rollover-you-already-know-is-a-calendar-spread"},{"level":2,"text":"بیس ٹریڈنگ: کیری کو لاک کرنا","id":"basis-trading-locking-the-carry"},{"level":2,"text":"یہ مستقبل کو کیوں باندھ کر رکھتا ہے۔","id":"why-this-keeps-the-future-tethered"},{"level":2,"text":"ایک مبتدی خالص ثالثی کیوں نہیں چلاتا","id":"why-a-beginner-does-not-run-pure-arbitrage"}],"imgCount":2,"hasContent":true},"17":{"html":"<p>تصور کریں کہ آپ نے ایک فوری لیوریجڈ شرط کے طور پر مستقبل کا ایک بہت حصہ خریدا ہے۔ آپ نے تقریباً ایک لاکھ کا مارجن لگایا، آپ کو یقین تھا کہ اسٹاک بڑھے گا، اور پھر زندگی مصروف ہوگئی اور آپ پوزیشن کو بھول گئے۔ مہینے کا آخری منگل آتا ہے، معاہدہ ختم ہو جاتا ہے، اور کچھ دنوں بعد آپ کا بروکر آپ سے 500 RELIANCE حصص کی پوری قیمت مانگ رہا ہے، تقریباً ساڑھے چھ لاکھ نقد، کیونکہ اب آپ اسٹاک کی اصل ڈیلیوری لینے کے پابند ہیں۔ یہ کوئی خرابی نہیں ہے۔ بالکل اسی طرح سنگل اسٹاک مستقبل کو طے کرنے کے لیے ڈیزائن کیا گیا ہے، اور یہ سب سے زیادہ حیرت انگیز حیرت ہے جو چھوٹے تاجروں کو پکڑتا ہے جو ابھی تک کبھی نہیں پڑھتے ہیں۔</p>\n<p>یہ باب مستقبل کی دنیا میں ایک تیز تقسیم کرنے والی لکیر کے بارے میں ہے۔ جب ایک معاہدہ ختم ہو جاتا ہے اور پہلے سے بند نہیں ہوتا ہے، تو یہ اصل میں کیسے ختم ہوتا ہے؟ RELIANCE جیسے اسٹاک کے مستقبل کے لیے جواب حصص کی فزیکل ڈیلیوری ہے۔ انڈیکس مستقبل کے لیے جیسے کہ NIFTY یا BANKNIFTY جواب ایک سادہ نقد فرق ہے۔ دونوں اس میں زیادہ مختلف نہیں ہوسکتے ہیں کہ وہ آپ سے کیا مطالبہ کرتے ہیں، اور یہ جانتے ہوئے کہ کلین ایگزٹ اور مہنگے حادثے میں کیا فرق ہے۔</p>\n<h2 id=\"two-ways-a-contract-can-finish\">معاہدہ ختم کرنے کے دو طریقے</h2>\n<p>ہر فیوچر کنٹریکٹ میں تصفیہ کا ایک طریقہ ہوتا ہے اس میں آپ کی تجارت سے بہت پہلے۔ آپ اسے منتخب نہیں کرتے۔ ایکسچینج اسے معاہدے کی پوری کلاس کے لیے ٹھیک کرتا ہے۔ صرف دو طریقے ہیں، اور پورا باب ان کو الگ کرنے پر منحصر ہے۔</p>\n<ul>\n<li><strong>جسمانی تصفیہ</strong> مطلب حقیقی اثاثے ختم ہونے پر ہاتھ بدل جاتے ہیں۔ خریدار کنٹریکٹ کی پوری قیمت نقد میں ادا کرتا ہے اور اپنے ڈیمٹ اکاؤنٹ میں بنیادی حصص وصول کرتا ہے۔ بیچنے والا اصل حصص فراہم کرتا ہے اور پوری نقد قیمت وصول کرتا ہے۔ کسی چیز میں فرق نہیں ہے۔ معاہدہ حقیقی طور پر مکمل ہوتا ہے۔</li>\n<li><strong>نقد تصفیہ</strong> مطلب کوئی بھی کچھ نہیں دیتا۔ میعاد ختم ہونے پر آپ کی داخلے کی قیمت اور آخری تصفیہ کی قیمت کے درمیان صرف روپے کا فرق کریڈٹ یا ڈیبٹ کیا جاتا ہے۔ کوئی حصص منتقل نہیں ہوتا ہے، کسی مکمل قیمت کی ضرورت نہیں ہے، پوزیشن صرف ایک منافع یا نقصان کے نمبر میں گھل جاتی ہے۔</li>\n</ul>\n<p>ہندوستان میں قاعدہ صاف ستھرا اور یاد رکھنے کے قابل ہے۔ <strong>تمام سنگل اسٹاک فیوچرز جسمانی طور پر طے پاتے ہیں۔ تمام انڈیکس فیوچر نقد میں طے کرتے ہیں۔</strong> RELIANCE، ایک واحد اسٹاک ہونے کی وجہ سے، جسمانی طور پر آباد ہے۔ NIFTY اور BANKNIFTY، انڈیکس ہونے کے ناطے، کیش سیٹلڈ ہیں۔ ایک بار جب معاہدہ اپنے آخری دن تک پہنچ جاتا ہے تو اس کے درمیان کوئی نہیں ہوتا ہے اور نہ ہی آپٹ آؤٹ ہوتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اسٹاک کا مستقبل حصص کی فزیکل ڈیلیوری سے طے ہوتا ہے۔ ایک انڈیکس مستقبل خالص فرق کے طور پر نقد میں طے ہوتا ہے۔ تصفیہ کا طریقہ پورے کنٹریکٹ کلاس کے تبادلے کے ذریعے طے کیا جاتا ہے، آپ کے ذریعہ منتخب نہیں کیا جاتا ہے۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہاں دو مختلف بستیاں بنتی ہیں، اور ان کو الگ رکھنا قابل قدر ہے۔ آپ کا یومیہ مارک ٹو مارکیٹ منافع یا نقصان ہے a <strong>فنڈز کی تصفیہ</strong>، ہمیشہ نقد ادائیگی کی جاتی ہے۔ دی <strong>ختم ہونے پر حتمی تصفیہ</strong> وہ ہے جو پروڈکٹ کے لحاظ سے مختلف ہوتا ہے: انڈیکس فیوچر خالصتاً نقدی میں ختم ہوتا ہے، جب کہ سنگل اسٹاک فیوچر کو ایکسپائری ختم کرنے کے لیے لے جاتا ہے <strong>سیکورٹیز کی جسمانی ترسیل</strong>، دو ڈیمیٹ اکاؤنٹس کے درمیان منتقل ہونے والے حصص۔ عام NSE کلیئرنگ سیٹلمنٹ میکانزم کا صفحہ بیان کرتا ہے کہ نقد فنڈز - منافع اور نقصان کا تصفیہ، جو کہ شیئر کی ترسیل سے ایک الگ مرحلہ ہے، اس لیے اس کے نقد الفاظ کو نہ پڑھیں کیونکہ اسٹاک مستقبل ترسیل سے گریز کرتا ہے۔ اس بات کی مستند تصدیق کہ سنگل اسٹاک ڈیریویٹوز جسمانی طور پر طے شدہ ہیں NSE ایکویٹی ڈیریویٹوز کنٹریکٹ کی تفصیلات اور NSE کلیئرنگ سیٹلمنٹ شیڈول (اس کا STT شیڈول انھیں فزیکل سیٹلڈ اسٹاک ڈیریویٹیوز کے طور پر درج کرتا ہے)۔ یہ قوانین ایکسچینج اور ریگولیٹر کی طرف سے مقرر کیے گئے ہیں اور اس سے پہلے تبدیل ہو چکے ہیں، لہذا کسی بھی میعاد ختم ہونے سے پہلے وہاں موجودہ علاج کی تصدیق کریں۔</p>\n</div></div>\n<h2 id=\"single-stock-futures-delivery-is-real\">سنگل اسٹاک فیوچر: ترسیل حقیقی ہے۔</h2>\n<p>ہمیں ان نمبروں کے ساتھ ٹھوس ہونے دیں جو آپ پہلے سے جانتے ہیں۔ RELIANCE 1,318 روپے کے قریب ٹریڈ کرتا ہے اور ایک لاٹ 500 شیئرز کا ہے، لہذا ایک لاٹ تقریباً 6,59,000 روپے کے اسٹاک کو کنٹرول کرتا ہے۔ اس پوزیشن کو کھولنے کے لیے آپ نے صرف ایک مارجن پوسٹ کیا، شاید 1,00,000 سے 1,30,000 روپے، جو کہ فیوچر کی پوری اپیل ہے۔ لیوریج تھوڑی مقدار میں کیش کو بڑی مقدار میں اسٹاک کو کنٹرول کرنے دیں۔</p>\n<p>یہ وہ کیچ ہے جو بیعانہ چھپاتا ہے۔ اگر آپ اس طویل RELIANCE مستقبل کو ختم ہونے تک روکے رکھتے ہیں، تو معاہدہ خاموشی سے آپ کو فرق ادا نہیں کرتا اور وہاں سے چلا جاتا ہے۔ یہ ایک فرض میں بدل جاتا ہے۔ <strong>معاہدے کی قیمت پر 500 اصل RELIANCE حصص خریدیں۔</strong>. اب آپ کو پورے 6,59,000 روپے نقد میں پیش کرنے ہوں گے، چھوٹے مارجن سے نہیں، کیونکہ آپ حقیقی طور پر حصص خرید رہے ہیں اور وہ آپ کے ڈیمٹ اکاؤنٹ میں آ جائیں گے۔</p>\n<p>بیچنے والے کو آئینے کی تصویر کا سامنا کرنا پڑتا ہے۔ ایک تاجر جس کا مستقبل RELIANCE کی میعاد ختم ہونے میں کم تھا اب اس کا پابند ہے۔ <strong>500 حقیقی RELIANCE حصص فراہم کریں۔</strong>. اگر وہ حصص ان کے ڈیمیٹ اکاؤنٹ میں نہیں بیٹھے ہیں، تو پوزیشن صاف طور پر طے نہیں کی جاسکتی ہے۔ ایکسچینج کو اپنی طرف سے حصص نیلامی کے ذریعے خریدنا ہوتے ہیں، اور اس کے اخراجات اور جرمانے بیچنے والے پر پڑتے ہیں۔ اسٹاک کے مستقبل کو مختصر طور پر فروخت کرنا اور اس کے بارے میں بھول جانا، اگر کچھ بھی ہے تو، طویل پہلو سے بھی زیادہ خطرناک ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-physical-settlement.png\" alt=\"معیاد ختم ہونے پر سنگل اسٹاک کا مستقبل اثاثوں کے حقیقی تبادلے میں بدل جاتا ہے: خریدار کو تقریباً 6,59,000 روپے کی مکمل کنٹریکٹ ویلیو نقد ادا کرنا ہوگی اور 500 RELIANCE حصص ڈیمیٹ میں وصول کرنا ہوں گے، جب کہ بیچنے والے کو وہ حقیقی حصص ڈیلیور کرنے ہوں گے، اس لیے کوئی بھی فریق اکیلے چھوٹے مارجن پر طے نہیں کرسکتا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایکسپائر ہونے پر ایک سٹاک کا مستقبل اثاثوں کے حقیقی تبادلے میں بدل جاتا ہے: خریدار کو تقریباً 6,59,000 روپے کی مکمل کنٹریکٹ ویلیو نقد میں ادا کرنا ہوگی اور 500 RELIANCE حصص ڈیمیٹ میں وصول کرنا ہوں گے، جب کہ بیچنے والے کو وہ حقیقی حصص ڈیلیور کرنے ہوں گے، لہذا کوئی بھی فریق اکیلے چھوٹے مارجن پر طے نہیں کر سکتا۔</figcaption></figure>\n<p>ایک چھوٹے تاجر کے لیے اس کا کیا مطلب ہے اس کے ساتھ بیٹھیں۔ آپ کو ایک لیوریجڈ دشاتمک شرط چاہیے تھی، جس اسٹاک کی نمائش کے چند دنوں کے لیے آپ نے دیکھا تھا۔ آپ کا کبھی طویل مدتی شیئر ہولڈر بننے کا ارادہ نہیں تھا، اور آپ نے یقینی طور پر اسٹاک خریدنے کے لیے ساڑھے چھ لاکھ مختص نہیں کیے تھے۔ پھر بھی محض کچھ نہ کرنے اور میعاد ختم ہونے کی اجازت دینے سے، آپ کو مکمل ڈیلیوری میں گھسیٹا جا سکتا ہے جسے آپ آرام سے فنڈ نہیں دے سکتے۔ پوری قیمت تلاش کرنے پر مجبور ہونا، یا ان حصص پر جرمانہ عائد کیا جانا جو آپ فراہم نہیں کر سکتے، ایک چھوٹی قیاس آرائی پر مبنی پوزیشن کو ایک بڑے اور مہنگے مسئلے میں بدل دیتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک RELIANCE لاٹ تقریباً 6,59,000 روپے کا اسٹاک ہے۔ اگر آپ طویل مستقبل کو ایکسپائری میں لے جاتے ہیں، تو یہ وہ نقد رقم ہے جو آپ کو ڈیلیوری لینے کے لیے پیدا کرنی چاہیے، نہ کہ تقریباً ایک لاکھ مارجن جس کے ساتھ آپ نے شروعات کی تھی۔ مختصر مستقبل لے کر جائیں اور آپ کو 500 حقیقی حصص حوالے کرنے چاہئیں۔ کسی بھی طرح سے، کچھ نہ کرنا ایک بھاری بل کے ساتھ ایک فیصلہ ہے۔</p>\n</div></div>\n<h2 id=\"the-margin-ramp-that-forces-your-hand\">مارجن ریمپ جو آپ کے ہاتھ کو مجبور کرتا ہے۔</h2>\n<p>ایکسچینج بخوبی جانتا ہے کہ زیادہ تر فیوچر ٹریڈرز کا مطلب کبھی بھی کچھ ڈیلیور کرنا نہیں تھا۔ حادثاتی ڈیلیوری اور ڈیفالٹس کے سیلاب کو روکنے کے لیے، یہ میعاد ختم ہونے کا خاموشی سے انتظار نہیں کرتا۔ یہ جان بوجھ کر آخری دنوں میں اسٹاک مستقبل کو زیادہ سے زیادہ مہنگا بناتا ہے، تاکہ آپ کو شعوری انتخاب کرنے پر مجبور کیا جائے۔</p>\n<p>یہ ہے <strong>فزیکل سیٹلمنٹ مارجن اسپائک</strong>. میعاد ختم ہونے کے دنوں میں، ڈیلیوری ایبل اسٹاک مستقبل کے لیے درکار مارجن کو مراحل میں بڑھایا جاتا ہے۔ جیسے جیسے آخری منگل قریب آتا ہے، ایکسچینج آپ کے معمول کے مارجن کے اوپر ڈیلیوری مارجن کو بتدریج شامل کرتا ہے، اور ہر اس شخص کے لیے جو اب بھی اختتام کے قریب ہے مکمل تصفیہ کی ذمہ داری کی طرف بڑھتا ہے۔ ایک ایسی پوزیشن جو ایک ہفتہ پہلے آرام دہ محسوس کرتی ہے اچانک اسے ختم ہونے والے ہفتے تک کھلا رکھنے کے لیے کہیں زیادہ نقد رقم کا مطالبہ کرتی ہے۔</p>\n<p>نیت ایماندار اور حفاظتی ہے۔ بڑھتا ہوا مارجن ایکسچینج ہے جو آپ کو کندھے پر تھپتھپاتا ہے اور کہتا ہے، ابھی فیصلہ کریں۔ یا تو اصل رقم اور ڈیلیور کرنے کے ارادے کا ارتکاب کریں، یا پوزیشن کو بند کریں اور ایک طرف ہٹ جائیں۔ یہ جان بوجھ کر لاپرواہی سے ایسی ڈیلیوری میں جانے کے آپشن کو ہٹاتا ہے جس کا آپ احترام نہیں کر سکتے۔ ایک ابتدائی کے لیے عملی اثر آسان ہے۔ اگر آپ کو لگتا ہے کہ آپ کی مارجن کی ضرورت تیزی سے بڑھ رہی ہے جیسے جیسے ایکسپائری قریب آتی ہے، تو یہ وہ سسٹم ہے جو آپ کو بتاتا ہے کہ اسٹاک کا مستقبل حقیقی ہونے والا ہے، اور انتظار کرنے کے بجائے عمل کرنا آپ کا اشارہ ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اسٹاک فیوچرز پر ایکسپائری ویک مارجن ریمپ کوئی جرمانہ یا خرابی نہیں ہے۔ یہ ایکسچینج ہے جو ہر ہولڈر کو حقیقی ڈیلیوری کو فنڈ دینے اور بند کرنے کے درمیان انتخاب کرنے پر مجبور کرتی ہے، اس لیے مارکیٹ ان تاجروں سے نہیں بھرتی جو طے نہیں کر سکتے۔ میعاد ختم ہونے کے قریب بڑھتے ہوئے مارجن کو ایک آخری تاریخ کے طور پر سمجھیں جس کے بارے میں آپ کو پیشگی خبردار کیا جا رہا ہے۔</p>\n</div></div>\n<h2 id=\"index-futures-only-the-difference-moves\">انڈیکس فیوچر: صرف فرق چلتا ہے۔</h2>\n<p>اب تقسیم کے دوسری طرف جائیں، اور محسوس کریں کہ یہ کتنا ہلکا ہے۔ انڈیکس ایسی چیز نہیں ہے جسے آپ پکڑ سکتے ہیں۔ آپ NIFTY کی ڈیلیوری نہیں لے سکتے، کیونکہ NIFTY ایک حسابی نمبر ہے جو پچاس کمپنیوں کی ٹوکری کے لیے کھڑا ہے۔ ڈیمیٹ اکاؤنٹ میں ڈالنے کے لیے کوئی NIFTY شیئرز نہیں ہیں۔ لہذا فزیکل ڈیلیوری ناممکن ہے، اور انڈیکس فیوچر مکمل طور پر طے پا جاتے ہیں۔ <strong>نقد</strong>.</p>\n<p>تصویر ایک NIFTY مستقبل۔ لاٹ 65 ہے اور انڈیکس 24,000 کے قریب ہے، لہذا ایک لاٹ تقریباً 15,60,000 روپے کی نمائش کی نمائندگی کرتا ہے۔ اگر آپ اس معاہدے کی میعاد ختم ہونے تک لے جاتے ہیں، تو کچھ بھی نہیں پہنچایا جاتا ہے اور کوئی پوری قیمت طلب نہیں کی جاتی ہے۔ ایکسچینج آپ کے داخلے کی قیمت اور آخری تصفیہ کی قیمت کو دیکھتا ہے، لیتا ہے۔ <strong>روپے کا فرق</strong>، اسے 65 کے لاٹ سے ضرب دیتا ہے، اور اس ایک رقم کو آپ کے اکاؤنٹ میں کریڈٹ یا ڈیبٹ کرتا ہے۔ اگر NIFTY آپ کے خریدے ہوئے مقام سے 100 پوائنٹس اوپر طے کرتا ہے، تو آپ کو 100 گنا 65 ملیں گے، جو کہ 6,500 روپے ہے، اور معاہدہ ختم ہو گیا ہے۔ اگر یہ 100 پوائنٹس کم ہوتا ہے، تو وہی 6,500 روپے ڈیبٹ ہوتے ہیں۔ یہ سارا واقعہ ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-cash-settlement.png\" alt=\"انڈیکس کا مستقبل کچھ بھی فراہم نہیں کر سکتا کیونکہ ایک انڈیکس قابل تجارت اثاثہ نہیں ہے، اس لیے ایکسپائری پر لاگت کی قیمت اور حتمی تصفیہ کی قیمت کے درمیان صرف روپے کا فرق ہاتھ بدلتا ہے، لاٹ سے ضرب کیا جاتا ہے، بغیر کسی حصص کے منتقل ہوتے ہیں اور نہ ہی مکمل معاہدہ کی قیمت کی ضرورت ہوتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>انڈیکس کا مستقبل کچھ بھی فراہم نہیں کر سکتا کیونکہ ایک انڈیکس قابل تجارت اثاثہ نہیں ہے، اس لیے ایکسپائری پر لاگت کی قیمت اور حتمی تصفیہ کی قیمت کے درمیان صرف روپے کا فرق ہاتھ بدلتا ہے، لاٹ سے ضرب کیا جاتا ہے، بغیر کسی حصص کے منتقل ہوتے ہیں اور نہ ہی مکمل معاہدہ کی قیمت کی ضرورت ہوتی ہے۔</figcaption></figure>\n<p>ہر وہ چیز دیکھیں جو یہاں نہیں ہوتی۔ آپ کے ڈیمیٹ اکاؤنٹ میں کوئی حصص ظاہر نہیں ہوتا ہے۔ آپ سے کبھی بھی پورے 15,60,000 روپے نہیں مانگے جاتے۔ کوئی نیلامی نہیں ہے، کوئی ڈیلیوری جرمانہ نہیں ہے، اس فرق سے آگے کوئی ذمہ داری نہیں ہے جسے آپ پہلے ہی اپنا نفع یا نقصان سمجھ چکے ہیں۔ یہاں تک کہ اگر آپ ایکسپائری میں انڈیکس کی پوزیشن کو مکمل طور پر بھول جاتے ہیں، تب بھی سب سے برا ہوتا ہے آپ کا عام منافع یا نقصان نقد میں طے ہوتا ہے، بالکل اسی طرح جیسے آپ نے خود تجارت بند کر دی ہو۔ حادثاتی ترسیل کا جال جو اسٹاک فیوچر کو پریشان کرتا ہے یہاں موجود نہیں ہوسکتا ہے۔</p>\n<p>یہ ایک اور ٹھوس وجہ ہے کہ ایک ابتدائی عام طور پر سنگل اسٹاک کے بجائے انڈیکس سے شروع ہوتا ہے۔ انڈیکس فیوچرز گہرے مائع ہوتے ہیں، یہ آپ کو سنگل کمپنی کی خبروں کے جھٹکے سے بچاتے ہیں، اور اہم طور پر وہ جسمانی ترسیل کے تمام خطرے کو دور کرتے ہیں۔ بہت کم ہے جو حادثاتی طور پر بری طرح غلط ہو سکتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>آپ NIFTY مستقبل کو اس کے آخری سیکنڈ تک رکھ سکتے ہیں اور صرف ایک چیز جو ہو سکتی ہے وہ ہے آپ کے منافع یا نقصان کا نقد کریڈٹ یا ڈیبٹ۔ انڈیکس کے مستقبل کا کوئی ورژن نہیں ہے جہاں آپ حقیقی حصص کے مالک، یا واجب الادا ہوں۔ آلہ ترسیل کے قابل نہیں ہے۔</p>\n</div></div>\n<h2 id=\"the-final-settlement-price\">حتمی تصفیہ کی قیمت</h2>\n<p>دونوں طریقے، چاہے حصص ہوں یا نقد رقم کی تبدیلی، میعاد ختم ہونے والے دن مقرر کردہ ایک سرکاری نمبر کے خلاف ماپا جاتا ہے، اس لیے اس کے بارے میں درست ہونا ضروری ہے۔ دی <strong>حتمی تصفیہ کی قیمت</strong> بنیادی سے آتا ہے. انڈیکس کے مستقبل کے لیے جیسے کہ NIFTY یہ انڈیکس کی باضابطہ اختتامی قدر ہے۔ سنگل اسٹاک کے مستقبل کے لیے جیسے کہ RELIANCE یہ بنیادی حصص کا ایکسچینج سے طے شدہ آفیشل کلوز ہے۔</p>\n<p>سے <strong>3 اگست 2026</strong>، وہ اسٹاک بند عام طور پر کے ذریعے دریافت کیا جاتا ہے <strong>اختتامی نیلامی سیشن ( CAS)</strong> کیونکہ مشتقات کے ساتھ اسٹاک پہلے CAS مرحلے میں شامل ہیں۔ مسلسل کیش ٹریڈنگ 15:15 پر ختم ہوتی ہے۔ 15:00-15:15 VWAP ایک حوالہ قیمت بن جاتا ہے، اور نیلامی توازن کی قیمت کا انتخاب کرتی ہے جو قابل عمل مقدار کو زیادہ سے زیادہ کرتی ہے۔ اگر کوئی توازن کی قیمت نہیں ملتی ہے تو، VWAP حوالہ قریب ہو جاتا ہے۔ یہ پرانے اصول کی جگہ لے لیتا ہے جس نے ان اسٹاکس کے لیے بند ہونے والی ونڈو VWAP کو عام حتمی بند کے طور پر سمجھا تھا۔</p>\n<p>کیش سیٹلڈ انڈیکس مستقبل کے لیے، آفیشل انڈیکس کلوز نقد فرق کا تعین کرتا ہے۔ انڈیکس میں بذات خود کوئی الگ CAS نہیں ہے، لیکن اس کی قدر CAS کے اجزاء کے لیے نیلامی سے دریافت شدہ بندوں کا استعمال کرتی ہے اور VWAP CAS سے باہر کے اجزاء کے لیے بند ہوتی ہے۔ جسمانی طور پر طے شدہ اسٹاک کے مستقبل کے لیے، زیرِ نظر اسٹاک کا آفیشل کلوز ڈیلیوری سیٹلمنٹ ویلیو کا تعین کرتا ہے۔ ایکویٹی ڈیریویٹیو کنٹریکٹس خود 15:40 تک تجارت جاری رکھتے ہیں اور اپنا اپنا 15:10-15:40 VWAP بند کرنے کا طریقہ برقرار رکھتے ہیں۔ اس معاہدے کو بنیادی کی CAS سے حاصل شدہ حتمی تصفیہ کی قیمت کے ساتھ الجھائیں نہیں۔</p>\n<h2 id=\"the-blunt-rule-to-carry-away\">لے جانے کا دو ٹوک اصول</h2>\n<p>تفصیل کو ہٹا دیں اور رہنمائی مختصر ہے، اور یہ ایک قسم کا اصول ہے جس پر بغیر کسی استثناء کے عمل کرنا چاہیے۔</p>\n<p><strong>جب تک آپ حقیقی طور پر ڈیلیوری دینے یا لینے کا ارادہ نہ رکھتے ہوں اس وقت تک ایک ہی سٹاک مستقبل کو ختم نہ کریں۔</strong> اگر آپ لیوریجڈ شرط چاہتے ہیں اور اس سے زیادہ کچھ نہیں تو آخری دنوں سے پہلے پوزیشن کو بند کر دیں یا اسے اگلے مہینے تک لے جائیں، جب کہ لیکویڈیٹی اچھی ہے اور ڈیلیوری کا مارجن ابھی کم نہیں ہوا ہے۔ مہینے کے آخری منگل کو ایک سخت ڈیڈ لائن کے طور پر سمجھیں جس دن سے آپ کنٹریکٹ کے نام پر مہر لگاتے ہیں، اور اس سے پہلے عمل کریں، اس پر نہیں۔</p>\n<p>انڈیکس فیوچرز آپ کو اس چوکسی میں نرمی کرنے دیتے ہیں، کیونکہ بدترین صورت منافع یا نقصان کا نقد تصفیہ ہے جسے آپ پہلے ہی سمجھ چکے ہیں۔ اسٹاک فیوچر ایسا نہیں کرتے۔ وہی لیوریج جس نے RELIANCE پوزیشن کو پرکشش بنایا بالکل وہی ہے جو حادثاتی ڈیلیوری کو اتنا تکلیف دہ بناتا ہے، کیونکہ پوری قدر آپ کے لگائے گئے مارجن کو کم کرتی ہے۔ جانیں کہ آپ کا معاہدہ تقسیم کے کس طرف ہے، اور کبھی بھی قابل ترسیل اسٹاک مستقبل کو آخری دنوں میں خاموشی سے نہ جانے دیں۔ وہ ایک عادت آپ کو تمام فیوچر ٹریڈنگ میں سب سے مہنگے سرپرائز سے بچا لے گی۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ تجارت کھولیں گے تو اپنے کیلنڈر پر ہر اسٹاک-مستقبل کی میعاد ختم ہونے کو نشان زد کریں، اور پہلے سے فیصلہ کریں کہ آیا آپ ڈیلیوری کو بند کریں گے، رول کریں گے یا حقیقی طور پر لیں گے۔ اگر آپ کبھی بھی صرف لیوریجڈ شرط چاہتے ہیں، تو اس کا جواب تقریباً ہمیشہ فزیکل سیٹلمنٹ ہفتہ سے پہلے نکلنا ہے، اس میں نہیں۔</p>\n</div></div>\n","toc":[{"level":2,"text":"معاہدہ ختم کرنے کے دو طریقے","id":"two-ways-a-contract-can-finish"},{"level":2,"text":"سنگل اسٹاک فیوچر: ترسیل حقیقی ہے۔","id":"single-stock-futures-delivery-is-real"},{"level":2,"text":"مارجن ریمپ جو آپ کے ہاتھ کو مجبور کرتا ہے۔","id":"the-margin-ramp-that-forces-your-hand"},{"level":2,"text":"انڈیکس فیوچر: صرف فرق چلتا ہے۔","id":"index-futures-only-the-difference-moves"},{"level":2,"text":"حتمی تصفیہ کی قیمت","id":"the-final-settlement-price"},{"level":2,"text":"لے جانے کا دو ٹوک اصول","id":"the-blunt-rule-to-carry-away"}],"imgCount":2,"hasContent":true},"18":{"html":"<p>جب کوئی ابتدائی طور پر قابل تجارت مستقبل کی فہرست کھولتا ہے تو دو بالکل مختلف قسم کے معاہدے ساتھ ساتھ بیٹھتے ہیں۔ ایک ایک کمپنی کا مستقبل ہے، جیسے RELIANCE، جہاں اس ایک کاروبار کی خوش قسمتی کے ساتھ قیمت بڑھتی اور گرتی ہے۔ دوسرا ایک پورے انڈیکس کا مستقبل ہے، جیسے NIFTY یا BANKNIFTY، جہاں قیمت بہت سی کمپنیوں کی ایک ٹوکری کو ایک ساتھ منتقل کرنے کی عکاسی کرتی ہے۔ وہ اسکرین پر ایک جیسے نظر آتے ہیں، دونوں کی قیمت، بہت زیادہ سائز اور ایکسپائری ہے، لیکن وہ مختلف طریقے سے برتاؤ کرتے ہیں جو آپ کے خطرے کے لیے بہت اہم ہیں۔ اپنے تجربے کی سطح کے لیے غلط کا انتخاب کرنا ایک عام ابتدائی غلطی ہے، اس لیے آئیے واضح طور پر دیکھیں کہ ان کو کیا الگ کرتا ہے۔</p>\n<p>مختصر ورژن یہ ہے۔ ایک <strong>انڈیکس مستقبل</strong> متنوع ٹوکری کو ٹریک کرتا ہے اور آسانی سے حرکت کرتا ہے۔ اے <strong>اسٹاک مستقبل</strong> ایک کمپنی کو ٹریک کرتا ہے اور خبروں کے ایک ٹکڑے پر پرتشدد طور پر جھک سکتا ہے۔ دونوں مفید ہیں، لیکن وہ یکساں طور پر معاف کرنے والے نہیں ہیں، اور ایک نیا آنے والا عام طور پر انڈیکس کے ساتھ شروع کرتے ہوئے زیادہ محفوظ ہوتا ہے۔</p>\n<h2 id=\"two-kinds-of-underlying\">دو قسم کی بنیادی چیزیں</h2>\n<p>فرق اس سے شروع ہوتا ہے جس پر معاہدہ بنایا گیا ہے۔ اے <strong>اسٹاک مستقبل</strong> اس کے بنیادی طور پر ایک حصہ ہے. RELIANCE ہماری چل رہی مثال ہے، ارد گرد تجارت <strong>1,318 روپے</strong>، بہت سے کے ساتھ <strong>500 شیئرز</strong>لہذا ایک کنٹریکٹ ایک کمپنی کے تقریباً 6,59,000 روپے کو کنٹرول کرتا ہے۔ اگر RELIANCE خراب کمائی کی اطلاع دیتا ہے یا اسے کسی ریگولیٹری ہیڈ لائن کا سامنا کرنا پڑتا ہے، تو وہ ایک واقعہ آپ کی پوری پوزیشن کو چلاتا ہے۔</p>\n<p>ایک <strong>انڈیکس مستقبل</strong> اس کے بنیادی طور پر ایک انڈیکس ہے. ہندوستان میں سب سے زیادہ تجارت کرنے والے دو ہیں۔ <strong>NIFTY</strong>، بہت سے کے ساتھ <strong>65</strong>، اور <strong>BANKNIFTY</strong>، بہت سے کے ساتھ <strong>30</strong>. ایک انڈیکس ایک کمپنی نہیں ہے بلکہ بہت سے لوگوں کی وزنی ٹوکری ہے۔ NIFTY مختلف شعبوں میں پچاس بڑی کمپنیوں کو ٹریک کرتا ہے۔ BANKNIFTY بڑے بینکوں کو ٹریک کرتا ہے۔ جب آپ مستقبل کے اشاریہ کی تجارت کرتے ہیں، تو کسی ایک کمپنی کی خبر آپ کی پوزیشن پر حاوی نہیں ہو سکتی، کیونکہ انڈیکس مختلف سمتوں میں آنے والے بہت سے ناموں کا اوسط ہوتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اسٹاک کا مستقبل ایک کمپنی پر سوار ہوتا ہے۔ ایک انڈیکس مستقبل بہت سی کمپنیوں کی متنوع ٹوکری پر سوار ہوتا ہے۔ یہ ایک فرق تقریباً ہر چیز کو شکل دیتا ہے کہ دونوں کیسے برتاؤ کرتے ہیں اور وہ آپ کو کتنا حیران کر سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"cash-settlement-versus-delivery\">کیش سیٹلمنٹ بمقابلہ ترسیل</h2>\n<p>دونوں میعاد ختم ہونے پر بھی مختلف طریقے سے طے پاتے ہیں، اور یہ ابتدائی افراد کو چوکس کر دیتا ہے۔ <strong>انڈیکس فیوچر نقد سے طے شدہ ہیں۔</strong> حوالے کرنے کے لیے حصص کی کوئی ٹوکری نہیں ہے، اس لیے ایکسپائر ہونے پر پوزیشن صرف آخری سیٹلمنٹ قیمت پر بند ہو جاتی ہے اور نفع یا نقصان کو نقد میں ایڈجسٹ کیا جاتا ہے۔ کچھ بھی جسمانی ہاتھ نہیں بدلتا۔ آپ ڈیلیوری ذمہ داری کے کسی خوف کے بغیر میعاد ختم ہونے کے لیے NIFTY مستقبل رکھ سکتے ہیں۔</p>\n<p>اے <strong>اسٹاک مستقبل</strong> بھارت میں کی طرف سے آباد ہے <strong>جسمانی ترسیل</strong> اگر میعاد ختم ہونے تک لے جایا جائے۔ حتمی تصفیہ کے لیے ایک RELIANCE ہولڈ کریں اور آپ 500 حقیقی حصص کی ڈیلیوری لینے اور پوری قیمت، تقریباً 6,59,000 روپے ادا کرنے کے پابند ہو سکتے ہیں، جو آپ کے پوسٹ کیے گئے مارجن سے کہیں زیادہ ہے۔ یہی وجہ ہے کہ پچھلے باب کا رول اوور ڈسپلن اسٹاک فیوچر کے لیے انڈیکس فیوچر کے مقابلے میں بہت زیادہ اہمیت رکھتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>فیچر</th>\n<th>انڈیکس مستقبل ( NIFTY، BANKNIFTY)</th>\n<th>اسٹاک مستقبل (RELIANCE)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیرِ نظر</td>\n<td>بہت سی کمپنیوں کی ٹوکری۔</td>\n<td>ایک ہی کمپنی</td>\n</tr>\n<tr>\n<td>لاٹ سائز</td>\n<td>NIFTY 65،BANKNIFTY 30</td>\n<td>500</td>\n</tr>\n<tr>\n<td>میعاد ختم ہونے پر تصفیہ</td>\n<td>کیش</td>\n<td>جسمانی ترسیل</td>\n</tr>\n<tr>\n<td>سنگل کمپنی کی خبروں کا خطرہ</td>\n<td>ٹوکری بھر میں پتلا</td>\n<td>مکمل طور پر آپ پر آتا ہے۔</td>\n</tr>\n<tr>\n<td>عام لیکویڈیٹی</td>\n<td>بہت گہرا</td>\n<td>بڑے ناموں میں اچھا، چھوٹے میں پتلا</td>\n</tr>\n</tbody></table>\n<h2 id=\"liquidity-depth-makes-a-market-fair\">لیکویڈیٹی: گہرائی مارکیٹ کو منصفانہ بناتی ہے۔</h2>\n<p><strong>لیکویڈیٹی</strong> یہ ہے کہ آپ قیمت کو اپنے خلاف کیے بغیر کتنی آسانی سے داخل اور باہر نکل سکتے ہیں۔ انڈیکس فیوچر، خاص طور پر NIFTY اور BANKNIFTY، پوری ہندوستانی مارکیٹ میں سب سے زیادہ مائع آلات میں سے ہیں۔ بہت زیادہ حجم ہر سیشن میں تجارت کرتا ہے، خرید و فروخت کی قیمت کے درمیان فرق سخت ہے، اور یہاں تک کہ ایک بڑا آرڈر مناسب قیمت پر آسانی سے پُر ہو جاتا ہے۔</p>\n<p>اسٹاک فیوچر مختلف ہوتے ہیں۔ RELIANCE جیسے سب سے بڑے نام بہت مائع ہیں اور اچھی طرح سے تجارت کرتے ہیں، سخت اسپریڈز اور کافی گہرائی کے ساتھ۔ لیکن بہت سے چھوٹے اسٹاک فیوچر پتلے ہیں۔ خرید و فروخت کی قیمت کے درمیان ایک وسیع فرق کا مطلب ہے کہ آپ اندر اور باہر جانے کے لیے زیادہ ادائیگی کرتے ہیں، اور ایک ہی آرڈر قیمت کو ادھر ادھر ہلا سکتا ہے۔ لہذا جب کہ سب سے بڑا اسٹاک فیوچر تجارت کرنا آسان ہے، اوسط اسٹاک مستقبل انڈیکس مستقبل سے کم قابل اعتماد ہے۔</p>\n<ul>\n<li>انڈیکس فیوچرز مارکیٹ میں سب سے گہری، سب سے زیادہ مستقل لیکویڈیٹی پیش کرتے ہیں۔</li>\n<li>RELIANCE جیسے بڑے اسٹاک فیوچر بھی مائع ہیں اور منصفانہ تجارت کرتے ہیں۔</li>\n<li>چھوٹے اسٹاک فیوچر پتلے ہوسکتے ہیں، وسیع اسپریڈز اور تیز قیمتوں کے ساتھ۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>لیکویڈیٹی عیش و آرام نہیں ہے، یہ تحفظ ہے۔ ایک گہری مارکیٹ میں آپ کا اسٹاپ اس کے قریب بھر جاتا ہے جہاں آپ نے اسے رکھا تھا۔ ایک پتلی میں، ایک تیز حرکت آپ کو توقع سے کہیں زیادہ خراب کر سکتی ہے۔ انڈیکس فیوچرز ابتدائی طور پر دستیاب سب سے گہری لیکویڈیٹی فراہم کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"gap-risk-the-single-stock-danger\">فرق کا خطرہ: واحد اسٹاک خطرہ</h2>\n<p>یہاں سب سے اہم عملی فرق ہے، اور اس وجہ سے کہ اسٹاک کا مستقبل ایک ابتدائی کو بری طرح سے نقصان پہنچا سکتا ہے۔ ایک کمپنی کو اچانک خبروں، کمائی کا جھٹکا، ایک ریگولیٹری آرڈر، کریڈٹ میں کمی، ایک مینجمنٹ ایگزٹ، جو کہ تجارتی اوقات سے باہر پہنچتی ہے، کا نشانہ بن سکتی ہے۔ جب مارکیٹ دوبارہ کھلتی ہے، تو کل کے بند سے اسٹاک آسانی سے آگے نہیں بڑھتا ہے۔ یہ <strong>خلا</strong>, ایک بالکل مختلف قیمت پر کھلنا جس کے درمیان تجارت کا کوئی موقع نہیں ہے۔ آپ کا سٹاپ نقصان، وہ سطح جہاں سے آپ باہر نکلنا چاہتے تھے، بس چھلانگ لگا دی گئی ہے۔ آپ بہت بدتر ہیں، اور مستقبل کا فائدہ کئی گنا بڑھ جاتا ہے جو سیدھے آپ کے مارجن اکاؤنٹ میں جاتا ہے۔</p>\n<p>اس خطرے کو محسوس کرنے کے لیے ایک حقیقی واحد اسٹاک کو دیکھیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/chart-reliance-daily.png\" alt=\"RELIANCE گزشتہ 120 سیشنز میں روزانہ کینڈلز، 1,318 روپے کے قریب بند ہو رہی ہیں۔ اس ایک کمپنی کی خبر پر ایک ہی اسٹاک کا مستقبل زندہ یا مر جاتا ہے، اور راتوں رات ایک سرپرائز اگلی موم بتی کو آخری بند سے بہت دور کھول سکتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>RELIANCE گزشتہ 120 سیشنز میں روزانہ کینڈلز، 1,318 روپے کے قریب بند ہو رہی ہیں۔ اس ایک کمپنی کی خبر پر ایک ہی اسٹاک کا مستقبل زندہ رہتا ہے یا مر جاتا ہے، اور راتوں رات ایک سرپرائز اگلی موم بتی کو آخری بند سے بہت دور کھول سکتا ہے۔</figcaption></figure>\n<p>ان موم بتیوں کا مطالعہ کریں۔ زیادہ تر دن معمولی طور پر آگے بڑھتے ہیں، لیکن سنگل سٹاک چارٹ کبھی کبھار چھلانگیں دکھائے گا جہاں قیمت پہلے کی بندش سے بہت دور کھلی تھی۔ ان میں سے ہر ایک فرق اس خبر کی نمائندگی کرتا ہے جو مارکیٹ کے بند ہونے کے دوران مارا جاتا ہے۔ اس طرح کے فرق کے ذریعے لیوریجڈ RELIANCE مستقبل کے انعقاد کا مطلب ہے کہ آپ اس خلا میں ہی رد عمل ظاہر کرنے کا کوئی موقع نہیں رکھتے ہوئے پوری چال پہنتے ہیں۔</p>\n<p>ایک انڈیکس اس کو کم کرتا ہے۔ پورے NIFTY کو پرتشدد طریقے سے فرق کرنے کے لیے، بہت سی کمپنیوں کو ایک ساتھ مارنا پڑے گا، جس کے لیے عام طور پر ایک کمپنی کے برے دن کی بجائے ایک وسیع مارکیٹ جھٹکا درکار ہوتا ہے۔ انڈیکس کے ایک رکن کی تباہی کو انتالیس دیگر افراد نے نرم کیا ہے۔ اس لیے انڈیکس فیوچر کا فرق بھی، لیکن کمپنی سے متعلق خبروں پر بہت کم وحشیانہ طور پر، کیونکہ کوئی بھی کمپنی ٹوکری کو کنٹرول نہیں کرتی۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>فرق کا خطرہ سنگل اسٹاک فیوچرز کا واضح خطرہ ہے۔ ایک لیوریجڈ اسٹاک پوزیشن کمپنی کی خبروں پر راتوں رات آپ کے اسٹاپ کے ذریعے اڑا سکتی ہے جو آپ نے کبھی نہیں دیکھی تھی۔ انڈیکس اس خطرے کو کئی ناموں میں پھیلاتا ہے۔ ایک اسٹاک اسے مکمل طور پر آپ پر مرکوز کرتا ہے۔</p>\n</div></div>\n<h2 id=\"practical-differences-in-risk-and-use\">خطرے اور استعمال میں عملی فرق</h2>\n<p>ٹکڑوں کو ایک ساتھ رکھیں اور دونوں آلات مختلف مقاصد کے مطابق ہیں۔ <strong>انڈیکس فیوچرز</strong> وسیع مارکیٹ میں تجارت کے لیے، معیشت پر یا بینکوں پر ایک شعبے کے طور پر اپنے خیالات کا اظہار کرنے، اور متنوع پورٹ فولیو کو ہیج کرنے کے لیے، جو کہ اگلے باب کا موضوع ہے۔ وہ ہموار، گہرائی سے مائع، نقد رقم اور واحد کمپنی کی بارودی سرنگوں سے پاک ہیں۔</p>\n<p><strong>اسٹاک فیوچر</strong> ایک مخصوص کمپنی کو دیکھنے کا آلہ ہے۔ اگر آپ کی تحقیق یہ کہتی ہے کہ خاص طور پر RELIANCE کی قیمت غلط ہے، تو اسٹاک کا مستقبل آپ کو بالکل اسی پر عمل کرنے دیتا ہے، دوسرے ناموں سے کوئی کمی نہیں کرتے۔ یہی نفاست ان کی طاقت اور خطرہ ہے۔ جب آپ صحیح ہوتے ہیں تو آپ کو مکمل حرکت ملتی ہے، اور جب خبریں آپ کو اندھا کر دیتی ہیں تو پورا خلا حاصل ہوتا ہے۔</p>\n<ul>\n<li>انڈیکس مستقبل کا استعمال کریں تاکہ مجموعی مارکیٹ یا ایک پورے شعبے میں تنوع کو شامل کیا جاسکے۔</li>\n<li>ایک کمپنی کے مخصوص، اچھی طرح سے تحقیق شدہ نقطہ نظر پر عمل کرنے کے لیے اسٹاک مستقبل کا استعمال کریں۔</li>\n<li>انڈیکس سے ہموار رویے کی توقع کریں اور سنگل اسٹاک سے زیادہ تیز رویے کی توقع کریں۔</li>\n</ul>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>بینکنگ سیکٹر میں تیزی سے کام کرنے والا تاجر ایک BANKNIFTY مستقبل خریدتا ہے، بہت زیادہ 30، اور ایک ہی وقت میں کئی بینکوں کے سامنے آتا ہے، اس لیے کسی ایک بینک کی ٹھوکر تجارت کو تباہ نہیں کرتی۔ ایک تاجر جو اس بات پر قائل ہے کہ اکیلے ہی کم قیمت ہے ایک RELIANCE مستقبل خریدتا ہے، بہت زیادہ 500، اور قبول کرتا ہے کہ اب ایک کمپنی کی خبر پوری پوزیشن کو چلاتی ہے۔</p>\n</div></div>\n<h2 id=\"why-a-beginner-usually-starts-with-the-index\">ایک ابتدائی عام طور پر انڈیکس سے کیوں شروع ہوتا ہے۔</h2>\n<p>فیوچرز میں نئے کسی کے لیے، انڈیکس تقریباً ہمیشہ نرم کلاس روم ہوتا ہے۔ لیکویڈیٹی سب سے زیادہ دستیاب ہے، اس لیے اندراج اور اخراج مناسب ہے۔ نقدی کا تصفیہ لاکھوں مالیت کی حادثاتی ترسیل کی ذمہ داری کے خوف کو دور کرتا ہے۔ اور ٹوکری کے تنوع کا مطلب یہ ہے کہ ایک مبتدی کو راتوں رات اس سفاکانہ فرق کے خطرے کا سامنا نہیں کرنا پڑتا ہے کہ ایک اسٹاک بغیر وارننگ کے بڑھ سکتا ہے۔</p>\n<p>اس میں سے کوئی بھی انڈیکس کو محفوظ نہیں بناتا ہے۔ یہ اب بھی ایک لیوریجڈ انسٹرومنٹ ہے جو تیزی سے پیسے کھو سکتا ہے، اور اگلے ابواب آپ کو اسے بھولنے نہیں دیتے ہیں۔ لیکن ان دونوں میں سے، انڈیکس طویل اور مختصر سفر کرنے، مارک ٹو مارکیٹ پڑھنے، اور پوزیشن کو سنبھالنے کے طریقہ کار کو سیکھنے کے لیے زیادہ بخشنے والی جگہ ہے، بغیر کسی ایک کمپنی کے راتوں رات آپ کے خلاف ہونے والے اضافی خطرے کے۔</p>\n<p>دیرپا نقطہ یہ ہے کہ انڈیکس اور اسٹاک فیوچر کزن ہیں، جڑواں نہیں۔ انڈیکس آپ کو متنوع، گہرائی سے مائع، نقدی سے طے شدہ ٹوکری فراہم کرتا ہے جو آسانی سے چلتی ہے۔ سنگل سٹاک آپ کو ایک تیز، ارتکاز شرط فراہم کرتا ہے جو کسی کمپنی کی خبروں پر سختی سے فرق کر سکتا ہے اور میعاد ختم ہونے پر فزیکل ڈیلیوری کا مطالبہ کر سکتا ہے۔ انڈیکس کے ساتھ شروع کریں، جانیں کہ مستقبل آپ کے خطرے کو پھیلانے والی وسیع مارکیٹ کے ساتھ کیسا برتاؤ کرتا ہے، اور صرف ایک بار واحد اسٹاک فیوچرز میں گریجویٹ ہو جائیں جب آپ اس فرق کا احترام کریں جو صرف ایک نام پر شرط لگانے کے ساتھ آتا ہے۔</p>\n","toc":[{"level":2,"text":"دو قسم کی بنیادی چیزیں","id":"two-kinds-of-underlying"},{"level":2,"text":"کیش سیٹلمنٹ بمقابلہ ترسیل","id":"cash-settlement-versus-delivery"},{"level":2,"text":"لیکویڈیٹی: گہرائی مارکیٹ کو منصفانہ بناتی ہے۔","id":"liquidity-depth-makes-a-market-fair"},{"level":2,"text":"فرق کا خطرہ: واحد اسٹاک خطرہ","id":"gap-risk-the-single-stock-danger"},{"level":2,"text":"خطرے اور استعمال میں عملی فرق","id":"practical-differences-in-risk-and-use"},{"level":2,"text":"ایک ابتدائی عام طور پر انڈیکس سے کیوں شروع ہوتا ہے۔","id":"why-a-beginner-usually-starts-with-the-index"}],"imgCount":1,"hasContent":true},"19":{"html":"<p>دو تاجر ایک ہی RELIANCE کو 1,318 روپے سے 1,340 روپے کی طرف بڑھتے ہوئے دیکھتے ہیں اور مخالف نتائج پر پہنچتے ہیں۔ ایک صحت مند ریلی میں شامل ہونے کے قابل دیکھتا ہے۔ دوسرا دھندلاہٹ کے قابل ایک تھکا ہوا اچھال دیکھتا ہے۔ وہ ایک ہی قیمت کو دیکھ رہے ہیں، تو دوسرا تاجر کیا دیکھ رہا ہے کہ پہلا غائب ہے؟ اکثر جواب ہوتا ہے۔ <strong>کھلی دلچسپی</strong>، ایک ایسا نمبر جو ہر فیوچر اسکرین پر قیمت اور والیوم کے ساتھ خاموشی سے بیٹھتا ہے اور آپ کو وہ کچھ بتاتا ہے جو دوسرے میں سے کوئی نہیں کرسکتا۔ قیمت آپ کو بتاتی ہے کہ معاہدہ کہاں تجارت کرتا ہے۔ حجم آپ کو بتاتا ہے کہ سیشن کتنا مصروف تھا۔ کھلی دلچسپی آپ کو بتاتی ہے کہ میز پر ابھی بھی کتنی شرطیں ہیں، اور آیا ہجوم پوزیشن بنا رہا ہے یا خاموشی سے باہر نکلنے کی طرف بڑھ رہا ہے۔</p>\n<p>ایک بار جب آپ اسے پڑھنا سیکھ لیں تو، کھلی دلچسپی فلیٹ قیمت کے چارٹ کو عزم کے بارے میں ایک کہانی میں بدل دیتی ہے۔ یہ آپ کو نہیں بتائے گا کہ کیا خریدنا ہے۔ یہ آپ کو بتائے گا کہ آپ جس حرکت کو پہلے ہی دیکھ رہے ہیں اس کے پیچھے کتنا یقین ہے، اور یہ ایک الگ اور بہت مفید چیز ہے۔</p>\n<h2 id=\"what-open-interest-actually-counts\">کھلی دلچسپی اصل میں کیا شمار کرتی ہے</h2>\n<p><strong>کھلی دلچسپی</strong>عام طور پر مختصر کرکے OI، مستقبل کے معاہدوں کی تعداد ہے جو فی الحال کھلے ہیں اور ابھی تک بند نہیں ہوئے ہیں۔ یہ ہر معاہدے کو ایک بار شمار کرتا ہے۔ ایک کنٹریکٹ میں ایک طرف خریدار ہوتا ہے اور دوسری طرف بیچنے والا، اور دونوں مل کر کھلی دلچسپی کا ایک یونٹ بناتے ہیں، دو نہیں۔ لہذا جب آپ یہ پڑھتے ہیں کہ RELIANCE جولائی کے مستقبل میں چالیس ہزار معاہدوں کی کھلی دلچسپی ہے، تو اس کا مطلب ہے کہ چالیس ہزار لائیو معاہدے ابھی تک خریداروں اور بیچنے والوں کے درمیان کھڑے ہیں جو ابھی تک اسکوائر نہیں ہوئے ہیں۔</p>\n<p>کلیدی لفظ ہے۔ <strong>کھلا</strong>. جس لمحے معاہدے کے دونوں فریق اپنی پوزیشنیں بند کرتے ہیں، وہ معاہدہ گنتی سے غائب ہو جاتا ہے۔ اس لیے کھلی دلچسپی نامکمل کاروبار کا چل رہا ہے، اس بات کا اسنیپ شاٹ کہ اس وقت کتنے فیوچر بیٹس لائیو ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>کھلی دلچسپی فیوچر کے معاہدوں کی تعداد ہے جو ابھی تک کھلے ہیں اور ابھی بند نہیں ہوئے ہیں، ہر معاہدے کو ایک بار گنتے ہیں۔ یہ اس بات کی پیمائش کرتا ہے کہ اس وقت مارکیٹ میں کتنی پوزیشنز زندہ ہیں، نہ کہ کتنی تجارتیں ہوئیں۔</p>\n</div></div>\n<h2 id=\"open-interest-is-not-volume\">کھلی دلچسپی حجم نہیں ہے۔</h2>\n<p>مبتدی مسلسل کھلی دلچسپی کو حجم کے ساتھ الجھاتے ہیں، اور دونوں بالکل مختلف سوالات کے جوابات دیتے ہیں۔</p>\n<p><strong>حجم</strong> شمار کرتا ہے کہ دن کے دوران کتنے معاہدوں میں ہاتھ تبدیل ہوئے۔ جب بھی کوئی معاہدہ تجارت کرتا ہے، یہ دن کے حجم میں اضافہ کرتا ہے، چاہے اس تجارت نے نئی پوزیشن کھولی ہو یا پرانی کو بند کیا ہو۔ حجم سرگرمی کا ایک پیمانہ ہے، اس بات کا کہ سیشن کتنا مصروف تھا۔</p>\n<p><strong>کھلی دلچسپی</strong> شمار کرتا ہے کہ اس ساری سرگرمی کے بعد کتنی پوزیشنیں کھلی رہتی ہیں۔ یہ عزم کا ایک پیمانہ ہے، اس بات کا کہ ابھی بھی کتنا سوار ہے۔</p>\n<p>فرق کو یاد رکھنے کا صاف ترین طریقہ وہی ہے جو راتوں رات ہوتا ہے۔ حجم ہر سیشن کے آغاز پر صفر پر دوبارہ سیٹ ہو جاتا ہے، کیونکہ یہ صرف ایک دن کی تجارت کو شمار کرتا ہے۔ کھلی دلچسپی ری سیٹ نہیں ہوتی ہے۔ یہ معاہدہ کی پوری زندگی میں پوزیشنوں کے کھلنے اور بند ہونے کے ساتھ ہی آگے بڑھتا اور جمع ہوتا، بڑھتا اور گرتا رہتا ہے۔ ایک مصروف دن کا حجم بہت زیادہ ہو سکتا ہے لیکن کھلی دلچسپی میں کوئی تبدیلی نہیں کی جا سکتی ہے، اگر ہر نئے خریدار کو کسی پرانی پوزیشن کو بند کرنے والے کے ساتھ ملایا گیا ہو۔ ایک پرسکون دن میں معمولی حجم ہو سکتا ہے پھر بھی کھلے مفاد میں اضافہ ہو سکتا ہے، اگر اس ٹریڈنگ میں سے زیادہ تر تازہ رقم داخل ہو رہی تھی۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-oi-vs-volume.png\" alt=\"حجم ہر صبح صفر پر ری سیٹ ہوتا ہے اور صرف دن کی تجارت کو شمار کرتا ہے، جبکہ کھلی دلچسپی آگے بڑھ جاتی ہے اور جمع ہوتی ہے، اس بات کا پتہ لگاتی ہے کہ معاہدے کی پوری زندگی میں کتنی پوزیشنیں اب بھی زندہ ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>حجم ہر صبح صفر پر ری سیٹ ہوتا ہے اور صرف دن کی تجارت کو شمار کرتا ہے، جبکہ کھلی دلچسپی آگے بڑھ جاتی ہے اور جمع ہوتی ہے، اس بات کا پتہ لگاتی ہے کہ معاہدے کی پوری زندگی میں کتنی پوزیشنیں اب بھی زندہ ہیں۔</figcaption></figure>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>حجم ایک روزانہ کی پیمائش ہے جو ہر صبح دوبارہ ترتیب دیتا ہے۔ کھلی دلچسپی ایک رننگ کل ہے جو دنوں میں جمع ہوتی ہے۔ ایک آپ کو بتاتا ہے کہ آج کتنا مصروف تھا؛ دوسرا آپ کو بتاتا ہے کہ کتنا داؤ پر لگا ہوا ہے۔</p>\n</div></div>\n<h2 id=\"how-open-interest-rises-and-falls\">کھلی دلچسپی کیسے بڑھتی اور گرتی ہے۔</h2>\n<p>کھلی دلچسپی تبھی تبدیل ہوتی ہے جب کوئی معاہدہ حقیقی طور پر بنایا جاتا ہے یا اسے تباہ کیا جاتا ہے، اور یہ اس بات پر منحصر ہوتا ہے کہ کون کس کے ساتھ تجارت کر رہا ہے۔</p>\n<p>جب ایک <strong>نیا خریدار</strong> ملاقات a <strong>نیا بیچنے والا</strong>، ایک بالکل نیا معاہدہ بنایا گیا ہے۔ ان دونوں میں سے کسی کا بھی پہلے کوئی عہدہ نہیں تھا اور اب ان کے درمیان تازہ معاہدہ ہوا ہے۔ کھلی دلچسپی ایک ایک کرکے بڑھ جاتی ہے۔ اصلی پیسے نے مارکیٹ کا عہد کیا ہے۔</p>\n<p>جب ایک ہولڈر جو ہے <strong>طویل</strong> ایک ہولڈر کو فروخت کرتا ہے جو ہے <strong>مختصر</strong> اور دونوں بند ہو رہے ہیں، وہ معاہدہ ختم ہو گیا ہے۔ ان میں سے ہر ایک کا معاہدہ طے پا چکا ہے۔ کھلی دلچسپی ایک ایک کرکے گرتی ہے۔ پیسہ بازار چھوڑ گیا ہے۔</p>\n<p>درمیان میں، کھلی دلچسپی بھی فلیٹ رہ سکتی ہے۔ اگر ایک نیا خریدار ایک پرانے خریدار کی حیثیت سنبھالتا ہے جو باہر نکل رہا ہے، تو معاہدہ صرف ہاتھ بدلتا ہے۔ ایک پوزیشن بند ہوتی ہے، ایک کھلتی ہے، کل کوئی تبدیلی نہیں ہوتی۔ لہذا کھلی دلچسپی میں اضافے کا مطلب ہے کہ نئی پوزیشنیں بن رہی ہیں اور تازہ پیسہ بہہ رہا ہے، جب کہ کھلے سود میں کمی کا مطلب ہے کہ پوزیشنیں بند ہو رہی ہیں اور پیسہ باہر نکل رہا ہے۔ یہ واحد امتیاز ہر چیز کے پیچھے انجن ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>RELIANCE مستقبل کی تجارت کا تصور کریں اور ایک گھنٹے میں دو سو معاہدوں سے کھلی دلچسپی بڑھ جاتی ہے۔ یہ آپ کو بتاتا ہے کہ دو سو حقیقی طور پر نئے معاہدے بنائے گئے تھے، ہر ایک کی لاٹ سائز 500، لہذا RELIANCE کے تقریباً ایک لاکھ شیئرز کی تازہ نمائش صرف ان تاجروں کے ذریعے کی گئی تھی جو پہلے نہیں تھے۔</p>\n</div></div>\n<h2 id=\"the-price-and-open-interest-table\">قیمت اور کھلی دلچسپی کی میز</h2>\n<p>یہ وہ جگہ ہے جہاں کھلی دلچسپی اس کی برقراری حاصل کرتی ہے۔ قیمت کی سمت کو کھلی دلچسپی کی سمت کے ساتھ جوڑ کر، آپ پڑھ سکتے ہیں کہ کس قسم کا پیسہ حرکت کر رہا ہے۔ چار مجموعے ہیں، اور وہ دل سے سیکھنے کے قابل ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>قیمت</th>\n<th>کھلی دلچسپی</th>\n<th>اس کا عام طور پر کیا مطلب ہے۔</th>\n<th>حرکت کی طاقت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>اوپر</td>\n<td>اوپر</td>\n<td>تازہ خواہشیں داخل ہو رہی ہیں، نئے خریدار ارتکاب کر رہے ہیں۔</td>\n<td>مضبوط، اچھی طرح سے تعاون یافتہ رجحان</td>\n</tr>\n<tr>\n<td>اوپر</td>\n<td>نیچے</td>\n<td>مختصر احاطہ، شارٹس واپس بند کرنے کے لئے خریدنا</td>\n<td>کمزور، نئی خریداری پر نہیں بند ہونے پر ریلی</td>\n</tr>\n<tr>\n<td>نیچے</td>\n<td>اوپر</td>\n<td>تازہ شارٹس کی عمارت، نئے بیچنے والے کمٹمنٹ کر رہے ہیں۔</td>\n<td>یقین کے ساتھ مضبوط نیچے کا رجحان</td>\n</tr>\n<tr>\n<td>نیچے</td>\n<td>نیچے</td>\n<td>پرانے خریداروں نے ہار مان لی</td>\n<td>کمزور، باہر نکلنے پر زوال نئی فروخت پر نہیں۔</td>\n</tr>\n</tbody></table>\n<p>ہر قطار کو ایک چھوٹی کہانی کے طور پر پڑھیں۔</p>\n<p><strong>کھلی دلچسپی کے ساتھ قیمت میں اضافہ</strong> ریلی کی سب سے صحت مند قسم ہے. نئے خریدار داخل ہو رہے ہیں اور نئے معاہدوں کی تشکیل کر رہے ہیں، اس لیے اس اضافے کو حقیقی نئے عزم کی حمایت حاصل ہے۔ اس رجحان کے پیچھے ایندھن ہے۔</p>\n<p><strong>کھلی دلچسپی کے ساتھ قیمت میں اضافہ</strong> قیمت چارٹ پر ایک جیسا لگتا ہے لیکن ایک مختلف جانور ہے۔ یہاں قیمت بڑھ رہی ہے جبکہ اوپن سود سکڑ رہا ہے، جس کا مطلب ہے کہ خریداری زیادہ تر شارٹس کی واپسی سے ہو رہی ہے تاکہ ان کی کھوئی ہوئی پوزیشن کو بند کیا جا سکے۔ یہ ہے <strong>مختصر احاطہ</strong>, ایک ریلی جو لوگوں کی طرف سے کارفرما ہے بجائے اس کے کہ نئے خریداروں کا ارتکاب ہو رہا ہو۔ پھنسے ہوئے شارٹس کو ڈھانپنے کے بعد، ایندھن ختم ہو جاتا ہے، لہذا اس قسم کا اضافہ اس سے کہیں زیادہ کمزور ہوتا ہے جو نظر آتا ہے۔</p>\n<p><strong>کھلی دلچسپی کے ساتھ قیمت نیچے</strong> پہلی صف کا آئینہ ہے۔ قیمت گر رہی ہے اور کھلی دلچسپی بڑھ رہی ہے، جس کا مطلب ہے کہ نئے بیچنے والے قدم رکھ رہے ہیں اور نئی مختصر پوزیشنیں بنا رہے ہیں۔ اس کمی کے پیچھے حقیقی یقین ہے، نہ صرف اعصابی فروخت۔</p>\n<p><strong>کھلی دلچسپی کے ساتھ قیمت نیچے</strong> کی طرف سے کارفرما ایک زوال ہے <strong>کھولنا چاہتا ہے</strong>، پرانے خریدار تولیہ میں پھینک کر باہر بند کر رہے ہیں۔ ایک بار جب تھکی ہوئی خواہشیں فروخت ہو جاتی ہیں، تو فروخت کا دباؤ خشک ہو سکتا ہے، اس لیے یہ کمی بڑھتی ہوئی کھلی دلچسپی پر گرنے سے کمزور ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-oi-price-matrix.png\" alt=\"قیمت کی سمت اور کھلی دلچسپی کی سمت کے چار مجموعے، یہ ظاہر کرتے ہیں کہ کب کسی اقدام کو تازہ عزم کی حمایت حاصل ہے اور جب یہ صرف پرانی پوزیشنوں کو بند کیا جا رہا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>قیمت کی سمت اور کھلی دلچسپی کی سمت کے چار مجموعے، یہ ظاہر کرتے ہیں کہ کب کسی اقدام کو تازہ عزم کی حمایت حاصل ہے اور جب یہ صرف پرانی پوزیشنوں کو بند کیا جا رہا ہے۔</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب ریلی کی قیادت شارٹ کورنگ کے ذریعے کی جاتی ہے تو قیمت بڑھنے کے باوجود کھلی دلچسپی گر جاتی ہے۔ یہ آپ کا اشارہ ہے کہ یہ اقدام ادھار کے وقت پر چل رہا ہے، کیونکہ کوئی بھی تازہ دم نہیں خرید رہا ہے، شارٹس محض فرار ہو رہے ہیں۔</p>\n</div></div>\n<h2 id=\"open-interest-and-the-rollover-week\">کھلی دلچسپی اور رول اوور ہفتہ</h2>\n<p>ہر معاہدے کی زندگی میں ایک لمحہ ایسا ہوتا ہے جب کھلی دلچسپی خاص طور پر واضح کہانی بیان کرتی ہے، اور وہ ہے میعاد ختم ہونے سے پہلے کا رول اوور ہفتہ۔ جیسے جیسے قریب کا مہینہ اپنے آخری منگل کے قریب آتا ہے، وہ تاجر جو اپنے نقطہ نظر کو زندہ رکھنا چاہتے ہیں وہ اپنے قریب کے مہینے کی پوزیشنوں کو بند کر دیتے ہیں اور اگلے مہینے میں اسی نمائش کو دوبارہ کھولتے ہیں۔ آپ نے اس سے پہلے کے باب میں رول اوور کے طور پر ملاقات کی۔</p>\n<p>کھلی دلچسپی کی اسکرین پر یہ صاف ظاہر ہوتا ہے۔ دی <strong>قریب مہینہ</strong> کھلی دلچسپی اس وقت گرتی ہے جب پوزیشنیں بند ہوتی ہیں، اور اسی وقت <strong>اگلے مہینے</strong> کھلی دلچسپی بڑھ جاتی ہے کیونکہ ان عہدوں کو ایک ماہ آگے دوبارہ بنایا جاتا ہے۔ آپ لفظی طور پر مارکیٹ کی کشش ثقل کے مرکز کو ایک معاہدے سے دوسرے معاہدے میں شفٹ ہوتے دیکھ رہے ہیں۔ جب اگلے مہینے کی کھلی دلچسپی قریب کے مہینے سے آگے نکل جاتی ہے، تو سائیکل مؤثر طریقے سے بدل جاتا ہے، اور کارروائی آگے بڑھ جاتی ہے۔</p>\n<p>یہ ایک حقیقی اشارہ ہے، تجسس نہیں۔ اگلے مہینے میں کھلی دلچسپی کی بھاری تبدیلی آپ کو بتاتی ہے کہ تاجر کیری کی ادائیگی کے لیے کافی پرعزم ہیں اور ایک اور مہینے تک قیام کریں گے۔ ایک کمزور تبدیلی، جہاں پوزیشنیں بند ہیں لیکن دوبارہ تعمیر نہیں کی گئی ہیں، اشارہ کرتا ہے کہ ہجوم اپنے نقطہ نظر کی تجدید کرنے کے بجائے ایک طرف ہٹ رہا ہے۔ مہینوں میں کھلی دلچسپی کہاں بیٹھتی ہے یہ دیکھنا آپ کو اس معاہدے کی تجارت کرتا رہتا ہے جس میں حقیقی لیکویڈیٹی ہوتی ہے اور آپ کو بتاتا ہے کہ سائیکل کس طرح بدل رہا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>رول اوور ہفتہ کے دوران آپ ایکسپائر ہونے والے مہینے میں کھلی دلچسپی کے نکاس کو دیکھ سکتے ہیں اور اگلے مہینے میں پول کر سکتے ہیں۔ جس دن اگلے مہینے میں قریب کے مہینے سے زیادہ کھلی دلچسپی ہوتی ہے وہ دن ہوتا ہے جس دن مارکیٹ نے عملی طور پر اپنی توجہ کو آگے بڑھایا ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"open-interest-confirms-it-does-not-command\">کھلی دلچسپی تصدیق کرتی ہے، یہ حکم نہیں دیتی</h2>\n<p>اب ایماندار حصہ. کھلی دلچسپی ایک طاقتور لینس ہے، لیکن یہ خریدنے کا بٹن نہیں ہے۔ یہ خود ہی آپ کو داخل ہونے یا باہر نکلنے کو نہیں کہتا۔ یہ کیا کرتا ہے <strong>تصدیق کریں</strong> کہانی جو قیمت پہلے ہی بتا رہی ہے، یہ بتا کر کہ آیا حقیقی عزم کسی اقدام کے پیچھے کھڑا ہے یا یہ اقدام صرف پرانی پوزیشنوں کو بند کیا جا رہا ہے۔</p>\n<p>اس طرح استعمال کیا جاتا ہے کہ یہ واقعی قیمتی ہے۔ اگر NIFTY، 24,000 کے قریب اس کے 65 کے لاٹ کے ساتھ، زیادہ پیس رہا ہے اور اس کے ساتھ کھلی دلچسپی بڑھ رہی ہے، تو آپ کے پاس اس بات کا ثبوت ہے کہ اپ ٹرینڈ میں تازہ مومنین ہیں اور بہتر تعاون یافتہ ہے۔ اگر وہی NIFTY چڑھ رہا ہے جبکہ اوپن انٹرسٹ گر رہا ہے، تو آپ ریلی کو شک کی نگاہ سے دیکھنا جانتے ہیں، کیونکہ یہ نئی خریداری کے بجائے شارٹ کورنگ پر چل رہی ہے۔ قیمت آپ کو سمت دیتی ہے۔ کھلی دلچسپی آپ کو اس کے پیچھے پڑھنے کا یقین دلاتی ہے۔</p>\n<p>لیکن اگر آپ اکیلے اس پر انحصار کرتے ہیں تو کھلی دلچسپی گمراہ کر سکتی ہے۔ ایک ہی نمبر ایک سے زیادہ کہانیوں کو فٹ کر سکتا ہے، آپ جو ڈیٹا دیکھتے ہیں وہ عام طور پر فوری کے بجائے دن کے آخر میں ہوتا ہے، اور ایک دن کی تبدیلی شور ہو سکتی ہے۔ قیمت، حجم اور بنیاد کے ساتھ ساتھ کئی لوگوں کے درمیان ایک دیانتدار گواہ کے طور پر کھلی دلچسپی کا برتاؤ کریں، کبھی بھی تنہا اوریکل کے طور پر نہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کھلی دلچسپی ایک تصدیقی سگنل ہے، کبھی بھی اسٹینڈ اکیلی خرید و فروخت کا محرک نہیں۔ یہ آپ کو بتاتا ہے کہ کیا کسی اقدام کے پیچھے حقیقی عزم ہے۔ یہ آپ کو عمل کرنے کو نہیں کہتا۔ اسے قیمت اور اپنے منصوبے کے ساتھ جوڑیں، اور کبھی بھی کھلی دلچسپی کے پڑھنے پر خود تجارت نہ کریں۔</p>\n</div></div>\n<p>دیرپا سبق آسان ہے۔ قیمت آپ کو دکھاتی ہے کہ مستقبل کی تجارت اور حجم آپ کو بتاتا ہے کہ دن کتنا مصروف تھا، لیکن کھلی دلچسپی آپ کو دکھاتی ہے کہ مارکیٹ میں اب بھی کتنا یقین ہے اور تازہ پیسہ کس طرف جھک رہا ہے۔ قیمت اور کھلی دلچسپی کے جدول کی چار قطاریں سیکھیں، رول اوور پر مہینوں کے درمیان شمار کی تبدیلی دیکھیں، اور اس رجحان کی طاقت کا اندازہ لگانے کے لیے جو آپ دیکھتے ہیں اسے استعمال کریں جس کا آپ پہلے سے مطالعہ کر رہے ہیں۔ اس طرح پڑھیں، کھلی دلچسپی آپ کو تجارت کے حوالے نہیں کرے گی، لیکن یہ آپ کو اس بات کے بارے میں ایماندار بنائے گی کہ آپ جن چالوں کا پیچھا کرنے کے لیے آمادہ ہوتے ہیں ان کے پیچھے واقعی کتنا یقین ہے۔</p>\n","toc":[{"level":2,"text":"کھلی دلچسپی اصل میں کیا شمار کرتی ہے","id":"what-open-interest-actually-counts"},{"level":2,"text":"کھلی دلچسپی حجم نہیں ہے۔","id":"open-interest-is-not-volume"},{"level":2,"text":"کھلی دلچسپی کیسے بڑھتی اور گرتی ہے۔","id":"how-open-interest-rises-and-falls"},{"level":2,"text":"قیمت اور کھلی دلچسپی کی میز","id":"the-price-and-open-interest-table"},{"level":2,"text":"کھلی دلچسپی اور رول اوور ہفتہ","id":"open-interest-and-the-rollover-week"},{"level":2,"text":"کھلی دلچسپی تصدیق کرتی ہے، یہ حکم نہیں دیتی","id":"open-interest-confirms-it-does-not-command"}],"imgCount":2,"hasContent":true},"20":{"html":"<p>اس کی تصویر بنائیں۔ آپ ایک صبح اپنی ٹریڈنگ اسکرین کھولتے ہیں، فیصلہ کرتے ہیں کہ ایک مقبول مڈ کیپ اسٹاک چلنے کے لیے تیار نظر آتا ہے، اور اس کا بہت سا مستقبل خریدنے کی کوشش کریں۔ آرڈر سیدھا واپس آ گیا، مسترد کر دیا گیا۔ آپ کا اکاؤنٹ ٹھیک ہے، آپ کا مارجن کافی سے زیادہ ہے، اور مارکیٹ بہت کھلی ہے۔ تو بس کیا ہوا؟ اسٹاک میں کچھ داخل ہوا ہے جسے کہا جاتا ہے۔ <strong>ایف اینڈ او پابندی</strong>، اور جب تک یہ پابندی جاری ہے، ایکسچینج کسی کو بھی اس میں نئی ​​پوزیشن کھولنے نہیں دے گا۔ آپ کو الگ نہیں کیا جا رہا ہے۔ ملک کا ہر تاجر ایک ہی بند دروازے کی طرف دیکھ رہا ہے۔</p>\n<p>یہ باب آپ کے ہر فیوچر معاہدے کے پیچھے بیٹھی خاموش اصول کتاب کے بارے میں ہے۔ زیادہ تر وقت یہ اصول آپ کو کبھی نہیں چھوتے ہیں، یہی وجہ ہے کہ ابتدائی لوگ اپنے وجود کو بھول جاتے ہیں اور پھر پکڑے جاتے ہیں۔ آپ کو سمجھنا ضروری ہے کہ تین ہیں: <strong>مارکیٹ میں پوزیشن کی حد</strong>, the <strong>ایف اینڈ او پابندی</strong> جو اس کی پیروی کرتا ہے، اور <strong>مقدار منجمد</strong> ایک آرڈر کے سائز پر۔ ان میں سے کوئی بھی آپ کو سزا دینے کے لیے نہیں ہے۔ یہ سب مارکیٹ کو ٹوٹنے سے روکنے کے لیے موجود ہیں۔</p>\n<h2 id=\"why-these-limits-exist-at-all\">یہ حدود کیوں موجود ہیں؟</h2>\n<p>مشتق مارکیٹ صرف کام کرتی ہے جب کہ کوئی بھی کھلاڑی کسی معاہدے کو کنٹرول کرنے کے لیے اتنا بڑا نہیں ہو سکتا۔ تصور کریں کہ ایک بہت گہری جیب والا تاجر خاموشی سے اتنی بڑی پوزیشن بنا رہا ہے کہ وہ اسٹاک کے مستقبل میں زیادہ تر کھلے مفاد کا مؤثر طریقے سے مالک ہے۔ اس کے بعد وہ باقی سب کو نچوڑ سکتے ہیں، قیمت کو خود کے مطابق موڑ سکتے ہیں جبکہ دوسری طرف چھوٹے تاجروں کو دینے پر مجبور کیا جاتا ہے۔ اسے مارکیٹ کو کارنر کرنا کہا جاتا ہے، اور یہ بالکل وہی ہے جسے روکنے کے لیے پوزیشن کی حدیں وضع کی گئی ہیں۔</p>\n<p>ایک دوسری، گہری وجہ ہے۔ کلیئرنگ ہاؤس ہر مستقبل کی تجارت کے پیچھے کھڑا ہے اور اس کی ضمانت دیتا ہے۔ اگر ایک اسٹاک میں پوزیشنوں کو بغیر کسی حد کے غبارے کی اجازت دی گئی تو، ایک بڑے کھلاڑی کی طرف سے اچانک ڈیفالٹ باہر کی طرف لپک سکتا ہے اور پورے سیٹلمنٹ سسٹم کو خطرہ بنا سکتا ہے۔ ایک بار میں کتنا کھلا ہو سکتا ہے اس کا تعین کرنا اس خطرے پر مشتمل ہے۔ حدود مجموعی طور پر مارکیٹ کے لیے ایک سرکٹ بریکر ہیں، نہ صرف انفرادی تاجروں کے لیے ایک ریفری۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>پوزیشن کی حدیں دو وجوہات کی بناء پر موجود ہیں: کسی ایک کھلاڑی کو کنٹریکٹ کو کارنر کرنے اور باقی سب کو نچوڑنے سے روکنے کے لیے، اور ایک بڑی پوزیشن کے ڈیفالٹ ہونے اور اس کے ساتھ کلیئرنگ سسٹم کو گھسیٹنے کے نظامی خطرہ کو شامل کرنا۔</p>\n</div></div>\n<h2 id=\"the-market-wide-position-limit\">مارکیٹ کی وسیع پوزیشن کی حد</h2>\n<p>سرخی کی ٹوپی ہے <strong>مارکیٹ میں پوزیشن کی حد</strong>، تقریبا ہمیشہ لکھا جاتا ہے۔ <strong>MWPL</strong>. یہ کسی ایک اسٹاک کے مشتقات، فیوچرز اور آپشنز کو ملا کر ہر شریک کے لیے کھلی پوزیشنوں کی کل تعداد کی حد ہے۔ اس اسٹاک میں ہر ایک کے پاس موجود ہر چیز کو شامل کریں، اور رقم کو MWPL سے آگے جانے کی اجازت نہیں ہے۔</p>\n<p>ٹوپی ایک مقررہ نمبر نہیں ہے جو ہوا سے کھینچی گئی ہو۔ یہ اسٹاک کے ساتھ منسلک ہے <strong>مفت فلوٹ</strong>یعنی پروموٹرز اور دیگر لاک ان ہولڈرز کے پاس رکھے گئے بلاکس کو چھوڑ کر عوامی تجارت کے لیے اصل میں دستیاب حصص۔ MWPL کو اس فری فلوٹ کے فیصد کے طور پر سیٹ کیا گیا ہے، اور ریگولیٹر کے فریم ورک کے تحت ایکسچینج کے ذریعہ درست فیصد کی وضاحت کی گئی ہے۔ سوچ سمجھدار ہے۔ ایک بڑے، آزادانہ طور پر تجارت کی جانے والی حصص کی بنیاد کے ساتھ ایک اسٹاک ایک چھوٹے، مضبوطی سے رکھے ہوئے بازار کے مقابلے میں بڑی ڈیریویٹیو مارکیٹ کو محفوظ طریقے سے سپورٹ کر سکتا ہے، اس لیے بنیادی کی حقیقی لیکویڈیٹی کے ساتھ کیپ اسکیل ہوتی ہے۔</p>\n<p>چونکہ یہ فری فلوٹ کا فیصد ہے، MWPL کا جائزہ لیا جاتا ہے اور وقت کے ساتھ ساتھ کمپنی کے حصص کی بنیاد میں تبدیلی کے ساتھ نظر ثانی کی جاتی ہے۔ آپ کو خود اس کا حساب لگانے کی ضرورت نہیں ہے۔ ایکسچینج ہر اسٹاک کے لیے اس کے استعمال کے ساتھ ساتھ حد شائع کرتا ہے، اور یہ سیشن کے ذریعے انتباہات جاری کرتا ہے جب استعمال مقررہ حد سے تجاوز کر جاتا ہے۔ مجموعی کھلی دلچسپی بذات خود دن کے اختتام پر پھیل جاتی ہے، اس لیے انٹرا ڈے الرٹس کو لائیو فیصد کے طور پر نہ سمجھیں، جیسا کہ آپ کی وارننگ کہ اسٹاک پابندی کے قریب پہنچ رہا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-position-limits.png\" alt=\"مارکیٹ وائڈ پوزیشن کی حد اسٹاک کے فری فلوٹ کے حصے کے طور پر سیٹ کی گئی ایک حد ہے، اور تمام تاجروں کی کل کھلی دلچسپی اس کی طرف پوری ہوتی ہے۔ ایک بار جب یہ کل کیپ کے تقریباً 95 فیصد تک پہنچ جاتا ہے تو اسٹاک F&amp;O پابندی میں داخل ہو جاتا ہے، جہاں صرف اس وقت تک بند ہونے والی تجارت کی اجازت ہوتی ہے جب تک کہ کھلا سود تقریباً 80 فیصد سے نیچے نہ چلا جائے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>مارکیٹ وائڈ پوزیشن کی حد اسٹاک کے فری فلوٹ کے حصے کے طور پر سیٹ کی گئی ایک حد ہے، اور تمام تاجروں کی کل کھلی دلچسپی اس کی طرف پوری ہوتی ہے۔ ایک بار جب یہ کل کیپ کے تقریباً 95 فیصد تک پہنچ جاتا ہے تو اسٹاک F&amp;O پابندی میں داخل ہو جاتا ہے، جہاں صرف اس وقت تک بند ہونے والی تجارت کی اجازت ہوتی ہے جب تک کہ کھلا سود تقریباً 80 فیصد سے نیچے نہ چلا جائے۔</figcaption></figure>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہاں پر درست فیصد ایکسچینج اور ریگولیٹر کے ذریعے متعین کیے گئے ہیں اور پہلے بھی تبدیل کیے جا چکے ہیں، اس لیے اس باب میں اعداد کو مستقل قانون کے بجائے ڈھانچہ سمجھیں۔ اس سے پہلے کہ آپ کسی مخصوص اعداد و شمار پر بھروسہ کریں، موجودہ حد کی تصدیق کریں</p>\n</div></div>\n<h2 id=\"the-f-o-ban-period\">F&amp;O پابندی کی مدت</h2>\n<p>یہ وہ جگہ ہے جہاں MWPL ایک تجریدی حد بننے سے رک جاتا ہے اور آپ کی اسکرین کو متاثر کرنا شروع کر دیتا ہے۔ جیسے جیسے اسٹاک میں کل کھلی دلچسپی اس کی ٹوپی کی طرف بڑھ جاتی ہے، ایکسچینج استعمال کیے جانے والے MWPL کا فیصد دیکھتا ہے۔ جب یہ اعداد و شمار ایک اونچی حد کو عبور کرتا ہے، تقریباً 95 فیصد حد، اسٹاک کو دھکیل دیا جاتا ہے۔ <strong>F&amp;O پابندی کی مدت</strong>.</p>\n<p>پابندی اسٹاک کو مکمل طور پر منجمد نہیں کرتی ہے۔ یہ جس چیز پر پابندی لگاتا ہے وہ ہے۔ <strong>تازہ عہدوں</strong>. جب کہ کوئی اسٹاک پابندی کی فہرست میں ہے، کوئی بھی تاجر اپنے فیوچر یا آپشنز میں نیا لانگ یا نیا شارٹ نہیں کھول سکتا۔ صرف ایک ہی چیز جس کی آپ کو اجازت ہے۔ <strong>کم یا مربع بند</strong> جو آپ پہلے ہی رکھتے ہیں۔ آپ بند کر سکتے ہیں، آپ شامل نہیں کر سکتے۔ پوری مارکیٹ کو حقیقت میں بتایا جا رہا ہے کہ یہ معاہدہ خطرناک حد تک بھرا ہوا ہے اور کوئی بھی اس میں مزید اضافہ نہیں کر سکتا۔</p>\n<p>پابندی مستقل نہیں ہے۔ جیسے جیسے ٹریڈرز بند ہو جاتے ہیں اور کھلی دلچسپی میں کمی آتی ہے، استعمال میں MWPL کا فیصد گر جاتا ہے۔ ایک بار جب یہ نچلی حد سے نیچے واپس آجاتا ہے، تقریباً 80 فیصد، نارمل ٹریڈنگ دوبارہ شروع ہو جاتی ہے اور نئی پوزیشنز کی دوبارہ اجازت ہوتی ہے۔ 95 فیصد کے قریب داخلے کی سطح اور 80 فیصد کے قریب خارجی سطح کے درمیان فرق ہر چند منٹوں میں ایک اسٹاک کو پابندی کے اندر اور باہر جھلملانے سے روکتا ہے۔ اسے واپس جانے سے پہلے حفاظت کا ایک حقیقی مارجن صاف کرنا ہوگا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>F&amp;O پابندی کے دوران آپ اس اسٹاک میں صرف موجودہ پوزیشن کو کم یا بند کر سکتے ہیں۔ آپ تازہ لمبا یا مختصر نہیں کھول سکتے، اور آپ اس پوزیشن میں اضافہ نہیں کر سکتے جس پر آپ پہلے سے موجود ہیں۔ کبھی بھی یہ نہ سمجھیں کہ آپ ممنوعہ نام میں اوسط کر سکیں گے۔ اگر آپ مزید چاہتے ہیں تو، پابندی ختم ہونے تک دروازہ بند ہے۔</p>\n</div></div>\n<p>سمجھنے کے قابل ایک دستک پر اثر ہے. چونکہ کوئی بھی ممنوعہ اسٹاک میں نئی ​​پوزیشنیں نہیں کھول سکتا، اس لیے صرف تجارت باقی رہ گئی ہے لوگ بند ہو رہے ہیں۔ یہ اکثر مستقبل میں تیز، یکطرفہ غیر منقولہ پیدا کرتا ہے۔ وہ تاجر جو پھنسے ہوئے ہیں اور باہر نکلنا چاہتے ہیں انہیں دوسرے تاجروں کو بیچنا پڑتا ہے جو صرف بند کرنا چاہتے ہیں، لہذا قیمت نسبتاً کم حقیقی دو طرفہ دلچسپی پر سخت بدل سکتی ہے۔ اس وجہ سے ممنوعہ اسٹاک کا مستقبل بے ترتیبی سے برتاؤ کر سکتا ہے، اور یہ پتلی، صرف بند ہونے والی بھیڑ بالکل اسی لیے ہے کہ ایک ابتدائی کو اپنے ارد گرد زیادہ محتاط رہنا چاہیے۔</p>\n<h3 id=\"reading-the-daily-ban-list\">روزانہ پابندی کی فہرست پڑھنا</h3>\n<p>ایکسچینج شائع کرتا ہے۔ <strong>ایف اینڈ او پابندی کی فہرست</strong> ہر تجارتی دن. اس میں ان اسٹاکس کا نام دیا گیا ہے جن کی کھلی دلچسپی اعلیٰ حد کو عبور کر چکی ہے اور اس لیے صرف تجارت کو بند کرنے تک محدود ہے۔ فہرست کو سیشن کے آغاز کے ارد گرد اپ ڈیٹ کیا جاتا ہے، لہذا آپ تجارت کرنے سے پہلے چیک کر سکتے ہیں کہ آیا آپ جس اسٹاک پر نظریں لگا رہے ہیں اس پر فی الحال پابندی لگا دی گئی ہے۔ اسے پڑھنے میں سیکنڈ لگتے ہیں اور آپ کو مسترد شدہ آرڈر کے گندے حیرت سے بچاتا ہے یا اس سے بھی بدتر یہ کہ آپ ایک ایسے نام میں پھنس گئے ہیں جس میں آپ شامل نہیں کر سکتے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی سنگل اسٹاک مستقبل میں تجارت کرنے سے پہلے F&amp;O پابندی کی فہرست کو اپنے معمول کا حصہ بنائیں۔ اگر نام فہرست میں ہے، تو اسے ایک اسٹاک کی طرح سمجھیں جس سے آپ باہر نکل سکتے ہیں لیکن داخل نہیں ہوسکتے، اور ایک پتلی، صرف بند ہونے والی مارکیٹ سے لڑنے کے بجائے ایک طرف کھڑے ہوں۔</p>\n</div></div>\n<h2 id=\"client-level-and-member-level-limits\">کلائنٹ کی سطح اور ممبر کی سطح کی حدود</h2>\n<p>MWPL پوری مارکیٹ کے لیے حد ہے۔ اس کے نیچے دو تنگ ٹوپیاں بیٹھی ہیں جو آپ اور آپ کے بروکر پر لاگو ہوتی ہیں۔</p>\n<ul>\n<li>اے <strong>کلائنٹ کی سطح کی پوزیشن کی حد</strong> یہ بتاتا ہے کہ ایک اسٹاک کے مشتقات میں کوئی ایک کلائنٹ کتنا بڑا ہو سکتا ہے۔ یہ ایک تاجر کو خاموشی سے ایسی پوزیشن بنانے سے روکتا ہے جو، مارکیٹ کی چوڑی حد کے نیچے رہتے ہوئے، خود ہی خلل ڈالنے کے لیے کافی بڑا ہے۔</li>\n<li>اے <strong>ٹریڈنگ ممبر کی حد</strong> یہ بتاتا ہے کہ ایک ممبر، مجموعی طور پر آپ کا بروکر، اس معاہدے میں اپنے تمام کلائنٹس میں کتنا حصہ رکھ سکتا ہے۔ یہ ارتکاز کے خطرے کو پھیلاتا ہے تاکہ کوئی بھی رکن ناکامی کا واحد نقطہ نہ بن جائے۔</li>\n</ul>\n<p>آپ شاذ و نادر ہی ایک ابتدائی تجارت کے طور پر ان کے خلاف ایک یا دو بہت زیادہ برش کریں گے، کیونکہ تعداد بڑی ہے۔ لیکن یہ اس وجہ سے ہیں کہ ایک بہت بڑا تاجر بغیر اختتام کے صرف اضافہ جاری نہیں رکھ سکتا، اور وہ کسی ایک کلائنٹ یا کسی ایک رکن کو معاہدے پر غلبہ پانے سے روکنے کے لیے MWPL کے ساتھ مل کر کام کرتے ہیں۔ اصول ہر سطح پر یکساں ہے۔ سسٹم میں کسی ایک نقطہ کو زیادہ بڑا ہونے کی اجازت نہیں ہے۔</p>\n<h2 id=\"the-quantity-freeze\">مقدار منجمد</h2>\n<p>آخری کنٹرول a کے سائز کے بارے میں ہے۔ <strong>ایک حکم</strong>آپ کی کل پوزیشن نہیں۔ ہر معاہدہ ایک ہوتا ہے۔ <strong>مقدار منجمد</strong> حد، اکائیوں کی زیادہ سے زیادہ تعداد ایکسچینج ایک آرڈر میں قبول کرے گی۔ اس سے بڑا آرڈر بھیجیں اور اسے مسترد کردیا جاتا ہے۔ ایک ہی کل سائز کی تجارت کرنے کے لیے آپ کو اسے کئی چھوٹے آرڈرز میں توڑنا چاہیے، ہر ایک منجمد مقدار سے نیچے۔</p>\n<p>زحمت کیوں؟ کتاب کو مارنے والا ایک زبردست آرڈر اچانک، پرتشدد حرکت کا سبب بن سکتا ہے اور یہ ایک موٹی انگلی کی غلطی بھی ہو سکتی ہے، کوئی شخص اپنے مطلب سے کہیں زیادہ ٹائپ کرتا ہے۔ منجمد رفتار ٹکرانے کے طور پر کام کرتا ہے۔ بہت بڑی تجارت کو ٹکڑوں میں کاٹنے پر مجبور کر کے، ایکسچینج ایک بڑے آرڈر کو ایک ہی پرنٹ میں مارکیٹ کو مارنے سے روکتا ہے اور آرڈر بک کو ٹکڑوں میں سائز کو جذب کرنے کا موقع فراہم کرتا ہے۔</p>\n<p>منجمد کا اظہار کنٹریکٹ کے اپنے یونٹوں میں ہوتا ہے۔ یاد رکھیں کہ ایک RELIANCE مستقبل 500 حصص کا ہے اور ایک NIFTY کا مستقبل بہت زیادہ 65 ہے۔ منجمد مقدار عام مٹھی بھر لاٹوں سے بہت زیادہ مقرر کی گئی ہے، لہذا ایک عام تاجر جو ایک یا دو لاٹ RELIANCE بھیجتا ہے، یا اس کے قریب کچھ لاٹ کبھی نہیں آتا۔ یہ صرف غیر معمولی طور پر بڑے احکامات پر کاٹتا ہے، جہاں یہ خاموشی سے عملدرآمد کو منظم رکھنے کا اپنا کام کرتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-quantity-freeze.png\" alt=\"فی کنٹریکٹ منجمد مقدار سے اوپر کے ایک آرڈر کو یکسر مسترد کر دیا جاتا ہے، اس لیے ایک بڑی تجارت کو کئی چھوٹے آرڈرز میں کاٹا جانا چاہیے کہ ہر ایک حد سے نیچے بیٹھتا ہے، اور آرڈر بک کو ایک پرتشدد پرنٹ کے بجائے سائز کو ٹکڑوں میں جذب کرنے دیتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>فی کنٹریکٹ منجمد مقدار سے اوپر کے ایک آرڈر کو یکسر مسترد کر دیا جاتا ہے، اس لیے ایک بڑی تجارت کو کئی چھوٹے آرڈرز میں کاٹا جانا چاہیے کہ ہر ایک حد سے نیچے بیٹھتا ہے، اور آرڈر بک کو ایک پرتشدد پرنٹ کے بجائے سائز کو ٹکڑوں میں جذب کرنے دیتا ہے۔</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>مقدار منجمد ہونے کی وجہ سے بڑے ادارہ جاتی آرڈرز ایک بلاک کے بجائے چھوٹے کلپس کے سلسلے میں آتے ہیں۔ ایکسچینج حد سے زیادہ ایک آرڈر کو قبول نہیں کرے گا، اس لیے بڑے سائز کو ڈیزائن کے لحاظ سے توڑ دیا جاتا ہے، جو اس بات کا بھی حصہ ہے کہ کیوں ایک گہرا، مائع کنٹریکٹ بڑے کھلاڑیوں کو بغیر کسی لالچ کے جذب کر سکتا ہے۔</p>\n</div></div>\n<h2 id=\"the-habit-to-carry-away\">لے جانے کی عادت</h2>\n<p>یہ تینوں کنٹرولز ایک مقصد کا اشتراک کرتے ہیں، مارکیٹ کو منظم رکھنا اور کوئی ایک کھلاڑی زیادہ طاقتور نہیں، اور آپ کے لیے یہ ایک مختصر، عملی معمول پر ابلتے ہیں۔</p>\n<p>اس سے پہلے کہ آپ سنگل اسٹاک مستقبل میں تجارت کریں، F&amp;O پابندی کی فہرست چیک کریں۔ اگر نام اس پر ہے، تو آپ صرف کم یا بند کر سکتے ہیں، کبھی نہیں کھول سکتے اور نہ ہی شامل کر سکتے ہیں، لہذا اس کے ارد گرد منصوبہ بندی کریں اور یہ نہ سمجھیں کہ آپ بعد میں اس میں اضافہ کر سکتے ہیں۔ ذہن میں رکھیں کہ ممنوعہ اسٹاک کا مستقبل ایک پتلی، صرف بند ہونے والی مارکیٹ ہے جو تیزی سے جھول سکتی ہے، جو شاذ و نادر ہی ہوتا ہے جہاں کوئی ابتدائی بننا چاہتا ہو۔ جب آپ کسی آرڈر کا سائز بناتے ہیں، تو اسے آرام سے منجمد مقدار سے نیچے رکھیں تاکہ اسے ایک ہی بار میں قبول کر لیا جائے، اور اگر یہ غیر معمولی طور پر بڑا ہو تو اسے تقسیم کریں۔ اور چونکہ درست فیصد اور حدیں ایکسچینج کے ذریعے طے کی گئی ہیں اور وہ تبدیل ہو سکتی ہیں، اس لیے موجودہ اعداد و شمار کو NSE پوزیشن کی حد کے صفحہ کے خلاف تصدیق کریں بجائے اس کے کہ آپ کو آدھی یاد رکھنے والے نمبر پر بھروسہ کریں۔ ڈھانچہ کو ایک بار سیکھیں، ہر بار تفصیلات کو چیک کریں، اور یہ اصول حیران کن ردعمل کی بجائے خاموش حفاظتی جال بن جاتے ہیں۔</p>\n","toc":[{"level":2,"text":"یہ حدود کیوں موجود ہیں؟","id":"why-these-limits-exist-at-all"},{"level":2,"text":"مارکیٹ کی وسیع پوزیشن کی حد","id":"the-market-wide-position-limit"},{"level":2,"text":"F&O پابندی کی مدت","id":"the-f-o-ban-period"},{"level":3,"text":"روزانہ پابندی کی فہرست پڑھنا","id":"reading-the-daily-ban-list"},{"level":2,"text":"کلائنٹ کی سطح اور ممبر کی سطح کی حدود","id":"client-level-and-member-level-limits"},{"level":2,"text":"مقدار منجمد","id":"the-quantity-freeze"},{"level":2,"text":"لے جانے کی عادت","id":"the-habit-to-carry-away"}],"imgCount":2,"hasContent":true},"21":{"html":"<p>ایک صبح آپ اپنی ٹریڈنگ اسکرین کھولتے ہیں اور کچھ غلط نظر آتا ہے۔ آپ کی RELIANCE پوزیشن، جسے آپ نے پورے ہفتے دیکھا ہے، اچانک کہتا ہے کہ لاٹ 1000 شیئرز ہے، نہ کہ 500 شیئرز جسے آپ دل سے جانتے ہیں۔ آپ کو یقین ہے کہ آپ نے 1320 سٹرائیک پر جو آپشن خریدا ہے وہ اب 660 پڑھتا ہے۔ ایک سیکنڈ کے لیے آپ کا پیٹ گر جاتا ہے۔ کیا آپ نے اپنی آدھی رقم راتوں رات کھو دی؟ کیا کچھ ٹوٹ گیا؟ جواب، خوشی سے، نہیں ہے. کچھ بھی غلط نہیں ہوا۔ کمپنی نے اپنے حصص کے ساتھ کچھ کیا، اور ایکسچینج نے خاموشی سے آپ کے معاہدے کو دوبارہ لکھا تاکہ آپ کی پوزیشن بالکل وہی ہے جو ایک دن پہلے تھی۔ یہ کارپوریٹ ایکشنز کی دنیا ہے، اور ایک بار جب آپ اسے سمجھ لیتے ہیں تو ایک خوفناک حیرت ایک مکمل غیر واقعہ میں بدل جاتی ہے۔</p>\n<h2 id=\"what-a-corporate-action-does-to-a-share\">ایک کارپوریٹ ایکشن شیئر کے ساتھ کیا کرتا ہے۔</h2>\n<p>اے <strong>کارپوریٹ کارروائی</strong> کسی کمپنی کا دانستہ فیصلہ ہے جو اپنے حصص کو کچھ ساختی طریقے سے تبدیل کرتی ہے۔ جن سے فیوچر ٹریڈر اکثر ملاقات کرے گا وہ ہیں a <strong>اسٹاک تقسیم</strong>, a <strong>بونس کا مسئلہ</strong>, a <strong>حقوق کا مسئلہ</strong>, a <strong>خصوصی منافع</strong>، اور a <strong>انضمام</strong> یا ڈیمرجر. ان میں سے ہر ایک، اپنے اپنے طریقے سے، یا تو ایک حصص کی قیمت یا وجود میں موجود حصص کی تعداد میں تبدیلی کرتا ہے، اور بعض اوقات دونوں ایک ساتھ۔</p>\n<p>اسٹاک تقسیم کریں۔ ایک کمپنی جس کے حصص کی تجارت 1,318 روپے کے قریب ہوتی ہے وہ قیمت بہت زیادہ ہونے کا فیصلہ کر سکتی ہے اور ہر شیئر کو دو حصوں میں تقسیم کر سکتی ہے۔ اس کے بعد دو گنا زیادہ حصص ہیں، اور چونکہ کمپنی مجموعی طور پر ایک جیسی ہے، اس لیے اب ہر شیئر کی قیمت تقریباً نصف ہے، 659 روپے کے قریب۔ کاروبار کے بارے میں کچھ نہیں بدلا۔ پائی ایک ہی سائز کی ہے، بس مزید ٹکڑوں میں کاٹ لیں۔ بونس کا مسئلہ دوسرے راستے سے بہت کچھ ایسا ہی کرتا ہے۔ کمپنی موجودہ ہولڈرز کو اضافی مفت حصص فراہم کرتی ہے، لہذا حصص کی تعداد بڑھ جاتی ہے اور فی حصص کی قیمت مماثل ہوتی ہے۔ دونوں صورتوں میں زیادہ حصص موجود ہیں اور ہر ایک انفرادی طور پر سستا ہے۔</p>\n<p>اب ان میں سے کسی کو بھی اوپن فیوچر یا آپشن پوزیشن کے خلاف پکڑیں، اور آپ دیکھ سکتے ہیں کہ آنے والی پریشانی۔</p>\n<h2 id=\"the-problem-an-open-position-faces\">ایک کھلی پوزیشن کا سامنا کرنے والا مسئلہ</h2>\n<p>تصور کریں کہ آپ کا ایک لمبا مستقبل RELIANCE ہے۔ لاٹ 500 شیئرز ہے اور مستقبل میں 1320 کے قریب تجارت ہوتی ہے، لہذا آپ کی پوزیشن تقریباً 6,60,000 روپے کے اسٹاک کی نمائندگی کرتی ہے۔ راتوں رات کمپنی اپنے حصص کو ایک کے بدلے دو تقسیم کرتی ہے، اور اگلی صبح اسٹاک 660 کے قریب کھلتا ہے، اس لیے نہیں کہ کچھ برا ہوا تھا بلکہ خالصتاً اس لیے کہ ہر شیئر اب اس کا نصف ہے۔</p>\n<p>اگر ایکسچینج نے کچھ نہیں کیا تو، آپ کا مستقبل، جو اب بھی 500 حصص کے طور پر بیان کیا جاتا ہے، اب صرف 500 گنا 660، جو کہ 3,30,000 روپے بنتا ہے۔ ایسا لگتا ہے کہ آپ کی پوزیشن راتوں رات اپنی آدھی قدر کھو چکی ہے، حالانکہ کاروبار میں کوئی تبدیلی نہیں ہوئی اور آپ نے کچھ غلط نہیں کیا۔ وہی ظلم کسی آپشن کو مارتا۔ ایک 1320 سٹرائیک جو 1318 کے اسٹاک کے مقابلے میں اچھی طرح سے تھی، اچانک 660 اسٹاک سے بہت اوپر جائے گی اور بیکار نظر آئے گی۔ تقسیم کی میکانکس، قدر میں کوئی حقیقی حرکت نہیں، آپ کی تجارت کو تباہ کر دیتی۔</p>\n<p>یہ صریحاً غیر منصفانہ ہے، اور تبادلہ اس کی اجازت نہیں دے سکتا۔ مشتق ایک وعدہ ہے جو حصہ کے اوپر لکھا ہوا ہے۔ اگر اس کے نیچے حصہ کی دوبارہ تعریف کی گئی ہے، تو اس کے معنی کو برقرار رکھنے کے لیے وعدہ کو دوبارہ لکھا جانا چاہیے۔ بصورت دیگر ہر تقسیم اور بونس ہر معاہدے کے ایک طرف اور دوسرے کو ناحق نقصان پہنچائے گا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک کارپوریٹ ایکشن حصص کی قیمت یا حصص کی تعداد کو ان وجوہات کی بنا پر تبدیل کرتا ہے جن کا کمپنی کے کم یا زیادہ ہونے سے کوئی تعلق نہیں ہوتا ہے۔ اگر آپ کا معاہدہ اچھوت چھوڑ دیا جاتا ہے، تو یہ مکمل طور پر میکانکی تبدیلی آپ کی پوزیشن کو بگاڑ دے گی، ایسا لگتا ہے جیسے آپ نے کچھ حاصل نہیں کیا یا قیمت کھو دی ہے جب حقیقی کچھ نہیں ہوا تھا۔</p>\n</div></div>\n<h2 id=\"the-principle-the-exchange-preserves-value\">اصول: تبادلہ قدر کو محفوظ رکھتا ہے۔</h2>\n<p>یہاں وہ خیال ہے جو پورے باب کو آسان بنا دیتا ہے۔ جب کوئی کارپوریٹ ایکشن کسی اسٹاک کو فیوچر اور آپشنز کے ساتھ ٹکراتا ہے تو ایکسچینج <strong>ایڈجسٹ کرتا ہے</strong> ہر کھلا معاہدہ تاکہ ہر پوزیشن کی قدر پوری کارروائی میں محفوظ رہے۔ آپ کے پاس بالکل وہی چیز ہے جو آپ نے پہلے رکھی تھی۔ ایڈجسٹمنٹ کے میکانکس سے کسی کو فائدہ نہیں ہوتا ہے اور کوئی نہیں ہارتا ہے۔</p>\n<p>یہ باب میں سب سے زیادہ یقین دلانے والی حقیقت ہے۔ ایڈجسٹمنٹ تجارت نہیں ہے، ٹیکس نہیں ہے اور فیس نہیں ہے۔ یہ بک کیپنگ ہے جو آپ کو مکمل رکھتی ہے۔ اس کے بعد آپ کے نفع یا نقصان کو ایڈجسٹ شدہ پوزیشن سے ماپا جاتا ہے، اس لیے آپ نہ تو کوئی ونڈ فال جیب میں ڈالیں گے اور نہ ہی تقسیم یا بونس سے ہونے والے فینٹم نقصان کو نگلیں گے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>جب کوئی کارپوریٹ ایکشن بنیادی حصہ کو تبدیل کرتا ہے، تو ایکسچینج اوپن فیوچرز اور آپشن کے معاہدوں کو دوبارہ اسکیل کرتا ہے تاکہ ہر پوزیشن کی قدر بالکل محفوظ رہے۔ ایڈجسٹمنٹ سے کسی کو فائدہ نہیں ہوتا اور نہ ہی کسی کو نقصان ہوتا ہے۔ یہ ایک ویلیو نیوٹرل ری رائٹ ہے، مارکیٹ کی حرکت نہیں۔</p>\n</div></div>\n<h2 id=\"the-adjustment-factor\">ایڈجسٹمنٹ کا عنصر</h2>\n<p>معاہدوں کو منصفانہ طور پر دوبارہ اسکیل کرنے کے لیے، ایکسچینج پہلے ایک نمبر پر کام کرتا ہے جسے کہا جاتا ہے۔ <strong>ایڈجسٹمنٹ عنصر</strong>. صاف لفظوں میں یہ ایک سوال کا جواب دیتا ہے: ایک پرانا حصہ کتنے نئے حصص بنتا ہے؟</p>\n<p>ایک تقسیم کے لیے دو کے لیے، ایک پرانا حصہ دو نئے حصص بن جاتا ہے، اس لیے ایڈجسٹمنٹ کا عنصر دو ہے۔ ایک بونس کے لیے جہاں کمپنی ہر حصص کے لیے ایک مفت حصہ دیتی ہے، اکثر ایک سے ایک لکھا جاتا ہے، ہر پرانا شیئر مؤثر طریقے سے دو ہو جاتا ہے، تو پھر عنصر دو ہوتا ہے۔ ایکسچینج اس عنصر کو ہر ایڈجسٹ کارپوریٹ ایکشن کے لیے شائع کرتا ہے، اور باقی سب کچھ اس سے نکلتا ہے۔</p>\n<p>ایک بار جب عنصر معلوم ہوجاتا ہے، دوبارہ اسکیلنگ میکانی ہے. دی <strong>بہت سائز</strong> فیکٹر سے ضرب کیا جاتا ہے، کیونکہ اب فی معاہدہ زیادہ، سستے حصص ہیں۔ دی <strong>ہڑتال کی قیمت</strong> ہر آپشن کو ایک ہی عنصر سے تقسیم کیا جاتا ہے، کیونکہ ہر شیئر انفرادی طور پر سستا ہوتا ہے۔ فیوچر کی قیمت اور آپ کے آپشن پریمیم کو اسی تناسب سے دوبارہ بیان کیا جاتا ہے۔ ایک طرف کو اوپر کی طرف ضرب کریں اور دوسرے کو ایک جیسی تعداد سے نیچے تقسیم کریں، اور کل قیمت جہاں سے شروع ہوئی تھی وہیں واپس آجائے گی۔</p>\n<h2 id=\"splits-and-bonus-issues-a-worked-example\">تقسیم اور بونس کے مسائل: ایک قابل عمل مثال</h2>\n<p>آئیے ہم 4RELIANCEنمبروں کو ایک تقسیم کے لیے دو کے ذریعے چلتے ہیں، دو کا ایڈجسٹمنٹ عنصر۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>تقسیم سے پہلے</th>\n<th>تقسیم کے بعد</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>شیئر کی قیمت</td>\n<td>تقریباً 1320 روپے</td>\n<td>تقریباً 660 روپے</td>\n</tr>\n<tr>\n<td>لاٹ سائز</td>\n<td>500 شیئرز</td>\n<td>1000 شیئرز</td>\n</tr>\n<tr>\n<td>ایک فیوچر لاٹ ویلیو</td>\n<td>تقریباً 6,60,000 روپے</td>\n<td>تقریباً 6,60,000 روپے</td>\n</tr>\n<tr>\n<td>ایک آپشن ہڑتال</td>\n<td>1320</td>\n<td>660</td>\n</tr>\n</tbody></table>\n<p>دیکھیں کہ مستقبل میں کیا ہوا۔ لاٹ 500 سے 1000 تک دگنا ہو گیا اور قیمت تقریباً 1320 سے آدھی ہو کر تقریباً 660 ہو گئی۔ ان کو ضرب دیں اور آپ کو دونوں طرف سے تقریباً 6,60,000 روپے کی نمائش ملے گی۔ آپ کا ایک لاٹ ابھی بھی ایک لاٹ ہے، کام پر ایک ہی رقم، صرف دو گنا زیادہ شیئرز کا اظہار کیا گیا ہے جس کی قیمت نصف ہے۔</p>\n<p>آپشن بالکل صاف ہے۔ 1320 کی سٹرائیک 660 کی سٹرائیک بن جاتی ہے اور جو لاٹ اس کو کنٹرول کرتا ہے وہ 500 سے بڑھ کر 1000 ہو جاتا ہے۔ 1318 کے سٹاک کے مقابلے میں دو روپے کا آپشن 659 سٹاک کے مقابلے میں 660 کی سٹرائیک بن جاتا ہے، پھر بھی دو گنا حصص پر فی حصص رقم میں تقریباً ایک روپیہ ہے۔ اس کی اصل قیمت نہیں بڑھی، صرف اس کے لیبلز نے حرکت کی۔ ایک سے ایک بونس ایک جیسی ریاضی پیدا کرتا ہے، کیونکہ یہ بھی حصص کی تعداد کو دوگنا اور قیمت کو آدھا کر دیتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-corporate-action.png\" alt=\"ایک RELIANCE کنٹریکٹ کی قدر کو محفوظ کرنے والے دوبارہ لکھنے کے طور پر دکھایا گیا ایک اسٹاک کی دو کے لیے: لاٹ کا پیمانہ 500 سے 1000 شیئرز تک ہوتا ہے جب کہ قیمت اور آپشن اسٹرائیک اسکیل تقریباً 1320 سے 660 تک نیچے آجاتا ہے، اس لیے قیمت سے ضرب کردہ لاٹ سائز تقریباً 6,60,00 روپے پر رہتا ہے اور دونوں طرف اس کی اصل قیمت کیا تھی۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک RELIANCE کنٹریکٹ کی قدر کو محفوظ کرنے والے دوبارہ لکھنے کے طور پر دکھایا گیا ایک اسٹاک کی دو کے لیے: لاٹ 500 سے 1000 شیئرز تک بڑھتا ہے جب کہ قیمت اور آپشن اسٹرائیک اسکیل تقریباً 1320 سے 660 تک نیچے آجاتا ہے، اس لیے قیمت سے ضرب کردہ لاٹ سائز تقریباً 6,60,000 روپے پر رہتا ہے اور دونوں طرف کی پوزیشن بالکل وہی ہے جو اس سے پہلے تھی۔</figcaption></figure>\n<p>تو آپ کی سکرین راتوں رات کیوں بدل گئی؟ کیونکہ ایڈجسٹمنٹ کمپنی کی طرف سے اعلان کردہ دو تاریخوں سے منسلک ہے۔ دی <strong>ریکارڈ کی تاریخ</strong> وہ دن ہے جب کمپنی اپنے شیئر رجسٹر کی جانچ کرتی ہے تاکہ یہ فیصلہ کیا جا سکے کہ کون تقسیم یا بونس کا حقدار ہے۔ دی <strong>سابقہ ​​تاریخ</strong>, عام طور پر اس سے پہلے مقرر کیا جاتا ہے، اسٹاک کی تجارت کا پہلا دن ہوتا ہے۔ <strong>بغیر</strong> وہ استحقاق منسلک ہے، جو بالکل اس وقت ہوتا ہے جب قیمت اپنی نئی نچلی سطح پر آجاتی ہے۔ ایکسچینج معاہدہ کی ایڈجسٹمنٹ کو سابقہ ​​تاریخ سے لاگو کرتا ہے، لہذا دوبارہ اسکیل شدہ لاٹ، دوبارہ اسکیل کی گئی اسٹرائیک اور سستی حصص کی قیمت سب ایک ساتھ ظاہر ہوتے ہیں، اور آپ کی پوزیشن ویلیو غیر منقطع ہوتی ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ نے ایک تقسیم کے لیے دو سے پہلے ایک RELIANCE 1320 کال رکھی ہے۔ سابقہ ​​تاریخ پر اسٹاک 660 کے قریب کھلتا ہے، آپ کی کال کو 660 سٹرائیک کے طور پر دوبارہ لسٹ کیا جاتا ہے، اور اس کے پیچھے 500 سے 1000 شیئرز تک اضافہ ہوتا ہے۔ آپ نے کچھ نہیں کیا، کچھ ادا نہیں کیا اور آپ سے کچھ نہیں لیا گیا۔ آپ کی سکرین پر نمبر بدل گئے، ان کے پیچھے قیمت نہیں بدلی۔</p>\n</div></div>\n<h2 id=\"special-dividends\">خصوصی منافع</h2>\n<p>منافع ایک ایسا معاملہ ہے جہاں عام طور پر تبادلہ ہوتا ہے۔ <strong>کچھ نہیں</strong>. کمپنیاں ہر وقت عام ڈیویڈنڈ ادا کرتی رہتی ہیں، اسٹاک اپنی سابقہ ​​تاریخ پر تقریباً ڈیویڈنڈ سے کم ہوجاتا ہے، اور چونکہ یہ چھوٹی، متوقع کمی عام زندگی کا حصہ ہے، اس لیے ڈیریویٹیو کنٹریکٹس اچھوت رہ ​​جاتے ہیں۔ ہر روٹین کی ادائیگی کے لیے ایڈجسٹ کرنا بے جا منڈلانا ہوگا۔</p>\n<p>استثناء ہے a <strong>خصوصی منافع</strong>, ایک غیر معمولی طور پر بڑی ایک آف ادائیگی. جب ڈیویڈنڈ کافی بڑا ہوتا ہے، تو سابقہ ​​تاریخ کا ڈراپ اب کوئی چھوٹا سا جھٹکا نہیں ہوتا ہے بلکہ ایک حقیقی جھٹکا ہوتا ہے جو کھلے اختیارات کی پوزیشنوں کو تقسیم کی طرح مسخ کر دیتا ہے۔ تو ایکسچینج سیٹ کرتا ہے a <strong>دہلیز</strong>، اسٹاک کی قیمت کا ایک فیصد، جس کے اوپر ڈیویڈنڈ غیر معمولی شمار ہوتا ہے اور ایڈجسٹمنٹ کو متحرک کرتا ہے۔ حد سے نیچے، کوئی تبدیلی نہیں۔ اس کے اوپر، ہڑتالوں کو ادائیگی کے لیے ایڈجسٹ کیا جاتا ہے تاکہ آپشن ہولڈرز کو ڈراپ سے غیر منصفانہ طور پر تکلیف نہ ہو۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ڈیویڈنڈ کی حد اور درست طریقہ ایکسچینج کے ذریعے متعین کیا جاتا ہے، آپ یا آپ کے بروکر نے نہیں، اور ان پر پہلے بھی نظر ثانی کی جا چکی ہے۔ فی صد اصول کو ایک مقررہ قانون کے بجائے موجودہ فریم ورک کے طور پر سمجھیں، اور تازہ ترین NSE کارپوریٹ ایکشن ایڈجسٹمنٹ سرکلر کے خلاف نافذ ہونے والے اعداد و شمار کی تصدیق کریں اس سے پہلے کہ آپ یہ فرض کر لیں کہ کسی خاص ڈیویڈنڈ کے ساتھ کیا سلوک کیا جائے گا۔</p>\n</div></div>\n<h2 id=\"rights-issues-and-mergers\">حقوق کے مسائل اور انضمام</h2>\n<p>باقی کارپوریٹ ایکشنز کو ایک ہی مقصد کے ساتھ سنبھالا جاتا ہے، قدر کو محفوظ رکھا جاتا ہے، لیکن انہیں زیادہ دیکھ بھال کی ضرورت ہوتی ہے کیونکہ ریاضی کم صاف ہے۔</p>\n<p>اے <strong>حقوق کا مسئلہ</strong> موجودہ حصص یافتگان کو مارکیٹ سے کم قیمت پر نئے حصص خریدنے دیتا ہے، جو ہر موجودہ حصص کی قدر کو کم کرتا ہے۔ تقسیم کی طرح کوئی واحد صاف تناسب نہیں ہے۔ ایکسچینج حقوق کے تناسب اور رعایتی قیمت سے ایک ایڈجسٹمنٹ عنصر کی گنتی کرتا ہے، پھر لاٹ کو دوبارہ اسکیل کرتا ہے اور اسی قدر غیر جانبدار طریقے سے اس عنصر کے ذریعے اسٹرائیک کرتا ہے۔ اصول غیر تبدیل شدہ ہے۔ صرف نمبر آنکھ کی گولی کے لئے مشکل ہے.</p>\n<p><strong>انضمام</strong>، انضمام اور ڈیمرجرز کو کیس کے لحاظ سے ہینڈل کیا جاتا ہے، کیونکہ بنیادی خود ہی شناخت کو تبدیل کر سکتا ہے۔ بعض اوقات نئے مشترکہ وجود کی عکاسی کرنے کے لیے معاہدے کو ایڈجسٹ کیا جاتا ہے اور تجارت جاری رہتی ہے۔ بعض اوقات، جب ایک کمپنی کو جذب کیا جا رہا ہوتا ہے اور ایک علیحدہ اسٹاک کے طور پر اس کا وجود ختم ہو جاتا ہے، تو اس کے اخذ کردہ معاہدوں کو مناسب قیمت پر طے کیا جاتا ہے اور اسے بند کر دیا جاتا ہے، یا بقایا کمپنی کے معاہدوں میں تبدیل کر دیا جاتا ہے۔ کوئی عالمگیر نسخہ نہیں ہے۔ ہر ایونٹ کے لیے ایکسچینج ایک مخصوص سرکلر ہجے کرتا ہے کہ کھلے معاہدوں کا کیا ہوتا ہے، اس لیے فیصلہ کبھی بھی بہتر نہیں کیا جاتا۔</p>\n<h2 id=\"what-you-actually-need-to-do\">آپ کو اصل میں کیا کرنے کی ضرورت ہے۔</h2>\n<p>تمام مشینری کے لیے، عملی ہدایت مختصر اور پرسکون ہے۔ آپ کو کچھ کرنے کی ضرورت نہیں ہے۔ آپ کوئی آرڈر نہیں دیتے، فارم پر دستخط نہیں کرتے اور کوئی ایڈجسٹمنٹ فیس نہیں دیتے۔ ایکسچینج آپ کے معاہدے کو سابقہ ​​تاریخ پر خود بخود ری سکیل کر دیتا ہے اور آپ کی پوزیشن پوری ہوتی ہے۔</p>\n<p>آپ پر جو واجب ہے وہ سمجھنا ہے، لہذا جس صبح آپ کا لاٹ 500 کی بجائے 1000 پڑھتا ہے یا آپ کی ہڑتال 1320 کے بجائے 660 پڑھتی ہے، آپ اسے غلطی یا نقصان کے بجائے فوری طور پر کارپوریٹ ایکشن ایڈجسٹمنٹ کے طور پر پہچان لیتے ہیں۔ دو عادتیں اسے آسان بنا دیتی ہیں۔ سب سے پہلے، کسی بھی اسٹاک کے لیے کارپوریٹ ایکشن کے اعلانات پر ایک نظر ڈالیں جس پر آپ ڈیریویٹو رکھتے ہیں، اس لیے تقسیم، بونس یا خصوصی ڈیویڈنڈ کبھی بھی آپ پر حملہ نہیں کرتا۔ دوسرا، جب کوئی چیز دوبارہ اسکیل کی ہوئی نظر آتی ہے، تو NSE کارپوریٹ ایکشن ایڈجسٹمنٹ صفحہ پر درست علاج چیک کریں، جہاں اس مخصوص ایونٹ کا عنصر اور طریقہ شائع کیا گیا ہے۔ حدیں اور درست طریقے تبادلے سے متعین ہیں اور بدل سکتے ہیں، اس لیے موجودہ سرکلر، میموری نہیں، اختیار ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>آپ کو کبھی بھی کارپوریٹ ایکشن ایڈجسٹمنٹ پر عمل کرنے کی ضرورت نہیں ہے، لیکن آپ کو اسے ہمیشہ سمجھنا چاہیے۔ اگر آپ کا لاٹ سائز یا اسٹرائیک اچانک مختلف نظر آتا ہے تو گھبرائیں نہیں اور غلطی کا خیال نہ کریں۔ اس اسٹاک کے لیے NSE کارپوریٹ ایکشن ایڈجسٹمنٹ سرکلر کے خلاف اس کی تصدیق کریں، محفوظ قیمت دیکھیں، اور آگے بڑھیں۔</p>\n</div></div>\n<p>ٹیک وے اس کورس کے معیارات کے لحاظ سے نرم ہے۔ زیادہ تر فیوچر ٹریڈنگ خطرے کے بارے میں ہے جس سے آپ کو دفاع کرنا چاہیے۔ کارپوریٹ ایکشن ایک غیر معمولی معاملہ ہے جہاں سسٹم خاموشی سے آپ کے حق میں کام کرتا ہے، آپ کے معاہدے کو دوبارہ تیار کرتا ہے تاکہ تقسیم، بونس یا خصوصی ڈیویڈنڈ آپ کی قدر نہ چھین سکے یا آپ کو کوئی غیر حاصل شدہ فائدہ نہ دے سکے۔ جانیں کہ ایسا ہوتا ہے، جانیں کہ آپ کے نمبر کیوں بدلتے ہیں، اور ایکسچینج کو اپنی بک کیپنگ کرنے دیں جب آپ خود تجارت کو دیکھتے ہیں۔</p>\n","toc":[{"level":2,"text":"ایک کارپوریٹ ایکشن شیئر کے ساتھ کیا کرتا ہے۔","id":"what-a-corporate-action-does-to-a-share"},{"level":2,"text":"ایک کھلی پوزیشن کا سامنا کرنے والا مسئلہ","id":"the-problem-an-open-position-faces"},{"level":2,"text":"اصول: تبادلہ قدر کو محفوظ رکھتا ہے۔","id":"the-principle-the-exchange-preserves-value"},{"level":2,"text":"ایڈجسٹمنٹ کا عنصر","id":"the-adjustment-factor"},{"level":2,"text":"تقسیم اور بونس کے مسائل: ایک قابل عمل مثال","id":"splits-and-bonus-issues-a-worked-example"},{"level":2,"text":"خصوصی منافع","id":"special-dividends"},{"level":2,"text":"حقوق کے مسائل اور انضمام","id":"rights-issues-and-mergers"},{"level":2,"text":"آپ کو اصل میں کیا کرنے کی ضرورت ہے۔","id":"what-you-actually-need-to-do"}],"imgCount":1,"hasContent":true},"22":{"html":"<p>آپ نے اپنا ذہن بنا لیا ہے۔ RELIANCE مشکل سے چڑھ رہا ہے، آپ چاہتے ہیں، اور بڑھتی ہوئی قیمت کا پیچھا کرنے کے بجائے آپ خریداری کا آرڈر دیتے ہیں ایک آرام دہ فاصلے سے اوپر جہاں یہ ٹریڈنگ ہو رہی ہے، اگر یہ حرکت جاری رہتی ہے تو بھرنے کے لیے تیار ہے۔ آپ بٹن دبائیں۔ تصدیق کے بجائے آرڈر واپس آتا ہے۔ <strong>مسترد کر دیا</strong>. کچھ نہیں خریدا تھا۔ آپ اسکرین کو گھورتے ہیں، یقین ہے کہ آپ نے کچھ غلط کیا ہے، کیونکہ یقیناً اوپن مارکیٹ میں آپ اپنی پسند کے معاہدے کے لیے کوئی بھی قیمت پیش کر سکتے ہیں۔</p>\n<p>آپ نہیں کر سکتے، اور وہ حیرت اس باب کا موضوع ہے۔ ایکسچینج کسی معاہدے کو ایک دن میں اپنی مرضی کے مطابق کوئی فاصلہ طے کرنے نہیں دیتا، اور یہ آپ کو کسی بھی قیمت پر آرڈر کرنے نہیں دیتا۔ قیمت کے ارد گرد دیواریں ہیں، سائز کے ارد گرد دیواریں، اور ایک جنگلی دن پوری مارکیٹ کے ارد گرد دیواریں ہیں جو مکمل طور پر تجارت کو روک سکتی ہیں. ان دیواروں کو سمجھنا تکنیکی نہیں ہے۔ جب آپ ہارنے والی پوزیشن پر فائز ہوتے ہوئے ان میں سے کوئی بند کر دیتا ہے، تو یہ آپ کو باہر نکلنے سے روک سکتا ہے، اور ایک لیوریجڈ ٹریڈر کے لیے یہ ایک زخم اور آفت کے درمیان فرق ہے۔</p>\n<h2 id=\"the-daily-price-band\">روزانہ کی قیمت کا بینڈ</h2>\n<p>ہر فیوچر معاہدہ a کے اندر تجارت کرتا ہے۔ <strong>قیمت بینڈ</strong>، جسے کبھی کبھی آپریٹنگ رینج کہا جاتا ہے۔ یہ دن کے لیے ایک چھت اور فرش ہے، جو a کے اوپر اور نیچے فیصد کے طور پر ماپا جاتا ہے۔ <strong>حوالہ قیمت</strong>، عام طور پر پچھلے دن کی بندش یا تصفیہ کی قیمت۔ معاہدہ ان دو دیواروں کے درمیان کہیں بھی منتقل ہونے کے لیے آزاد ہے، لیکن یہ ان سے آگے تجارت نہیں کر سکتا اور نہ ہی کوئی حکم قبول کر سکتا ہے۔</p>\n<p>اس پر RELIANCE اینکر لگائیں۔ ارد گرد RELIANCE کے ساتھ <strong>1,318 روپے</strong> اور دس فیصد کا بینڈ، فرش 1,186 روپے کے قریب اور چھت 1,450 روپے کے قریب ہے۔ اس حد کے اندر آپ سارا دن خرید و فروخت کر سکتے ہیں۔ 1,470 روپے میں خریدنے کا آرڈر، چھت سے اوپر، کتاب پر آرام نہیں کرے گا اور نہیں بھرے گا۔ تبادلہ صرف اس سے انکار کرتا ہے۔ بینڈ کسی ایک موٹی انگلی والے آرڈر، افواہ، یا کسی معاہدے کو مضحکہ خیز قیمت تک پہنچانے اور اس کے ساتھ حقیقی رقم گھسیٹنے سے روکنے کے لیے موجود ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>قیمت کا بینڈ روزانہ کی چھت اور فرش ہوتا ہے، جو حوالہ قیمت کے اوپر اور نیچے فیصد کے طور پر مقرر کیا جاتا ہے، عام طور پر کل کے قریب۔ فیوچر کنٹریکٹ بینڈ کے اندر آزادانہ طور پر منتقل ہوسکتا ہے، لیکن اس سے آگے کا آرڈر ایکسچینج کے ذریعہ مسترد کردیا جاتا ہے، بعد میں پارک نہیں کیا جاتا۔</p>\n</div></div>\n<p>درست چوڑائی یاد رکھنے کی چیز نہیں ہے، کیونکہ یہ معاہدے کے لحاظ سے مختلف ہوتی ہے اور تبادلہ اس پر نظر ثانی کرتا ہے۔ مائع معاہدوں کو وسیع بینڈ ملتا ہے۔ پتلی یا نئی فہرست والے سخت ہوتے ہیں، اور NSE ہر سیکیورٹی کے لیے آپریٹنگ رینج شائع کرتا ہے۔ سبق اصول ہے، ایک مقررہ شکل نہیں: ہمیشہ ایک دیوار ہوتی ہے، اور اس کے قریب تجارت کرنے سے پہلے آپ کو یہ معلوم ہونا چاہیے کہ وہ کہاں ہے۔</p>\n<h2 id=\"why-your-futures-order-gets-rejected\">آپ کا فیوچر آرڈر کیوں مسترد ہو جاتا ہے۔</h2>\n<p>مسترد ہونا ایک غلطی کی طرح محسوس ہوتا ہے، لیکن یہ تقریباً ہمیشہ ہی ایسا نظام ہوتا ہے جو مارکیٹ کو کسی ایسے حکم سے بچاتا ہے جو کسی اصول کو توڑتا ہے۔ ایک ابتدائی کے لیے تین معمول کی وجوہات ہیں، اور ہر ایک کی ایک سادہ فکس ہے۔</p>\n<ul>\n<li><strong>قیمت بینڈ سے باہر ہے۔</strong> آپ نے چھت کے اوپر یا فرش کے نیچے قیمت کا نام دیا ہے۔ درست کرنا آسان ہے: اپنی قیمت کو آپریٹنگ رینج کے اندر واپس لائیں۔ اگر آپ حقیقی طور پر طاقت خریدنا چاہتے ہیں، تو آرڈر کو اس سے آگے کی بجائے چھت کے اندر دیں۔</li>\n<li><strong>سائز منجمد مقدار سے باہر ہے۔</strong> پوزیشن کی حدود سے متعلق ایک پہلے باب نے متعارف کرایا <strong>مقدار منجمد</strong>, لاٹوں کی سب سے بڑی تعداد جسے ایکسچینج ایک ہی آرڈر میں قبول کرے گا۔ ایک ہی بار میں اس سے زیادہ مانگیں اور حکم مسترد کر دیا جاتا ہے۔ ٹھیک کرنا ہے۔ <strong>ٹکڑا</strong> تجارت، ایک بڑے آرڈر کے بجائے کئی چھوٹے آرڈر بھیجنا جو ہر ایک منجمد ہو کر بیٹھ جاتا ہے۔</li>\n<li><strong>آپ حرکت کے بعد آپریٹنگ رینج سے باہر ہیں۔</strong> تیز دن پر بینڈ خود ہی شفٹ ہو سکتا ہے، اور ایک آرڈر جو ایک لمحے پہلے درست تھا موجودہ حد سے باہر ہو سکتا ہے۔ حل یہ ہے کہ لائیو رینج کو دوبارہ چیک کیا جائے اور دوبارہ قیمت لگائی جائے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>مسترد کردہ آرڈر معلومات ہے، خرابی نہیں۔ وجہ پڑھیں۔ اگر یہ کہتا ہے کہ قیمت حد سے باہر ہے، تو اپنی قیمت کو بینڈ کے اندر منتقل کریں۔ اگر یہ کہتا ہے کہ مقدار منجمد ہے تو ترتیب کو چھوٹے ٹکڑوں میں توڑ دیں۔ بازار ٹوٹا نہیں ہے۔ آپ نے صرف ایک دیوار سے ٹکرا دیا ہے جس میں ایکسچینج کو مقصد کے لیے رکھا گیا تھا۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-price-bands.png\" alt=\"فیوچر کنٹریکٹ ٹریڈنگ اس کے یومیہ پرائس بینڈ کے اندر: حوالہ قیمت درمیان میں بیٹھتی ہے، چھت اور فرش کو ایک مقررہ فیصد دور رکھا جاتا ہے، اور دیوار سے آگے رکھا گیا کوئی بھی آرڈر بھرنے کی بجائے مسترد کر دیا جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>فیوچر کنٹریکٹ ٹریڈنگ اس کے یومیہ پرائس بینڈ کے اندر: حوالہ قیمت درمیان میں بیٹھتی ہے، چھت اور فرش کو ایک مقررہ فیصد دور رکھا جاتا ہے، اور دیوار سے آگے رکھا گیا کوئی بھی آرڈر بھرنے کی بجائے مسترد کر دیا جاتا ہے۔</figcaption></figure>\n<h2 id=\"dynamic-price-bands-how-the-f-o-wall-bends\">ڈائنامک پرائس بینڈز: F&amp;O وال کیسے جھکتی ہے۔</h2>\n<p>ایک فکسڈ بینڈ میں ایک واضح خامی ہے۔ اگر کسی اسٹاک کے پاس حقیقی طور پر اچھی خبر ہے اور وہ بارہ فیصد منتقل ہونے کا مستحق ہے، تو دس فیصد کی سخت دیوار ایک منصفانہ، منظم حرکت کو منجمد کر دے گی اور سب کو پھنسائے گی، جو کہ مارکیٹ کے برعکس ہے۔ لہذا مائع مشتقات کے لیے تبادلہ استعمال کرتا ہے۔ <strong>متحرک قیمت بینڈ</strong>، جسے موڑنا بھی کہا جاتا ہے۔</p>\n<p>یہاں یہ ہے کہ یہ سادہ الفاظ میں کیسے کام کرتا ہے۔ معاہدہ معمول کے مطابق اپنا بینڈ رکھتا ہے۔ جب قیمت چھت یا فرش کے بالکل اوپر جاتی ہے اور وہاں تجارت کرتی ہے، تو ایکسچینج اسے ایک اشارہ سمجھتا ہے کہ یہ حرکت خرابی کی بجائے حقیقی ہوسکتی ہے۔ ایک مختصر، وضاحتی توقف کے بعد، یہ <strong>لچک</strong> بینڈ، اسے ایک اور قدم سے چوڑا کرتا ہے، اکثر پانچ فیصد، تاکہ مارکیٹ چلتی رہے۔ اگر قیمت بڑھتی رہتی ہے، تو بینڈ دن بھر، قدم بہ قدم، پھر سے جھک سکتا ہے۔</p>\n<p>ایک تاجر کے لیے اہم تفصیل یہ ہے کہ ہر فلیکس ٹریڈنگ میں ایک مختصر وقفے کے ساتھ آتا ہے، بینڈ کے ری سیٹ ہونے کے دوران چند منٹوں کے کولنگ آف لمحے ہوتے ہیں۔ لہذا ایک حقیقی مضبوط اقدام ہمیشہ کے لیے منجمد نہیں ہوتا، لیکن یہ ایک ہموار لائن میں بھی نہیں چلتا۔ یہ آگے بڑھتا ہے، دیوار کو حرکت دیتے وقت رکتا ہے، دوبارہ آگے بڑھتا ہے۔ اگر آپ ان منٹوں میں کام کرنے کی کوشش کر رہے ہیں، تو آپ کو معلوم ہو سکتا ہے کہ فلیکس مکمل ہونے تک معاہدہ تجارت نہیں کرے گا۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>متحرک بینڈنگ ایک سمجھوتہ ہے۔ ایک سخت بینڈ ایک منصفانہ اقدام کو منجمد کر دے گا۔ کوئی بینڈ بھاگنے کی اجازت نہیں دے گا۔ لہٰذا ایکسچینج بینڈ کو ہر بار تھوڑے وقفے کے بعد جب بھی قیمت اس پر جھکتی ہے، وسیع تر ہونے دیتی ہے۔ مارکیٹ چلتی رہتی ہے، لیکن مراحل میں، ایک صاف دوڑ میں نہیں۔</p>\n</div></div>\n<h2 id=\"index-circuit-breakers-halting-the-whole-market\">انڈیکس سرکٹ بریکرز: پوری مارکیٹ کو روکنا</h2>\n<p>ایک پرائس بینڈ ایک معاہدے کی حفاظت کرتا ہے۔ اے <strong>سرکٹ بریکر</strong> پوری مارکیٹ کی حفاظت کرتا ہے۔ جب ایک بینچ مارک انڈیکس، NIFTY یا SENSEX، ایک ہی دن میں بہت بڑی رقم منتقل کرتا ہے، تو ایکسچینج پورے بورڈ میں، نقدی اور مشتقات میں تجارت روک دیتا ہے، تاکہ ہر کسی کو ٹھہرنے، سانس لینے، اور جو کچھ ہو رہا ہے اسے جذب کر سکے۔</p>\n<p>مارکیٹ وائڈ بریکر میں تین ٹرگر لیولز ہوتے ہیں، جو تقریباً سیٹ ہوتے ہیں۔ <strong>دس، پندرہ اور بیس فیصد</strong> بینچ مارک میں حرکت کرتا ہے، پچھلے بند سے ماپا جاتا ہے۔ جو بھی انڈیکس کسی لیول کی خلاف ورزی کرتا ہے پہلے پوری مارکیٹ کے لیے رک جاتا ہے۔ اہم موڑ یہ ہے کہ رکنے کی لمبائی کا انحصار اس سطح پر ہوتا ہے جس کی خلاف ورزی کی گئی ہے اور یہ دن کے وقت پر ہوتا ہے۔ اسی دس فیصد گرنے کی وجہ سے صبح سویرے ایک لمبا وقفہ اور دوپہر میں ایک مختصر وقفہ ہوتا ہے، کیونکہ سیشن کا کم و بیش وقت طے ہونا باقی ہے۔ ایک بیس فیصد اقدام مشکل اسٹاپ ہے: اس سے تجارت ختم ہوجاتی ہے۔ <strong>باقی دن</strong>، اس سے کوئی فرق نہیں پڑتا ہے کہ جب یہ حملہ کرتا ہے۔</p>\n<p>نیچے دی گئی جدول اصول کی شکل دکھاتی ہے۔ دورانیے کو مثالی کے طور پر سمجھیں، کیونکہ ایکسچینج کے ذریعے درست منٹوں کی وضاحت کی گئی ہے اور ان پر بھروسہ کرنے سے پہلے موجودہ NSE سرکٹ فلٹر اصولوں کے خلاف جانچ پڑتال کے قابل ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>انڈیکس حرکت</th>\n<th>سیشن کے اوائل میں</th>\n<th>بعد میں سیشن میں</th>\n<th>دیر سے دوپہر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تقریباً 10%</td>\n<td>طویل وقفہ، تقریباً تین چوتھائی گھنٹے</td>\n<td>چھوٹا رکا، تقریباً پندرہ منٹ</td>\n<td>کوئی روک نہیں</td>\n</tr>\n<tr>\n<td>تقریباً 15%</td>\n<td>لمبا رکا، ایک گھنٹے سے زیادہ</td>\n<td>مختصر وقفہ</td>\n<td>دن بھر تجارت رک جاتی ہے۔</td>\n</tr>\n<tr>\n<td>تقریباً 20%</td>\n<td>تجارت کسی بھی وقت باقی دن کے لیے رک جاتی ہے۔</td>\n<td></td>\n<td></td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-circuit-breaker.png\" alt=\"مارکیٹ وائیڈ سرکٹ بریکر: تقریباً 10، 15 یا 20 فیصد کا ایک بینچ مارک انڈیکس حرکت تمام ٹریڈنگ کو روک دیتا ہے، جس میں وقفہ دن کے اوائل میں زیادہ دیر تک رہتا ہے اور 20 فیصد کی حرکت باقی سیشن کے لیے مارکیٹ کو روکتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>مارکیٹ وائیڈ سرکٹ بریکر: تقریباً 10، 15 یا 20 فیصد کا ایک بینچ مارک انڈیکس حرکت تمام ٹریڈنگ کو روک دیتا ہے، جس میں وقفہ دن کے اوائل میں زیادہ دیر تک رہتا ہے اور 20 فیصد کی حرکت باقی سیشن کے لیے مارکیٹ کو روکتی ہے۔</figcaption></figure>\n<p>جب دس یا پندرہ فیصد کی سطح پر روکا جاتا ہے تو، مارکیٹ صرف آخری قیمت پر واپس نہیں آتی ہے۔ یہ ایک مختصر کے ذریعے دوبارہ کھلتا ہے۔ <strong>پری اوپن کال نیلامی</strong>, ایک ونڈو جہاں آرڈرز اکٹھے کیے جاتے ہیں اور ایک نئی افتتاحی قیمت دریافت کی جاتی ہے، اس سے پہلے کہ عام تجارت دوبارہ شروع ہو جائے۔ تعطل کے دوران ہی بازار جما ہوا ہے۔ آپ خرید نہیں سکتے، آپ بیچ نہیں سکتے، اور آپ باہر نہیں نکل سکتے۔ آپ کی کھلی جگہیں بالکل اسی جگہ پر بیٹھتی ہیں جہاں وہ تھیں، جہاں بھی قیمت دوبارہ کھلتی ہے وہاں پوری طرح سے ظاہر ہوتی ہے، اور آپ کے آرام کے احکامات کا انتظار ہوتا ہے۔ یہ وہ لمحہ ہے جس کی طرف پورا باب تعمیر ہو رہا ہے۔</p>\n<h2 id=\"when-a-band-or-a-halt-traps-you\">جب کوئی بینڈ یا روک آپ کو پھنساتا ہے۔</h2>\n<p>اب فائدہ اٹھانے کے لیے اس میں شامل ہو جائیں، کیونکہ یہی وہ جگہ ہے جہاں خطرہ رہتا ہے۔ فرض کریں کہ آپ ایک طویل RELIANCE مستقبل، نمائش کے 500 حصص، اور بری خبروں کے کامیاب ہونے والے ہیں۔ معاہدہ مشکل سے گرتا ہے اور اس کے نچلے بینڈ میں گر جاتا ہے۔ فرش پر بیچنے والے ہیں لیکن کم یا کوئی خریدار زیادہ تجارت کرنے کو تیار نہیں ہیں، لہذا قیمت ہے۔ <strong>حد بند</strong> نیچے آپ باہر نکلنے کے لیے سیل آرڈر دیتے ہیں، اور ہو سکتا ہے کہ وہ بھر نہ سکے، کیونکہ بیچنے کے لیے آپ کو خریدار کی ضرورت ہوتی ہے، اور ایک بینڈ پر جس سے ہر کوئی بھاگنا چاہتا ہے، خریدار غائب ہو جاتے ہیں۔ آپ نقصان میں پھنسے ہوئے ہیں، جب تک بینڈ فلیکس نہیں ہو جاتا یا خریدار واپس نہیں آتے، اس وقت تک عمل کرنے سے قاصر ہیں، اس وقت تک قیمت اب بھی کم ہو سکتی ہے۔</p>\n<p>بڑے پیمانے پر بازار میں ایک ہی کام کرتا ہے۔ انڈیکس ایک سرکٹ لیول کو توڑ دیتا ہے، ٹریڈنگ رک جاتی ہے، اور آپ کی ہارنے والی پوزیشن اپنی جگہ پر جم جاتی ہے۔ آپ کا ایگزٹ پلان اب بیکار ہے، کیونکہ ایکسچینج نے ایک ہی وقت میں سب کے لیے دروازے بند کر دیے ہیں، اور جب مارکیٹ پری اوپن نیلامی کے ذریعے دوبارہ کھلتی ہے تو قیمت اس سے بہت آگے بڑھ سکتی ہے جہاں سے آپ نکلنا چاہتے تھے۔</p>\n<p>یہی وجہ ہے کہ سٹاپ لوس ایک منصوبہ ہے، وعدہ نہیں۔ گیپ اور ایونٹ کے خطرے سے متعلق بعد کا باب اس کی طرف لوٹتا ہے، لیکن اصول یہاں بھی ہے: سٹاپ صرف اس صورت میں کام کر سکتا ہے جب مارکیٹ کھلی ہو اور آپ کی سطح پر تجارت ہو۔ بینڈ لاک یا رکا ہوا بازار دونوں میں سے کوئی بھی پیشکش نہیں کرتا ہے، لہذا ایک سٹاپ جس پر آپ نے اپنے نقصان کو ایک نمبر تک محدود کرنے پر بھروسہ کیا ہے وہ آپ کو بدتر بنا سکتا ہے، یا اس وقت تک نہیں بھر سکتا جب تک کہ قیمت ختم نہ ہو جائے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>پرائس بینڈ یا سرکٹ ہالٹ آپ کو کھونے والی تجارت سے باہر نکلنے سے روک سکتا ہے۔ ایک حد بند قیمت پر بیچنے کے لیے کوئی خریدار نہیں ہو سکتا، اور تعطل کے دوران کوئی بھی تجارت نہیں کر سکتا۔ جب مارکیٹ حد سے زیادہ یا منجمد ہو تو سٹاپ لاس باہر نکلنے کی ضمانت نہیں دیتا۔ ہر لیوریجڈ پوزیشن کا سائز یہ فرض کرتے ہوئے کہ آپ اپنی منتخب کردہ قیمت پر نہیں نکل سکتے۔</p>\n</div></div>\n<h2 id=\"trading-near-the-limits\">حد کے قریب تجارت</h2>\n<p>اس میں سے کوئی بھی آپ کو مستقبل سے خوفزدہ نہیں کرنا چاہئے۔ یہ آپ کے سائز اور منصوبہ بندی کو تبدیل کرنا چاہئے. دیواریں حقیقی ہیں، وہ پہلے سے جانی جاتی ہیں، اور ایک محتاط تاجر ان سے چونکنے کے بجائے ان کا احترام کرتا ہے۔</p>\n<ul>\n<li>اپنے احکامات جاری رکھیں <strong>بینڈ کے اندر</strong>. اگر آپ کو قیمت کے لیے مسترد کر دیا جاتا ہے، تو دیوار سے لڑنے کے بجائے آپریٹنگ رینج کے اندر چلے جائیں۔</li>\n<li>کے نیچے ایک بڑے آرڈر کو سلائس کریں۔ <strong>مقدار منجمد</strong> اسے مکمل بھیجنے کے بجائے۔</li>\n<li>علاج a <strong>حد بند یا روکا ہوا</strong> مارکیٹ ایک ایسی پوزیشن کے طور پر جس میں آپ پھنس سکتے ہیں، اور سائز اتنا چھوٹا ہے کہ پھنس جانا زندہ رہ سکتا ہے۔</li>\n<li>کبھی فرض نہ کریں a <strong>روکو</strong> باہر نکلنے کی ضمانت دیتا ہے۔ یہ آپ کی نیت ہے، تبادلے کا وعدہ نہیں۔</li>\n<li>بالکل یاد رکھیں <strong>بینڈ کی چوڑائی اور سرکٹ کی سطحیں تبادلے سے متعین ہیں۔</strong> اور تبدیل کریں، اس لیے میموری سے کسی نمبر پر بھروسہ کرنے کے بجائے موجودہ NSE اصولوں کو چیک کریں۔</li>\n</ul>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>نتائج والے دن ایک تاجر کے پاس مستقبل کے درمیانے سائز کے تین لاٹ ہوتے ہیں۔ خبر بری ہے، کنٹریکٹ نیچے اور اس کے نچلے بینڈ پر لاک ہو جاتا ہے، اور ٹریڈر کا سٹاپ بالکل نیچے بیٹھتا ہے، کبھی متحرک نہیں ہوتا کیونکہ وہاں کچھ بھی تجارت نہیں کرتا۔ دو گھنٹے تک نقصان منجمد ہے اور کاغذ پر بڑھ رہا ہے، اسے فروخت کرنے والا کوئی خریدار نہیں ہے۔ اگر تاجر کے پاس تین کی بجائے ایک لاٹ ہوتا تو وہی بند بازار اکاؤنٹ کے لیے خطرے کی بجائے ایک ناخوشگوار صبح ہوتی۔ دیوار نہیں بدلی۔ سائز نے کیا.</p>\n</div></div>\n<p>ایماندار ٹیک وے مستحکم ہے۔ ایکسچینج مارکیٹ کو منظم رکھنے اور ایک برے لمحے کو افراتفری کی طرف بڑھنے سے روکنے کے لیے یہ حدود بناتا ہے، اور یہ زیادہ تر وقت آپ کی حفاظت کرتے ہیں۔ لیکن بہت ہی طریقہ کار جو گھبراہٹ کو پرسکون کرتا ہے، بینڈ اور رک جانا، وہ چیز بھی ہے جو آپ کو باہر نکلنے پر مہر لگا کر نقصان میں رکھ سکتی ہے۔ اپنے آرڈرز کو دیواروں کے اندر رکھیں، اپنے سائز کو اتنا چھوٹا رکھیں کہ بند بازار مہلک ہونے کی بجائے غیر آرام دہ ہو، اور کبھی بھی اس طرح تجارت نہ کریں جیسے سٹاپ ایک ضمانت ہے۔ غیر معمولی دن جب دیواریں بند ہوتی ہیں، تاجر جس نے پہلے ہی یہ فرض کر لیا تھا کہ وہ دوبارہ کھلنے پر بھی وہی کھڑا ہے۔</p>\n","toc":[{"level":2,"text":"روزانہ کی قیمت کا بینڈ","id":"the-daily-price-band"},{"level":2,"text":"آپ کا فیوچر آرڈر کیوں مسترد ہو جاتا ہے۔","id":"why-your-futures-order-gets-rejected"},{"level":2,"text":"ڈائنامک پرائس بینڈز: F&O وال کیسے جھکتی ہے۔","id":"dynamic-price-bands-how-the-f-o-wall-bends"},{"level":2,"text":"انڈیکس سرکٹ بریکرز: پوری مارکیٹ کو روکنا","id":"index-circuit-breakers-halting-the-whole-market"},{"level":2,"text":"جب کوئی بینڈ یا روک آپ کو پھنساتا ہے۔","id":"when-a-band-or-a-halt-traps-you"},{"level":2,"text":"حد کے قریب تجارت","id":"trading-near-the-limits"}],"imgCount":2,"hasContent":true},"23":{"html":"<p>تصور کریں کہ آپ نے حصص کا ایک پورٹ فولیو بنانے میں برسوں گزارے ہیں جن پر آپ یقین رکھتے ہیں۔ آپ طویل عرصے تک ان کے مالک ہونے پر خوش ہیں۔ لیکن آپ خبریں پڑھتے ہیں اور آپ گھبرا جاتے ہیں۔ ہو سکتا ہے بجٹ آ رہا ہو، یا عالمی سطح پر ہلچل ہو، اور آپ کو شبہ ہے کہ اگلے مہینے میں پوری مارکیٹ دس فیصد گر سکتی ہے۔ آپ اپنے حصص کو فروخت نہیں کرنا چاہتے، کیونکہ فروخت کا مطلب ہے ٹیکس، اخراجات، اور زیادہ واپس خریدنے کا خطرہ۔ پھر بھی آپ بیٹھ کر اپنی دولت کا دسواں حصہ بخارات بنتے دیکھنا نہیں چاہتے۔ ایک تیسرا آپشن ہے، اور یہی وجہ ہے کہ فیوچر پہلی جگہ ایجاد ہوئے۔ آپ کر سکتے ہیں۔ <strong>ہیج</strong>.</p>\n<p>ہیجنگ ایک فیوچر پوزیشن کا استعمال کر رہی ہے اس چیز کو بچانے کے لیے جو آپ کے پاس پہلے سے ہے قیمت میں کمی سے۔ یہ فیوچر مارکیٹ کا اصل، سنجیدہ مقصد ہے، جو تمام قیاس آرائیوں سے پرانا ہے، اور اسے سمجھنے سے یہ بدل جائے گا کہ آپ پورے آلے کو کس طرح دیکھتے ہیں۔ مستقبل صرف شرط لگانے کا ایک طریقہ نہیں ہے۔ یہ تحفظ خریدنے کا ایک طریقہ بھی ہے۔</p>\n<h2 id=\"the-original-job-of-a-future\">مستقبل کا اصل کام</h2>\n<p>تاجروں کے قیاس آرائیوں کے لیے فیوچر کا استعمال کرنے سے بہت پہلے، پروڈیوسر اور مالکان ان کا استعمال اس خطرے کو دور کرنے کے لیے کرتے تھے جو وہ نہیں چاہتے تھے۔ ایک کسان جسے فصل کی کٹائی سے پہلے قیمت میں کمی کا خدشہ تھا آج فروخت کی قیمت میں بند کر سکتا ہے۔ ایک مل جس کو قیمت میں اضافے کا خدشہ تھا وہ قیمت خرید میں بند ہو سکتی ہے۔ ہر ایک نے ایک ایسا خطرہ مول لیا جسے وہ اٹھانے کے لیے تیار کسی پر نہیں چاہتے تھے۔ یہ ہیجنگ ہے، اور یہ اب بھی مستقبل کا خالص ترین استعمال ہے۔</p>\n<p>ایک جدید سرمایہ کار کے لیے بھی یہی منطق لاگو ہوتی ہے۔ آپ کے پاس حصص کی ایک ٹوکری ہے۔ آپ کو مارکیٹ گرنے کا سامنا ہے۔ اے <strong>ہیج</strong> دوسری پوزیشن ہے، جب آپ کے حصص ہار جاتے ہیں تو جان بوجھ کر حاصل کرنے کے لیے ترتیب دی جاتی ہے، اس لیے دونوں تقریباً منسوخ ہو جاتے ہیں۔ آپ ہیج پر پیسہ کمانے کی کوشش نہیں کر رہے ہیں۔ آپ تکلیف دہ نتیجہ کو کم تکلیف دہ بنانے کی کوشش کر رہے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ہیج ایک فیوچر پوزیشن ہے جو آپ کے پاس پہلے سے موجود کسی چیز میں خطرے کو پورا کرنے کے لیے لی جاتی ہے۔ جب آپ کی ہولڈنگز گرتی ہیں تو ہیج حاصل ہوتا ہے، دھچکا نرم ہوتا ہے۔ اس کا کام تحفظ ہے، منافع نہیں۔</p>\n</div></div>\n<h2 id=\"shorting-an-index-future-to-protect-a-portfolio\">پورٹ فولیو کی حفاظت کے لیے انڈیکس مستقبل کو مختصر کرنا</h2>\n<p>شیئر پورٹ فولیو کے لیے سب سے زیادہ عام ہیج ہے۔ <strong>ایک انڈیکس مستقبل مختصر جاؤ</strong>. پچھلے ابواب سے یاد کریں کہ مختصر ہونے کا مطلب ہے کہ قیمت گرنے پر آپ کو فائدہ ہوتا ہے۔ اگر آپ NIFTY مستقبل بیچتے ہیں اور مارکیٹ گرتی ہے، تو اس مختصر پوزیشن میں فائدہ ہوتا ہے۔ اگر آپ کا متنوع پورٹ فولیو بھی مارکیٹ کے ساتھ آتا ہے، تو آپ کے حصص اسی وقت کھو جاتے ہیں۔ شارٹ پر فائدہ حصص پر ہونے والے نقصان کو پورا کرتا ہے۔ یہ سارا میکانزم ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-hedging.png\" alt=\"حصص کا ایک پورٹ فولیو ایک مختصر انڈیکس مستقبل کے ساتھ مل کر ایک محفوظ مقام پیدا کرتا ہے: جب مارکیٹ گرتی ہے، تو حصص پر ہونے والے نقصان کو مختصر مستقبل میں حاصل ہونے والے منافع سے پورا کیا جاتا ہے، جس سے کل قدر کو مستحکم کیا جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>حصص کا ایک پورٹ فولیو ایک مختصر انڈیکس مستقبل کے ساتھ مل کر ایک محفوظ مقام پیدا کرتا ہے: جب مارکیٹ گرتی ہے، تو حصص پر ہونے والے نقصان کو مختصر مستقبل میں حاصل ہونے والے منافع سے پورا کیا جاتا ہے، جس سے کل قدر کو مستحکم کیا جاتا ہے۔</figcaption></figure>\n<p>ایک کیوں استعمال کریں۔ <strong>انڈیکس مستقبل</strong> ہر اسٹاک کو مختصر کرنے کے بجائے؟ چونکہ ایک متنوع پورٹ فولیو وسیع مارکیٹ کے ساتھ آگے بڑھنے کا رجحان رکھتا ہے، لہذا ایک مائع انڈیکس مستقبل ایک ہی تجارت میں پوری ٹوکری کے مارکیٹ کے خطرے کو پورا کر سکتا ہے۔ آپ کو مختصر RELIANCE کی ضرورت نہیں ہے، پھر بینک، پھر باقی۔ آپ نے ایک NIFTY مستقبل مختصر کیا ہے اور آپ نے ایک ہی وقت میں ہر چیز کی عمومی مارکیٹ کی نمائش کا احاطہ کیا ہے۔ انڈیکس گہرا مائع اور نقدی پر مشتمل ہے، جو اسے اس کام کے لیے قدرتی آلہ بناتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ کے پاس تقریباً 16,00,000 روپے کا متنوع پورٹ فولیو ہے۔ قلیل مدتی کمی کے خوف سے، آپ ایک NIFTY مستقبل بیچتے ہیں۔ اگلے دو ہفتوں کے دوران مارکیٹ پانچ فیصد گر جائے گی۔ آپ کے شیئرز کا کاغذ پر تقریباً 80,000 روپے کا نقصان ہوتا ہے، لیکن آپ کے مختصر NIFTY مستقبل میں اتنی ہی رقم حاصل ہوتی ہے، اس لیے آپ کی کل دولت بمشکل منتقل ہوتی ہے۔ ہیج نے اپنا کام کیا۔</p>\n</div></div>\n<h2 id=\"beta-and-how-many-lots-to-short\">بیٹا اور کتنے لاٹ شارٹ</h2>\n<p>ایک ہیج کو اچھی طرح سے سائز کرنے کے لیے آپ کو ایک اور آئیڈیا کی ضرورت ہے، اور یہ سادہ الفاظ میں آسان ہے۔ <strong>بیٹا</strong> پیمائش کرتا ہے کہ آپ کا پورٹ فولیو انڈیکس کے مقابلے میں کتنا حرکت کرتا ہے۔ ایک کے بیٹا کا مطلب ہے کہ آپ کا پورٹ فولیو تقریباً NIFTY جیسا ہی چلتا ہے: اگر NIFTY دس فیصد گرتا ہے، تو آپ کا پورٹ فولیو تقریباً دس فیصد گر جاتا ہے۔ ایک سے اوپر کا بیٹا، 1.3 کہتے ہیں، کا مطلب ہے کہ آپ کا پورٹ فولیو انڈیکس سے زیادہ اچھلتا ہے اور زیادہ گرتا ہے۔ ایک سے نیچے بیٹا، 0.7 کہتے ہیں، اس کا مطلب ہے کہ یہ پرسکون ہے اور کم گرتا ہے۔</p>\n<p>بیٹا آپ کو بتاتا ہے کہ آپ کو درحقیقت کتنے انڈیکس تحفظ کی ضرورت ہے۔ ایک تیز، اعلی بیٹا پورٹ فولیو کو اس کی سادہ روپے کی قدر سے زیادہ بڑے ہیج کی ضرورت ہوتی ہے، کیونکہ یہ انڈیکس سے زیادہ مشکل ہوتا ہے۔ ایک پرسکون، کم بیٹا پورٹ فولیو کو چھوٹے ہیج کی ضرورت ہوتی ہے۔</p>\n<p>دی <strong>ہیج تناسب</strong> کیا صرف ایک سوال کا سادہ زبان میں جواب ہے: کتنے انڈیکس لاٹ میری ہولڈنگز کے مارکیٹ کے خطرے سے تقریباً مماثل ہیں؟ آپ اسے تین مراحل میں تیار کرتے ہیں، کسی فارمولے کی ضرورت نہیں ہے۔</p>\n<ul>\n<li>اس پورٹ فولیو کی کل قیمت سے شروع کریں جس کی آپ حفاظت کرنا چاہتے ہیں۔</li>\n<li>اسے بیٹا کے لیے ایڈجسٹ کریں: اگر آپ کا پورٹ فولیو انڈیکس سے زیادہ جمپیر ہے تو اس کی پیمائش کریں، اگر یہ پرسکون ہو تو نیچے کریں۔</li>\n<li>لاٹوں کی تعداد حاصل کرنے کے لیے ایک انڈیکس فیوچر کنٹریکٹ کی روپے کی قدر سے اس ایڈجسٹ ویلیو کو تقسیم کریں۔</li>\n</ul>\n<p>اس پر نمبر لگائیں۔ فرض کریں کہ آپ کے پورٹ فولیو کی قیمت ایک کے قریب بیٹا کے ساتھ تقریباً 15,60,000 روپے ہے، اور NIFTY 24,000 کے قریب تجارت کرتا ہے، تو ایک NIFTY بہت سے <strong>65</strong> تقریباً 24,000 گنا 65 کو کنٹرول کرتا ہے جو کہ تقریباً 15,60,000 روپے ہے۔ آپ کے پورٹ فولیو کی قیمت اور ایک معاہدے کی قدر تقریباً یکساں ہے، اور بیٹا تقریباً ایک ہے، اس لیے کسی ایک NIFTY کو مختصر کرنا مستقبل میں آپ کو اچھی طرح سے بچاتا ہے۔ اگر آپ کا پورٹ فولیو دو گنا بڑا ہوتا تو آپ دو لاٹوں کو مختصر کرتے۔ اگر اس کا بیٹا 1.5 تھا، تو آپ کو سادہ قیمت سے زیادہ انڈیکس کی نمائش کی ضرورت ہوگی، لہذا آپ اگلے لاٹ تک پہنچ سکتے ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>بیٹا یہ ہے کہ آپ کا پورٹ فولیو انڈیکس کے مقابلے میں کتنا حرکت کرتا ہے۔ ہیج ریشو اسے ایک عملی سوال کا جواب دینے کے لیے استعمال کرتا ہے: کتنے انڈیکس لاٹز میری ہولڈنگز کو تقریباً آفسیٹ کرتے ہیں؟ اعلی بیٹا کا مطلب ہے ایک بڑا ہیج؛ لوئر بیٹا کا مطلب ہے چھوٹا۔</p>\n</div></div>\n<h2 id=\"a-worked-example-hedging-a-rs-15-00-000-book\">کام کی مثال: 15,00,000 روپے کی کتاب کو ہیج کرنا</h2>\n<p>آئیے ہم اس تمام کو حقیقی نمبروں کے ساتھ کنکریٹ بنائیں، کیونکہ جب آپ اسے کام کرتے ہوئے دیکھتے ہیں تو ایک ہیج تجریدی محسوس کرنا بند کر دیتا ہے۔ فرض کریں کہ آپ کی ہولڈنگ بک کی قیمت ہے۔ <strong>15,00,000 روپے</strong>, بڑے، مانوس حصص میں پھیلے ہوئے، ایک کے قریب بیٹا کے ساتھ، اس لیے یہ وسیع مارکیٹ کے ساتھ تقریباً قدم بڑھاتا ہے۔ آپ برسوں تک ہر شیئر کے مالک ہونے پر راضی ہیں، لیکن ایک تناؤ والا پندرہ دن آگے ہے اور آپ بغیر فروخت کیے کور چاہتے ہیں۔</p>\n<p>سب سے پہلے، یہ معلوم کریں کہ آپ کو اصل میں کتنے انڈیکس کی ضرورت ہے۔ NIFTY قریب ٹریڈ کر رہا ہے۔ <strong>24,000</strong>، اور ایک NIFTY لاٹ ہے۔ <strong>65 یونٹس</strong>لہذا ایک معاہدہ تقریباً 24,000 گنا 65 ہے، جو کہ تقریباً ہے۔ <strong>15,60,000 روپے</strong> نمائش کے. اب ہیج ریشو کو صاف لفظوں میں چلائیں: جس قدر کو آپ محفوظ کرنا چاہتے ہیں، جو کہ 15,00,000 روپے ہے، اسے اپنے ایک کے بیٹا سے پیمانہ کریں، جو اسے 15,00,000 روپے کے قریب چھوڑ دیتا ہے، پھر ایک معاہدے کے 15,60,000 روپے سے تقسیم کریں۔ جواب صرف ایک لاٹ کے نیچے ہے۔ اس لیے ایک NIFTY مستقبل کو مختصر کرنا آپ کی کتاب کا احاطہ کرتا ہے، اور آپ کو ایک صاف تجارت کے ساتھ اچھی طرح سے ہیج کیا جاتا ہے۔</p>\n<p>اب دونوں نتائج کو اگلے دو ہفتوں میں آگے چلائیں، کیونکہ ایک ہیج صرف اس وقت سمجھ میں آتا ہے جب آپ دیکھیں کہ یہ ہر سمت میں کیا کرتا ہے۔</p>\n<p>اگر بازار گرتا ہے۔ <strong>پانچ فیصد</strong>، NIFTY تقریباً 1,200 پوائنٹس، 24,000 سے 22,800 تک سلائیڈ کرتا ہے۔ آپ کا پورٹ فولیو، ایک بیٹا کے ساتھ، 15,00,000 روپے کا تقریباً پانچ فیصد کھو دیتا ہے، جو کہ <strong>75,000 روپے</strong>. لیکن آپ کا مختصر NIFTY مستقبل 1,200 پوائنٹس گنا 65 حاصل کرتا ہے، جو کہ تقریباً <strong>78,000 روپے</strong>. دونوں اعداد و شمار تقریباً منسوخ ہو چکے ہیں، اس لیے مارکیٹ میں کمی کے دوران آپ کی دولت بمشکل کم ہوتی ہے۔ یہ وہ تحفظ ہے جس کے لیے آپ نے ادائیگی کی، بالکل اسی طرح کام کرنا جیسا کہ ڈیزائن کیا گیا ہے۔</p>\n<p>اگر اس کے بجائے مارکیٹ میں اضافہ ہوتا ہے۔ <strong>پانچ فیصد</strong>، NIFTY تقریباً 1,200 پوائنٹس سے 25,200 پر چڑھتا ہے۔ اب آپ کا پورٹ فولیو تقریباً بڑھتا ہے۔ <strong>75,000 روپے</strong>، جو بہت اچھا لگتا ہے، لیکن آپ کا مختصر مستقبل تقریباً 1,200 پوائنٹس گنا 65 کھو دیتا ہے، تقریباً <strong>78,000 روپے</strong>. ایک بار پھر دونوں نے تقریباً منسوخ کر دیا، اور اس بار ڈنک مارا: آپ نے ریلی واپس کر دی۔ یہاں ایک چھوٹی سی میز میں وہی کہانی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>مارکیٹ میں 5 فیصد اضافہ</th>\n<th>پورٹ فولیو (بیٹا 1)</th>\n<th>مختصر ایک NIFTY مستقبل</th>\n<th>مشترکہ نتیجہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>22,800 پر گرتا ہے۔</td>\n<td>تقریباً 75000 روپے کا نقصان ہوتا ہے۔</td>\n<td>تقریباً 78,000 روپے کا فائدہ</td>\n<td>تقریبا فلیٹ، آپ محفوظ ہیں</td>\n</tr>\n<tr>\n<td>25,200 تک بڑھ گیا۔</td>\n<td>تقریباً 75,000 روپے کا فائدہ</td>\n<td>تقریباً 78,000 روپے کا نقصان ہوتا ہے۔</td>\n<td>تقریباً فلیٹ، آپ نے الٹا چھوڑ دیا۔</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>15,00,000 روپے کی کتاب کے مقابلے میں ایک مختصر NIFTY آپ کی دولت میں تقریباً کوئی تبدیلی نہیں کرتا، مارکیٹ کے پانچ فیصد جھول، اوپر یا نیچے، بدل دیتا ہے۔ یہ ہم آہنگی پوری بات ہے۔ ہیج سمت کا انتخاب نہیں کرتا ہے۔ یہ صرف آپ کی کتاب سے مارکیٹ کی سمت کو ہٹا دیتا ہے جب تک کہ یہ آن ہے۔</p>\n</div></div>\n<p>غور کریں کہ مستقبل نے کیا کیا اور کیا نہیں کیا۔ اس سے آپ کو کچھ حاصل نہیں ہوا۔ یہ اس زوال کے لئے کھڑا تھا جس کا آپ کو خوف تھا اور، پوری انصاف کے ساتھ، وہ عروج بھی واپس آیا جس کی آپ کو امید تھی۔ اس لیے آپ کو صرف اس وقت ہیج لگانا چاہیے جب تجارت کے لیے کوئی وجہ ہو: کوئی معروف واقعہ جیسے کہ بجٹ یا نتیجہ جس سے آپ پیٹ نہیں سکتے، یا چھٹی کا طویل وقفہ جہاں مارکیٹ ہضم شدہ عالمی خبروں کے لیے دوبارہ کھل جاتی ہے اور آپ وقت پر ردعمل ظاہر نہیں کر سکتے۔ جب ایسا کوئی محرک نہیں ہوتا ہے اور آپ مارکیٹ کے عام اتار چڑھاو پر سوار ہونے پر راضی ہوتے ہیں جو سالوں میں اوپر کی طرف بڑھتا ہے، تو سب سے سستا اور عقلمند ہیج عام طور پر کوئی نہیں ہوتا ہے۔</p>\n<h2 id=\"what-the-hedge-costs-you-in-a-rally\">ایک ریلی میں ہیج آپ کو کیا قیمت دیتا ہے</h2>\n<p>یہ وہ حصہ ہے جو ابتدائی افراد اکثر کھو دیتے ہیں، اور یہ پورے خیال کا ایماندار مرکز ہے۔ ہیج صرف اس وقت آپ کی حفاظت نہیں کرتا جب مارکیٹ گرتی ہے۔ یہ بھی <strong>جب مارکیٹ میں اضافہ ہوتا ہے تو آپ کے فائدے کو محدود کرتا ہے۔</strong>. مختصر انڈیکس مستقبل جو آپ کو ایک ڈراپ میں ادائیگی کرتا ہے آپ کے حصص میں اضافے کو پورا کرتے ہوئے، ریلی میں پیسے کھو دے گا۔ آپ نے اپنے پورٹ فولیو کو تقریباً مارکیٹ سے غیرجانبدار بنا لیا ہے، جس کا مطلب ہے کہ آپ منفی پہلو سے محفوظ ہیں اور برابری کے ساتھ اوپر کی طرف پیچھے ہیں۔</p>\n<p>فرض کریں، آپ ہیج کرنے کے بعد، مارکیٹ گرنے کے بجائے پانچ فیصد چڑھ جاتی ہے۔ آپ کے حصص میں تقریباً 80,000 روپے کا فائدہ ہوتا ہے، جو کہ بہت اچھا ہے، لیکن آپ کا مختصر NIFTY مستقبل تقریباً اسی طرح کھو جائے گا، اس لیے آپ کا خالص فائدہ کم ہے۔ آپ نے زوال سے تحفظ کے بدلے ریلی ترک کر دی۔ یہاں کوئی مفت لنچ نہیں ہے۔ ایک ہیج کچھ منفی پہلو کو دور کرنے کے لئے کچھ الٹا تجارت کرتا ہے۔ بالکل وہی ہے جو انشورنس کرتا ہے۔</p>\n<p>ایک چھوٹی سی چلانے کی قیمت بھی ہے۔ شارٹ انڈیکس مستقبل میں رکھنے سے معمول کے اخراجات ہوتے ہیں، اور جیسا کہ آپ نے بنیاد کے ساتھ دیکھا، ایک مختصر پوزیشن کا لے جانے کی لاگت سے اپنا تعلق ہوتا ہے۔ وقت گزرنے کے ساتھ، ایک مستقل ہیج خاموشی سے واپسی پر گھسیٹتا ہے، یہی وجہ ہے کہ ہیجز عام طور پر عارضی ہوتے ہیں، ایک مخصوص پریشانی کے لیے لگ جاتے ہیں اور پریشانی ختم ہونے پر اتار دی جاتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک ہیج سڈول ہے. وہی مختصر مستقبل جو زوال کی وجہ سے ریلی میں آپ کے فوائد کو مٹا دے گا۔ اگر آپ ہیج اور بازار پھر چڑھتے ہیں، دھوکہ محسوس نہیں کرتے. آپ نے تحفظ کے لیے ادائیگی کی اور تحفظ کی قیمت آپ کو الٹا، بالکل اسی طرح ڈیزائن کی گئی ہے۔</p>\n</div></div>\n<h2 id=\"a-hedge-is-insurance-not-a-profit-machine\">ہیج انشورنس ہے، منافع کی مشین نہیں۔</h2>\n<p>یہ سب اپنے سر میں رکھنے کا سب سے صاف طریقہ یہ ہے کہ ہیج کے بارے میں سوچیں۔ <strong>انشورنس</strong> آپ کے پورٹ فولیو پر۔ آپ کسی گھر کی بیمہ اس لیے نہیں کرتے کہ آپ اس کے جل جانے کی توقع رکھتے ہیں بلکہ اس لیے کہ اگر ایسا ہوا تو آپ نقصان برداشت نہیں کر سکتے۔ پریمیم وہ رقم ہے جسے آپ ذہنی سکون کے لیے خرچ کرنے پر راضی ہیں۔ ایک ہیج اسی طرح کام کرتا ہے۔ آپ جو الٹا چھوڑ دیتے ہیں، اور چلنے والی چھوٹی لاگت، وہ پریمیم ہے جو آپ مارکیٹ میں کمی کو زندہ رکھنے کے لیے ادا کرتے ہیں۔</p>\n<p>یہ فریمنگ آپ کو یہ بھی بتاتی ہے کہ ہیج کیا نہیں ہے۔ یہ اضافی پیسہ کمانے کا طریقہ نہیں ہے۔ اگر آپ اپنے تمام پہلوؤں کو برقرار رکھتے ہوئے کریش سے فائدہ اٹھانے کی امید میں مستقبل کے اشاریہ کو مختصر کرتے ہیں، تو آپ اب ہیجنگ نہیں کر رہے ہیں، آپ دو پوزیشنوں کے ساتھ قیاس آرائیاں کر رہے ہیں۔ ایک حقیقی ہیج ایک ڈھکی ہوئی اوپر کی قیمت کو کشن والے نیچے کی قیمت کے طور پر قبول کرتا ہے۔ دونوں کو الجھانا یہ ہے کہ لوگ کس طرح اپنے آپ سے لاپرواہ تجارت میں بات کرتے ہیں اور انہیں ہوشیار کہتے ہیں۔</p>\n<h2 id=\"when-to-hedge-and-when-not-to\">کب ہیج کرنا ہے اور کب نہیں۔</h2>\n<p>ہیجنگ ایک ٹول ہے، عادت نہیں۔ اس تک مسلسل پہنچنا مہنگا اور بے معنی ہے، کیونکہ طویل عرصے کے دوران مارکیٹوں میں اضافہ ہوتا ہے اور ایک مستقل مختصر آپ کی واپسی کا خون بہا دیتا ہے۔ جان بوجھ کر استعمال کریں۔</p>\n<ul>\n<li>جب آپ کو کسی مخصوص، وقت کے پابند خطرے کا سامنا کرنا پڑتا ہے تو آپ حقیقی طور پر ڈرتے ہیں: ایک بڑا واقعہ، جس کے نتیجے میں آپ پیٹ نہیں کر سکتے، ایک ایسی مارکیٹ جو آپ کے خیال میں پھیلی ہوئی ہے، اور آپ اپنی ہولڈنگز فروخت کیے بغیر اس میں سوار ہونا چاہتے ہیں۔</li>\n<li>بنیادی حصص فروخت کرتے وقت ہیج کرنا ٹیکس یا طویل مدتی وجوہات کی بناء پر مہنگا یا ناپسندیدہ ہوگا، لہذا عارضی مستقبل ڈمپنگ اور دوبارہ خریدنے سے زیادہ صاف ہے۔</li>\n<li>مستقل طور پر ہیج نہ کریں، کیونکہ اوپر کی حد اور چلتی لاگت وقت کے ساتھ ساتھ آپ کے منافع کو کم کر دے گی۔</li>\n<li>اگر آپ ایمانداری سے اپنی پوزیشن کو کم کرنا چاہتے ہیں تو ہیج نہ کریں۔ بعض اوقات کچھ حصص بیچنا ہیج چلانے سے آسان اور سستا ہوتا ہے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ایک ہیج کو عارضی چھتری کے طور پر سمجھیں، مستقل چھت نہیں۔ اسے ایک مخصوص طوفان کے لیے لگائیں، بیٹا کے ساتھ اس کا سائز بنائیں تاکہ یہ درحقیقت آپ کے پورٹ فولیو کا احاطہ کرے، اور خطرہ گزر جانے کے بعد اسے اتار دیں۔ ہمیشہ کے لیے چھوڑ دیا، یہ خاموشی سے آپ کو اس ترقی کی قیمت ادا کرتا ہے جس کی آپ حفاظت کرنے کی کوشش کر رہے تھے۔</p>\n</div></div>\n<p>پائیدار سبق یہ ہے کہ مستقبل نے زندگی کا آغاز ایک ڈھال کے طور پر کیا، نہ کہ تلوار کے طور پر۔ آپ کے پاس پہلے سے موجود پورٹ فولیو کے خلاف مائع انڈیکس کے مستقبل کو مختصر کرکے، آپ ایک بھی حصہ بیچے بغیر مارکیٹ کے گرنے کے درد کو ختم کر سکتے ہیں۔ بیٹا کے ساتھ اس کا سائز بنائیں، قبول کریں کہ یہ آپ کے اوپری حصے کو اتنا ہی اچھالتا ہے جتنا کہ یہ آپ کے منفی پہلو کو بڑھاتا ہے، اور ہر وقت یاد رکھیں کہ ہیج انشورنس ہے۔ اس کا مقصد آپ کو امیر بنانا نہیں ہے۔ اس کا مقصد آپ کو سونے دینا ہے۔</p>\n","toc":[{"level":2,"text":"مستقبل کا اصل کام","id":"the-original-job-of-a-future"},{"level":2,"text":"پورٹ فولیو کی حفاظت کے لیے انڈیکس مستقبل کو مختصر کرنا","id":"shorting-an-index-future-to-protect-a-portfolio"},{"level":2,"text":"بیٹا اور کتنے لاٹ شارٹ","id":"beta-and-how-many-lots-to-short"},{"level":2,"text":"کام کی مثال: 15,00,000 روپے کی کتاب کو ہیج کرنا","id":"a-worked-example-hedging-a-rs-15-00-000-book"},{"level":2,"text":"ایک ریلی میں ہیج آپ کو کیا قیمت دیتا ہے","id":"what-the-hedge-costs-you-in-a-rally"},{"level":2,"text":"ہیج انشورنس ہے، منافع کی مشین نہیں۔","id":"a-hedge-is-insurance-not-a-profit-machine"},{"level":2,"text":"کب ہیج کرنا ہے اور کب نہیں۔","id":"when-to-hedge-and-when-not-to"}],"imgCount":1,"hasContent":true},"24":{"html":"<p>جدوجہد کرنے والے تاجروں سے پوچھیں کہ کیا غلط ہوا اور ان میں سے زیادہ تر خراب چارٹ یا گم شدہ سگنل کی طرف اشارہ نہیں کریں گے۔ وہ آپ کو بتائیں گے کہ وہ بہت بڑے تھے۔ انہوں نے اتنی بڑی پوزیشن پر رکھی کہ ایک عام جھولے نے ایک ماہ کے محتاط فوائد یا اس سے بھی بدتر، ان کے سرمائے کا ایک حصہ ضائع کر دیا۔ مستقبل میں بقا کی واحد سب سے اہم مہارت صحیح سمت کا انتخاب نہ کرنا ہے۔ یہ فیصلہ کر رہا ہے۔ <strong>کتنے لاٹ</strong> تجارت کرنے کے لیے، اور ایماندارانہ جواب تقریباً ہمیشہ آپ کی خواہش سے کم ہوتا ہے۔</p>\n<p>یہ باب اسی فیصلے کے بارے میں ہے۔ یہ گلیمرس نہیں ہے اور یہ کبھی بھی پرجوش محسوس نہیں کرے گا، یہی وجہ ہے کہ ابتدائی لوگ اسے کیوں چھوڑ دیتے ہیں اور بالکل کیوں اڑا دیتے ہیں۔ پوزیشن کا سائز درست کریں اور آپ بد قسمتی کے طویل دور سے بچ سکتے ہیں۔ اسے غلط سمجھیں اور یہاں تک کہ ایک اچھی حکمت عملی بھی آپ کو نہیں بچائے گی، کیونکہ آپ کھیل میں اتنی دیر تک نہیں رہیں گے کہ اچھی تجارت کو کام کرنے دیں۔</p>\n<h2 id=\"start-with-what-you-can-afford-to-lose\">اس سے شروع کریں جو آپ کھونے کے متحمل ہوسکتے ہیں۔</h2>\n<p>زیادہ تر ابتدائی لوگ غلط سوال پوچھ کر تجارت کا سائز بناتے ہیں۔ وہ پوچھتے ہیں، \"میں کتنے لاٹ خرید سکتا ہوں؟\" مارجن انہیں سستے میں آنے دیتا ہے، لہذا جواب بڑا محسوس ہوتا ہے، اور وہ اسے زیادہ سے زیادہ کر دیتے ہیں۔ صحیح سوال اس کے برعکس ہے۔ پوچھیں، \"اگر یہ تجارت میرے خلاف ہو تو میں کتنا کھونے کو تیار ہوں؟\" اس سے سائز بہتا ہے، اور صرف وہی۔</p>\n<p>پیشہ ور افراد جو طریقہ استعمال کرتے ہیں اسے کہا جاتا ہے۔ <strong>مقررہ جزوی خطرہ</strong>. اصول آسان ہے: کسی بھی ایک تجارت پر آپ کو عام طور پر اپنے تجارتی سرمائے کا صرف ایک چھوٹا، مقررہ حصہ خطرہ لاحق ہوتا ہے۔ <strong>1% سے 2%</strong>. مارجن کا 1% نہیں، معاہدے کی قیمت کا 1% نہیں، بلکہ کل رقم کا 1% جو آپ نے ٹریڈنگ کے لیے مختص کیا ہے۔ تجارتی سرمائے کے 5,00,000 روپے کے ساتھ، 1% رسک بجٹ 5,000 روپے ہے۔ یہ 5,000 روپے سب سے زیادہ ہے اگر آپ کا سٹاپ ہٹ جاتا ہے تو آپ اس ایک تجارت پر لاگت آئے گی۔ باقی سب ریاضی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>فکسڈ فریکشنل رسک کا مطلب ہے کہ کسی ایک تجارت پر اپنے سرمائے کا ایک چھوٹا سا مقررہ حصہ، 1% تا 2%، خطرے میں ڈالنا۔ پوزیشن کا سائز وہ ہے جو بھی رقم آپ کے اسٹاپ لاس کو اس بجٹ کے برابر بناتی ہے۔ آپ پہلے نقصان کا فیصلہ کریں، پھر قرعہ اندازی کریں۔</p>\n</div></div>\n<p>اتنا چھوٹا کیوں؟ کیونکہ نقصانات جھرمٹ میں آتے ہیں۔ یہاں تک کہ ایک اچھا تاجر بھی لگاتار پانچ یا چھ ہارے ہوئے لے سکتا ہے، اور یہ عام بات ہے، ناکامی نہیں۔ اگر ہر نقصان سرمائے کا 1% ہے، تو لگاتار چھ تقریباً 6% ہے، ایک ایسا زخم جس سے آپ ٹھیک ہو جاتے ہیں۔ اگر ہر نقصان 20% ہے کیونکہ آپ بڑے تھے، لگاتار دو اور آپ معذور ہیں۔ فی تجارت چھوٹا خطرہ وہ ہے جو آپ کو تجارت کو جاری رکھنے کے لیے کافی سرمائے اور کافی اعصاب کے ساتھ ناگزیر خراب سلسلے سے بچنے دیتا ہے۔</p>\n<h2 id=\"work-backward-from-the-stop\">اسٹاپ سے پیچھے کی طرف کام کریں۔</h2>\n<p>یہاں وہ حصہ ہے جو سائز کنکریٹ بناتا ہے۔ آپ تجارت کو اس وقت تک سائز نہیں دے سکتے جب تک کہ آپ کو معلوم نہ ہو کہ اگر آپ غلط ہیں تو آپ کہاں سے نکلیں گے۔ وہ باہر نکلنا آپ کا ہے۔ <strong>فاصلہ بند کرو</strong>آپ کے داخلے اور قیمت کے درمیان پوائنٹس کی تعداد جس پر آپ تسلیم کرتے ہیں کہ تجارت ناکام ہو گئی ہے۔ اسٹاپ پہلے آتا ہے۔ اس سے سائز کا حساب لگایا جاتا ہے۔</p>\n<p>استدلال کا سلسلہ تین سادہ مراحل میں چلتا ہے:</p>\n<ul>\n<li>پوائنٹس میں اپنے اسٹاپ کا فاصلہ طے کریں۔ یہ چارٹ اور آپ کے منصوبے سے آتا ہے، اس سے نہیں کہ آپ کتنا خطرہ مول لینا چاہتے ہیں۔</li>\n<li>اسے ایک لاٹ کے روپے کے نقصان میں تبدیل کریں: خطرے کے پوائنٹس کو روپے فی پوائنٹ فی لاٹ سے ضرب۔</li>\n<li>اپنے خطرے کے بجٹ کو اس ایک لاٹ نقصان سے تقسیم کریں۔ نتیجہ، گول نیچے، یہ ہے کہ آپ کتنے لاٹ لے سکتے ہیں۔</li>\n</ul>\n<p>یہ سارا انجن ہے۔ نوٹ کریں کہ وسیع سٹاپ کا مطلب ہے فی لاٹ بڑا نقصان، جس کا مطلب ہے کم لاٹ۔ ایک سخت سٹاپ اسی بجٹ کے لیے مزید لاٹوں کی اجازت دیتا ہے۔ آپ کا سائز ایک مقررہ عادت نہیں ہے۔ یہ ہر تجارت کے ساتھ بدلتا ہے اس پر منحصر ہے کہ سمجھدار اخراج کہاں بیٹھتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-position-sizing.png\" alt=\"پوزیشن کی سائزنگ نے اسٹاپ سے پیچھے کی طرف کام کیا: تاجر ایک چھوٹا خطرہ بجٹ طے کرتا ہے، سٹاپ کے فاصلے سے ایک لاٹ کے روپے کے نقصان کی پیمائش کرتا ہے، اور یہ معلوم کرنے کے لیے تقسیم کرتا ہے کہ کتنے لاٹ فٹ ہیں، جو اکثر صرف ایک ہوتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>پوزیشن کی سائزنگ نے اسٹاپ سے پیچھے کی طرف کام کیا: تاجر ایک چھوٹا خطرہ بجٹ طے کرتا ہے، سٹاپ کے فاصلے سے ایک لاٹ کے روپے کے نقصان کی پیمائش کرتا ہے، اور یہ معلوم کرنے کے لیے تقسیم کرتا ہے کہ کتنے لاٹ فٹ ہیں، جو اکثر صرف ایک ہوتی ہے۔</figcaption></figure>\n<h2 id=\"a-clean-nifty-example\">ایک صاف NIFTY مثال</h2>\n<p>اس پر حقیقی نمبر لگائیں۔ آپ کے پاس سرمایہ 5,00,000 روپے ہے، لہذا آپ کا 1% بجٹ 5,000 روپے ہے۔ آپ 24,000 کے قریب NIFTY مستقبل کی ٹریڈنگ کو طویل کرنا چاہتے ہیں، جہاں ہر ایک پوائنٹ کی قیمت ہے۔ <strong>65 روپے</strong> بہت آپ کا پلان کہتا ہے کہ اگر مستقبل آپ کے خلاف 30 پوائنٹس گرتا ہے تو آپ باہر نکل جائیں گے، لہذا آپ کے اسٹاپ کا فاصلہ 30 پوائنٹس ہے۔</p>\n<p>ایک لاٹ پر نقصان اگر سٹاپ مارا جائے تو 30 پوائنٹس گنا 65 روپے، جو کہ تقریباً ہے۔ <strong>1,950 روپے</strong>. وہ ایک لاٹ پہلے ہی آپ کے 5,000 روپے کے بجٹ کا تقریباً چالیس فیصد کھاتا ہے۔ اب تقسیم کریں: 5,000 روپے کو 1,950 روپے سے تقسیم کیا جائے تو تقریباً ڈھائی ہے۔ آپ کبھی گول نہیں کرتے، صرف نیچے، لہذا خام ریاضی دو لاٹوں کی طرف اشارہ کرتا ہے۔ لیکن دو لاٹ یہاں پر سمجھدار جواب نہیں ہے، اور یہ وہ جگہ ہے جہاں محتاط تاجر اپنے آپ کو لاپرواہ لوگوں سے الگ کرتے ہیں۔</p>\n<p>ایک سٹاپ ایک منصوبہ ہے، ضمانت نہیں ہے. ایک تیز مارکیٹ میں مستقبل آپ کی سطح سے سیدھا چھلانگ لگا سکتا ہے اور آپ کو 30 پوائنٹس سے بھی بدتر کر سکتا ہے، یہ مسئلہ آپ کو اگلے باب میں خلا اور واقعہ کے خطرے کے بارے میں مناسب طریقے سے پورا کریں گے۔ اس کے اوپری حصے میں، ہر راؤنڈ ٹرپ کے حقیقی اخراجات ہوتے ہیں، اور جیسا کہ ایک پہلے باب میں دکھایا گیا ہے، ایک NIFTY لاٹ کی خرید و فروخت کی قیمت تقریباً 929 روپے ہے اس سے پہلے کہ آپ ایک پیسہ کمائیں۔ دو لاٹ کا مطلب ہے لاگت دوگنا اور اگر سٹاپ سلپ ہو جائے تو پھسلن کو دوگنا کر دیں۔ ایک بار جب آپ ان حقیقتوں کو 5,000 روپے کی لائن میں جوڑ دیتے ہیں، تو دوسرا لاٹ خاموشی سے آپ کے بجٹ سے گزرنے والی بدترین صورتحال کو آگے بڑھا دیتا ہے۔ تو تم لے لو <strong>ایک بہت</strong>. کلین نمبر نے کہا کہ ڈھائی; ایمانداری اور حفاظت کا مارجن ایک کہتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ لاٹ کاؤنٹ ڈاؤن کریں، کبھی اوپر نہ جائیں، اور پھر پوچھیں کہ کیا لاگت اور ممکنہ پھسلنے والے اسٹاپ نے پہلے ہی آپ کا بفر کھا لیا ہے۔ اگر ان کے پاس ہے تو ایک اور لاٹ چھوڑ دیں۔ وہ تاجر جو مصروف محسوس کرنے کے لیے چکر لگاتا ہے وہی تاجر ہوتا ہے جو کام کرتا ہے۔</p>\n</div></div>\n<h2 id=\"size-by-the-contract-never-by-the-margin\">معاہدے کے مطابق سائز، کبھی مارجن سے نہیں۔</h2>\n<p>یہ وہ جال ہے جو چھوٹے اکاؤنٹس کو تباہ کر دیتا ہے، اس لیے اسے دو بار پڑھیں۔ مارجن ایک چھوٹا سا ڈپازٹ ہے جو آپ کو پوزیشن کھولنے دیتا ہے۔ یہ آپ کا خطرہ نہیں ہے۔ آپ کا خطرہ مکمل معاہدے کی قیمت اور آپ کے نقصان کے سائز سے طے ہوتا ہے اگر تجارت آپ کے خلاف ہوتی ہے۔</p>\n<p>24,000 کے قریب ایک NIFTY انڈیکس ایکسپوزر کے تقریباً 15,60,000 روپے کو کنٹرول کرتا ہے، پھر بھی اسے رکھنے کا مارجن اس کا صرف ایک حصہ ہوسکتا ہے۔ ایک RELIANCE لاٹ پر <strong>1,318 روپے</strong> 500 شیئرز ہیں، تقریباً 6,59,000 روپے کا اسٹاک، اور مارجن بہت کم ہے۔ ایک بار جب آپ اسے دیکھ لیں تو خطرہ واضح ہے۔ اگر آپ مارجن کے حساب سے سائز کرتے ہیں، تو آپ سرمایہ کے 5,00,000 روپے کو دیکھتے ہیں، دیکھیں کہ ایک RELIANCE لاٹ کو شاید ایک لاکھ مارجن کی ضرورت ہے، اور نتیجہ اخذ کریں کہ آپ پانچ لاٹ رکھ سکتے ہیں۔ پانچ لاٹوں کی قیمت پانچ لاکھ کے سرمائے پر سواری کے تیس لاکھ سے زیادہ ہے۔ اس کتاب اور اکاؤنٹ پر ایک برا فرق ختم ہو گیا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کبھی بھی کسی پوزیشن کو مارجن سے سائز نہ کریں جو آپ کو اندر آنے دیتا ہے۔ مارجن ایک ڈپازٹ ہے، خطرے کا پیمانہ نہیں۔ مکمل معاہدے کی قیمت اور روپے کے نقصان کے حساب سے سائز آپ کے سٹاپ کا مطلب ہے۔ مارجن کی سائزنگ وہ واحد سب سے عام طریقہ ہے جو ابتدائی افراد لیوریجڈ اکاؤنٹ کو تمباکو نوشی کے سوراخ میں بدل دیتے ہیں۔</p>\n</div></div>\n<p>ایک ہی پسماندہ طریقہ اسٹاک کے مستقبل پر کام کرتا ہے، اور یہ آپ کو دکھاتا ہے کہ سنگل اسٹاک احترام کا مطالبہ کیوں کرتے ہیں۔ RELIANCE ہر ایک روپے کی قیمت کے لیے 500 روپے کو بہت زیادہ منتقل کرتا ہے، اس لیے ہر ایک پوائنٹ بھاری ہے۔ فرض کریں کہ آپ ایک RELIANCE لمبے 8 روپے گرنے پر باہر نکلیں گے۔ یعنی 8 گنا 500 روپے کا نقصان <strong>4,000 روپے</strong> ایک ہی لاٹ پر، جو آپ کے 5000 روپے کے بجٹ کا اسی فیصد پہلے ہی نگل جاتا ہے۔ ایک لاٹ آپ کی مطلق حد ہے، اور بمشکل۔ سٹاپ کو مزید حقیقت پسندانہ 12 روپے تک پھیلائیں اور ایک لاٹ میں 6,000 روپے کا خطرہ ہے، جو بجٹ کی مکمل خلاف ورزی کرتا ہے۔ ایماندارانہ مطالعہ یہ ہے کہ اس سرمائے اور اس اسٹاپ کے ساتھ، ایک RELIANCE مستقبل بہت بڑا ہوسکتا ہے، اور صحیح تجارت کوئی تجارت نہیں ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>5,00,000 روپے والا تاجر 10 روپے کے سٹاپ کے ساتھ ایک RELIANCE مستقبل مختصر کرنا چاہتا ہے۔ دس روپے گنا 500 شیئرز 5000 روپے ہیں، بالکل ایک لاٹ کے لیے پورا 1% بجٹ۔ دوسری لاٹ کی کوئی گنجائش نہیں ہے اور نہ ہی سٹاپ کے پھسلنے کی گنجائش ہے۔ سائز سازی کی ریاضی تاجر کو واضح طور پر بتا رہی ہے کہ یہ اکاؤنٹ سب سے زیادہ ایک لاٹ لے سکتا ہے، اور یہاں تک کہ اس میں کوئی کمی نہیں ہے۔</p>\n</div></div>\n<h2 id=\"the-one-lot-reality\">ایک ہی حقیقت</h2>\n<p>ابتدائی افراد اکثر یہ محسوس کرتے ہیں کہ ایک لاٹ کی تجارت کرنا کسی طرح حقیقی تجارت نہیں ہے، کہ سنجیدہ لوگ دس تجارت کرتے ہیں۔ اوپر والا ریاضی اس کے برعکس کہتا ہے۔ بہت سے چھوٹے اکاؤنٹس کے لیے ایک لاٹ پہلے سے ہی زیادہ سے زیادہ ہوشیار سائز ہے، اور سخت سرمائے یا وسیع اسٹاپ پر ایک لاٹ بہت زیادہ ہو سکتا ہے۔ ایک لاٹ کی تجارت میں کوئی شرم نہیں ہے۔ ٹریڈنگ فائیو میں بہت زیادہ شرم اور حقیقی درد ہے کیونکہ مارجن نے اس کی اجازت دی ہے۔</p>\n<p>ایک سنگل لاٹ، جس کا سائز صحیح ہے اور ایک اسٹاپ کے ساتھ محفوظ ہے، ایک مکمل اور قابل احترام پوزیشن ہے۔ یہ آپ کو کھیل میں رکھتا ہے، آپ کو بقایا قیمت پر حقیقی رقم کے ساتھ سیکھنے دیتا ہے، اور جیسے جیسے آپ کا سرمایہ بڑھتا ہے قدرتی طور پر بڑھتا ہے۔ جو تاجر صبر کے ساتھ ایک لاٹ کو ملاتا ہے وہ دس جھولنے اور دھماکہ کرنے والے سے آگے نکل جائے گا۔</p>\n<h2 id=\"intraday-or-positional\">انٹرا ڈے یا پوزیشنل</h2>\n<p>آپ کتنی دیر تک پوزیشن پر فائز رہتے ہیں سائزنگ گفتگو کو بھی بدل دیتا ہے۔ ایک <strong>انٹرا ڈے</strong> تجارت کو قریب سے مربع کر دیا جاتا ہے، لہذا آپ کبھی بھی رات کے وقفے کو نہیں اٹھاتے، اور مارجن اکثر ہلکا ہوتا ہے۔ یہ زیادہ محفوظ لگتا ہے، اور یہ خطرے کے فرق پر ہے، لیکن اس کا اپنا جال ہے: سستی، بار بار تجارت آپ کو اوور ٹریڈ کرنے پر آمادہ کرتی ہے، معمولی سیٹ اپ لیتے ہیں اور بار بار اخراجات ادا کرتے ہیں یہاں تک کہ آپ کی کالز ٹھیک ہونے پر بھی اکاؤنٹ سے خون نہ نکل جائے۔</p>\n<p>اے <strong>پوزیشنی</strong> تجارت راتوں رات یا دنوں تک ہوتی ہے۔ اسے پورے مارجن کی ضرورت ہے، نہ کہ ہلکی انٹرا ڈے رقم کی، اور اس میں فرق اور ایونٹ کا خطرہ ہوتا ہے جس کا آپ اگلا مطالعہ کریں گے، جہاں مارکیٹ بند ہونے کے دوران کوئی پوزیشن آپ کے خلاف چھلانگ لگا سکتی ہے اور ایک سٹاپ آپ کی حفاظت نہیں کر سکتا۔ اس لیے پوزیشنی تجارت ایک وسیع منصوبہ اور عام طور پر چھوٹے سائز کے مستحق ہوتے ہیں، کیونکہ بدترین صورت بڑی اور کم قابل کنٹرول ہوتی ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>انٹرا ڈے رات بھر کے وقفے سے گریز کرتا ہے لیکن اوور ٹریڈنگ کو آزماتا ہے، اس لیے اپنی تجارت کی تعداد کی حفاظت کریں۔ پوزیشن کو مکمل مارجن کی ضرورت ہوتی ہے اور اس خلا سے بچ جاتا ہے جسے آپ کنٹرول نہیں کر سکتے، اس لیے اپنے سائز کی حفاظت کریں اور اسے چھوٹا رکھیں۔ ایک ہی ساز، دو مختلف مضامین۔</p>\n</div></div>\n<p>ٹیک وے ایک ہی وقت میں کند اور آزاد ہے۔ کسی ایک چارٹ کو دیکھنے سے پہلے اپنے خطرے کے بجٹ کا فیصلہ کریں، اپنا سٹاپ تلاش کریں، لاٹوں پر پیچھے کی طرف کام کریں، راؤنڈ ڈاون کریں، اور جواب کا احترام کریں چاہے وہ ایک یا کوئی بھی نہ ہو۔ سائز وہ لیور ہے جو آپ کو مہارت کے لیے کافی دیر تک زندہ رکھتا ہے۔</p>\n","toc":[{"level":2,"text":"اس سے شروع کریں جو آپ کھونے کے متحمل ہوسکتے ہیں۔","id":"start-with-what-you-can-afford-to-lose"},{"level":2,"text":"اسٹاپ سے پیچھے کی طرف کام کریں۔","id":"work-backward-from-the-stop"},{"level":2,"text":"ایک صاف NIFTY مثال","id":"a-clean-nifty-example"},{"level":2,"text":"معاہدے کے مطابق سائز، کبھی مارجن سے نہیں۔","id":"size-by-the-contract-never-by-the-margin"},{"level":2,"text":"ایک ہی حقیقت","id":"the-one-lot-reality"},{"level":2,"text":"انٹرا ڈے یا پوزیشنل","id":"intraday-or-positional"}],"imgCount":1,"hasContent":true},"25":{"html":"<p>آپ تقریباً سب کچھ ٹھیک کر سکتے ہیں۔ آپ سمت کو اچھی طرح سے چن سکتے ہیں، ایک سمجھدار سٹاپ لاس کو بالکل وہی جگہ رکھ سکتے ہیں جہاں چارٹ کہتا ہے کہ اس کا تعلق ہے، اور پوزیشن کو سائز دیں تاکہ عام نقصان چھوٹا ہو اور اس کی بازیافت ہو سکے۔ پھر تم سو جاؤ۔ اور جب آپ سوتے ہیں، دنیا کے دوسری طرف یا ایک پریس ریلیز میں، کچھ ہوتا ہے۔ اگلی صبح جب بازار دوبارہ کھلتا ہے تو مستقبل اس جگہ سے چند روپے دور نہیں ہوتا جہاں سے آپ نے اسے چھوڑا تھا۔ یہ بہت دور ہے، اور درمیان میں تجارت کا کوئی موقع نہیں تھا۔ یہ ایک خطرہ ہے جو صرف اس وقت ظاہر ہوتا ہے جب آپ راتوں رات فیوچر پوزیشن لے جاتے ہیں، اور اس نے کسی بھی خراب چارٹ پیٹرن سے زیادہ لیوریجڈ اکاؤنٹس کو ختم کر دیا ہے۔ اسے گیپ رسک کہا جاتا ہے، اور جو واقعہ اس کا سبب بنتا ہے وہ اس کا قریبی کزن، واقعہ کا خطرہ ہے۔</p>\n<p>یہ باب دونوں کے بارے میں ہے، اور اس غیر آرام دہ سچائی کے بارے میں کہ جس پر آپ نے بھروسہ کیا ہے وہ ہمیشہ وہی نہیں کرتا جو آپ کے خیال میں ہوتا ہے۔</p>\n<h2 id=\"when-the-market-is-shut-but-the-world-is-not\">جب بازار بند ہو لیکن دنیا بند نہ ہو۔</h2>\n<p>فیوچر مارکیٹ دن کے صرف ایک حصے کے لیے کھلی رہتی ہے۔ دنیا ہر وقت کھلی رہتی ہے۔ کمپنی کے نتائج کا اعلان بند ہونے کے بعد کیا جاتا ہے۔ بیرون ملک مرکزی بینک شرحوں کا فیصلہ کرتے ہیں جب ہندوستان سوتا ہے۔ عالمی منڈیاں راتوں رات گرتی ہیں، بجٹ پڑھا جاتا ہے، ایک RBI فیصلہ آتا ہے، انتخابی نتیجہ شمار ہوتا ہے۔ ان میں سے ہر ایک آپ کے مستقبل کی قیمت کو منتقل کر سکتا ہے، اور تقریباً سبھی ایسے ہوتے ہیں جب آپ تجارت نہیں کر سکتے۔</p>\n<p>جب مارکیٹ دوبارہ کھلتی ہے، تو قیمت کل کی نئی سطح کے قریب سے آسانی سے نہیں بڑھتی ہے۔ یہ <strong>خلا</strong>چارٹ پر خالی جگہ کے ساتھ تیزی سے اوپر یا نیچے کھولنا جہاں کوئی ٹریڈنگ نہیں ہوئی۔ اگر RELIANCE پر بند ہوتا ہے۔ <strong>1,318 روپے</strong> اور مایوس کن نتیجہ گھنٹوں کے بعد نکلتا ہے، اسٹاک اگلے سیشن کو 1,250، یا 1,210 پر کھول سکتا ہے، جس کے درمیان کچھ بھی نہیں ہوا۔ آپ کو 1,300، یا 1,280، یا راستے میں کہیں بھی ردعمل کا موقع نہیں ملا۔ پہلی قیمت جس پر آپ عمل کر سکتے تھے وہ ہے گیپڈ اوپن قیمت۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/chart-reliance-daily.png\" alt=\"ایک حقیقی RELIANCE روزانہ چارٹ۔ ان سیشنز کو دیکھیں جہاں ایک موم بتی پچھلے بند کے اوپر یا نیچے واضح عمودی خلا کے ساتھ کھلتی ہے، ان کے درمیان کوئی اوورلیپ نہیں ہوتا ہے۔ وہ خالی جگہ قیمت ہے جو مارکیٹ میں راتوں رات اچھل پڑی ہے، جس میں ہولڈر کے لیے اس کے اندر تجارت کرنے کا کوئی موقع نہیں ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایک حقیقی RELIANCE روزانہ چارٹ۔ ان سیشنز کو دیکھیں جہاں ایک موم بتی پچھلے بند کے اوپر یا نیچے واضح عمودی خلا کے ساتھ کھلتی ہے، ان کے درمیان کوئی اوورلیپ نہیں ہوتا ہے۔ وہ خالی جگہ قیمت ہے جس میں مارکیٹ راتوں رات اچھل پڑی ہے، جس میں ہولڈر کے لیے اس کے اندر تجارت کرنے کا کوئی موقع نہیں ہے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک فرق مارکیٹ کی قیمتوں کی ایک حد سے زیادہ چھلانگ ہے جب اسے بند کیا گیا تھا۔ آپ فرق کے اندر تجارت نہیں کر سکتے۔ آپ کے لیے دستیاب پہلی قیمت وہ ہے جہاں مستقبل دوبارہ کھلتا ہے، چاہے آپ نے اسے آخری بار دیکھا تھا۔</p>\n</div></div>\n<h2 id=\"a-stop-loss-does-not-promise-you-a-price\">سٹاپ نقصان آپ سے قیمت کا وعدہ نہیں کرتا ہے۔</h2>\n<p>یہ وہ حصہ ہے جو ابتدائیوں کو حیران کر دیتا ہے، اور یہ اس باب میں سب سے اہم خیال ہے۔ اسٹاپ لاس اس قیمت کی ضمانت نہیں دیتا جس پر آپ باہر نکلتے ہیں۔ یہ صرف اس بات کی ضمانت دیتا ہے کہ قیمت آپ کی سطح تک پہنچنے کے بعد آرڈر بھیجا جائے گا۔</p>\n<p>اس بارے میں سوچیں کہ سٹاپ دراصل کیسے کام کرتا ہے۔ آپ نے اپنے RELIANCE پر 1,290 پر ایک اسٹاپ لاس سیٹ کیا۔ معاہدہ آسان ہے: اگر قیمت 1,290 تک گر جاتی ہے، تو آپ کے ایگزٹ آرڈر کو متحرک کرکے مارکیٹ میں بھیج دیا جاتا ہے۔ ایک عام دن، اسٹاک کے 1,300, 1,295, 1,291 تک آسانی سے نیچے آنے کے ساتھ، آپ کا آرڈر 1,290 پر آتا ہے اور آپ اس کے قریب یا اس کے قریب بھر جاتے ہیں۔ اسٹاپ نے اپنا کام کیا۔</p>\n<p>اب ایک خلا شامل کریں۔ اسٹاک 1,318 پر بند ہوتا ہے، خوفناک خبریں راتوں رات بریک ہوتی ہیں، اور مستقبل اگلی صبح 1,250 پر کھلتا ہے۔ آپ کا سٹاپ لیول 1,290 کبھی ٹریڈ نہیں ہوا۔ قیمت نیچے جاتے ہوئے اس سے نہیں گزری۔ اس نے اس پر صاف چھلانگ لگائی۔ جیسے ہی مارکیٹ 1,250 پر کھلتی ہے، آپ کا اسٹاپ متحرک ہوجاتا ہے، کیونکہ قیمت اب 1,290 سے نیچے ہے، اور آپ کا آرڈر <strong>اگلی دستیاب قیمت</strong>جو کہ تقریباً 1,250 ہے۔ 1,290 نہیں۔ آپ نے 28 پوائنٹس کھونے کا منصوبہ بنایا اور آپ نے 68 کھوئے، کیونکہ قیمت آپ کے سٹاپ کے ذریعے سیدھی ہوگئی۔</p>\n<p>یہی وجہ ہے کہ سٹاپ لاس عام چالوں کے خلاف تحفظ ہے، خلا کے خلاف نہیں۔ ایک عام انٹرا ڈے سلائیڈ پر یہ آپ کے نقصان کو اس کے قریب رکھتا ہے جہاں آپ نے منصوبہ بنایا تھا۔ رات بھر کے وقفے کے دوران اسے مکمل طور پر چھوڑا جا سکتا ہے، اور جہاں بھی مارکیٹ دوبارہ کھلنے کا انتخاب کرتی ہے وہاں آپ بھر جاتے ہیں، جو آپ کے اسٹاپ سے کہیں زیادہ خراب ہو سکتا ہے۔ نقصان اس سے کہیں زیادہ ہو سکتا ہے جس کا آپ نے سائز لگایا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>سٹاپ لاس اس بات کی ضمانت دیتا ہے کہ قیمت آپ کی سطح تک پہنچنے پر آپ کا آرڈر بھیجا جائے گا۔ یہ آپ کو ملنے والی قیمت کی ضمانت نہیں دیتا۔ اگر مستقبل میں آپ کے سٹاپ سے گزرنے والے وقفے راتوں رات ختم ہو جاتے ہیں، تو آپ دوبارہ کھلنے والی قیمت پر پُر ہو جاتے ہیں، جو آپ کے منصوبہ بند نقصان سے کہیں زیادہ ہو سکتی ہے۔ کبھی بھی یہ نہ سمجھیں کہ سٹاپ رات بھر کی پوزیشن کو محفوظ بناتا ہے۔</p>\n</div></div>\n<h2 id=\"gap-plus-leverage-the-classic-account-blower\">گیپ پلس لیوریج: کلاسک اکاؤنٹ بنانے والا</h2>\n<p>خلا کسی کے لیے بھی ناگوار ہوتا ہے۔ کسی ایسے شخص کے لیے جس کا مستقبل فائدہ مند ہو، یہ تباہ کن ہو سکتا ہے، اور اس کی وجہ وہی لیوریج ہے جس نے انہیں اپنی طرف کھینچا۔</p>\n<p>RELIANCE نمبرز کو یاد کریں جو اس کورس میں گزرے ہیں۔ ایک لاٹ ہے۔ <strong>500 شیئرز</strong>. 1,318 روپے پر ایک ہی مستقبل کے بارے میں کنٹرول کرتا ہے۔ <strong>6,59,000 روپے</strong> اسٹاک کا، پھر بھی آپ صرف ارد گرد کا مارجن پوسٹ کرتے ہیں۔ <strong>1,10,000 روپے</strong>. یہ تقریباً چھ گنا کا لیوریج ہے۔ کیش ہولڈنگ پر، آپ کی ملکیت کی پوری قیمت کے مقابلے میں ایک فرق ماپا جاتا ہے۔ مستقبل میں، اسی روپے کے فرق کو آپ کے چھوٹے مارجن سے ماپا جاتا ہے۔</p>\n<p>نمبروں پر کام کریں۔ RELIANCE میں راتوں رات 6 فیصد کا فرق تقریباً 79 پوائنٹس ہے۔ 500 شیئرز پر تقریباً 39,500 روپے کا نقصان ہے۔ 6,59,000 روپے کے اسٹاک کے مقابلے میں جو ایک خرید و ہولڈ سرمایہ کار کے پاس ہے، یہ 6 فیصد ڈینٹ، تکلیف دہ لیکن زندہ رہنے کے قابل ہے۔ آپ کے تقریباً 1,10,000 روپے کے مارجن کے مقابلے، وہی 39,500 روپے آپ کے ایک تہائی سے زیادہ رقم ہے، ایک ہی کھلے میں، اس سے پہلے کہ آپ انگلی اٹھا سکیں۔ فرق کو 10 فیصد تک دھکیلیں، تقریباً 132 پوائنٹس، اور نقصان تقریباً 66,000 روپے ہے، ایک رات سے آپ کے نصف مارجن سے بھی زیادہ۔ یہ اس جملے کے پیچھے ریاضی ہے جو آپ تجربہ کار تاجروں سے سنیں گے: ایک گیپ پلس چھ گنا فائدہ اٹھانا کلاسک اکاؤنٹ بنانے والا ہے۔ خلا اچانک حرکت فراہم کرتا ہے، بیعانہ اسے ایک ایسے زخم میں ضرب دیتا ہے جسے کھاتہ جذب نہیں کر سکتا۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک تاجر 1,10,000 روپے کے قریب مارجن اور 1,290 پر ایک سٹاپ کے ساتھ راتوں رات ایک RELIANCE لے جاتا ہے۔ کمزور نتائج نے اسٹاک کو اوپن میں 1,250 تک گرادیا۔ سٹاپ ٹرگر کرتا ہے لیکن تقریباً 1,250 پر بھرتا ہے، نہ کہ 1,290، تقریباً 68 پوائنٹس کا نقصان، تقریباً 34,000 روپے۔ منصوبہ بند نقصان تقریباً 14,000 روپے تھا۔ خلا نے اسے تقریباً تین گنا کر دیا، اور اسٹاپ، جو ایک رات پہلے حفاظت کی طرح محسوس ہوتا تھا، چھلانگ لگانے کا کبھی موقع نہیں ملا۔</p>\n</div></div>\n<h2 id=\"event-driven-margin-hikes\">ایونٹ پر مبنی مارجن میں اضافہ</h2>\n<p>ایک دوسرا، پرسکون طریقہ ہے کہ کوئی واقعہ آپ کو تکلیف دے سکتا ہے، اور یہ اس وقت پہنچتا ہے جب آپ اسے کم سے کم برداشت کر سکتے ہوں۔ مارجن مقرر نہیں ہیں۔ ایکسچینج ان کو اس وقت بڑھاتا ہے جب اسے مارکیٹ کے زیادہ اتار چڑھاؤ کی توقع ہوتی ہے، اور بڑے طے شدہ واقعات بالکل اسی وقت ہوتے ہیں جب وہ اس کی توقع کرتا ہے۔ بجٹ کے ارد گرد، مرکزی بینک کے ایک بڑے فیصلے، انتخابی نتیجہ، یا اس کے فزیکل سیٹلمنٹ ہفتے میں ایک اسٹاک کے نتائج، متاثرہ کنٹریکٹ پر مطلوبہ مارجن اکثر پہلے سے بڑھا دیا جاتا ہے۔</p>\n<p>آپ پر اثر عجیب ہے۔ ایک پوزیشن جو آپ نے تقریباً 1,10,000 روپے کے مارجن پر آرام سے کھولی ہے وہ اچانک کھلے رہنے کے لیے مزید نقد رقم کا مطالبہ کر سکتی ہے، خاص طور پر اس خطرے سے جس کا آپ کو سامنا ہے بڑھ رہا ہے۔ اگر آپ کے پاس اضافی فنڈز تیار نہیں ہیں، تو آپ کو کسی تکلیف دہ لمحے میں پوزیشن کو کم کرنے یا بند کرنے پر مجبور کیا جا سکتا ہے، اس سے پہلے کہ واقعہ حل ہو جائے۔ لہذا ایک واقعہ آپ کو دو بار خرچ کر سکتا ہے: ایک بار اس کی وجہ سے خلا کے ذریعے، اور ایک بار زیادہ مارجن کے ذریعے یہ پہلے سے مطالبہ کرتا ہے. اپنے اکاؤنٹ کو مارجن کے آخری روپے تک چلانے کے بجائے کیش بفر رکھنا، آپ کو زبردستی نکالے بغیر اضافے سے بچنے دیتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایکسچینج معروف ہائی رسک واقعات سے پہلے مارجن بڑھاتے ہیں۔ ایسی پوزیشن جو کل آپ کے اکاؤنٹ کے مطابق ہو، کل مزید نقد رقم کا مطالبہ کر سکتی ہے، بالکل اسی طرح جیسے اتار چڑھاؤ بڑھتا ہے۔ ہمیشہ کیش بفر رکھیں تاکہ ایونٹ پر مبنی مارجن میں اضافہ آپ کو بدترین وقت پر مجبور نہ کرے۔</p>\n</div></div>\n<h2 id=\"how-to-defend-yourself\">اپنا دفاع کیسے کریں۔</h2>\n<p>آپ راتوں رات ہولڈنگ کرتے ہوئے خلا کے خطرے کو ختم نہیں کر سکتے ہیں، لیکن آپ اس سے تباہ ہونے سے انکار کر سکتے ہیں۔ دفاع سادہ ہیں اور وہ کام کرتے ہیں۔</p>\n<ul>\n<li><strong>سائز کو کم کریں یا معلوم واقعہ سے پہلے فلیٹ رہیں۔</strong> کیلنڈر آپ کو بتاتا ہے کہ نتائج، بجٹ، مرکزی بینک کی میٹنگ یا کوئی بڑا سیاسی پروگرام کب ہونے والا ہے۔ اگر آپ جانتے ہیں کہ ایونٹ آنے والا ہے، تو یہ وقت کم لے جانے کا ہے، یا کچھ بھی نہیں۔ ایسا کوئی اصول نہیں ہے جو کہتا ہو کہ آپ کو ہر ایونٹ کے ذریعے اپنی پوزیشن حاصل کرنی چاہیے۔ سب سے بڑے نامعلوم کو باہر بیٹھنا ایک پیشہ ورانہ عادت ہے، ڈرپوک نہیں۔</li>\n<li><strong>ایک ہیج پر غور کریں۔</strong> اگر آپ کسی ایونٹ کے ذریعے پوزیشن برقرار رکھنا چاہتے ہیں، تو آپ اس کے کچھ خطرے کو دور کر سکتے ہیں، مثال کے طور پر اسے مخالف پوزیشن کے ساتھ جوڑ کر تاکہ کسی بھی سمت میں پرتشدد فرق جزوی طور پر کم ہو جائے۔ ایک ہیج نرم لینڈنگ کے بدلے کچھ منافع چھوڑ دیتا ہے، اور ایک حقیقی سکے پلٹنے والے واقعے کے ارد گرد جو تجارت کرنے کے قابل ہو سکتی ہے۔</li>\n<li><strong>ماہ کے قریب مائع کو ترجیح دیں۔</strong> جب معاہدہ پتلا ہوتا ہے تو فرق زیادہ خراب ہوتا ہے، کیونکہ دوبارہ کھلنے والی قیمت بھی سائز میں تجارت کرنا مشکل ہو سکتی ہے۔ قریبی مہینہ کا مستقبل سب سے زیادہ مائع ہے، سخت ترین مارکیٹ کے ساتھ، لہذا آپ کا باہر نکلنا، جب یہ فائر ہوتا ہے، سب سے زیادہ خواہش مند خریداروں اور فروخت کنندگان سے ملتا ہے۔ دور مہینہ اور باریک تجارت شدہ سنگل سٹاک کنٹریکٹ ناقص لیکویڈیٹی کے ساتھ ایک خلا کو بڑھا دیتے ہیں۔ مبتدیوں کو قریب کے مہینے میں رہنا چاہئے۔</li>\n<li><strong>کبھی بھی یہ نہ سمجھیں کہ سٹاپ رات بھر کی پوزیشن کو محفوظ بناتا ہے۔</strong> اسٹاپ کی جگہ، ہمیشہ، لیکن ہر رات کی پوزیشن کو اس طرح سائز دیں جیسے کہ اسٹاپ کو چھوڑا جا سکتا ہے، کیونکہ یہ ایک خلا کے پار ہوسکتا ہے۔ آپ کو راتوں رات مستقبل لے جانے سے پہلے ایماندارانہ سوال یہ نہیں ہے کہ \"میرا اسٹاپ کہاں ہے\" بلکہ \"کیا میں اپنے خلاف اس خلا کو کھلے عام دیکھ کر زندہ رہ سکتا ہوں؟\" اگر جواب نفی میں ہے تو پوزیشن بہت بڑی ہے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی مستقبل کو راتوں رات لے جانے سے پہلے، ایونٹ کے کیلنڈر کو چیک کریں، سب سے بڑے نامعلوم میں کم یا کچھ بھی نہیں لے کر جائیں، مہینے کے قریب مائع میں رہیں، اور پوزیشن کو اس طرح سائز کریں کہ آپ کے اسٹاپ سے سیدھا ایک خلا بھی آپ کو زخموں سے دوچار کر دے، ٹوٹے نہیں۔</p>\n</div></div>\n<p>ٹیک وے نرم اور سادہ ہے۔ رات کا وقفہ وہ خطرہ ہے جو صرف اس وقت ظاہر ہوتا ہے جب آپ قریب سے گزرے ہوئے مستقبل کو اپنے پاس رکھتے ہیں، اور ایک سٹاپ لاس، جو آپ کی معمول کی ڈھال ہے، سیدھی چھلانگ لگا سکتا ہے۔ اس کا احترام کریں، مارجن میں اضافے کے لیے کیش بفر رکھیں، معلوم واقعات کے بارے میں روشنی ڈالیں، اور رات بھر کی ہر پوزیشن کو ایسی چیز کے طور پر پیش کریں جو آپ کو اپنے خلاف فرق کو دیکھ کر زندہ رہنے کے قابل ہونا چاہیے۔ ایسا کریں، اور صبح کی حیرت ایک زخم بن جاتی ہے جسے آپ اپنے اکاؤنٹ کو ختم کرنے والے دھچکے کے بجائے جذب کر سکتے ہیں۔</p>\n","toc":[{"level":2,"text":"جب بازار بند ہو لیکن دنیا بند نہ ہو۔","id":"when-the-market-is-shut-but-the-world-is-not"},{"level":2,"text":"سٹاپ نقصان آپ سے قیمت کا وعدہ نہیں کرتا ہے۔","id":"a-stop-loss-does-not-promise-you-a-price"},{"level":2,"text":"گیپ پلس لیوریج: کلاسک اکاؤنٹ بنانے والا","id":"gap-plus-leverage-the-classic-account-blower"},{"level":2,"text":"ایونٹ پر مبنی مارجن میں اضافہ","id":"event-driven-margin-hikes"},{"level":2,"text":"اپنا دفاع کیسے کریں۔","id":"how-to-defend-yourself"}],"imgCount":1,"hasContent":true},"26":{"html":"<p>یہ وہ جملہ ہے جس کی طرف اس کورس کا باقی حصہ تعمیر کر رہا ہے، اور یہ آرام دہ نہیں ہے۔ زیادہ تر لوگ جو لیوریجڈ فیوچر کی تجارت کرتے ہیں وہ پیسے کھو دیتے ہیں۔ کچھ نہیں۔ زیادہ تر ہندوستان اور دیگر جگہوں پر ریٹیل ڈیریویٹوز کے تاجروں کے مطالعہ کے بعد ہونے والے مطالعہ سے پتہ چلتا ہے کہ بڑی اکثریت کا ایک سال ان کے شروع سے زیادہ غریب ختم ہوتا ہے، اور ان میں سے ایک تکلیف دہ حصہ بہت زیادہ کھو جاتا ہے۔ یہ اس لیے نہیں کہ وہ بیوقوف یا سست ہیں۔ بہت سے لوگ ہوشیار، محنتی لوگ ہیں۔ وہ اس واحد خصوصیت کی وجہ سے ہار جاتے ہیں جس نے انہیں اپنی طرف متوجہ کیا: فائدہ اٹھانا۔ وہی ضرب جو ایک چھوٹی سی حرکت کو بڑے فائدے میں لے جاتا ہے ایک چھوٹی سی حرکت کو بڑے نقصان میں بدل دیتا ہے، اور یہ اس سے زیادہ تیزی سے کام کرتا ہے جتنا کہ زیادہ تر ابتدائی ردعمل ظاہر کر سکتے ہیں۔ یہ باب ایماندار ہے۔ اس کا کام آپ کو مستقبل سے ڈرانا نہیں ہے بلکہ آپ کو یہ بتانا ہے کہ کس طرح لیوریج اکاؤنٹس کو تباہ کرتی ہے، اور کس طرح نظم و ضبط والے چند لوگ زندہ رہتے ہیں۔</p>\n<p>اگر آپ کو اور کچھ یاد نہیں ہے تو یہ یاد رکھیں۔ آلہ خطرہ نہیں ہے۔ دی <strong>بیعانہ</strong> خطرہ ہے، اور آپ اسے کس طرح سائز اور کنٹرول کرتے ہیں یہ فیصلہ کرتا ہے کہ آیا آپ زندہ رہتے ہیں۔</p>\n<h2 id=\"why-most-futures-traders-lose\">زیادہ تر فیوچر ٹریڈرز کیوں ہار جاتے ہیں۔</h2>\n<p>فائدہ اٹھانا موہک ہے کیونکہ یہ اوپر کے راستے پر کام کرتا ہے۔ RELIANCE مثال کو یاد کریں جو اس کورس سے گزری ہے۔ اسٹاک کے ارد گرد تجارت <strong>1,318 روپے</strong>، ایک بہت ہے <strong>500 شیئرز</strong>لہذا ایک مستقبل تقریباً 6,59,000 روپے کے اسٹاک کو کنٹرول کرتا ہے، پھر بھی آپ تقریباً 1,00,000 سے 1,30,000 روپے کا مارجن پوسٹ کرتے ہیں۔ یہ تقریباً پانچ سے چھ گنا لیوریج ہے۔ RELIANCE میں معمولی پانچ فیصد اضافہ، 1318 سے تقریباً 1384 تک، 66 پوائنٹس ہے، جو کہ 500 شیئرز پر 33,000 روپے ہے۔ 1,10,000 روپے کے قریب مارجن کے خلاف جو کہ اسٹاک میں پانچ فیصد اضافے سے آپ کی رقم پر تیس فیصد کے قریب واپسی ہے۔ نشہ آور۔</p>\n<p>اب اسے دوسرے طریقے سے چلائیں، کیونکہ مارکیٹ بھی اتنا ہی خوش ہے۔ پانچ فیصد <strong>گر</strong> RELIANCE میں وہی 66 پوائنٹس ہیں، وہی 33,000 روپے، لیکن اب یہ نقصان ہے، اور یہ آپ کے خلاف پانچ فیصد اقدام سے آپ کے مارجن کا تیس فیصد کے قریب ہے۔ لیوریج بالکل ہموار ہے۔ یہ نقصانات کو بالکل اسی طرح ضرب دیتا ہے جتنا کہ فائدہ۔ زیادہ تر تاجروں کے ہارنے کی وجہ یہ نہیں ہے کہ ضرب غیر منصفانہ ہے، وہ یہ ہے کہ انسان فائدے کے خواب کے لیے پوزیشنوں کو سائز دیتے ہیں اور پھر ایک جیسے نقصان کے لیے تیار نہیں ہوتے، اور ان نقصانات میں سے کچھ، جو بہت زیادہ ہوتے ہیں، بہت سی چھوٹی جیتوں کو مٹا دیتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>لیوریج نقصانات کو بالکل اتنا ہی گنا کرتا ہے جتنا کہ فائدہ۔ زیادہ تر فیوچر ٹریڈرز اس وجہ سے نہیں ہارتے ہیں کہ مشکلات میں دھاندلی ہوتی ہے بلکہ اس وجہ سے کہ وہ اوپر کی طرف بڑھتے ہیں اور اتنے ہی بڑے نشیب و فراز سے تباہ ہو جاتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-gap-and-the-risk-while-you-sleep\">آپ کے سوتے وقت خلا اور خطرہ</h2>\n<p>جو حصہ آپ کے پاس ہے وہ گر سکتا ہے، لیکن آپ اسے دیکھ سکتے ہیں اور بیچ سکتے ہیں۔ ایک فائدہ مند مستقبل پرانے خطرے کا ایک تیز ورژن رکھتا ہے: <strong>رات کا وقفہ</strong>. بازار بند ہوتے ہیں، لیکن دنیا بند نہیں ہوتی۔ رات کو خبریں بریک ہوتی ہیں، نتیجہ مایوسی کا شکار ہوتا ہے، عالمی مارکیٹ کریش ہو جاتی ہے، اور جب ٹریڈنگ دوبارہ کھلتی ہے تو قیمت کل کے بند ہونے سے آسانی سے نہیں چلتی ہے۔ یہ <strong>خلا</strong>، جہاں سے آپ نے اسے آخری بار دیکھا تھا وہاں سے تیزی سے کھلنا، فرق میں تجارت کرنے کا کوئی موقع نہیں ہے۔</p>\n<p>لیوریجڈ پوزیشن کے لیے یہ سفاکانہ ہے۔ آپ کا احتیاط سے رکھا گیا سٹاپ نقصان، وہ سطح جہاں سے آپ باہر نکلنا چاہتے تھے، اسے چھوڑ دیا جاتا ہے۔ قیمت اس سے نیچے کھلتی ہے، آپ کہیں زیادہ خراب ہو جاتے ہیں، اور چونکہ آپ 1,10,000 روپے کے مارجن کے ساتھ 6,59,000 روپے کو کنٹرول کرتے ہیں، اس لیے ایک ایسا خلا جو کہ کیش ہولڈنگ پر قابل انتظام زخم ہو گا مستقبل کے لیے ایک سنگین زخم ہو سکتا ہے۔ صبح کی چائے پینے سے پہلے راتوں رات ایک خراب وقفہ آپ کے مارجن کا ایک بڑا ٹکڑا خرچ کر سکتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک سٹاپ نقصان آپ کو رات کے وقفے سے محفوظ نہیں رکھتا۔ جب آپ سوتے ہیں تو مارکیٹ آپ کے باہر نکلنے سے سیدھی چھلانگ لگا سکتی ہے، اور فائدہ اٹھانا اس چھلانگ کو بھاری نقصان میں بدل دیتا ہے۔ کبھی بھی راتوں رات فیوچرز کا زیادہ خطرہ نہ اٹھائیں جتنا آپ کھلے میں اپنے خلاف خلا کو دیکھ کر بچ سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-margin-call-spiral\">مارجن کال سرپل</h2>\n<p>یہ وہ جگہ ہے جہاں فائدہ اٹھانا تکلیف دہ سے تباہی میں بدل جاتا ہے، اور یہ ایک واضح تصویر کا مستحق ہے۔ جب نقصان آپ کے مارجن میں داخل ہو جاتا ہے، تو آپ کا اکاؤنٹ اس کم از کم سے نیچے آ سکتا ہے جس سے ایکسچینج کو پوزیشن برقرار رکھنے کی ضرورت ہوتی ہے۔ آپ کا بروکر پھر ایک جاری کرتا ہے۔ <strong>مارجن کال</strong>مزید فنڈز شامل کرنے یا پوزیشن کو کم کرنے کا مطالبہ۔ اگر آپ وقت پر عمل نہیں کر سکتے یا نہیں کر سکتے ہیں، تو پوزیشن ہے <strong>زبردستی بند</strong> مروجہ قیمت پر، نقصان کو بند کرنا چاہے آپ اسے پسند کریں یا نہ کریں۔</p>\n<p>ظلم تسلسل میں ہے، اور یہ اپنے آپ کو کھاتا ہے۔</p>\n<ul>\n<li>مارکیٹ آپ کی لیوریجڈ پوزیشن کے خلاف حرکت کرتی ہے، اور نقصان میں اضافہ ہوتا ہے۔</li>\n<li>آپ کا مارجن مطلوبہ سطح سے نیچے گرتا ہے، مارجن کال کو متحرک کرتا ہے۔</li>\n<li>آپ کو پیسے شامل کرنا ہوں گے یا پوزیشن کو کم کرنا ہوگا، اکثر بدترین ممکنہ لمحے پر۔</li>\n<li>اگر آپ نہیں کر سکتے ہیں، تو پوزیشن کو خراب قیمت پر زبردستی بند کر دیا جاتا ہے، نقصان کو کرسٹلائز کر کے۔</li>\n<li>نقصان آپ کے سرمائے کو سکڑتا ہے، اس لیے اگلی پوزیشن کا سائز چھوٹے بیس سے لگایا جاتا ہے، اور ایک اور خراب تجارت اکاؤنٹ کو ختم کر سکتی ہے۔</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-leverage-risk.png\" alt=\"لیوریج اسپائرل: لیوریج کی وجہ سے بڑھا ہوا نقصان مارجن کی کمی کا سبب بنتا ہے، جو مارجن کال کو متحرک کرتا ہے اور ناقص قیمت پر جبری اخراج کا سبب بنتا ہے، جس سے اکاؤنٹ ختم ہو جاتا ہے اور کم سرمایہ باقی رہ جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>لیوریج اسپائرل: لیوریج کی وجہ سے بڑھا ہوا نقصان مارجن کی کمی کا سبب بنتا ہے، جو مارجن کال کو متحرک کرتا ہے اور ناقص قیمت پر جبری اخراج کا سبب بنتا ہے، جس سے اکاؤنٹ ختم ہو جاتا ہے اور کم سرمایہ باقی رہ جاتا ہے۔</figcaption></figure>\n<p>دھیان دیں کہ جبری اخراج عام طور پر بدترین وقت پر اترتا ہے، جب قیمت آپ کے خلاف پہلے ہی سخت ہو چکی ہوتی ہے، اکثر ایک اچھال سے پہلے ہی۔ سرپل کو آپ کے یقین کی پرواہ نہیں ہے۔ یہ مکینیکل ہے۔ ایک بار لیوریج اور مارجن کی کمی ختم ہو جانے کے بعد، باہر نکلنے کا فیصلہ آپ کے لیے اس قیمت پر کیا جاتا ہے جس کا آپ نے انتخاب نہیں کیا تھا۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک تاجر 1,10,000 روپے کے قریب مارجن کے ساتھ ایک RELIANCE لمبا رکھتا ہے۔ بری خبروں نے اسٹاک کو راتوں رات 8 فیصد نیچے کردیا، تقریباً 52,000 روپے کا نقصان، تقریباً نصف مارجن۔ اکاؤنٹ مطلوبہ سطح سے نیچے آ جاتا ہے، مارجن کال ہو جاتی ہے، تاجر تیزی سے فنڈز شامل نہیں کر سکتا، اور جزوی بحالی سے پہلے، تاجر کبھی بھی لطف اندوز ہونے سے پہلے، پوزیشن کو زبردستی بند کر دیا جاتا ہے۔</p>\n</div></div>\n<h2 id=\"position-sizing-the-one-habit-that-decides-survival\">پوزیشن کا سائز: ایک عادت جو بقا کا فیصلہ کرتی ہے۔</h2>\n<p>اب بقا کی طرف، کیونکہ بہت سارے لوگ بغیر کسی دھماکے کے سالوں تک مستقبل کی تجارت کرتے ہیں۔ وہ سب سے بڑھ کر ایک عادت کا اشتراک کرتے ہیں: وہ <strong>کسی ایک تجارت پر اپنے سرمائے کا صرف ایک چھوٹا سا حصہ خطرے میں ڈالیں۔</strong>. انگوٹھے کا عام اصول یہ ہے کہ کسی تجارت پر اپنے تجارتی سرمائے کا ایک سے دو فیصد سے زیادہ خطرہ نہ لگائیں، یعنی آپ کے داخلے سے لے کر آپ کے سٹاپ تک کا فاصلہ، لاٹ سے ضرب کیا جائے، اگر سٹاپ مارا جاتا ہے تو آپ کو اس چھوٹے ٹکڑے سے زیادہ خرچ نہیں کرنا پڑے گا۔</p>\n<p>اس کے ذریعے کام کریں۔ فرض کریں کہ آپ کا تجارتی سرمایہ 5,00,000 روپے ہے اور آپ خطرے کو دو فیصد تک محدود کرتے ہیں، جو کہ 10,000 روپے فی تجارت ہے۔ 500 حصص کے مستقبل RELIANCE پر، 10,000 روپے کا خطرہ صرف 20 پوائنٹس کی گنجائش ہے، کیونکہ 20 گنا 500 10,000 روپے ہے۔ لہذا اگر آپ کا تجزیہ کہتا ہے کہ اسٹاپ 20 پوائنٹس کے فاصلے پر ہے، تو ایک لاٹ آپ کے خطرے کے مطابق ہے۔ اگر چارٹ کہتا ہے کہ سمجھدار سٹاپ 40 پوائنٹس کے فاصلے پر ہے، تو ایک لاٹ 20,000 روپے کا خطرہ لے گا، آپ کی حد کو دوگنا کر دے گا، لہذا نظم و ضبط کا انتخاب یہ ہے کہ مکمل لاٹ نہ لیا جائے، یا سخت سٹاپ کے ساتھ سیٹ اپ کا انتظار کریں۔ پوزیشن کا سائز آپ کے خطرے کی حد اور آپ کے رکنے کے فاصلے سے طے ہوتا ہے، کبھی بھی اس بات سے کہ آپ کتنے پر اعتماد محسوس نہیں کرتے۔</p>\n<p>یہ خاموش ریاضی ہے جو زندہ بچ جانے والوں کو جانی نقصان سے الگ کرتی ہے۔ زندہ بچ جانے والے کا سائز اتنا بڑھ جاتا ہے کہ غلط ہونے کی وجہ سے ایک چھوٹی، قابل وصول رقم خرچ ہوتی ہے۔ انعام کے لیے جانی نقصان کا سائز، اکاؤنٹ کے لیے بہت بڑی پوزیشن لیتا ہے، اور اسے ختم کرنے کے لیے صرف ایک خراب خلا کی ضرورت ہوتی ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>پہلے اپنے سٹاپ کا فیصلہ کریں، پھر پوزیشن کا سائز کریں تاکہ سٹاپ کو مارنے پر آپ کے سرمائے کا صرف ایک چھوٹا سا مقررہ حصہ خرچ ہو، تقریباً ایک سے دو فیصد۔ اسٹاپ فاصلے کو اپنا سائز منتخب کرنے دیں۔ کبھی بھی اپنے اعتماد یا کسی بڑی جیت کے لالچ کو اپنے لیے منتخب نہ ہونے دیں۔</p>\n</div></div>\n<h2 id=\"always-trade-with-a-stop\">ہمیشہ اسٹاپ کے ساتھ تجارت کریں۔</h2>\n<p>اے <strong>نقصان کو روکنے کے</strong> وہ قیمت ہے جس پر آپ نے پہلے سے اور سکون سے فیصلہ کیا ہے کہ تجارت کو غلط تسلیم کریں اور باہر نکل جائیں۔ لیوریج کے ساتھ، سٹاپ کے بغیر تجارت کرنا بہادری نہیں ہے، یہ آپ کے اکاؤنٹ کو حوالے کرنے کا ایک سست طریقہ ہے۔ ایک ایسا اقدام جو کہ نقد رکھنے پر محض غیر آرام دہ ہو، مستقبل کے لیے خطرے کا باعث ہو سکتا ہے، اس لیے آپ کو داخل ہونے سے پہلے اپنے باہر نکلنے کا علم ہونا چاہیے، تیزی سے نقصان کے گھبراہٹ میں کوئی ایجاد نہ کریں۔</p>\n<p>ایک سٹاپ کامل نہیں ہے. جیسا کہ آپ نے دیکھا، ایک رات کا وقفہ اس سے گزر سکتا ہے۔ لیکن ایک عام انٹرا ڈے اقدام پر یہ بالکل اپنا کام کرتا ہے، جہاں آپ نے منصوبہ بنایا تھا اس کے قریب ہونے والے نقصان کو محدود کرنا اور کسی ایک تجارت کو آپ کو ختم کرنے والی تجارت کو بننے سے روکنا۔ پہلے سے طے شدہ اسٹاپ کو چھوٹی پوزیشن کے سائز کے ساتھ جوڑیں اور آپ کے پاس دو عادات ہیں جو کسی بھی اشارے یا نظام سے زیادہ، ایک تاجر کو سیکھنے کے لیے کافی دیر تک زندہ رکھتی ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایک سٹاپ نقصان آپ کو ہر فرق سے نہیں بچائے گا، لیکن یہ عام نقصانات کو پورا کرتا ہے جو زیادہ تر تجارت کرتے ہیں۔ بغیر کسی منصوبہ بند اخراج کے فائدہ مند مستقبل میں داخل ہونا مارجن کال سرپل کا تیز ترین راستہ ہے۔ ہر بار داخل ہونے سے پہلے اپنے اخراج کو جانیں۔</p>\n</div></div>\n<h2 id=\"respect-the-leverage-and-a-sober-closing-word\">فائدہ اٹھانے کا احترام کریں، اور ایک نرم اختتامی لفظ</h2>\n<p>پیچھے ہٹیں اور پوری تصویر آسان ہے، چاہے یہ آسان نہ ہو۔ فیوچرز ایک تیز ٹول ہیں۔ احترام کے ساتھ استعمال کرتے ہوئے وہ آپ کو دونوں سمتوں میں تجارت کرنے دیتے ہیں، جو کچھ آپ کے پاس ہے اس کی حفاظت کرتے ہیں، اور سرمایہ کاری کو مؤثر طریقے سے کام کرنے دیتے ہیں۔ احترام کے بغیر استعمال کیا جاتا ہے وہ مارکیٹ میں ایک ابتدائی سے رقم لینے کا تیز ترین طریقہ ہے، اور جو لیور اسے کرتا ہے وہ لیوریج ہے۔</p>\n<p>لہذا جب آپ اس کورس کو ختم کرتے ہیں تو ان چند سچائیوں کو قریب رکھیں:</p>\n<ul>\n<li>زیادہ تر لیوریجڈ فیوچر ٹریڈرز ہار جاتے ہیں، اور بڑی پوزیشنیں عام طور پر اس کی وجہ ہوتی ہیں۔</li>\n<li>لیوریج نقصانات کو بالکل اتنا ہی بڑھاتا ہے جتنا کہ فائدہ، بغیر کسی طرفداری کے۔</li>\n<li>راتوں کا وقفہ آپ کے اسٹاپ کو چھوڑ سکتا ہے، اس لیے کبھی بھی اس سے زیادہ خطرہ مول نہ لیں جتنا آپ کھلے میں زندہ رہ سکتے ہیں۔</li>\n<li>مارجن کال سرپل ایک بار شروع ہونے پر مکینیکل اور ناقابل معافی ہے، لہذا اس کے کنارے سے دور رہیں۔</li>\n<li>فی تجارت اپنے سرمائے کا ایک چھوٹا، مقررہ حصہ خطرے میں ڈالیں، اپنے اسٹاپ کو اپنا سائز منتخب کرنے دیں، اور ہمیشہ اپنے باہر نکلنے کو جانیں۔</li>\n</ul>\n<p>اگر آپ حقیقی رقم داؤ پر لگائے بغیر ان سب کی مشق کرنا چاہتے ہیں، تو سینڈ باکس ٹریڈنگ میں مشق کریں، OpenAlgo میں تجزیہ کار وضع، جب تک کہ نظم و ضبط دوسری نوعیت کا نہ ہو۔ جو تاجر زندہ رہتے ہیں وہ شاذ و نادر ہی دلیر ہوتے ہیں۔ وہ وہ لوگ ہیں جنہوں نے بیعانہ کو آلہ کے متعین خطرے کے طور پر سمجھا، جس کا سائز کافی چھوٹا تھا کہ کئی بار غلط ہو سکتا تھا، اور دوسرے دن تجارت کرنے کے لیے زندہ رہتے تھے۔ ان میں سے ایک بنیں۔</p>\n","toc":[{"level":2,"text":"زیادہ تر فیوچر ٹریڈرز کیوں ہار جاتے ہیں۔","id":"why-most-futures-traders-lose"},{"level":2,"text":"آپ کے سوتے وقت خلا اور خطرہ","id":"the-gap-and-the-risk-while-you-sleep"},{"level":2,"text":"مارجن کال سرپل","id":"the-margin-call-spiral"},{"level":2,"text":"پوزیشن کا سائز: ایک عادت جو بقا کا فیصلہ کرتی ہے۔","id":"position-sizing-the-one-habit-that-decides-survival"},{"level":2,"text":"ہمیشہ اسٹاپ کے ساتھ تجارت کریں۔","id":"always-trade-with-a-stop"},{"level":2,"text":"فائدہ اٹھانے کا احترام کریں، اور ایک نرم اختتامی لفظ","id":"respect-the-leverage-and-a-sober-closing-word"}],"imgCount":1,"hasContent":true},"27":{"html":"<p>آپ کورس کے اختتام پر پہنچ گئے ہیں، اور اب آپ مستقبل کے بارے میں زیادہ تر لوگوں کے مقابلے میں زیادہ سمجھتے ہیں جو آپ کے ارد گرد تجارت کرتے ہیں۔ آپ جانتے ہیں کہ معاہدہ کیا ہے، لیوریج اور مارجن کیسے کام کرتے ہیں، ہر ایک دن پوزیشن کیوں طے کی جاتی ہے، بنیاد اور رول اوور کا کیا مطلب ہے، اسٹاک فیوچرز فزیکل طور پر کیسے سیٹل ہوتے ہیں جب کہ انڈیکس نقد میں سیٹل ہوتا ہے، اور پوزیشن کو کس طرح سائز کرنا ہے تاکہ غلط ہونے سے آپ ختم نہ ہوں۔ یہ ایک حقیقی بنیاد ہے۔ لیکن ایک پرسکون باب میں یہ سب کچھ جاننا ایسا نہیں ہے جیسے آپ کے اعصاب کو ایک اونچی آواز میں، تیز بازار میں حقیقی رقم کے ساتھ پکڑنا۔ یہ آخری باب دونوں کے درمیان پل ہے۔ یہ ان غلطیوں کو اکٹھا کرتا ہے جو ابتدائی اکاؤنٹس کو خاموشی سے خالی کر دیتی ہیں، پھر آپ کو ہر تجارت سے پہلے چلانے کے لیے ایک مختصر چیک لسٹ فراہم کرتی ہے، اس لیے آپ نے جو نظم و ضبط سیکھا ہے وہ دراصل مارکیٹ کے ساتھ رابطے میں رہتا ہے۔</p>\n<p>تقریباً ہر اڑا ہوا اکاؤنٹ انہی چند غلطیوں کا مجموعہ ہے۔ ان میں سے کوئی بھی غیر ملکی نہیں ہے۔ ان کو پہچاننا سیکھیں اور آپ نے پہلے سے ہی زیادہ تر نقصانات کو کم کر دیا ہے جو کہ ابتدائی افراد خود کو کرتے ہیں۔</p>\n<h2 id=\"the-mistakes-that-empty-beginner-accounts\">وہ غلطیاں جو ابتدائی اکاؤنٹس کو خالی کرتی ہیں۔</h2>\n<p>یہ وہ بار بار چلنے والے طریقے ہیں جن سے نئے فیوچر ٹریڈرز کھو جاتے ہیں، سیدھے ان تھریڈز سے جو اس پورے کورس میں چل چکے ہیں۔ انہیں ان چیزوں کی فہرست کے طور پر پڑھیں جنہیں نہیں کرنا ہے۔</p>\n<ul>\n<li><p><strong>نمائش کے بجائے مارجن کو ختم کرکے اوورسائزنگ کریں۔</strong> ایک RELIANCE مستقبل 500 حصص ہے، جس کے بارے میں کنٹرول ہے۔ <strong>6,59,000 روپے</strong> کے قریب تازہ ترین قیمت پر اسٹاک کا <strong>1,318 روپے</strong>اگرچہ آپ اسے کھولنے کے لیے تقریباً 1,00,000 سے 1,30,000 روپے کا مارجن پوسٹ کرتے ہیں۔ ابتدائی افراد چھوٹے مارجن کو دیکھتے ہیں، فیصلہ کرتے ہیں کہ وہ کئی لاٹوں کو \"برداشت\" کر سکتے ہیں، اور خاموشی سے بیس یا تیس لاکھ ایکسپوزر لے سکتے ہیں۔ نمائش وہ چیز ہے جو آپ کے خلاف حرکت کرتی ہے، مارجن نہیں۔</p>\n</li>\n<li><p><strong>سٹاپ کے بغیر تجارت.</strong> پہلے سے طے شدہ اخراج کے بغیر لیوریجڈ پوزیشن میں داخل ہونا ہمت نہیں ہے، یہ ایک سست ہتھیار ڈالنا ہے۔ داخل ہونے سے پہلے آپ کو اس قیمت کا علم ہونا چاہیے جس پر آپ تسلیم کرتے ہیں کہ تجارت غلط ہے، کیونکہ ایک ایسا اقدام جو کہ نقد رکھنے پر محض غیر آرام دہ ہو، مستقبل کے لیے خطرہ بن سکتا ہے۔</p>\n</li>\n<li><p><strong>ہارنے والے میں اوسط۔</strong> \"اوسط کو بہتر بنانے\" کے لیے ہاری ہوئی پوزیشن میں مزید اضافہ کرنا ہوشیار محسوس ہوتا ہے اور یہ تباہی کے تیز ترین طریقوں میں سے ایک ہے۔ آپ بالکل ٹھیک تجارت پر فائدہ اٹھا رہے ہیں اور مارکیٹ آپ کو پہلے ہی بتا رہی ہے کہ غلط ہے، لہذا ایک چھوٹا سا نقصان بڑا بن جاتا ہے۔</p>\n</li>\n<li><p><strong>illiquid دور مہینے کا پیچھا.</strong> قریب کے مہینے کا معاہدہ وہ جگہ ہے جہاں حجم اور ٹائٹ اسپریڈز رہتے ہیں۔ دور کا مہینہ اکثر پتلی گہرائی کے ساتھ وسیع پھیلاؤ پر تجارت کرتا ہے، لہذا آپ اندر جانے کے لیے اضافی ادائیگی کرتے ہیں، باہر نکلنے کے لیے دوبارہ ادائیگی کرتے ہیں، اور ہر بار پھسلن کا شکار ہوتے ہیں۔ ایک ابتدائی قریب مہینے میں تعلق رکھتا ہے.</p>\n</li>\n<li><p><strong>لین دین کے اخراجات اور اوور ٹریڈنگ کو نظر انداز کرنا۔</strong> ایک سنگل NIFTY راؤنڈ ٹرپ، ایک لاٹ 24,000 کے قریب خریدا اور بیچا گیا، اس کی قیمت تقریبا <strong>929 روپے</strong> ایک بار جب آپ بروکریج، STT، ایکسچینج اور GST چارجز، اسٹامپ ڈیوٹی اور باقی شامل کریں۔ یعنی تقریباً <strong>14 پوائنٹس</strong> ایک روپیہ کمانے سے پہلے مستقبل آپ کے حق میں چلنا چاہیے۔ ایک تاجر جو دن میں دس چکر لگاتا ہے وہ اسے دس گنا ادا کرتا ہے، اور اوور ٹریڈنگ سے کالز درست ہونے پر بھی اکاؤنٹ میں خون خرابہ ہوتا ہے۔</p>\n</li>\n<li><p><strong>سٹاک مستقبل کو حادثاتی طور پر جسمانی تصفیہ میں لے جانا۔</strong> RELIANCE اور دیگر سنگل اسٹاک فیوچرز طے پاتے ہیں۔ <strong>جسمانی ترسیل</strong>. ایک کو ایکسپائر ہونے تک روکے رکھیں اور آپ کو صرف فرق ادا نہیں کیا جائے گا، آپ کو اصل شیئرز دینے یا لینے چاہئیں، جس کا مطلب ہے کہ مکمل 6,59,000 روپے نقد یا خود اسٹاک تلاش کریں۔ کسی ایسے شخص کے لیے جو صرف لیوریجڈ شرط چاہتا ہے، یہ ایک گندی، مہنگی حیرت ہے۔ آخری دنوں سے پہلے اسٹاک مستقبل کو بند کریں یا رول کریں۔</p>\n</li>\n<li><p><strong>نقصان کے بعد بدلہ لینا۔</strong> نقصان کا ڈنکا، اور بڑی، تیز تر تجارت کے ساتھ \"اسے سیدھے واپس جیتنے\" کی خواہش طاقتور اور خطرناک ہے۔ بدلے کی تجارت جذبات کے حساب سے ہوتی ہے، نہ کہ آپ کے خطرے کے منصوبے سے، اور وہ یہ ہیں کہ کس طرح ایک بری صبح تباہ شدہ اکاؤنٹ بن جاتی ہے۔</p>\n</li>\n<li><p><strong>چھوٹے مارجن کو حقیقی خطرے کے ساتھ الجھانا۔</strong> مارجن وہ ڈپازٹ ہے جو آپ کو داخل کرنے دیتا ہے، زیادہ سے زیادہ نہیں جو آپ کھو سکتے ہیں۔ راتوں رات کا وقفہ آپ کو آپ کے پوسٹ کردہ مارجن سے زیادہ نقصان پہنچا سکتا ہے، جس سے آپ کو اس پوزیشن پر رقم واجب الادا رہ جاتی ہے جس کے بارے میں آپ نے سوچا تھا کہ محدود ہے۔ اس چھوٹے ڈپازٹ کے پیچھے آلہ کا خطرہ مکمل نمائش ہے۔</p>\n</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-common-mistakes.png\" alt=\"آٹھ بار بار ہونے والی ابتدائی غلطیاں، مارجن کو اوور سائز کرنے اور بغیر کسی روک کے ٹریڈنگ سے لے کر ہارنے والے میں اوسط حاصل کرنے اور مستقبل کے اسٹاک کو جسمانی تصفیہ میں لے جانے تک، ہر ایک ایسی عادت جو خاموشی سے لیوریجڈ اکاؤنٹ کو ختم کر دیتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>آٹھ بار بار ہونے والی ابتدائی غلطیاں، مارجن کو اوور سائز کرنے اور بغیر کسی روک کے ٹریڈنگ سے لے کر ہارنے والے میں اوسط حاصل کرنے اور مستقبل کے اسٹاک کو جسمانی تصفیہ میں لے جانے تک، ہر ایک ایسی عادت جو خاموشی سے لیوریجڈ اکاؤنٹ کو ختم کر دیتی ہے۔</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>غور کریں کہ ان میں سے کتنی غلطیاں مختلف کپڑے پہننے والی ایک غلطی ہیں: یہ بھول جانا کہ چھوٹا مارجن ایک بڑے، لیوریجڈ نمائش کے اوپر بیٹھا ہے۔ زیادہ سائز کرنا، اوسط کم کرنا، بدلے کی تجارت کرنا اور ڈیلیوری میں گھسیٹنا یہ سب کچھ اس بات کو کم کرنے سے شروع ہوتا ہے کہ آپ اصل میں کیا کنٹرول کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-pre-trade-checklist\">پری ٹریڈ چیک لسٹ</h2>\n<p>ان سب کا علاج بورنگ، دوبارہ قابل اور کام کرنے والا ہے۔ اس سے پہلے کہ آپ کسی بھی فیوچر آرڈر پر خرید دبائیں، اس چیک لسٹ پر چلیں۔ ایک عادت بننے کے بعد اس میں ایک منٹ سے بھی کم وقت لگتا ہے، اور یہ اوپر کی تقریباً ہر غلطی کو پکڑ لیتا ہے اس سے پہلے کہ اس سے آپ کو کچھ بھی ادا کرنا پڑے۔</p>\n<table>\n<thead>\n<tr>\n<th>اس سے پہلے کہ آپ دبائیں خریدیں۔</th>\n<th>جس سے یہ آپ کی حفاظت کرتا ہے۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ٹھیک ٹھیک معاہدہ اور میعاد ختم ہونے کی تصدیق کی۔</td>\n<td>غلط مہینے کی تجارت کرنا یا حیرت سے خود بخود طے پا جانا۔ علامت کو مکمل پڑھیں، مثال کے طور پر RELIANCE28JUL26FUT، اور جان لیں کہ 28 جولائی 2026 آخری منگل ہے، اس لیے آپ باہر نکلنے کا فیصلہ کریں، کیلنڈر کا نہیں۔</td>\n</tr>\n<tr>\n<td>کیلکولیٹر پر مارجن چیک کیا اور ایک کیش بفر پکڑا۔</td>\n<td>مارجن کی کمی اور زبردستی اخراج۔ اصل ضرورت کے لیے OpenAlgo مارجن کیلکولیٹر کا استعمال کریں، پھر فالتو نقد رقم رکھیں، کیونکہ ایکسچینجز بڑے واقعات سے پہلے مارجن کو بڑھاتے ہیں۔</td>\n</tr>\n<tr>\n<td>پوزیشن کا سائز سرمائے کے ایک مقررہ حصہ تک</td>\n<td>بڑا کرنا۔ صرف ایک سے دو فیصد سرمایہ فی تجارت کا خطرہ ہے، جس کا سائز مکمل نمائش اور سٹاپ کے فاصلے پر ہے، کبھی بھی پرکشش چھوٹے مارجن سے دور نہیں۔</td>\n</tr>\n<tr>\n<td>داخل ہونے سے پہلے ایک اسٹاپ سیٹ کریں۔</td>\n<td>پوزیشن آپ سے بھاگ رہی ہے۔ باہر نکلنے کی قیمت کا فیصلہ پہلے ہی پرسکون طریقے سے کریں، اس لیے تیزی سے نقصان گھبراہٹ کے بجائے ایک منصوبہ پر پورا اترتا ہے۔</td>\n</tr>\n<tr>\n<td>اخراجات کے حساب سے</td>\n<td>اوور ٹریڈنگ اور بریک ایون اندھا پن۔ جان لیں کہ ایک راؤنڈ ٹرپ تقریباً 929 روپے اور تقریباً 14 پوائنٹس کا ہے، اور اس کی قیمت سائز اور قیمت کے حساب سے ہے۔</td>\n</tr>\n<tr>\n<td>تقریب کا کیلنڈر چیک کیا۔</td>\n<td>فرق اور واقعہ کا خطرہ۔ نتائج تلاش کریں، ایک RBI فیصلہ، بجٹ، انتخابی گنتی یا ایکسپائری ہفتہ، اور سائز کو کم کریں یا معلوم صدمے سے پہلے فلیٹ رہیں۔</td>\n</tr>\n<tr>\n<td>جیت اور ہار کے لیے باہر نکلنے کا منصوبہ لکھا</td>\n<td>بہتی اور انتقامی تجارت۔ داخلے سے پہلے اپنے ہدف اور اپنے سٹاپ کا فیصلہ کریں، اس لیے دونوں نتائج پہلے ہی سنبھال لیے گئے ہیں اور اس وقت کی گرمی میں کوئی فیصلہ نہیں کیا جاتا ہے۔</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/futures/images/diagram-trade-checklist.png\" alt=\"ایک سات نکاتی پری ٹریڈ چیک لسٹ، معاہدے کی تصدیق اور مارجن کو چیک کرنے سے لے کر پوزیشن کو سائز دینے، اسٹاپ سیٹ کرنے، اخراجات کا حساب کتاب، ایونٹس کی جانچ اور ایگزٹ پلان لکھنے تک، ہر فیوچر آرڈر سے پہلے چلائی جاتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک سات نکاتی پری ٹریڈ چیک لسٹ، معاہدے کی تصدیق اور مارجن کو چیک کرنے سے لے کر پوزیشن کو سائز دینے، اسٹاپ سیٹ کرنے، اخراجات کا حساب کتاب، ایونٹس کی جانچ اور ایگزٹ پلان لکھنے تک، ہر فیوچر آرڈر سے پہلے چلائی جاتی ہے۔</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اس چیک لسٹ کو ایسی جگہ پر رکھیں جہاں آپ اس سے بچ نہیں سکتے، اپنے مانیٹر پر ٹیپ یا اپنے تجارتی نوٹوں میں پِن کر دیں۔ مقصد اسے حفظ کرنا نہیں ہے بلکہ اسے خودکار بنانا ہے، لہذا نظم و ضبط اس بات پر منحصر نہیں ہے کہ آپ اس صبح کو کیسا محسوس کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"run-the-checklist-on-one-real-trade\">ایک حقیقی تجارت پر چیک لسٹ چلائیں۔</h2>\n<p>پورے کورس کو ایک ہی پوزیشن پر اکٹھا کرتے ہوئے دیکھیں۔ فرض کریں کہ آپ ایک طویل NIFTY مستقبل قریب جانا چاہتے ہیں۔ <strong>24,000</strong>، جہاں کی بہت <strong>65</strong> مطلب ایک معاہدہ تقریباً 15,60,000 روپے کا ہے۔ آپ کا تجارتی سرمایہ 5,00,000 روپے ہے اور آپ ایک فیصد خطرے کو محدود کرتے ہیں، جو کہ 5,000 روپے ہے۔</p>\n<p>سب سے پہلے، معاہدہ اور ایکسپائری: آپ قریب کے مہینے کی علامت اور اس کی تاریخ کی تصدیق کرتے ہیں، لہذا آپ کو تصفیہ سے کبھی حیرت نہیں ہوتی۔ اگلا، مارجن: آپ اصل ضرورت کے لیے کیلکولیٹر کو چیک کرتے ہیں اور تصدیق کرتے ہیں کہ آپ کے پاس سب سے اوپر کیش بفر ہے۔ پھر سائز کرنا: آپ کا اسٹاپ 30 پوائنٹس کے فاصلے پر ہے، اور 65 روپے فی لاٹ پر، ایک لاٹ کا خطرہ تقریباً 1,950 روپے ہے۔ یہ آپ کے 5,000 روپے کے بجٹ میں فٹ بیٹھتا ہے، لیکن دو لاٹ 3,900 روپے کے قریب خطرے میں پڑ جائیں گے اور آپ کو کنارے کی طرف دھکیل دیں گے، اس لیے نظم و ضبط کا انتخاب ایک لاٹ ہے۔ آپ نے داخل ہونے سے پہلے وہ 30 نکاتی اسٹاپ سیٹ کیا۔ آپ لاگت نوٹ کرتے ہیں، تقریباً 929 روپے اور 14 پوائنٹس راؤنڈ ٹرپ، لہذا آپ کے ہدف کو صاف کرنا ہوگا کہ اسے لینے کے قابل ہونا چاہیے۔ آپ ایونٹ کے کیلنڈر پر نظر ڈالتے ہیں اور اپنے منصوبہ بند باہر نکلنے سے پہلے کوئی بڑی چیز نہیں دیکھتے ہیں۔ آخر میں آپ منصوبہ لکھتے ہیں: یہاں داخل ہوں، ہدف سے باہر نکلیں، سٹاپ پر کاٹیں، کوئی اوسط نیچے نہیں۔ سات چھوٹے چیک، اور ایک تجارت جو خاموشی سے تباہی میں نہیں بدل سکتی۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>وہی RELIANCE لمبا جو پانچ یا چھ لاٹوں پر پرکشش نظر آتا ہے، جو چند لاکھ کے مارجن پر تیس سے چالیس لاکھ کو کنٹرول کرتا ہے، پہلی ہی جانچ میں ناکام ہوجاتا ہے: یہ مارجن سے زیادہ سائز کرتا ہے اور ایک تجارت پر عام اکاؤنٹ کے دو فیصد سے زیادہ خطرہ ہوتا ہے۔ چیک لسٹ اسے مارکیٹ کرنے سے پہلے ہی روک دیتی۔</p>\n</div></div>\n<h2 id=\"where-you-go-from-here\">تم یہاں سے کہاں جاؤ</h2>\n<p>اب آپ کے پاس فیوچر کنٹریکٹ کی مکمل تصویر ہے، آج کیے گئے معاہدے سے لے کر کیش یا حصص تک جو میعاد ختم ہونے پر ہاتھ بدلتے ہیں، اور آپ اس ایک خصوصیت کو سمجھتے ہیں جو ہر چیز کا فیصلہ کرتی ہے، بیعانہ۔ وہ تاجر جو آخری ہیں وہ اگلی موم بتی کی پیشین گوئی کرنے میں سب سے زیادہ جرات مند یا بہترین نہیں ہیں۔ یہ وہ لوگ ہیں جو مارجن کے پیچھے نمائش کا احترام کرتے ہیں، سائز کافی چھوٹا ہوتا ہے جو کئی بار غلط ہو سکتا ہے، ہمیشہ ان کے باہر نکلنے کو جانتے ہیں، اور ایک چیک لسٹ چلاتے ہیں جو اچھے ارادوں کو عادت میں بدل دیتی ہے۔ ان میں سے ایک بنیں۔ اگر آپ کسی بھی چیز کو داؤ پر لگائے بغیر نظم و ضبط کی مشق کرنا چاہتے ہیں، تو سینڈ باکس ٹریڈنگ میں مشق کریں، OpenAlgo میں تجزیہ کار وضع، جب تک کہ معمول دوسری نوعیت کا نہ ہو۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مستقبل میں بقا زیادہ بار صحیح ہونے کے بارے میں نہیں ہے۔ یہ چھوٹے رہنے، مارجن کے پیچھے نمائش کو کنٹرول کرنے، اور چیک لسٹ کو کبھی نہ چھوڑنے کے بارے میں ہے۔ ایسا کریں اور آپ اپنے آپ کو وہ وقت دیں جو ہر تاجر کو درحقیقت سیکھنے کی ضرورت ہے۔</p>\n</div></div>\n<p>یہاں سے قدرتی اگلا مرحلہ ہے۔ <strong>اختیارات</strong>. مستقبل آپ کو ایک سیدھی، متوازی ادائیگی اور ایک ذمہ داری دیتا ہے جس سے آپ دور نہیں جا سکتے، جبکہ ایک آپشن آپ کو خطرے کی شکل دینے، اپنے نقصان کو ایک معروف پریمیم تک محدود کرنے، اور سیدھی لائن میں چلنے کے بجائے موڑنے والی پوزیشنیں بنانے دیتا ہے۔ اس سائٹ پر آپشن کورسز بالکل وہی جگہ لیتے ہیں جہاں یہ ختم ہوتا ہے، وہی اصلی ہندوستانی آلات اور وہی ایماندار، سادہ انگریزی نقطہ نظر اس امیر ٹول کٹ میں لے کر۔ آپ نے بنیاد رکھی ہے۔ جاؤ اور اگلی منزل شامل کرو۔</p>\n","toc":[{"level":2,"text":"وہ غلطیاں جو ابتدائی اکاؤنٹس کو خالی کرتی ہیں۔","id":"the-mistakes-that-empty-beginner-accounts"},{"level":2,"text":"پری ٹریڈ چیک لسٹ","id":"the-pre-trade-checklist"},{"level":2,"text":"ایک حقیقی تجارت پر چیک لسٹ چلائیں۔","id":"run-the-checklist-on-one-real-trade"},{"level":2,"text":"تم یہاں سے کہاں جاؤ","id":"where-you-go-from-here"}],"imgCount":2,"hasContent":true}}
